struct ContainerPlaybackPreparationTestAccess {
    static bool ChangeOriginalFingerprint(ContainerPlaybackTable& table,
        const PreparedContainerPlaybackRow& original) noexcept {
        auto* row = table.FindPrepared(original);
        if (row == nullptr) return false;
        ++row->programSemanticFingerprint;
        return true;
    }
};
struct PlayableInstanceDeadlineTestAccess {
    static bool ChangeOriginalKind(PlayableInstanceTable& table,
        const PreparedPlayableInstance& original) noexcept {
        auto* row = table.FindPrepared(original);
        if (row == nullptr || row->kind != PlayableKind::Container) return false;
        row->kind = PlayableKind::Piece;
        return true;
    }
};
