    void MakeFirstVariableControlChildCompositeTrack() {
        auto& property = properties[6];
        property.contentPropertyKind =
            harken::playableproperties::ContentPropertyKindV1::Track;
        property.stableId = harkentest::ObjectId(75);
        property.authoredStableOrder = 6;
        property.contentRevision = 1;
        property.routeStableId = VN_BUS_MASTER;
        property.compatibilityFingerprint = 6;
        property.payload = ResolvedPayload();
        property.programSemanticFingerprint =
            harken::ComputePlayablePropertyFingerprintV1(property);
        for (std::uint32_t index = 0; index < 2; ++index) {
            auto& placement = trackPlacements[index];
            placement.stablePlacementOrdinal = index;
            placement.stableOccurrenceOrdinal = 20u + index;
            placement.content = variableControlChildren[index].playable;
            placement.authoredStart = 0;
            placement.clipId = harkentest::ObjectId(5001u + index);
            placement.clipGuidHigh = 6001u + index;
            placement.clipGuidLow = 7001u + index;
            auto& occurrence = occurrences[6 + index];
            occurrence.parentKind =
                harken::playableproperties::ContentPropertyKindV1::Track;
            occurrence.parentStableId = property.stableId;
            occurrence.parentProgramSemanticFingerprint =
                property.programSemanticFingerprint;
            occurrence.stableOccurrenceOrdinal =
                placement.stableOccurrenceOrdinal;
            occurrence.childPlayable = placement.content;
            occurrence.payload = CanonicalPayload();
            occurrence.occurrenceSemanticFingerprint =
                harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        }
        track.rootDefinition.kind = harken::PlayableKindV1::Track;
        track.rootDefinition.stableId = property.stableId;
        track.rootDefinition.expectedProgramSemanticFingerprint =
            property.programSemanticFingerprint;
        track.rootDefinition.contentRevision = property.contentRevision;
        track.rootDefinition.routeStableId = property.routeStableId;
        track.rootDefinition.compatibilityFingerprint =
            property.compatibilityFingerprint;
        track.placementCount = 2;
        track.placements = trackPlacements;
        track.scheduleSemanticFingerprint =
            harken::ComputeTrackScheduleFingerprintV1(track);
        variableControlChildren[0].playable = track.rootDefinition;
        variableControlChildren[0].timingHint = {};
        occurrences[4].childPlayable =
            variableControlChildren[0].playable;
        occurrences[4].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(occurrences[4]);
        world.playablePropertyCount = 7;
        world.playableOccurrenceCount = 8;
        world.trackSchedules = &track;
        world.trackScheduleCount = 1;
        world.identity.runtimeSemanticFingerprint =
            harken::ComputeCurrentWorldFingerprintV4(world);
    }

