TEST(ActionFiringApi, DelayedPostActionCreatesChildOnlyAfterMaterialization) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    SetAbsoluteTime(&image.steps[1].delay,
                    DelayNanosecondsForTargetFrame(
                        *engine, engine->timelinePool.WindowEndFrame()));
    image.actions[1].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[1]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[1].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    EXPECT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine->actionFirings.OwnedDeferredCount(firing));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_AWAITING_MATERIALIZATION, step.state);
    EXPECT_EQ(0u, step.childFiring);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(0u, info.childFiringCount);

    DrainActionDeferred(engine);
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, step.state);
    EXPECT_NE(0u, step.childFiring);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(1u, info.childFiringCount);
    VnActionStepResult child{};
    child.structSize = sizeof(child);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(step.childFiring, 0, &child));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, child.state);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi,
     DelayedPostActionChildKeepsParentLogicSequence) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeDelayedSoundPlayAction(1000000000);
    image.MakeQuantizedPostAction(
        harken::ActionQuantizeTimingV1::Immediate,
        harken::ActionIfSilentV1::Immediate,
        DelayNanosecondsForTargetFrame(
            *engine, engine->timelinePool.WindowEndFrame()),
        10, 14, harkentest::ObjectId(51), 9);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionFiringInfo parentInfo{};
    parentInfo.structSize = sizeof(parentInfo);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &parentInfo));
    const std::uint64_t parentSequence = parentInfo.acceptedLogicSequence;
    ASSERT_NE(0u, parentSequence);
    const std::uint64_t issuedAtAdmission = engine->logicCommits.IssuedCount();
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    for (std::uint32_t drain = 0; drain < 64; ++drain) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
        if (step.childFiring != 0) {
            break;
        }
    }
    EXPECT_EQ(issuedAtAdmission, engine->logicCommits.IssuedCount());
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, step.state);
    ASSERT_NE(0u, step.childFiring);
    VnActionFiringInfo childInfo{};
    childInfo.structSize = sizeof(childInfo);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(step.childFiring, &childInfo));
    EXPECT_EQ(parentSequence, childInfo.acceptedLogicSequence);
    ASSERT_GE(engine->actionDeferredRecords.LiveCount(), 1u);
    harken::DeferredIntentClaim claim{};
    ASSERT_EQ(1u, engine->timelineDeferred.ClaimDue(
                      UINT64_MAX, engine->playableInstances, &claim, 1,
                      nullptr, nullptr, UINT64_MAX));
    EXPECT_EQ(parentSequence, claim.intent.commitSequence);
    EXPECT_EQ(harken::DeferredIntentRefusal::None,
              engine->timelineDeferred.Retry(claim.token, 0));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
}

