    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    const std::uint64_t delayedFrame =
        engine->timelinePool.WindowEndFrame() - 1u;
    image.MakeQuantizedSoundPlayAction(
        harken::ActionQuantizeTimingV1::NextBeat,
        harken::ActionIfSilentV1::Immediate,
        DelayNanosecondsForTargetFrame(*engine, delayedFrame),
        harken::ActionTargetKindV1::Sound);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc fallbackDesc = ValidPostDesc();
    fallbackDesc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle fallbackFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&fallbackDesc, &fallbackFiring));
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine->playableInstances.LiveCount());
    EXPECT_EQ(delayedFrame, engine->playableServices[0].startFrame);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(fallbackFiring));

    image.MakeQuantizedSoundPlayAction(
        harken::ActionQuantizeTimingV1::NextBeat, harken::ActionIfSilentV1::Drop,
        DelayNanosecondsForTargetFrame(*engine, delayedFrame),
        harken::ActionTargetKindV1::Sound);
