static void CheckTransferredQueueArrivalStop(bool scheduled, bool transportReset,
    bool startAfterObservation = false, bool unrelatedRoot = false) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    EXPECT_EQ(engine->decisions.Capacity(), engine->decisionRetirements.size());
    std::vector<float> first(2048, 0.25f);
    std::vector<float> second(32768, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(125000000);
    image.MakeImmediateSequenceQueuePlayAction();
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    post.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    auto& row = engine->playableServices[0];
    const auto root = row.rootInstance;
    harken::DecisionToken arrival{};
    for (std::uint32_t block = 0; block < 40 && !arrival.Valid(); ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        for (const auto& record : engine->decisionRetirements) {
            if (record.rootInstance == root &&
                record.phase == harken::EngineDecisionOwnershipPhase::ActiveArrival)
                arrival = record.decision;
        }
    }
    ASSERT_TRUE(arrival.Valid());
    ASSERT_FALSE(row.queueArrivalDecision.Valid());
    ASSERT_EQ(CanonicalActionWorld::kSecondSound, row.voice.soundId);
    const auto original = engine->decisionRetirements[arrival.slot];
    ASSERT_NE(nullptr, original.programBank);
    const auto bank = std::make_unique<harken::EngineQueueProgramBankBody>(*original.programBank);
    harken::DecisionCommittedSnapshot decision{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(arrival, &decision));
    EXPECT_EQ(decision.sliceCount, decision.consumedSlices);
    EXPECT_LE(decision.lastAudioSequence, engine->mixer.BlocksRendered());
    EXPECT_EQ(harken::AudioGroupState::Admitted, decision.audioState);
    EXPECT_LT(engine->mixer.BlocksRendered() * engine->config.blockFrames, row.queueCompletionFrame);
    harken::VoiceReleaseObserver release{};
    for (std::uint32_t index = 0; index < bank->programCount; ++index) {
        const auto arm = bank->schedules[index].armToken;
        if (arm.renderSlot == static_cast<std::uint32_t>(row.renderHandle) &&
            arm.renderGeneration == static_cast<std::uint32_t>(row.renderHandle >> 32))
            release = bank->releaseObservers[index];
    }
    ASSERT_TRUE(release.Valid());
    ASSERT_FALSE(engine->voices.ReleaseObserved(release));
    ASSERT_EQ(VN_OK, Vn_Update());
    ExpectFrozenQueueBank(*original.programBank, *bank);
    testing::Message memberStates;
    harken::ArmGroupSnapshot originalGroup{};
    ASSERT_TRUE(engine->armGroups.Capture(original.group, &originalGroup));
    for (std::uint16_t index = 0; index < originalGroup.memberCount; ++index) {
        harken::ArmGroupMemberSnapshot member{};
        ASSERT_TRUE(engine->armGroups.CaptureMember(original.group, index, &member));
        harken::TimelineArmObservation arm{};
        const bool observed = engine->timelineArms.Observe(member.token, &arm);
        memberStates << " member=" << index << " observed=" << observed
            << " tombstoned=" << member.tombstoned << " state=" << static_cast<int>(arm.state);
    }
    SCOPED_TRACE(memberStates);
    VnActionFiringHandle otherFiring = 0;
    harken::PlayableInstanceHandle otherRoot = 0;
    harken::TimelineArmToken otherArm{};
    harken::DecisionToken otherDecision{};
    if (unrelatedRoot) {
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &otherFiring));
        VnActionStepResult otherPlay{};
        otherPlay.structSize = sizeof(otherPlay);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(otherFiring, 0, &otherPlay));
        otherRoot = otherPlay.producedPlayableInstance;
        ASSERT_NE(root, otherRoot);
        for (std::uint32_t block = 0; block < 40 && !otherDecision.Valid(); ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
            for (const auto& record : engine->decisionRetirements) {
                if (record.rootInstance != otherRoot ||
                    record.phase != harken::EngineDecisionOwnershipPhase::ActiveArrival) continue;
                otherDecision = record.decision;
                const auto otherService = std::find_if(engine->playableServices.begin(),
                    engine->playableServices.end(), [&](const auto& candidate) {
                        return candidate.rootInstance == otherRoot;
                    });
                ASSERT_NE(engine->playableServices.end(), otherService);
                ASSERT_FALSE(otherService->queueArrivalDecision.Valid());
                otherArm = otherService->arm;
            }
        }
        ASSERT_TRUE(otherDecision.Valid());
        harken::TimelineArmObservation other{};
        ASSERT_TRUE(engine->timelineArms.Observe(otherArm, &other));
        ASSERT_EQ(harken::ArmState::Started, other.state);
    }
    if (scheduled) {
        post.actionId = image.actions[8].actionStableId;
        VnActionFiringHandle stop = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &stop));
        const auto descriptor = std::find_if(engine->authoredStopResources.begin(),
            engine->authoredStopResources.end(), [&](const auto& resource) {
                return resource.committed && resource.fence &&
                    resource.fence->decision.slot == arrival.slot &&
                    resource.fence->decision.generation == arrival.generation;
            });
        ASSERT_NE(engine->authoredStopResources.end(), descriptor);
        EXPECT_EQ(root, descriptor->fence->identity.root);
        const auto stopFrame = descriptor->fence->identity.stopFrame;
        ASSERT_LT(stopFrame, row.queueCompletionFrame);
        CheckCapturedStopAudioAndRetirement(*engine, root, row.renderHandle,
            release, row.startFrame, stopFrame);
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(stop));
    } else {
        if (startAfterObservation) {
            harken::ArmGroupMemberSnapshot member{};
            ASSERT_TRUE(engine->armGroups.CaptureMember(original.group, 0, &member));
            engine->timelineArms.ApplyClaimedAudioSlice(member.token);
            engine->queueArrivalCancelObservationHookForTest =
                [](harken::Engine& current, harken::TimelineArmToken arm) {
                    current.queueArrivalCancelObservationHookForTest = nullptr;
                    EXPECT_TRUE(current.timelineArms.Start(arm, current.mixer.BlocksRendered()));
                };
        }
        if (transportReset) {
            ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
                harken::BeginRuntimeTransportReset(*engine, 0));
        } else {
            const auto commandHead = engine->commands.PublishedHead();
            const auto stopped = harken::StopPlayable(*engine, root, 19);
            ASSERT_EQ(harken::PlayableControlStatus::Ok, stopped)
                << " recreate=" << engine->runtimeRecreateRequired;
            EXPECT_EQ(commandHead + 1u, engine->commands.PublishedHead());
            harken::CommandRecord command{};
            ASSERT_TRUE(engine->commands.Peek(command));
            EXPECT_EQ(harken::kOpcodeStop, command.opcode);
            EXPECT_EQ(row.renderHandle, command.payload.stop.handle);
            EXPECT_EQ(19u, command.payload.stop.fadeMs);
            EXPECT_FALSE(engine->voices.ReleaseObserved(release));
            ASSERT_EQ(harken::PlayableControlStatus::Ok,
                harken::StopPlayable(*engine, root, 99));
            EXPECT_EQ(commandHead + 1u, engine->commands.PublishedHead());
            for (std::uint16_t index = 0; index < originalGroup.memberCount; ++index) {
                harken::ArmGroupMemberSnapshot member{};
                ASSERT_TRUE(engine->armGroups.CaptureMember(original.group, index, &member));
                harken::TimelineArmObservation arm{};
                if (engine->timelineArms.Observe(member.token, &arm)) {
                    EXPECT_NE(harken::ArmState::Started, arm.state);
                }
            }
        }
        EXPECT_EQ(nullptr, engine->queueArrivalCancelObservationHookForTest);
        for (std::uint32_t block = 0; block < 32; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        if (transportReset)
            EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete,
                harken::BeginRuntimeTransportReset(*engine, 0));
    }
    EXPECT_FALSE(engine->playableInstances.Classify(root).live);
    EXPECT_FALSE(engine->decisions.Contains(arrival));
    if (unrelatedRoot) {
        EXPECT_TRUE(engine->playableInstances.Classify(otherRoot).live);
        EXPECT_TRUE(engine->decisions.Contains(otherDecision));
        harken::TimelineArmObservation other{};
        ASSERT_TRUE(engine->timelineArms.Observe(otherArm, &other));
        EXPECT_EQ(harken::ArmState::Started, other.state);
        const auto commandHead = engine->commands.PublishedHead();
        EXPECT_EQ(harken::PlayableControlStatus::StaleHandle,
            harken::StopPlayable(*engine, root, 0));
        EXPECT_EQ(commandHead, engine->commands.PublishedHead());
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, otherRoot, 19));
        for (std::uint32_t block = 0; block < 32; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(otherFiring));
    }
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, std::count_if(engine->decisionRetirements.begin(), engine->decisionRetirements.end(),
        [](const auto& record) { return record.decision.Valid(); }));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

