TEST(ActionFiringApi, MultiLeafQueueFutureStopDirectCancellationReclaimsPreparedDecision) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(2048, 0.25f);
    std::vector<float> second(8192, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(125000000);
    image.MakeImmediateSequenceQueuePlayAction();
    image.MakeSecondQueueChildCompositeTrack();
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    for (std::uint32_t cycle = 0; cycle < 3; ++cycle) {
        SCOPED_TRACE(cycle);
        auto post = ValidPostDesc();
        post.actionId = image.actions[9].actionStableId;
        post.emitter = emitter;
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        auto& row = engine->playableServices[0];
        const auto root = row.rootInstance;
        const auto ready = [&] {
            return row.queueArrivalDecision.Valid() && row.queueArrivalScheduleLeafCount > 1 &&
                row.queueContinuationPrepared && row.queueSuccessorDecision.Valid();
        };
        for (std::uint32_t block = 0; block < 128 && !ready(); ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        ASSERT_TRUE(ready()) << "arrival=" << row.queueArrivalDecision.Valid()
            << " members=" << row.queueArrivalScheduleLeafCount
            << " prepared=" << row.queueContinuationPrepared
            << " successor=" << row.queueSuccessorDecision.Valid();
        const auto arrival = row.queueArrivalDecision;
        const auto successor = row.queueSuccessorDecision;
        const auto preparedDecision = row.queueDecision;
        const auto originalArrivalGroup = row.queueArrivalArmGroup;
        const auto preparedConditional = row.queueConditional;
        harken::DecisionCommittedSnapshot arrivalSnapshot{};
        ASSERT_TRUE(engine->decisions.CaptureCommitted(arrival, &arrivalSnapshot));
        ASSERT_EQ(harken::AudioGroupState::Admitted, arrivalSnapshot.audioState);
        ASSERT_TRUE(engine->decisions.IsOpen(successor));
        ASSERT_TRUE(engine->decisions.IsOpen(preparedDecision));
        ASSERT_TRUE(preparedConditional.Valid());
        RecordProperty("root", std::to_string(root));
        RecordProperty("arrival", std::to_string(arrival.slot) + ":" + std::to_string(arrival.generation));
        RecordProperty("successor", std::to_string(successor.slot) + ":" + std::to_string(successor.generation));
        post.actionId = image.actions[8].actionStableId;
        VnActionFiringHandle stop = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &stop))
            << " observed=" << engine->mixer.BlocksRendered() * engine->config.blockFrames
            << " cutoff=" << engine->timelinePool.PublishCutoffFrame()
            << " window=" << engine->timelinePool.WindowStartFrame() << ":" << engine->timelinePool.WindowEndFrame()
            << " stop_roots=" << std::count_if(engine->authoredStopRoots.begin(), engine->authoredStopRoots.end(),
                   [](const auto& candidate) { return candidate.operation.has_value(); })
            << " stop_resources=" << std::count_if(engine->authoredStopResources.begin(), engine->authoredStopResources.end(),
                   [](const auto& candidate) { return candidate.operationSlot != UINT32_MAX; })
            << " commands_free=" << engine->commands.FreeSlots();
        const auto resource = std::find_if(engine->authoredStopResources.begin(),
            engine->authoredStopResources.end(), [&](const auto& candidate) {
                return candidate.committed && candidate.fence &&
                    candidate.fence->decision.slot == successor.slot &&
                    candidate.fence->decision.generation == successor.generation;
            });
        ASSERT_NE(engine->authoredStopResources.end(), resource);
        ASSERT_TRUE(resource->fence->Active());
        ASSERT_EQ(root, resource->fence->identity.root);
        ASSERT_GT(resource->fence->identity.stopFrame,
            engine->mixer.BlocksRendered() * engine->config.blockFrames);
        ASSERT_TRUE(resource->fence->TryBeginApply());
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, root, 0));
        EXPECT_EQ(arrival.slot, row.queueArrivalDecision.slot);
        EXPECT_EQ(arrival.generation, row.queueArrivalDecision.generation);
        harken::ArmGroupSnapshot originalArrival{};
        ASSERT_TRUE(engine->armGroups.Capture(originalArrivalGroup, &originalArrival));
        EXPECT_FALSE(row.queueContinuationPrepared);
        EXPECT_FALSE(engine->decisions.IsOpen(preparedDecision));
        EXPECT_TRUE(engine->decisions.Contains(successor));
        for (std::uint32_t block = 0; block < 32; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_FALSE(engine->playableInstances.Classify(root).live);
        EXPECT_FALSE(engine->decisions.Contains(arrival));
        EXPECT_FALSE(engine->decisions.Contains(preparedDecision));
        ASSERT_TRUE(engine->decisions.Contains(successor));
        EXPECT_EQ(1u, engine->decisions.LiveCount());
        EXPECT_EQ(0u, engine->armGroups.LiveCount());
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_FALSE(engine->runtimeRecreateRequired);
        harken::DecisionReserveRequest reserve{};
        reserve.ticket.sequence = 100;
        reserve.world = engine->variables.CurrentWorldGeneration();
        reserve.transport = engine->timelinePool.Epoch();
        reserve.expectedContinuationGeneration = 1;
        reserve.sliceCount = 1;
        std::vector<harken::DecisionToken> unrelatedDecisions;
        while (engine->decisions.LiveCount() < engine->decisions.Capacity()) {
            harken::DecisionToken token{};
            ASSERT_TRUE(engine->decisions.Reserve(reserve, &token));
            unrelatedDecisions.push_back(token);
        }
        harken::PlayableStartRequest unrelatedRequest{};
        unrelatedRequest.root = image.child.playable;
        const auto unrelated = harken::StartPlayable(*engine, unrelatedRequest);
        ASSERT_EQ(harken::PlayableStartStatus::Accepted, unrelated.status);
        const auto unrelatedEpoch = engine->playableInstances.Classify(unrelated.instance).scheduleEpoch;
        resource->fence->FinishApply();
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine->decisions.Contains(successor));
        harken::DecisionToken reused{};
        ASSERT_TRUE(engine->decisions.Reserve(reserve, &reused));
        EXPECT_EQ(successor.slot, reused.slot);
        EXPECT_GT(reused.generation, successor.generation);
        EXPECT_TRUE(engine->playableInstances.Classify(unrelated.instance).live);
        EXPECT_EQ(unrelatedEpoch, engine->playableInstances.Classify(unrelated.instance).scheduleEpoch);
        for (const auto token : unrelatedDecisions) {
            EXPECT_TRUE(engine->decisions.IsOpen(token));
            ASSERT_TRUE(engine->decisions.Cancel(token));
            ASSERT_TRUE(engine->decisions.ReclaimCancelled(token));
        }
        ASSERT_TRUE(engine->decisions.Cancel(reused));
        ASSERT_TRUE(engine->decisions.ReclaimCancelled(reused));
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, unrelated.instance, 0));
        for (std::uint32_t block = 0; block < 32; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(0u, engine->playableInstances.LiveCount());
        EXPECT_EQ(0u, engine->decisions.LiveCount());
        EXPECT_EQ(0u, engine->armGroups.LiveCount());
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(stop));
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        EXPECT_EQ(0u, std::count_if(engine->authoredStopRoots.begin(), engine->authoredStopRoots.end(),
            [](const auto& candidate) { return candidate.operation.has_value(); }));
        EXPECT_EQ(0u, std::count_if(engine->authoredStopResources.begin(), engine->authoredStopResources.end(),
            [](const auto& candidate) { return candidate.operationSlot != UINT32_MAX; }));
    }
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

static void CheckSameKeyResetWithExistingFutureStop(bool stopBeforeBoundary, bool rollback = false) {
    auto config = harkentest::MakeNullConfig(8, 256, 48000);
    if (rollback) config.emitterVariableSlots = 1;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    const auto reset = image.steps[10];
    const auto rejectedVariable = image.steps[12];
    const auto secondVariable = image.steps[13];
    std::array<harken::ActionStepProgramViewV1, 3> rollbackSteps{};
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(
        *engine, stopBeforeBoundary ? 3072 : 5376));
    image.MakeImmediateSequenceQueuePlayAction();
    image.queueChildren[1].playable = image.queueChildren[0].playable;
    image.queueCompletionLeaves[1].content = image.queueChildren[1].playable;
    image.occurrences[3].childPlayable = image.queueChildren[1].playable;
    image.occurrences[3].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[3]);
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.steps[14] = reset;
    image.actions[10] = {};
    image.actions[10].actionStableId = harkentest::ObjectId(51);
    image.actions[10].steps = &image.steps[14];
    image.actions[10].stepCount = 1;
    image.actions[10].expandedStepOccurrenceCount = 1;
    image.actions[10].expandedFiringCount = 1;
    if (rollback) {
        rollbackSteps = {reset, rejectedVariable, secondVariable};
        image.actions[10].steps = rollbackSteps.data();
        image.actions[10].stepCount = 3;
        image.actions[10].expandedStepOccurrenceCount = 3;
    }
    image.actions[10].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[10]);
    image.world.actionCount = 11;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    post.emitter = emitter;
    VnActionFiringHandle play = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &play));
    auto& row = engine->playableServices[0];
    ASSERT_TRUE(row.queueSameProgramKey);
    ASSERT_TRUE(row.queueContinuationPrepared);
    const auto root = row.rootInstance;
    const auto originalDecision = row.queueDecision;
    const auto originalConditional = row.queueConditional;
    const auto originalVoice = row.renderHandle;
    const auto boundary = row.queueCompletionFrame;
    post.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stop = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &stop));
    const auto stopResource = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& resource) {
            return resource.committed && resource.fence && resource.fence->identity.root == root;
        });
    ASSERT_NE(engine->authoredStopResources.end(), stopResource);
    const auto stopFrame = stopResource->fence->identity.stopFrame;
    ASSERT_EQ(stopBeforeBoundary, stopFrame <= boundary);
    const auto originalStopIdentity = stopResource->fence->identity;
    const auto originalStopSlot = stopResource->operationSlot;
    const auto stopResourceCount = engine->authoredStopRoots[originalStopSlot].resourceCount;
    const auto occupiedStopResources = std::count_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [](const auto& candidate) {
            return candidate.operationSlot != UINT32_MAX;
        });
    const auto originalPinned = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& candidate) {
            return candidate.fence && candidate.fence->decision.slot == originalDecision.slot &&
                candidate.fence->decision.generation == originalDecision.generation;
        });
    ASSERT_NE(engine->authoredStopResources.end(), originalPinned);
    ASSERT_TRUE(originalPinned->fence->Active());
    const auto before = CaptureActionPreparationOwners(*engine);
    post.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle resetFiring = 0;
    const auto resetResult = Vn_PostAction(&post, &resetFiring);
    testing::Test::RecordProperty("stop_frame", std::to_string(stopFrame));
    testing::Test::RecordProperty("boundary", std::to_string(boundary));
    testing::Test::RecordProperty("reset_result", std::to_string(resetResult));
    if (stopBeforeBoundary || rollback) {
        EXPECT_EQ(rollback ? VN_VARIABLE_EMITTER_SLOT_EXHAUSTED : VN_BACKPRESSURE,
                  resetResult);
        if (resetResult != VN_OK) {
            ExpectActionPreparationOwnersUnchanged(*engine, before);
            EXPECT_EQ(0u, resetFiring);
            EXPECT_EQ(originalDecision.slot, row.queueDecision.slot);
            EXPECT_EQ(originalDecision.generation, row.queueDecision.generation);
            EXPECT_EQ(originalConditional.version, row.queueConditional.version);
            EXPECT_EQ(originalVoice, row.renderHandle);
            EXPECT_EQ(stopResourceCount, engine->authoredStopRoots[originalStopSlot].resourceCount);
            EXPECT_TRUE(engine->authoredStopRoots[originalStopSlot].operation->Active(originalStopIdentity));
            EXPECT_EQ(occupiedStopResources, std::count_if(engine->authoredStopResources.begin(),
                engine->authoredStopResources.end(), [](const auto& candidate) {
                    return candidate.operationSlot != UINT32_MAX;
                }));
            EXPECT_EQ(0u, std::count_if(engine->authoredStopResources.begin(),
                engine->authoredStopResources.end(), [](const auto& candidate) { return candidate.prepared; }));
            EXPECT_TRUE(originalPinned->fence->Active());
            EXPECT_FALSE(engine->runtimeRecreateRequired);
            return;
        }
    } else {
        ASSERT_EQ(VN_OK, resetResult);
    }
    const auto replacement = row.queueDecision;
    ASSERT_TRUE(row.queueSameProgramKey);
    ASSERT_TRUE(replacement.slot != originalDecision.slot || replacement.generation != originalDecision.generation);
    harken::DecisionCommittedSnapshot snapshot{};
    ASSERT_TRUE(engine->decisions.CaptureCommitted(replacement, &snapshot));
    EXPECT_GT(snapshot.futurePinCount, 0u);
    const auto inherited = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& resource) {
            return resource.committed && resource.fence && resource.fence->decision.slot == replacement.slot &&
                resource.fence->decision.generation == replacement.generation;
        });
    EXPECT_NE(engine->authoredStopResources.end(), inherited);
    ASSERT_NE(engine->authoredStopResources.end(), inherited);
    const auto operationSlot = inherited->operationSlot;
    const auto operationIdentity = inherited->fence->identity;
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames + engine->config.blockFrames < stopFrame) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    auto& operation = engine->authoredStopRoots[operationSlot];
    ASSERT_TRUE(operation.operation.has_value());
    ASSERT_TRUE(operation.operation->Active(operationIdentity));
    ASSERT_EQ(0u, operation.operation->AppliedAudioSequence());
    ASSERT_GT(engine->timelinePool.PublishCutoffFrame(), stopFrame);
    engine->nullBackend.Pump(2);
    ASSERT_TRUE(operation.operation.has_value());
    EXPECT_GT(operation.operation->AppliedAudioSequence(), 0u);
    for (std::uint32_t block = 0; block < 32; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_FALSE(engine->decisions.Contains(replacement));
    EXPECT_FALSE(engine->playableInstances.Classify(root).live);
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
}

