static void CheckDeferredQueueCompletionAtFutureStop(bool compositeSuccessor, bool nestedParent,
                                                    bool advanceBeforeFinalOnset = false) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(nestedParent ? 2048u :
        static_cast<std::size_t>(engine->timelinePool.WindowEndFrame() + 256u), 0.25f);
    std::vector<float> second(8192, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(
        *engine, nestedParent ? 15000u : advanceBeforeFinalOnset ? 6144u : 4096u));
    image.MakeImmediateSequenceQueuePlayAction();
    auto nestedChild = image.queueChildren[0];
    if (nestedParent) {
        image.MakeImmediateQueueNestedContainerPlayAction(false);
        image.containers[0].mode = harken::ContainerModeV1::SequenceQueue;
        nestedChild.stableChildOrdinal = image.child.stableChildOrdinal;
        nestedChild.frequencyWeight = 0;
        image.containers[0].memoryScope = harken::MemoryScopeV1::Emitter;
        image.containers[0].queueCycle = harken::QueueCycleV1::Once;
        image.containers[0].queueSplice = harken::QueueSpliceV1::Butt;
        image.containers[0].children = &nestedChild;
    } else {
        if (compositeSuccessor) image.MakeSecondQueueChildCompositeTrack();
    }
    image.steps[10].target = image.steps[11].target;
    image.actions[8].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    post.emitter = emitter;
    VnActionFiringHandle play = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &play));
    auto& publicRow = engine->playableServices[0];
    const auto root = publicRow.rootInstance;
    auto* initialResource = FrontierActiveResourceService(*engine, publicRow);
    ASSERT_NE(nullptr, initialResource);
    auto& row = *initialResource;
    const auto originalVoice = row.renderHandle;
    const auto naturalFrame = row.startFrame + first.size();
    const auto originalQueue = nestedParent ? publicRow.queueInstance : row.queueInstance;
    const auto originalEpoch = engine->playableInstances.Classify(root).scheduleEpoch;
    harken::QueueInstanceSnapshot originalQueueSnapshot{};
    ASSERT_TRUE(engine->queueInstances.Capture(originalQueue, &originalQueueSnapshot));
    EXPECT_EQ(nestedParent, row.parentService.Valid());
    testing::Test::RecordProperty("initial_deferred_full", row.queueDeferredNeedsFullPreparation ? "true" : "false");
    testing::Test::RecordProperty("initial_signal_only", row.queueSignalOnlyNoOverlap ? "true" : "false");
    if (!nestedParent) {
        ASSERT_TRUE(row.queueSignalOnlyNoOverlap);
        ASSERT_TRUE(row.queueDeferredNeedsFullPreparation);
    } else {
        EXPECT_EQ(row.ownerInstance, publicRow.frontierChildService.owner);
        EXPECT_EQ(row.ownerEpoch, publicRow.frontierChildService.epoch);
    }
    if (!nestedParent) {
        while (engine->mixer.BlocksRendered() * engine->config.blockFrames < naturalFrame - 3584u) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
    }
    post.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stop = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &stop));
    const auto resource = std::find_if(engine->authoredStopResources.begin(),
        engine->authoredStopResources.end(), [&](const auto& candidate) {
            return candidate.committed && candidate.fence && candidate.fence->identity.root == root;
        });
    ASSERT_NE(engine->authoredStopResources.end(), resource);
    const auto stopFrame = resource->fence->identity.stopFrame;
    const auto stopIdentity = resource->fence->identity;
    const auto stopSlot = resource->operationSlot;
    ASSERT_TRUE(resource->fence->Active());
    const auto sourceRelease = row.releaseObserver;
    ASSERT_LT(naturalFrame, stopFrame);
    testing::Test::RecordProperty("source_natural_frame", std::to_string(naturalFrame));
    testing::Test::RecordProperty("stop_frame", std::to_string(stopFrame));
    bool sawStartRefused = false;
    bool sawReplacementVoice = false;
    for (std::uint32_t block = 0; block < 8; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    if (advanceBeforeFinalOnset) {
        const auto leadFrames = static_cast<std::uint64_t>(std::max(1u,
            engine->timelinePool.PublishLeadQuanta())) * engine->config.blockFrames;
        ASSERT_GT(stopFrame, leadFrames);
        const auto beforeBoundaryFrame = (stopFrame - 1u - leadFrames) /
            engine->config.blockFrames * engine->config.blockFrames;
        while (engine->mixer.BlocksRendered() * engine->config.blockFrames < beforeBoundaryFrame)
            engine->nullBackend.Pump(1);
    } else {
        while ((engine->mixer.BlocksRendered() + 1u) * engine->config.blockFrames < stopFrame)
            engine->nullBackend.Pump(1);
    }
    const auto resumedFrame = engine->mixer.BlocksRendered() * engine->config.blockFrames;
    ASSERT_LT(resumedFrame, stopFrame);
    if (advanceBeforeFinalOnset) {
        ASSERT_LT(std::max(resumedFrame + engine->timelinePool.PublishLeadQuanta() * engine->config.blockFrames,
            engine->timelinePool.PublishCutoffFrame()), stopFrame);
    } else {
        ASSERT_GE(resumedFrame + engine->timelinePool.PublishLeadQuanta() * engine->config.blockFrames, stopFrame);
    }
    ASSERT_TRUE(engine->voices.ReleaseObserved(sourceRelease));
    ASSERT_TRUE(resource->fence->Active());
    testing::Test::RecordProperty("resumed_frame", std::to_string(resumedFrame));
    harken::PlayableStartRequest unrelatedRequest{};
    unrelatedRequest.root = image.child.playable;
    unrelatedRequest.root.stableId = image.properties[1].stableId;
    unrelatedRequest.root.expectedProgramSemanticFingerprint = image.properties[1].programSemanticFingerprint;
    unrelatedRequest.root.contentRevision = image.properties[1].contentRevision;
    unrelatedRequest.root.routeStableId = image.properties[1].routeStableId;
    unrelatedRequest.root.compatibilityFingerprint = image.properties[1].compatibilityFingerprint;
    const auto unrelated = harken::StartPlayable(*engine, unrelatedRequest);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, unrelated.status);
    const auto unrelatedEpoch = engine->playableInstances.Classify(unrelated.instance).scheduleEpoch;
    if (advanceBeforeFinalOnset) {
        engine->queueContinuationFinalOnsetHookForTest =
            [](harken::Engine& current, harken::PlayableInstanceHandle currentRoot) {
                current.queueContinuationFinalOnsetHookForTest = nullptr;
                while (current.playableInstances.Classify(currentRoot).parent != 0)
                    currentRoot = current.playableInstances.Classify(currentRoot).parent;
                const auto operation = std::find_if(current.authoredStopRoots.begin(),
                    current.authoredStopRoots.end(), [&](const auto& candidate) {
                        return candidate.operation && candidate.operation->Identity().root == currentRoot;
                    });
                ASSERT_NE(current.authoredStopRoots.end(), operation);
                const auto stop = operation->operation->Identity().stopFrame;
                const auto block = current.config.blockFrames;
                const auto lead = static_cast<std::uint64_t>(std::max(1u,
                    current.timelinePool.PublishLeadQuanta())) * block;
                const auto before = std::max(current.mixer.BlocksRendered() * block + lead,
                    current.timelinePool.PublishCutoffFrame());
                ASSERT_LT(before, stop);
                current.nullBackend.Pump(1);
                const auto after = std::max(current.mixer.BlocksRendered() * block + lead,
                    current.timelinePool.PublishCutoffFrame());
                EXPECT_GE(after, stop);
                EXPECT_LT(current.mixer.BlocksRendered() * block, stop);
                testing::Test::RecordProperty("early_onset", std::to_string(before));
                testing::Test::RecordProperty("final_onset", std::to_string(after));
                testing::Test::RecordProperty("final_onset_hook_calls", "1");
            };
    }
    bool naturallyCompletedBeforeStop = false;
    for (std::uint32_t attempt = 0; attempt < 8; ++attempt) {
        if (engine->playableInstances.Classify(root).live) {
            EXPECT_EQ(originalEpoch, engine->playableInstances.Classify(root).scheduleEpoch);
            harken::QueueInstanceSnapshot beforeService{};
            if (engine->queueInstances.Capture(originalQueue, &beforeService)) {
                EXPECT_EQ(originalQueueSnapshot.logicMirror.version, beforeService.logicMirror.version);
                EXPECT_EQ(originalQueueSnapshot.logicMirror.currentChildOrdinal, beforeService.logicMirror.currentChildOrdinal);
            }
            ASSERT_TRUE(engine->authoredStopRoots[stopSlot].operation.has_value());
            ASSERT_TRUE(engine->authoredStopRoots[stopSlot].operation->Active(stopIdentity));
            ASSERT_EQ(0u, engine->authoredStopRoots[stopSlot].operation->AppliedAudioSequence());
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        if (advanceBeforeFinalOnset && attempt == 0) {
            if (!nestedParent) EXPECT_EQ(nullptr, engine->queueContinuationFinalOnsetHookForTest);
            EXPECT_NE(harken::PlayableControlReason::StartRefused, row.controlReason);
        }
        const auto rootState = engine->playableInstances.Classify(root);
        naturallyCompletedBeforeStop = naturallyCompletedBeforeStop || !rootState.live ||
            rootState.terminalOutcome.kind == harken::PlayableTerminalKind::NaturalCompletion;
        sawStartRefused = sawStartRefused || row.controlReason == harken::PlayableControlReason::StartRefused ||
            publicRow.controlReason == harken::PlayableControlReason::StartRefused;
        sawReplacementVoice = sawReplacementVoice ||
            (FrontierActiveResourceService(*engine, publicRow) != nullptr &&
                FrontierActiveResourceService(*engine, publicRow)->renderHandle != originalVoice &&
                engine->voices.Resolve(FrontierActiveResourceService(*engine, publicRow)->renderHandle) != nullptr);
    }
    ASSERT_EQ(resumedFrame + (advanceBeforeFinalOnset ? engine->config.blockFrames : 0u),
        engine->mixer.BlocksRendered() * engine->config.blockFrames);
    if (advanceBeforeFinalOnset) EXPECT_EQ(nullptr, engine->queueContinuationFinalOnsetHookForTest);
    testing::Test::RecordProperty("natural_completed_before_stop", naturallyCompletedBeforeStop ? "true" : "false");
    bool sawApplied = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        engine->nullBackend.Pump(1);
        const auto& currentStop = engine->authoredStopRoots[stopSlot].operation;
        if (currentStop && currentStop->Identity().generation == stopIdentity.generation)
            sawApplied = sawApplied || currentStop->AppliedAudioSequence() != 0;
        ASSERT_EQ(VN_OK, Vn_Update());
        sawStartRefused = sawStartRefused || row.controlReason == harken::PlayableControlReason::StartRefused ||
            publicRow.controlReason == harken::PlayableControlReason::StartRefused;
        sawReplacementVoice = sawReplacementVoice ||
            (FrontierActiveResourceService(*engine, publicRow) != nullptr &&
                FrontierActiveResourceService(*engine, publicRow)->renderHandle != originalVoice &&
                engine->voices.Resolve(FrontierActiveResourceService(*engine, publicRow)->renderHandle) != nullptr);
    }
    EXPECT_TRUE(naturallyCompletedBeforeStop || sawApplied);
    if (naturallyCompletedBeforeStop) {
        ASSERT_TRUE(engine->voices.ReleaseObserved(sourceRelease));
        EXPECT_GT(resumedFrame, naturalFrame);
    }
    EXPECT_FALSE(sawStartRefused);
    EXPECT_FALSE(sawReplacementVoice);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    VnActionStepResult stopResult{};
    stopResult.structSize = sizeof(stopResult);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stop, 0, &stopResult));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, stopResult.state);
    EXPECT_EQ(VN_OK, stopResult.result);
    EXPECT_FALSE(engine->playableInstances.Classify(root).live);
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_TRUE(engine->playableInstances.Classify(unrelated.instance).live);
    EXPECT_EQ(unrelatedEpoch, engine->playableInstances.Classify(unrelated.instance).scheduleEpoch);
    EXPECT_EQ(1u, engine->voices.ActiveCount());
    ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, unrelated.instance, 0));
    for (std::uint32_t block = 0; block < 32; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(stop));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(play));
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

