TEST(ActionFiringApi, SameKeyProjectionStartsDifferentSoundAtOriginalOffsetWithoutUpdate) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(2051, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    std::array<harken::ContainerChildProgramViewV2, 3> children{
        image.queueChildren[0], image.queueChildren[0], image.queueChildren[1]};
    children[1].stableChildOrdinal = image.queueChildren[1].stableChildOrdinal;
    children[1].authoredStableOrder = 1;
    children[2].stableChildOrdinal = 9;
    children[2].authoredStableOrder = 2;
    image.containers[2].children = children.data();
    image.containers[2].childCount = 3;
    image.occurrences[4] = image.occurrences[3];
    image.occurrences[3].childPlayable = children[1].playable;
    image.occurrences[3].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[3]);
    image.occurrences[4].stableOccurrenceOrdinal = 9;
    image.occurrences[4].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[4]);
    image.world.playableOccurrenceCount = 5;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    auto& row = engine->playableServices[0];
    const auto source = row.renderHandle;
    const auto target = row.queueSuccessorArm;
    const auto originalArm = row.arm;
    ASSERT_EQ(3u, row.queueConditional.version);
    ASSERT_EQ(2u, row.queueNextState.cursor);
    ASSERT_FALSE(row.queueSameProgramKey);
    ASSERT_EQ(2u, engine->voices.ActiveCount());
    ASSERT_TRUE(target.Valid());
    ASSERT_EQ(0u, engine->timelineArms.Resolve(target)->startFrame);
    harken::TimelineArmObservation originalStarted{};
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (engine->timelineArms.Observe(originalArm, &originalStarted) &&
            originalStarted.state == harken::ArmState::Started) break;
    }
    ASSERT_EQ(harken::ArmState::Started, originalStarted.state);
    harken::EngineTimelineVoiceInstallIdentity installation{};
    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(source, &installation));
    const auto boundary = installation.onsetFrame + first.size();
    ASSERT_EQ(boundary, row.queueCompletionFrame);
    ASSERT_EQ(3u, boundary % engine->config.blockFrames);
    ASSERT_EQ(source, row.renderHandle);
    ASSERT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(originalArm, row.arm));
    ASSERT_EQ(boundary, engine->timelineArms.Resolve(target)->startFrame);
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <
           boundary / engine->config.blockFrames * engine->config.blockFrames) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    const auto before = engine->mixer.BlocksRendered();
    engine->nullBackend.Pump(1);
    ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
    EXPECT_EQ(source, row.renderHandle);
    harken::TimelineArmObservation observation{};
    ASSERT_TRUE(engine->timelineArms.Observe(target, &observation));
    EXPECT_EQ(harken::ArmState::Started, observation.state);
    EXPECT_EQ(before + 1u, observation.startedBlockSequence);
    const auto* output = engine->nullBackend.LastBlock();
    const auto channels = engine->nullBackend.Channels();
    EXPECT_GT(output[2u * channels], 0.01f);
    EXPECT_LT(output[4u * channels], 0.0f);
    harken::EffectiveQueueState effective{};
    ASSERT_TRUE(engine->queueInstances.ResolveEffective(row.queueInstance, &effective));
    EXPECT_EQ(3u, effective.version);
    EXPECT_EQ(2u, effective.cursor);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (std::uint32_t block = 0; block < 64 && row.phase != harken::EnginePlayableStartPhase::Free; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(harken::EnginePlayableStartPhase::Free, row.phase);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

TEST(ActionFiringApi, QuantizedStopFadeStartsBeforeTheBoundary) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                    &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                    &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositePiecePlayAction();
    image.MakeQuantizedSoundPlayAction(
        harken::ActionQuantizeTimingV1::Immediate);
    image.MakeQuantizedSoundStopAction(
        harken::ActionQuantizeTimingV1::NextBeat);
    SetAbsoluteTime(&image.steps[15].fade, 10000000);
    image.actions[11].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[11]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc pieceDesc = ValidPostDesc();
    pieceDesc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle pieceFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&pieceDesc, &pieceFiring));
    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    const std::uint64_t entryFrame = engine->playableServices[0].startFrame;
    const std::uint64_t expected =
        MusicalBoundaryFrameAfter(entryFrame, 0, 960, 1);
    const std::uint64_t fadeFrames =
        (10000000ull * 48000ull + 999999999ull) / 1000000000ull;

    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[11].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    if (expected >= engine->timelinePool.WindowEndFrame()) {
        harken::ActionDeferredRecordToken token{};
        harken::ActionDeferredRecord record{};
        harken::ActionDeferredRecordState state =
            harken::ActionDeferredRecordState::Free;
        ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
            0, &token, &record, &state));
        EXPECT_EQ(expected, record.intendedBoundaryFrame);
        EXPECT_EQ(expected, record.lastRowFrame);
        EXPECT_EQ(expected - fadeFrames, record.firstRowFrame);
    } else {
        EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
        EXPECT_EQ(2u, engine->playableInstances.LiveCount());
        EXPECT_NE(harken::PlayableControlLifecycle::Cancelling,
                  engine->playableServices[1].controlLifecycle);
    }
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(playFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(pieceFiring));
}

TEST(ActionFiringApi, NaturalEndStopUsesRemainingSourceDuration) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    image.MakeQuantizedSoundStopAction(
        harken::ActionQuantizeTimingV1::NaturalEnd,
        harken::ActionIfSilentV1::Immediate, 0,
        harken::ActionTargetKindV1::Sound, 10, 14, harkentest::ObjectId(51));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    const std::uint64_t startFrame = engine->playableServices[0].startFrame;
    const std::uint64_t expected = startFrame + 4096u;

    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    if (expected >= engine->timelinePool.WindowEndFrame()) {
        EXPECT_EQ(1u, engine->actionDeferredRecords.LiveCount());
        harken::ActionDeferredRecordToken token{};
        harken::ActionDeferredRecord record{};
        harken::ActionDeferredRecordState state =
            harken::ActionDeferredRecordState::Free;
        ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
            0, &token, &record, &state));
        EXPECT_EQ(expected, record.intendedBoundaryFrame);
        EXPECT_EQ(1u, engine->playableInstances.LiveCount());
    } else {
        EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
        EXPECT_EQ(1u, engine->playableInstances.LiveCount());
        EXPECT_NE(harken::PlayableControlLifecycle::Cancelling,
                  engine->playableServices[0].controlLifecycle);
    }
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(playFiring));
}

