TEST(ActionFiringApi, ReferencedExitMarkerStopUsesTheReferencePieceTimeline) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                    &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                    &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositePiecePlayAction(true);
    image.MakeQuantizedSoundPlayAction(
        harken::ActionQuantizeTimingV1::Immediate);
    image.MakeQuantizedSoundStopAction(
        harken::ActionQuantizeTimingV1::ExitMarker,
        harken::ActionIfSilentV1::Drop, 5'000'000,
        harken::ActionTargetKindV1::Piece, 11, 15,
        harkentest::ObjectId(52), true);
    SetAbsoluteTime(&image.steps[15].fade, 5'000'000);
    image.actions[11].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[11]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc referenceDesc = ValidPostDesc();
    referenceDesc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle olderReferenceFiring = 0;
    ASSERT_EQ(VN_OK,
              Vn_PostAction(&referenceDesc, &olderReferenceFiring));
    const auto olderReference = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& row) {
            return row.Invocation().actionFiring == olderReferenceFiring;
        });
    ASSERT_NE(engine->playableServices.end(), olderReference);
    const std::uint64_t olderReferenceRoot = olderReference->rootInstance;
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    VnActionFiringHandle referenceFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&referenceDesc, &referenceFiring));
    const auto reference = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& row) {
            return row.Invocation().actionFiring == referenceFiring;
        });
    ASSERT_NE(engine->playableServices.end(), reference);
    const std::uint64_t referenceRoot = reference->rootInstance;
    ASSERT_NE(olderReferenceRoot, referenceRoot);
    const std::uint64_t expected = reference->startFrame + 480u;
    constexpr std::uint64_t kFadeFrames = 240u;

    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(playFiring, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    ASSERT_NE(referenceRoot, play.producedPlayableInstance);

    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[11].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_NE(VN_ACTION_STEP_NO_OP, stop.state);
    EXPECT_NE(VN_ACTION_STEP_SUPPRESSED, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(1u, stop.remainingPlayableCount);
    if (expected >= engine->timelinePool.WindowEndFrame()) {
        harken::ActionDeferredRecordToken token{};
        harken::ActionDeferredRecord record{};
        harken::ActionDeferredRecordState state =
            harken::ActionDeferredRecordState::Free;
        ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
            0, &token, &record, &state));
        EXPECT_EQ(expected, record.intendedBoundaryFrame);
        EXPECT_EQ(expected - kFadeFrames, record.firstRowFrame);
        EXPECT_EQ(expected, record.lastRowFrame);
        EXPECT_EQ(play.producedPlayableInstance, record.rootPlayable);
    } else {
        EXPECT_EQ(expected, RematerializedStopSilence(engine));
        EXPECT_EQ(expected - kFadeFrames,
                  RematerializedStopFadeStart(engine));
    }
    EXPECT_TRUE(engine->playableInstances.Classify(referenceRoot).live);
    EXPECT_TRUE(engine->playableInstances.Classify(olderReferenceRoot).live);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(playFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(referenceFiring));
    EXPECT_EQ(VN_IN_USE,
              Vn_ReleaseActionFiring(olderReferenceFiring));
}

TEST(ActionFiringApi,
     DirectReferencedExitMarkerStopKeepsResolvedFrameAfterReferenceRetires) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    const std::uint64_t markerOffset =
        engine->timelinePool.WindowEndFrame() +
        4u * engine->config.blockFrames;
    std::vector<float> first(markerOffset + 4096u, 0.25f);
    std::vector<float> second(markerOffset + 4096u, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                    &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                    &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateCompositePiecePlayAction(true);
    image.pieceMarkers[0].position = static_cast<std::int64_t>(markerOffset);
    image.piece.scheduleSemanticFingerprint =
        harken::ComputePieceScheduleFingerprintV1(image.piece);
    image.queueChildren[0].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Piece, image.piece.rootDefinition.stableId,
        image.piece.scheduleSemanticFingerprint);
    image.MakeQuantizedSoundPlayAction(
        harken::ActionQuantizeTimingV1::Immediate);
    image.MakeQuantizedSoundStopAction(
        harken::ActionQuantizeTimingV1::ExitMarker,
        harken::ActionIfSilentV1::Drop, 0,
        harken::ActionTargetKindV1::Piece, 11, 15,
        harkentest::ObjectId(52), true);
    SetAbsoluteTime(&image.steps[15].fade, 10'000'000);
    image.actions[11].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[11]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto reference = harken::StartCurrentPlayableByIdentity(
        harken::PlayableKindV1::Piece, image.piece.rootDefinition.stableId, 0);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, reference.status);
    ASSERT_NE(0u, reference.instance);
    const auto referenceRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& row) {
            return row.rootInstance == reference.instance;
        });
    ASSERT_NE(engine->playableServices.end(), referenceRow);
    const std::uint64_t expected = referenceRow->startFrame + markerOffset;
    constexpr std::uint64_t kFadeFrames = 480u;

    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(playFiring, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto target =
        engine->playableInstances.Classify(play.producedPlayableInstance);
    ASSERT_TRUE(target.live);

    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[11].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_EQ(VN_ACTION_STEP_AWAITING_MATERIALIZATION, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(1u, stop.remainingPlayableCount);
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    harken::ActionDeferredRecordToken token{};
    harken::ActionDeferredRecord record{};
    harken::ActionDeferredRecordState state =
        harken::ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &token, &record, &state));
    EXPECT_EQ(expected, record.intendedBoundaryFrame);
    EXPECT_EQ(expected - kFadeFrames, record.firstRowFrame);
    EXPECT_EQ(expected, record.lastRowFrame);
    EXPECT_EQ(play.producedPlayableInstance, record.rootPlayable);
    EXPECT_EQ(target.scheduleEpoch, record.rootScheduleEpoch);

    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, reference.instance, 0));
    for (std::uint32_t block = 0;
         block < 64u &&
         engine->playableInstances.Classify(reference.instance).live;
         ++block) {
        ASSERT_LT(engine->mixer.BlocksRendered() * engine->config.blockFrames,
                  expected);
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_FALSE(engine->playableInstances.Classify(reference.instance).live);
    EXPECT_LT(engine->mixer.BlocksRendered() * engine->config.blockFrames,
              expected);
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    harken::ActionDeferredRecord retained{};
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &token, &retained, &state));
    EXPECT_EQ(expected, retained.intendedBoundaryFrame);
    EXPECT_EQ(play.producedPlayableInstance, retained.rootPlayable);
    EXPECT_EQ(target.scheduleEpoch, retained.rootScheduleEpoch);

    EXPECT_EQ(expected, DrainRematerializedStopSilence(engine));
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(playFiring));
}

