    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_EQ(VN_ACTION_STEP_SUPPRESSED, stop.state);
    EXPECT_EQ(0u, stop.capturedPlayableCount);
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
