TEST(ActionFiringApi, DeferredStopEmitterLossRetainsRecordUntilTargetGone) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(4, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    const std::uint64_t stopFrame =
        engine->timelinePool.WindowEndFrame() + engine->config.blockFrames;
    std::vector<float> samples(stopFrame + 4096u, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeDelayedSeparateSoundStopAction(
        DelayNanosecondsForTargetFrame(*engine, stopFrame));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[9].actionStableId;
    playDesc.emitter = emitter;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[8].actionStableId;
    stopDesc.emitter = emitter;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_EQ(VN_ACTION_STEP_AWAITING_MATERIALIZATION, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);

    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
    EXPECT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    const std::uint64_t afterEmitterStop = engine->commands.PublishedHead();
    DrainActionDeferred(engine);
    EXPECT_TRUE(StopCommandsSince(*engine, afterEmitterStop).empty());

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(stopFiring, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_TARGET_GONE, info.terminalReason);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_EQ(VN_ACTION_STEP_CANCELLED, stop.state);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(stopFiring));
    const VnResult playRelease = Vn_ReleaseActionFiring(playFiring);
    EXPECT_TRUE(playRelease == VN_OK || playRelease == VN_IN_USE);
}

TEST(ActionFiringApi,
     RematerializedImmediateStopKeepsAdmissionSilence) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeDelayedSeparateSoundStopAction(DelayNanosecondsForTargetFrame(
        *engine, engine->timelinePool.WindowEndFrame()));
    image.SetSeparateStopFade(10000000);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    harken::ActionDeferredRecordToken token{};
    harken::ActionDeferredRecord record{};
    harken::ActionDeferredRecordState state =
        harken::ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &token, &record, &state));
    const std::uint64_t admitted = record.intendedBoundaryFrame;
    const std::uint64_t fadeFrames =
        (10000000ull * 48000ull + 999999999ull) / 1000000000ull;
    ASSERT_NE(0u, admitted);
    const std::uint64_t rematerialized =
        DrainRematerializedStopSilence(engine);
    EXPECT_EQ(admitted, rematerialized);
    EXPECT_NE(admitted + fadeFrames, rematerialized);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(playFiring));
}

TEST(ActionFiringApi,
     RematerializedLocalStopKeepsAdmissionSilence) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.properties[0].payload.presentMask |= UINT64_C(1) << 3;
    image.properties[0].payload.values[3].bits = 0;
    image.RelinkFirstSound();
    image.MakeImmediateSoundPlayAction();
    const std::uint64_t delayed = engine->timelinePool.WindowEndFrame();
    image.MakeQuantizedSoundStopAction(
        harken::ActionQuantizeTimingV1::CurrentLoopEnd,
        harken::ActionIfSilentV1::Immediate,
        DelayNanosecondsForTargetFrame(*engine, delayed),
        harken::ActionTargetKindV1::Sound, 10, 14, harkentest::ObjectId(51));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc playDesc = ValidPostDesc();
    playDesc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&playDesc, &playFiring));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    const std::uint64_t start = engine->playableServices[0].startFrame;
    const std::uint64_t length = 4096u;
    const std::uint64_t offset = delayed > start ? delayed - start + 1u : 1u;
    const std::uint64_t expected =
        start + ((offset + length - 1u) / length) * length;
    ASSERT_GE(expected, engine->timelinePool.WindowEndFrame());
    VnPostActionDesc stopDesc = ValidPostDesc();
    stopDesc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&stopDesc, &stopFiring));
    harken::ActionDeferredRecordToken token{};
    harken::ActionDeferredRecord record{};
    harken::ActionDeferredRecordState state =
        harken::ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &token, &record, &state));
    EXPECT_EQ(expected, record.intendedBoundaryFrame);
    EXPECT_EQ(expected, DrainRematerializedStopSilence(engine));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(playFiring));
}

