TEST(ActionFiringApi, OriginalInitialFilingRetainsFactoryFutureAcrossSelectedAliasChanges) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> samples(512, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    const auto owners = CaptureActionReclaimableOwners(engine);
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    auto& row = engine.playableServices[0];
    const auto selected = static_cast<const harken::EngineQueueFutureFilingLayout&>(row);
    const auto queue = row.queueInstance;
    const auto* original = engine.OriginalQueueInitialFilingFor(row);
    ASSERT_NE(nullptr, original);
    ASSERT_TRUE(original->initialFutureBank.Valid());
    ASSERT_NE(nullptr, selected.queueSuccessorProgramBank);
    ASSERT_EQ(1u, selected.queueTransitionGroupArmCount);
    ASSERT_EQ(selected.queueConditional.version, original->initialFuture.queueConditional.version);
    const auto generation = row.invocationGeneration;
    ++row.invocationGeneration;
    EXPECT_EQ(nullptr, engine.OriginalQueueInitialFilingFor(row));
    row.invocationGeneration = generation;

    engine.nullBackend.Pump(1);
    const auto mirrorSlot = selected.queueSuccessorScheduleBase;
    const auto savedArm = engine.playableSuccessorArms[mirrorSlot];
    const auto savedRender = engine.playableSuccessorRenderHandles[mirrorSlot];
    const auto savedStart = engine.playableSuccessorStartFrames[mirrorSlot];
    const auto savedCompletion = engine.playableSuccessorCompletions[mirrorSlot];
    auto& mirror = selected.queueSuccessorProgramPlane == 0
        ? engine.playableSchedules[mirrorSlot] : engine.playableSuccessorSchedules[mirrorSlot];
    const auto savedMirror = mirror;
    harken::TimelineArmObservation acknowledged{};
    ASSERT_TRUE(engine.timelineArms.Observe(savedArm, &acknowledged));
    ASSERT_NE(0u, acknowledged.armedCompletionSequence);

    // Corrupt only public scheduling aliases. No new native capability or
    // Reset acceptance is manufactured by this negative storage test.
    row.queueDecision = {};
    row.queueConditional = {};
    row.queueSuccessorProgramBank = nullptr;
    row.queueTransitionGroupArms = {};
    row.queueTransitionGroupArmCount = 0;
    row.queueSuccessorCompletion = {};
    engine.playableSuccessorArms[mirrorSlot] = {};
    engine.playableSuccessorRenderHandles[mirrorSlot] = 0;
    engine.playableSuccessorStartFrames[mirrorSlot] = 0;
    engine.playableSuccessorCompletions[mirrorSlot] = {};
    mirror = {};
    std::size_t members = 0, programs = 0, events = 0, leaves = 0, groups = 0, holders = 0;
    const bool collected = harken::test::CollectInitialQueueTimingMembersForTest(
        engine, firing, row.startFrame + 128u, &members, &programs,
        &events, &leaves, &groups, &holders);
    EXPECT_TRUE(collected);
    EXPECT_EQ(1u, members);
    if (collected && members == 1u) {
        const auto& member = engine.initialQueueTimingMembersScratch[0];
        EXPECT_EQ(selected.queueSuccessorProgramBank, member.successorBank);
        EXPECT_EQ(selected.queueDecision.slot, member.decision.slot);
        EXPECT_EQ(selected.queueDecision.generation, member.decision.generation);
        EXPECT_EQ(selected.queueConditional.version, member.conditional.version);
        EXPECT_EQ(row.queueUnplacedGroupCount, groups);
        if (groups == 2u) {
            const auto& future = engine.initialQueueTimingGroupsScratch[1];
            EXPECT_EQ(original->initialFuture.queueTransitionGroupArms.data(), future.members);
            EXPECT_EQ(1u, future.memberCount);
            EXPECT_EQ(selected.queueTransitionGroupArms[0].generation, future.members[0].generation);
        }
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
        EXPECT_TRUE(harken::test::StageInitialQueueSuccessorMirrorsForTest(engine, firing, programs));
        auto& actualInstallation = engine.timelineVoiceInstallIdentities[savedArm.renderSlot];
        const auto actualStart = actualInstallation.onsetFrame;
        ++actualInstallation.onsetFrame;
        EXPECT_FALSE(harken::test::StageInitialQueueSuccessorMirrorsForTest(engine, firing, programs));
        actualInstallation.onsetFrame = actualStart;
        EXPECT_TRUE(harken::test::StageInitialQueueSuccessorMirrorsForTest(engine, firing, programs));
#endif
    }
    engine.ReflectOriginalQueueFiling(row);
    EXPECT_FALSE(row.queueDecision.Valid());
    EXPECT_EQ(nullptr, row.queueSuccessorProgramBank);
    EXPECT_TRUE(original->initialFutureBank.Valid());
    static_cast<harken::EngineQueueFutureFilingLayout&>(row) = selected;
    engine.playableSuccessorArms[mirrorSlot] = savedArm;
    engine.playableSuccessorRenderHandles[mirrorSlot] = savedRender;
    engine.playableSuccessorStartFrames[mirrorSlot] = savedStart;
    engine.playableSuccessorCompletions[mirrorSlot] = savedCompletion;
    mirror = savedMirror;
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    EXPECT_TRUE(row.queueDecisionCommitted);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (unsigned block = 0; block < 64; ++block) {
        engine.nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_FALSE(engine.originalQueueConditionalHolders[queue.slot].initialFutureBank.Valid());
    EXPECT_FALSE(engine.originalQueueConditionalHolders[queue.slot].initialFutureCaptured);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(post.emitter));
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(engine));
}

TEST(ActionFiringApi, PendingImmediateQueueDoesNotHoldIndependentPage) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                   candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_EQ(harken::EnginePlayableStartPhase::PendingImmediateEntry,
              row->phase);
    ASSERT_TRUE(row->queueTimingPending);
    ASSERT_TRUE(row->queueUnplacedCredit.Valid());
    ASSERT_FALSE(row->queuePreparedPages.Valid());

    const std::uint64_t independentFrame = std::max(
        engine->timelinePool.WindowStartFrame() + 2u * kBlockFrames,
        engine->timelinePool.PublishCutoffFrame() + kBlockFrames);
    ASSERT_LT(independentFrame + kBlockFrames,
              engine->timelinePool.WindowEndFrame());
    constexpr std::uint64_t kIndependentTransaction = 0x12345u;
    ASSERT_EQ(harken::ReserveStatus::Committed,
              ReserveActionPreparationTransaction(
                  *engine, kIndependentTransaction, independentFrame).status);
    std::uint32_t page = 0;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(independentFrame, &page));
    engine->timelinePool.Publish(independentFrame + kBlockFrames);
    const auto* header = engine->timelinePool.Page(page);
    ASSERT_NE(nullptr, header);
    ASSERT_TRUE(header->frozen);
    EXPECT_EQ(1u, header->committedTransactionCount);
    std::array<harken::ConsumedEvent, 1> consumed{};
    ASSERT_EQ(1u, engine->timelinePool.ConsumePageRt(
                      independentFrame / kBlockFrames,
                      consumed.data(), consumed.size()));
    EXPECT_EQ(kIndependentTransaction, consumed[0].transactionId);
}

TEST(ActionFiringApi, StartedImmediateSourceRejectsPrivateCancelAndReusesRetiredSlot) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(16384, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateVariableControlToVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));

    auto postStarted = [&](VnActionFiringHandle* firing,
                           harken::TimelineArmToken* arm,
                           OriginalSourceRetirementProof* source) {
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, firing));
        bool started = false;
        for (std::uint32_t block = 0; block < 16; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            for (std::uint32_t index = 0;
                 index < engine->sourceTerminals.Capacity(); ++index) {
                const auto* candidate = engine->sourceTerminals.At(index);
                if (!candidate->occupied ||
                    !engine->ResolveSourceResourceOwner(candidate->resourceOwner))
                    continue;
                const auto* owner = engine->ResolveSourceResourceOwner(
                    candidate->resourceOwner);
                if (!owner->InvocationValid() ||
                    owner->Invocation().actionFiring != *firing) continue;
                harken::EngineTimelineVoiceInstallIdentity install{};
                if (!engine->CaptureTimelineVoiceInstallIdentity(
                        candidate->render, &install)) continue;
                *arm = install.startArm;
                *source = CaptureOriginalSource(*engine, candidate->leaf);
                break;
            }
            harken::TimelineArmObservation observation{};
            started = arm->Valid() &&
                engine->timelineArms.Observe(*arm, &observation) &&
                observation.startedBlockSequence != 0;
            if (started) break;
        }
        ASSERT_TRUE(started);
        const auto* record = engine->sourceTerminals.Resolve(source->token);
        ASSERT_NE(nullptr, record);
        EXPECT_FALSE(engine->timelineArms.RequestCancelNeverPublished(*arm));
        EXPECT_FALSE(record->retryAfterMissedEntry);
    };

    VnActionFiringHandle first = 0;
    harken::TimelineArmToken firstArm{};
    OriginalSourceRetirementProof firstSource{};
    postStarted(&first, &firstArm, &firstSource);
    ASSERT_TRUE(firstSource.token.Valid());
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(first, 0));
    harken::SourceTerminalPayload firstCompletion{};
    for (std::uint32_t block = 0; block < 16; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (engine->sourceTerminals.Capture(
                firstSource.token, engine->mixer.BlocksRendered(),
                &firstCompletion)) break;
    }
    EXPECT_EQ(harken::SourceTerminalKind::Stop, firstCompletion.kind);
    ExpectOriginalSourceRetiresAfterLaterBlock(*engine, firstSource);
    EXPECT_EQ(nullptr, engine->sourceTerminals.Resolve(firstSource.token));
    for (std::uint32_t block = 0; block < 32 &&
         engine->playableInstances.LiveCount() != 0; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());

    VnActionFiringHandle second = 0;
    harken::TimelineArmToken secondArm{};
    OriginalSourceRetirementProof secondSource{};
    postStarted(&second, &secondArm, &secondSource);
    ASSERT_TRUE(secondSource.token.Valid());
    EXPECT_EQ(firstSource.token.slot, secondSource.token.slot);
    EXPECT_NE(firstSource.token.generation, secondSource.token.generation);
    EXPECT_EQ(nullptr, engine->sourceTerminals.Resolve(firstSource.token));
    const auto* replacement = engine->sourceTerminals.Resolve(secondSource.token);
    ASSERT_NE(nullptr, replacement);
    EXPECT_EQ(secondSource.leaf, replacement->leaf);
    EXPECT_EQ(secondSource.epoch, replacement->acceptedEpoch);
    EXPECT_TRUE(engine->voices.ReleaseObserved(firstSource.release));
    EXPECT_FALSE(engine->voices.ReleaseObserved(secondSource.release));
    EXPECT_TRUE(engine->playableInstances.Classify(secondSource.leaf).live);
    EXPECT_TRUE(engine->playableInstances.HasSourceRetirementHold(
        secondSource.leaf));
    EXPECT_FALSE(engine->timelineArms.RequestCancelNeverPublished(firstArm));
    EXPECT_NE(firstArm.generation, secondArm.generation);
    EXPECT_FALSE(replacement->retryAfterMissedEntry);
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(second, 0));
    ExpectOriginalSourceRetiresAfterLaterBlock(*engine, secondSource);
}

TEST(ActionFiringApi, PublishedNestedVariableControlStartsSoundWithNormalUpdate) {
    for (const std::uint32_t blockFrames : {64u, 256u}) {
        SCOPED_TRACE(blockFrames);
        (void)Vn_Term();
        harkentest::EngineSession session(
            harkentest::MakeNullConfig(8, blockFrames, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> samples(16384, 0.25f);
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
                .contentRevision);
        image.MakeImmediateVariableControlToVariableControlPlayAction();
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harken::InstallContainerWorldV1(*engine, image.world).status);
        auto post = ValidPostDesc();
        post.actionId = image.actions[9].actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        harken::ImmediateLaneHandle lane{};
        for (std::uint32_t index = 0;
             index < engine->immediateEntryAttemptCapacity; ++index) {
            const auto& attempt = engine->immediateEntryAttempts[index];
            if (attempt.active && attempt.root == firing) lane = attempt.lane;
        }
        std::string trace;
        bool heard = false;
        bool started = false;
        for (std::uint32_t block = 0; block < 16; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            std::string dueTrace;
            const auto quantum = engine->mixer.BlocksRendered();
            const auto* due = lane.Valid()
                ? engine->immediateActionLane.CaptureDue(lane.slot, quantum)
                : nullptr;
            if (due != nullptr) {
                dueTrace = ",due=" + std::to_string(due->quantum) + "/" +
                    std::to_string(due->eventCount) + "/" +
                    std::to_string(due->groupCount) + "/" +
                    std::to_string(due->memberCount);
                const auto* events = engine->immediateActionLane.Events(
                    lane.slot, due);
                if (events != nullptr) {
                    for (std::uint32_t index = 0;
                         index < due->eventCount; ++index) {
                        dueTrace += ",event=" +
                            std::to_string(events[index].event.executeFrame) +
                            "/" + std::to_string(events[index].event.payload) +
                            "/" + std::to_string(
                                events[index].armProgramGeneration) +
                            "/" + std::to_string(
                                events[index].event.frontier.Present());
                    }
                }
                const auto* groups = engine->immediateActionLane.Groups(
                    lane.slot, due);
                if (groups != nullptr) {
                    for (std::uint32_t index = 0;
                         index < due->groupCount; ++index) {
                        harken::Plan03PageGroupView view{};
                        const bool resolved = engine->timelinePool.
                            ResolvePlan03GroupSliceRt(groups[index].identity,
                                &view);
                        dueTrace += ",group=" +
                            std::to_string(groups[index].identity.decision.slot) +
                            "/" + std::to_string(resolved);
                        if (resolved && view.frontier != nullptr) {
                            const auto& binding = *view.frontier;
                            dueTrace += "/" + std::to_string(
                                static_cast<int>(binding.role)) +
                                "/" + std::to_string(
                                    binding.operation.owner.serviceSlot) +
                                "/" + std::to_string(
                                    binding.operation.owner.serviceGeneration) +
                                "/" + std::to_string(
                                    binding.variableSide.Valid()) +
                                "/" + std::to_string(
                                    binding.queueInitial.Valid());
                        }
                    }
                }
                ASSERT_TRUE(engine->immediateActionLane.ReleaseCapture(
                    lane.slot, due));
            }
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            const bool audible = std::any_of(output, output + blockFrames,
                [](float sample) { return sample > 0.01f; });
            heard = heard || audible;
            harken::ImmediateLaneObservation laneState{};
            const bool laneObserved = lane.Valid() &&
                engine->immediateActionLane.Observe(lane, &laneState);
            trace += "b" + std::to_string(block) + ":seq=" +
                std::to_string(engine->mixer.BlocksRendered()) +
                ",pcm=" + std::to_string(audible) +
                ",lane=" + std::to_string(laneObserved) + "/" +
                std::to_string(laneState.committed) + "/" +
                std::to_string(laneState.claimed) + "/" +
                std::to_string(laneState.applied) + "/" +
                std::to_string(laneState.missed) + "/" +
                std::to_string(laneState.cancelled) + dueTrace;
            std::uint32_t matchingSources = 0;
            for (std::uint32_t index = 0;
                 index < engine->sourceTerminals.Capacity(); ++index) {
                const auto* source = engine->sourceTerminals.At(index);
                if (!source->occupied) continue;
                const auto* owner = engine->ResolveSourceResourceOwner(
                    source->resourceOwner);
                if (owner == nullptr || !owner->InvocationValid() ||
                    owner->Invocation().actionFiring != firing) continue;
                ++matchingSources;
                harken::EngineTimelineVoiceInstallIdentity install{};
                const bool installed = engine->CaptureTimelineVoiceInstallIdentity(
                    source->render, &install);
                harken::TimelineArmObservation armState{};
                const bool armObserved = installed &&
                    engine->timelineArms.Observe(install.startArm, &armState);
                const auto* voice = engine->voices.Resolve(source->render);
                started = started || (armObserved &&
                    armState.startedBlockSequence != 0);
                trace += ",src=" + std::to_string(index) + "/" +
                    std::to_string(source->generation) + "/" +
                    std::to_string(source->render) + "/" +
                    std::to_string(source->leaf) +
                    ",owner=" + std::to_string(owner->identity.slot) + "/" +
                    std::to_string(owner->identity.generation) +
                    ",install=" + std::to_string(installed) +
                    ",arm=" + std::to_string(armObserved) + "/" +
                    std::to_string(armObserved ?
                        static_cast<int>(armState.state) : -1) + "/" +
                    std::to_string(armState.startedBlockSequence) +
                    ",cursor=" + std::to_string(voice != nullptr
                        ? voice->srcCursor : 0);
            }
            trace += ",sources=" + std::to_string(matchingSources) + ";";
            if (heard && started) break;
        }
        testing::Test::RecordProperty(
            "published_vc_trace_" + std::to_string(blockFrames), trace);
        EXPECT_TRUE(heard);
        EXPECT_TRUE(started);
    }
}

TEST(ActionFiringApi, PublishedNestedVariableControlAcceptsRandomMiddleAndSiblingOwners) {
    for (const bool siblings : {false, true}) {
        SCOPED_TRACE(siblings);
        (void)Vn_Term();
        harkentest::EngineSession session(
            harkentest::MakeNullConfig(16, 64, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> samples(16384, 0.25f);
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
                .contentRevision);
        if (siblings)
            image.MakeImmediateVariableControlWithTwoNestedSiblingsPlayAction();
        else
            image.MakeImmediateVariableControlThroughRandomToVariableControlPlayAction();
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harken::InstallContainerWorldV1(*engine, image.world).status);
        auto post = ValidPostDesc();
        post.actionId = image.actions[9].actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));

        float peak = 0.0f;
        std::uint32_t startedSources = 0;
        for (std::uint32_t block = 0; block < 16; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            for (std::uint32_t sample = 0; sample < 64; ++sample)
                peak = std::max(peak, output[sample]);
            startedSources = 0;
            for (std::uint32_t index = 0;
                 index < engine->sourceTerminals.Capacity(); ++index) {
                const auto* source = engine->sourceTerminals.At(index);
                if (!source->occupied) continue;
                const auto* owner = engine->ResolveSourceResourceOwner(
                    source->resourceOwner);
                if (owner == nullptr || !owner->InvocationValid() ||
                    owner->Invocation().actionFiring != firing) continue;
                harken::EngineTimelineVoiceInstallIdentity install{};
                harken::TimelineArmObservation arm{};
                if (engine->CaptureTimelineVoiceInstallIdentity(
                        source->render, &install) &&
                    engine->timelineArms.Observe(install.startArm, &arm) &&
                    arm.startedBlockSequence != 0)
                    ++startedSources;
            }
            if (startedSources >= (siblings ? 2u : 1u) && peak > 0.01f) break;
        }
        EXPECT_GT(peak, 0.01f);
        EXPECT_EQ(siblings ? 2u : 1u, startedSources);
    }
}

TEST(ActionFiringApi, PendingNestedQueueCancelRequiresExactSourceIdentity) {
    enum class Mismatch { Install, Cohort, Owner, Epoch, ReleaseObserver };
    for (const auto mismatch : {Mismatch::Install, Mismatch::Cohort,
                                Mismatch::Owner, Mismatch::Epoch,
                                Mismatch::ReleaseObserver}) {
        SCOPED_TRACE(static_cast<int>(mismatch));
        (void)Vn_Term();
        harkentest::EngineSession session(
            harkentest::MakeNullConfig(8, 256, 48000));
        ASSERT_EQ(VN_OK, session.InitResult());
        auto* engine = session.Engine();
        std::vector<float> samples(256, 0.25f);
        const auto pcm = harkentest::MonoDesc(samples, 48000);
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
        ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
        CanonicalActionWorld image(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
                .contentRevision,
            engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
                .contentRevision);
        image.MakeImmediateQueueNestedContainerPlayAction(false);
        std::array<harken::ContainerChildProgramViewV2, 2> innerChildren{
            image.queueChildren[1], image.queueChildren[1]};
        innerChildren[0].stableChildOrdinal = 8;
        innerChildren[1].stableChildOrdinal = 9;
        innerChildren[0].authoredStableOrder = 0;
        innerChildren[1].authoredStableOrder = 1;
        innerChildren[0].frequencyWeight = 0;
        innerChildren[1].frequencyWeight = 0;
        image.containers[0].mode = harken::ContainerModeV1::SequenceQueue;
        image.containers[0].memoryScope = harken::MemoryScopeV1::Emitter;
        image.containers[0].queueCycle = harken::QueueCycleV1::Once;
        image.containers[0].queueSplice = harken::QueueSpliceV1::Butt;
        image.containers[0].childCount = 2;
        image.containers[0].children = innerChildren.data();
        image.occurrences[0].stableOccurrenceOrdinal = 8;
        image.occurrences[0].childPlayable = innerChildren[0].playable;
        image.occurrences[0].occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
        std::vector<harken::PlayableOccurrencePropertyViewV1> occurrences(
            image.world.playableOccurrences,
            image.world.playableOccurrences + image.world.playableOccurrenceCount);
        auto secondOccurrence = image.occurrences[0];
        secondOccurrence.stableOccurrenceOrdinal = 9;
        secondOccurrence.childPlayable = innerChildren[1].playable;
        secondOccurrence.occurrenceSemanticFingerprint =
            harken::ComputePlayableOccurrenceFingerprintV1(secondOccurrence);
        occurrences.push_back(secondOccurrence);
        std::sort(occurrences.begin(), occurrences.end(),
            [](const auto& lhs, const auto& rhs) {
                return std::tuple(lhs.parentKind, lhs.parentStableId,
                                  lhs.stableOccurrenceOrdinal) <
                       std::tuple(rhs.parentKind, rhs.parentStableId,
                                  rhs.stableOccurrenceOrdinal);
            });
        image.world.playableOccurrences = occurrences.data();
        image.world.playableOccurrenceCount =
            static_cast<std::uint32_t>(occurrences.size());
        image.world.identity.runtimeSemanticFingerprint =
            harken::ComputeCurrentWorldFingerprintV4(image.world);
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
            harken::InstallContainerWorldV1(*engine, image.world).status);
        auto post = ValidPostDesc();
        post.actionId = image.actions[9].actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));

        harken::SourceTerminalRecord* source = nullptr;
        harken::EnginePlayableServiceRow* member = nullptr;
        for (std::uint32_t index = 0;
             index < engine->sourceTerminals.Capacity(); ++index) {
            auto* candidate = engine->sourceTerminals.At(index);
            if (!candidate->occupied) continue;
            auto* owner = engine->ResolveSourceResourceOwner(
                candidate->resourceOwner);
            if (owner == nullptr || !owner->queueTimingPending ||
                !owner->InvocationValid() ||
                owner->Invocation().actionFiring != firing) continue;
            source = candidate;
            member = owner;
            break;
        }
        ASSERT_NE(nullptr, source);
        ASSERT_NE(nullptr, member);
        harken::EngineTimelineVoiceInstallIdentity install{};
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(
            source->render, &install));
        ASSERT_TRUE(install.startArm.Valid());
        const auto originalRender = source->render;
        const auto originalCohort = member->pendingImmediateCohortRoot;
        const auto originalOwner = source->resourceOwner;
        const auto originalEpoch = source->acceptedEpoch;
        const auto originalRelease = source->release;
        harken::EngineTimelineVoiceInstallIdentity exact{};
        ASSERT_TRUE(engine->CapturePendingQueueSourceIdentity(*member, *source, &exact));
        switch (mismatch) {
        case Mismatch::Install:
            source->render = 0;
            break;
        case Mismatch::Cohort:
            ++member->pendingImmediateCohortRoot;
            break;
        case Mismatch::Owner:
            ++source->resourceOwner.serviceGeneration;
            break;
        case Mismatch::Epoch:
            ++source->acceptedEpoch;
            break;
        case Mismatch::ReleaseObserver:
            ++source->release.targetSequence;
            break;
        }
        EXPECT_FALSE(engine->CapturePendingQueueSourceIdentity(*member, *source, &exact));
        EXPECT_TRUE(source->occupied);
        EXPECT_FALSE(source->retryAfterMissedEntry);
        source->render = originalRender;
        member->pendingImmediateCohortRoot = originalCohort;
        source->resourceOwner = originalOwner;
        source->acceptedEpoch = originalEpoch;
        source->release = originalRelease;
        ASSERT_TRUE(engine->CapturePendingQueueSourceIdentity(*member, *source, &exact));
        EXPECT_EQ(install.startArm.slot, exact.startArm.slot);
        EXPECT_EQ(install.startArm.generation, exact.startArm.generation);
        engine->nullBackend.Pump(3);
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_TRUE(source->occupied);
        EXPECT_EQ(originalRender, source->render);
        EXPECT_FALSE(source->retryAfterMissedEntry);
    }
}

TEST(ActionFiringApi, PendingImmediateNestedQueueGatesSignalOnlyFrontier) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(256, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateQueueNestedContainerPlayAction(false);
    std::array<harken::ContainerChildProgramViewV2, 2> innerChildren{
        image.queueChildren[1], image.queueChildren[1]};
    innerChildren[0].stableChildOrdinal = 8;
    innerChildren[1].stableChildOrdinal = 9;
    innerChildren[0].authoredStableOrder = 0;
    innerChildren[1].authoredStableOrder = 1;
    innerChildren[0].frequencyWeight = 0;
    innerChildren[1].frequencyWeight = 0;
    image.containers[0].mode = harken::ContainerModeV1::SequenceQueue;
    image.containers[0].memoryScope = harken::MemoryScopeV1::Emitter;
    image.containers[0].queueCycle = harken::QueueCycleV1::Once;
    image.containers[0].queueSplice = harken::QueueSpliceV1::Butt;
    image.containers[0].childCount = 2;
    image.containers[0].children = innerChildren.data();
    image.occurrences[0].stableOccurrenceOrdinal = 8;
    image.occurrences[0].childPlayable = innerChildren[0].playable;
    image.occurrences[0].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[0]);
    std::vector<harken::PlayableOccurrencePropertyViewV1> occurrences(
        image.world.playableOccurrences,
        image.world.playableOccurrences + image.world.playableOccurrenceCount);
    auto secondOccurrence = image.occurrences[0];
    secondOccurrence.stableOccurrenceOrdinal = 9;
    secondOccurrence.childPlayable = innerChildren[1].playable;
    secondOccurrence.occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(secondOccurrence);
    occurrences.push_back(secondOccurrence);
    std::sort(occurrences.begin(), occurrences.end(),
        [](const auto& lhs, const auto& rhs) {
            return std::tuple(lhs.parentKind, lhs.parentStableId,
                              lhs.stableOccurrenceOrdinal) <
                   std::tuple(rhs.parentKind, rhs.parentStableId,
                              rhs.stableOccurrenceOrdinal);
        });
    image.world.playableOccurrences = occurrences.data();
    image.world.playableOccurrenceCount =
        static_cast<std::uint32_t>(occurrences.size());
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    std::uint32_t pendingRows = 0;
    std::uint32_t credits = 0;
    std::uint32_t queueRows = 0;
    std::uint32_t entryRows = 0;
    std::uint32_t liveRows = 0;
    for (std::uint32_t index = 0;
         index < engine->playableServices.size(); ++index) {
        const auto& row = engine->playableServices[index];
        if (row.phase != harken::EnginePlayableStartPhase::Free) ++liveRows;
        if (row.queueMode) ++queueRows;
        if (row.pendingImmediateEntry) ++entryRows;
        if (row.phase != harken::EnginePlayableStartPhase::Free)
            testing::Test::RecordProperty(
                "row_" + std::to_string(index),
                std::to_string(static_cast<int>(row.phase)) + "," +
                std::to_string(row.queueMode) + "," +
                std::to_string(row.pendingImmediateEntry) + "," +
                std::to_string(row.queueTimingPending) + "," +
                std::to_string(row.queueUnplacedCredit.Valid()) + "," +
                std::to_string(row.queueCompletionFrame) + "," +
                std::to_string(row.queueDeferredNeedsFullPreparation) + "," +
                std::to_string(row.queueSignalOnlyNoOverlap) + "," +
                std::to_string(row.queueNaturalEnd));
        if (!row.queueTimingPending) continue;
        ++pendingRows;
        if (row.queueUnplacedCredit.Valid()) ++credits;
    }
    testing::Test::RecordProperty("pending_queue_rows", pendingRows);
    testing::Test::RecordProperty("credit_holders", credits);
    testing::Test::RecordProperty("queue_rows", queueRows);
    testing::Test::RecordProperty("entry_rows", entryRows);
    testing::Test::RecordProperty("live_rows", liveRows);
    std::uint32_t initialSourceSlot = UINT32_MAX;
    std::uint32_t initialSourceGeneration = 0;
    harken::PlayableInstanceHandle initialSourceLeaf = 0;
    harken::TimelineArmToken initialSourceArm{};
    for (std::uint32_t index = 0; index < engine->sourceTerminals.Capacity(); ++index) {
        const auto* source = engine->sourceTerminals.At(index);
        if (!source->occupied) continue;
        if (engine->ResolveSourceResourceOwner(source->resourceOwner) ==
            &engine->playableServices[1]) {
            initialSourceSlot = index;
            initialSourceGeneration = source->generation;
            initialSourceLeaf = source->leaf;
            harken::EngineTimelineVoiceInstallIdentity exactInstall{};
            ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(
                source->render, &exactInstall));
            initialSourceArm = exactInstall.startArm;
            EXPECT_EQ(static_cast<std::uint32_t>(source->render),
                      initialSourceArm.renderSlot);
            EXPECT_EQ(static_cast<std::uint32_t>(source->render >> 32),
                      initialSourceArm.renderGeneration);
            EXPECT_EQ(source->release.slot, exactInstall.releaseObserver.slot);
            EXPECT_EQ(source->release.targetSequence,
                      exactInstall.releaseObserver.targetSequence);
            EXPECT_EQ(source->controller, engine->playableServices[1].rootInstance);
            EXPECT_EQ(source->acceptedEpoch,
                      engine->playableInstances.Classify(source->leaf).scheduleEpoch);
            EXPECT_EQ(source->resourceOwner.invocationGeneration,
                      engine->playableServices[1].invocationGeneration);
        }
        harken::EngineTimelineVoiceInstallIdentity install{};
        const bool installed = engine->CaptureTimelineVoiceInstallIdentity(source->render, &install);
        harken::TimelineArmObservation initialArm{};
        testing::Test::RecordProperty("source_at_post_" + std::to_string(index),
            std::to_string(source->controller) + "," +
            std::to_string(source->acceptedEpoch) + "," +
            std::to_string(engine->playableInstances.Classify(source->leaf).scheduleEpoch) + "," +
            std::to_string(installed) + "," +
            std::to_string(installed && engine->timelineArms.Observe(install.startArm, &initialArm)
                ? static_cast<int>(initialArm.state) : -1));
    }
    EXPECT_EQ(2u, queueRows);
    EXPECT_EQ(2u, entryRows);
    EXPECT_EQ(1u, pendingRows);
    EXPECT_EQ(1u, credits);
    const auto& wrapper = engine->playableServices[0];
    const auto& current = engine->playableServices[1];
    EXPECT_TRUE(wrapper.pendingImmediateEntry);
    EXPECT_FALSE(wrapper.queueTimingPending);
    EXPECT_FALSE(wrapper.queueUnplacedCredit.Valid());
    EXPECT_FALSE(wrapper.queueDecision.Valid());
    EXPECT_EQ(0u, wrapper.queueCurrentOccurrence.generation);
    EXPECT_EQ(&wrapper, engine->ResolvePlayableService(current.parentService));
    EXPECT_TRUE(current.queueTimingPending);
    EXPECT_TRUE(current.queueUnplacedCredit.Valid());
    EXPECT_TRUE(current.queueDecision.Valid());
    EXPECT_EQ(firing, current.pendingImmediateCohortRoot);
    EXPECT_EQ(wrapper.queueInitialCohortEntryFrame, current.queueInitialCohortEntryFrame);
    EXPECT_GT(current.queueCompletionFrame, current.startFrame);
    // The opaque outer Queue delegates completion; the finite inner Current owns
    // a prerequisite at entry and a distinct conditional group at completion.
    EXPECT_TRUE(wrapper.queueSignalOnlyNoOverlap);
    EXPECT_FALSE(current.queueSignalOnlyNoOverlap);
    EXPECT_TRUE(current.queueFirstContinuationLane);
    EXPECT_TRUE(harken::IsBoundKnownCompletionPredicate(current.queueCurrentCompletion));
    EXPECT_EQ(current.startFrame, current.queueCurrentCompletion.absoluteLogicalStartFrame);
    EXPECT_EQ(current.startFrame + samples.size(), current.queueCompletionFrame);
    EXPECT_EQ(current.queueCompletionFrame,
              current.queueCurrentCompletion.absoluteLogicalCompleteFrame);
    EXPECT_EQ(samples.size(), current.queueCurrentCompletion.totalLogicalOutputFrames);
    EXPECT_EQ(harken::CompletionOwnerKind::SingleQueue,
              current.queueCurrentCompletion.owner.kind);
    EXPECT_EQ(current.queueDecision.slot, current.queueCurrentCompletion.owner.singleDecision.slot);
    EXPECT_EQ(current.queueDecision.generation,
              current.queueCurrentCompletion.owner.singleDecision.generation);
    EXPECT_TRUE(current.initialQueueEntryDecision.Valid());
    EXPECT_FALSE(current.initialQueueEntryDecision.slot == current.queueDecision.slot &&
                 current.initialQueueEntryDecision.generation == current.queueDecision.generation);
    harken::QueueInstanceSnapshot innerQueue{};
    ASSERT_TRUE(engine->queueInstances.Capture(current.queueInstance, &innerQueue));
    EXPECT_EQ(current.Invocation().worldGeneration, innerQueue.world);
    EXPECT_EQ(current.rootInstance, innerQueue.rootInstance);
    EXPECT_EQ(image.containers[0].containerStableId, innerQueue.containerStableId);
    EXPECT_EQ(current.queueContainerStableId, innerQueue.containerStableId);
    EXPECT_EQ(current.queueProgramSemanticFingerprint, innerQueue.programSemanticFingerprint);
    EXPECT_EQ(innerChildren.size(), innerQueue.childCount);
    EXPECT_EQ(innerChildren[0].stableChildOrdinal, innerQueue.logicMirror.currentChildOrdinal);
    EXPECT_EQ(2u, current.queueUnplacedGroupCount);
    EXPECT_EQ(0u, current.queueUnplacedTransactionCount);
    EXPECT_EQ(2u, current.queueUnplacedDemand.groupHeaders);
    EXPECT_EQ(0u, current.queueUnplacedDemand.events);
    EXPECT_EQ(current.startFrame, current.queueUnplacedGroupFrames[0]);
    EXPECT_EQ(current.queueCompletionFrame, current.queueUnplacedGroupFrames[1]);
    EXPECT_EQ(current.queueUnplacedCredit.slot, current.queueUnplacedDemandCredit.slot);
    EXPECT_EQ(current.queueUnplacedCredit.generation, current.queueUnplacedDemandCredit.generation);
    EXPECT_EQ(current.queueUnplacedCredit.epoch, current.queueUnplacedDemandCredit.epoch);
    std::size_t sourceMemberSlot = 0;
    ASSERT_TRUE(engine->ResolvePlayableMemberSlot(current.scheduleStorageBase, &sourceMemberSlot));
    const auto* currentSource = engine->sourceTerminals.Resolve(engine->variableControlMemberCompletions[sourceMemberSlot].source);
    ASSERT_NE(nullptr, currentSource);
    EXPECT_EQ(&current, engine->ResolveSourceResourceOwner(currentSource->resourceOwner));
    EXPECT_EQ(initialSourceSlot, engine->variableControlMemberCompletions[sourceMemberSlot].source.slot);
    EXPECT_EQ(initialSourceGeneration, engine->variableControlMemberCompletions[sourceMemberSlot].source.generation);
    ASSERT_NE(UINT32_MAX, initialSourceSlot);
    ASSERT_TRUE(initialSourceArm.Valid());
    EXPECT_EQ(current.queueCurrentOccurrence.slot, current.queueCurrentCompletion.occurrence.slot);
    EXPECT_EQ(current.queueCurrentOccurrence.generation,
              current.queueCurrentCompletion.occurrence.generation);
    EXPECT_EQ(initialSourceArm.renderGeneration, current.queueCurrentCompletion.renderGeneration);
    EXPECT_EQ(initialSourceLeaf, currentSource->leaf);
    harken::CompletionOwnerRef nativeCurrentOwner{};
    ASSERT_TRUE(engine->timelineOccurrences.CaptureCompletionOwner(
        current.queueCurrentOccurrence, &nativeCurrentOwner));
    EXPECT_TRUE(harken::SameCompletionOwner(current.queueCurrentCompletion.owner, nativeCurrentOwner));
    engine->nullBackend.Pump(3);
    const auto* delayedOutput = engine->nullBackend.LastBlock();
    ASSERT_NE(nullptr, delayedOutput);
    for (std::uint32_t sample = 0; sample < engine->nullBackend.BlockFrames() * engine->nullBackend.Channels(); ++sample)
        EXPECT_FLOAT_EQ(0.0f, delayedOutput[sample]);
    harken::TimelineArmObservation beforeUpdate{};
    ASSERT_TRUE(engine->timelineArms.Observe(initialSourceArm, &beforeUpdate));
    ASSERT_EQ(0u, beforeUpdate.startedBlockSequence);
    bool cancelCalled = false;
    engine->timelineArms.SetNeverPublishedCancelHookForTests(+[](void* context) {
        *static_cast<bool*>(context) = true;
    }, &cancelCalled);
    struct CancelHookReset {
        harken::Engine& engine;
        ~CancelHookReset() { engine.timelineArms.SetNeverPublishedCancelHookForTests(nullptr, nullptr); }
    } cancelHookReset{*engine};
    bool heardOriginal = false;
    bool observedOriginalStart = false;
    bool observedSourceReleaseFence = false;
    std::uint64_t sourceReleaseSeenAt = 0;
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (block == 0) {
            engine->timelineArms.SetNeverPublishedCancelHookForTests(nullptr, nullptr);
            EXPECT_FALSE(cancelCalled);
            const auto* exactSource = engine->sourceTerminals.At(initialSourceSlot);
            ASSERT_TRUE(exactSource->occupied);
            EXPECT_FALSE(exactSource->retryAfterMissedEntry);
        }
        const auto* initialSource = engine->sourceTerminals.At(initialSourceSlot);
        if (initialSource->occupied &&
            initialSource->generation == initialSourceGeneration &&
            initialSource->releaseSeen) {
            observedSourceReleaseFence = true;
            sourceReleaseSeenAt = initialSource->releaseSeenAt;
            EXPECT_TRUE(engine->playableInstances.HasSourceRetirementHold(
                initialSourceLeaf));
        } else if (!initialSource->occupied && observedSourceReleaseFence) {
            EXPECT_GT(engine->mixer.BlocksRendered(), sourceReleaseSeenAt);
        }
        std::string sourceSlots;
        for (std::uint32_t index = 0; index < engine->sourceTerminals.Capacity(); ++index) {
            const auto* source = engine->sourceTerminals.At(index);
            if (!source->occupied) continue;
            EXPECT_EQ(initialSourceSlot, index);
            EXPECT_EQ(initialSourceGeneration, source->generation);
            sourceSlots += std::to_string(index) + ",";
        }
        testing::Test::RecordProperty("source_slots_update_" + std::to_string(block),
            sourceSlots + "/" +
            std::to_string(static_cast<int>(engine->playableServices[0].phase)) + "," +
            std::to_string(static_cast<int>(engine->playableServices[1].phase)) + "," +
            std::to_string(engine->playableServices[1].queueTimingPending));
        const auto before = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        ASSERT_EQ(before + 1u, engine->mixer.BlocksRendered());
        const auto* output = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        heardOriginal |= std::any_of(output, output + engine->nullBackend.BlockFrames() * engine->nullBackend.Channels(),
            [](float sample) { return sample > 0.01f; });
        harken::TimelineArmObservation started{};
        if (engine->timelineArms.Observe(initialSourceArm, &started) && started.startedBlockSequence != 0) {
            observedOriginalStart = true;
            EXPECT_GT(started.startedBlockSequence, 3u);
        }
    }
    EXPECT_TRUE(heardOriginal);
    EXPECT_TRUE(observedOriginalStart);
    EXPECT_TRUE(observedSourceReleaseFence);
    std::uint32_t remainingGates = 0;
    std::uint32_t remainingRows = 0;
    for (const auto& row : engine->playableServices) {
        if (row.phase == harken::EnginePlayableStartPhase::Free ||
            !row.InvocationValid() ||
            row.Invocation().actionFiring != firing) continue;
        ++remainingRows;
        remainingGates += row.queueTimingPending ? 1u : 0u;
    }
    testing::Test::RecordProperty("rows_after_update", remainingRows);
    testing::Test::RecordProperty("gates_after_update", remainingGates);
    if (engine->playableServices[0].InvocationValid()) {
        const auto& root = engine->playableServices[0];
        testing::Test::RecordProperty("root_after_update",
            std::to_string(static_cast<int>(root.phase)) + "," +
            std::to_string(root.pendingImmediateEntry) + "," +
            std::to_string(root.Invocation().actionTerminalResult) + "," +
            std::to_string(static_cast<int>(root.controlReason)));
    }
    EXPECT_EQ(0u, remainingGates);
    for (std::uint32_t block = 0; block < 128 &&
         engine->playableInstances.LiveCount() != 0; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    testing::Test::RecordProperty("playables_after_reclaim",
                                  engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    for (std::uint32_t index = 0; index < engine->sourceTerminals.Capacity(); ++index)
        EXPECT_FALSE(engine->sourceTerminals.At(index)->occupied);
    EXPECT_EQ(initialSourceGeneration + 1u,
              engine->sourceTerminals.At(initialSourceSlot)->generation);
    for (std::uint32_t index = 0; index < engine->sourceTerminals.Capacity(); ++index) {
        const auto* source = engine->sourceTerminals.At(index);
        if (!source->occupied) continue;
        harken::EngineTimelineVoiceInstallIdentity install{};
        const bool installed = engine->CaptureTimelineVoiceInstallIdentity(source->render, &install);
        harken::TimelineArmObservation sourceArm{};
        const bool sourceArmLive = installed && engine->timelineArms.Observe(install.startArm, &sourceArm);
        testing::Test::RecordProperty("source_after_reclaim_" + std::to_string(index),
            std::to_string(source->leaf) + "," +
            std::to_string(source->render) + "," +
            std::to_string(source->controller) + "," +
            std::to_string(source->retryAfterMissedEntry) + "," +
            std::to_string(source->releaseSeen) + "," +
            std::to_string(engine->voices.ReleaseObserved(source->release)) + "," +
            std::to_string(source->resourceOwner.serviceSlot) + "," +
            std::to_string(source->resourceOwner.instance) + "," +
            std::to_string(engine->voices.Resolve(source->render) != nullptr) + "," +
            std::to_string(installed) + "," +
            std::to_string(sourceArmLive ? static_cast<int>(sourceArm.state) : -1) + "," +
            std::to_string(installed && install.releaseObserver.slot == source->release.slot &&
                           install.releaseObserver.targetSequence == source->release.targetSequence) + "," +
            std::to_string(engine->ResolveSourceResourceOwner(source->resourceOwner) ==
                           &engine->playableServices[source->resourceOwner.serviceSlot]));
    }
    for (std::uint32_t index = 0;
         index < engine->playableServices.size(); ++index) {
        const auto& row = engine->playableServices[index];
        if (row.phase == harken::EnginePlayableStartPhase::Free ||
            !row.InvocationValid() ||
            row.Invocation().actionFiring != firing) continue;
        testing::Test::RecordProperty(
            "row_after_reclaim_" + std::to_string(index),
            std::to_string(static_cast<int>(row.phase)) + "," +
            std::to_string(row.queueTimingPending) + "," +
            std::to_string(row.queueUnplacedCredit.Valid()) + "," +
            std::to_string(row.ownerInstance) + "," +
            std::to_string(row.renderHandle) + "," +
            std::to_string(engine->voices.Resolve(row.renderHandle) != nullptr));
        testing::Test::RecordProperty(
            "row_lifecycle_after_reclaim_" + std::to_string(index),
            std::to_string(static_cast<int>(row.controlLifecycle)) + "," +
            std::to_string(row.terminalObserved) + "," +
            std::to_string(row.queueNaturalEnd) + "," +
            std::to_string(row.queueInstance.Valid()) + "," +
            std::to_string(row.queueCurrentOccurrence.generation) + "," +
            std::to_string(row.queueRetiringOccurrence.generation) + "," +
            std::to_string(row.partitionRetiring) + "," +
            std::to_string(row.frontierChildService.Valid()) + "," +
            std::to_string(row.queueCleanupStarted) + "," +
            std::to_string(engine->playableInstances.HasSourceRetirementHold(row.rootInstance)) + "," +
            std::to_string(engine->playableInstances.FirstChild(row.rootInstance)) + "," +
            std::to_string(engine->playableInstances.HasSourceRetirementHold(
                engine->playableInstances.FirstChild(row.rootInstance))) + "," +
            std::to_string(row.scheduleLeafCount) + "," +
            std::to_string(row.queueSourceArm.Valid()) + "," +
            std::to_string(row.queueCurrentScheduleLeafCount) + "," +
            std::to_string(row.queueCurrentScheduleBase));
        harken::TimelineArmObservation observation{};
        if (engine->timelineArms.Observe(row.arm, &observation))
            testing::Test::RecordProperty(
                "arm_after_reclaim_" + std::to_string(index),
                std::to_string(static_cast<int>(observation.state)) + "," +
                std::to_string(observation.startedBlockSequence) + "," +
                std::to_string(observation.logicalCompletionSequence));
    }
    VnActionFiringInfo completed{};
    completed.structSize = sizeof(completed);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &completed));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, completed.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, completed.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, completed.terminalReason);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(post.emitter));

}

void ExpectTwoContinuousVariableControlQueuesReserveBothContinuations(
    bool cancelOneSuccessor) {
    SCOPED_TRACE(cancelOneSuccessor);
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(16, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateNestedQueueVariableControlPlayAction();
    image.variableControlChildren[1].playable =
        image.variableControlChildren[0].playable;
    image.occurrences[5].childPlayable =
        image.variableControlChildren[1].playable;
    image.occurrences[5].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[5]);
    image.containers[3].childCount = 2;
    image.containers[3].discreteAxisCount = 0;
    image.containers[3].discreteAxes = nullptr;
    image.containers[3].discreteRowCount = 0;
    image.containers[3].discreteRows = nullptr;
    image.variableControlContinuousAxis = {0, 0, image.variables[3].variableId};
    for (std::uint32_t index = 0; index < 2; ++index) {
        auto& cell = image.variableControlOverlayCells[index];
        cell.kind = harken::ContinuousCellKindV1::Interval;
        cell.lower = 0.0f;
        cell.upper = 8.0f;
        cell.lowerInclusive = 1;
        cell.upperInclusive = 1;
        auto& row = image.variableControlOverlayRows[index];
        row.stableRowOrdinal = index + 3u;
        row.authoredStableOrder = index;
        row.childStableOrdinal =
            image.variableControlChildren[index].stableChildOrdinal;
        row.cellCount = 1;
        row.cells = &cell;
    }
    image.containers[3].continuousAxisCount = 1;
    image.containers[3].continuousAxes = &image.variableControlContinuousAxis;
    image.containers[3].continuousRowCount = 2;
    image.containers[3].continuousRows = image.variableControlOverlayRows;
    image.containers[3].evaluationPeriodFrames = 64;
    image.containers[3].maxActiveRows = 2;
    image.containers[3].maxLiveRows = 2;
    image.world.playableOccurrenceCount = 6;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    ASSERT_GE(engine->config.maxPlan03GroupHeadersPerPage, 4u);
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    std::array<const harken::EnginePlayableServiceRow*, 2> queues{};
    std::uint32_t count = 0;
    for (const auto& row : engine->playableServices) {
        if (row.pendingImmediateCohortRoot != firing || !row.queueMode) continue;
        if (count < queues.size()) queues[count] = &row;
        ++count;
    }
    ASSERT_EQ(2u, count);
    ASSERT_NE(nullptr, queues[0]);
    ASSERT_NE(nullptr, queues[1]);
    EXPECT_TRUE(queues[0]->queueFirstContinuationLane);
    EXPECT_TRUE(queues[1]->queueFirstContinuationLane);
    EXPECT_NE(queues[0]->identity.slot, queues[1]->identity.slot);
    EXPECT_NE(queues[0]->queueInstance.slot, queues[1]->queueInstance.slot);
    EXPECT_EQ(2u, queues[0]->queueUnplacedGroupCount);
    EXPECT_EQ(2u, queues[1]->queueUnplacedGroupCount);
    const std::array<harken::QueueInstanceToken, 2> queueTokens{
        queues[0]->queueInstance, queues[1]->queueInstance};
    const auto attempted = std::find_if(
        engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() +
            engine->immediateEntryAttemptCapacity,
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.get() +
                  engine->immediateEntryAttemptCapacity, attempted);
    bool sawCommitted = false;
    std::array<float, 16> blockMean{};
    for (std::uint32_t update = 0; update < blockMean.size(); ++update) {
        engine->nullBackend.Pump(1);
        float sum = 0.0f;
        const auto samples = engine->nullBackend.BlockFrames() *
            engine->nullBackend.Channels();
        for (std::uint32_t sample = 0; sample < samples; ++sample)
            sum += engine->nullBackend.LastBlock()[sample];
        blockMean[update] = sum / samples;
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::ImmediateLaneObservation observation{};
        const bool observed = attempted->lane.Valid() &&
            engine->immediateActionLane.Observe(
                attempted->lane, &observation);
        sawCommitted = sawCommitted ||
            (observed && observation.committed);
        harken::QueueInstanceSnapshot firstQueue{};
        harken::QueueInstanceSnapshot secondQueue{};
        const bool firstCaptured = engine->queueInstances.Capture(
            queues[0]->queueInstance, &firstQueue);
        const bool secondCaptured = engine->queueInstances.Capture(
            queues[1]->queueInstance, &secondQueue);
        if (update == 5) {
            ASSERT_TRUE(firstCaptured);
            ASSERT_TRUE(secondCaptured);
            EXPECT_EQ(6u, firstQueue.initialActivationSequence);
            EXPECT_EQ(6u, secondQueue.initialActivationSequence);
            if (cancelOneSuccessor)
                EXPECT_TRUE(engine->decisions.TryInvalidatePending(
                    queues[0]->queueDecision));
        }
        if (update >= 5) {
            std::uint32_t recordIndex = attempted->queueContinuationHead;
            for (std::uint32_t child = 0;
                 child < attempted->queueContinuationCount &&
                 recordIndex < engine->queueContinuationRecords.size();
                 ++child) {
                const auto& record = engine->queueContinuationRecords[recordIndex];
                harken::FrontierActivationReceipt receipt{};
                auto* activation = engine->decisions.ResolveFrontierActivation(
                    record.coordinator);
                const auto read = activation == nullptr ?
                    harken::FrontierReceiptRead::InFlight :
                    activation->Read(record.descriptor.entry,
                        engine->mixer.BlocksRendered(), &receipt);
                if (update == 6) {
                    EXPECT_EQ(harken::FrontierReceiptRead::Ready, read);
                    EXPECT_EQ(cancelOneSuccessor ?
                            harken::FrontierReceiptOutcome::DefinitivelyNotApplied :
                            harken::FrontierReceiptOutcome::Applied,
                        receipt.outcome);
                    if (!cancelOneSuccessor)
                        EXPECT_EQ(harken::FrontierReceiptReason::None,
                            receipt.reason);
                }
                recordIndex = record.next;
            }
        }
    }
    EXPECT_TRUE(sawCommitted);
    EXPECT_NEAR(0.5f, blockMean[5], 1e-4f);
    EXPECT_NEAR(cancelOneSuccessor ? 0.0f : -0.5f,
        blockMean[6], 1e-4f);
    EXPECT_NEAR(cancelOneSuccessor ? 0.0f : -0.5f,
        blockMean[7], 1e-4f);
    EXPECT_FALSE(attempted->active);
    EXPECT_EQ(0u, attempted->queueContinuationCount);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    harken::QueueInstanceSnapshot retired{};
    EXPECT_FALSE(engine->queueInstances.Capture(queueTokens[0], &retired));
    EXPECT_FALSE(engine->queueInstances.Capture(queueTokens[1], &retired));
    EXPECT_FALSE(engine->runtimeRecreateRequired);

}

TEST(ActionFiringApi, TwoContinuousVariableControlQueuesReserveBothContinuations) {
    ExpectTwoContinuousVariableControlQueuesReserveBothContinuations(false);
}

TEST(ActionFiringApi, TwoContinuousVariableControlQueueSuccessorFailureIsAtomic) {
    ExpectTwoContinuousVariableControlQueuesReserveBothContinuations(true);
}

TEST(ActionFiringApi, TwoContinuousVariableControlQueueBranchesShareInitialCohort) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(16, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(256, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateNestedQueueVariableControlPlayAction();
    image.variableControlChildren[1].playable =
        image.variableControlChildren[0].playable;
    image.occurrences[5].childPlayable =
        image.variableControlChildren[1].playable;
    image.occurrences[5].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[5]);
    image.containers[3].childCount = 2;
    image.containers[3].discreteAxisCount = 0;
    image.containers[3].discreteAxes = nullptr;
    image.containers[3].discreteRowCount = 0;
    image.containers[3].discreteRows = nullptr;
    image.variableControlContinuousAxis =
        {0, 0, image.variables[3].variableId};
    for (std::uint32_t index = 0; index < 2; ++index) {
        auto& cell = image.variableControlOverlayCells[index];
        cell.kind = harken::ContinuousCellKindV1::Interval;
        cell.lower = 0.0f;
        cell.upper = 8.0f;
        cell.lowerInclusive = 1;
        cell.upperInclusive = 1;
        auto& row = image.variableControlOverlayRows[index];
        row.stableRowOrdinal = index + 3u;
        row.authoredStableOrder = index;
        row.childStableOrdinal =
            image.variableControlChildren[index].stableChildOrdinal;
        row.cellCount = 1;
        row.cells = &cell;
    }
    image.containers[3].continuousAxisCount = 1;
    image.containers[3].continuousAxes =
        &image.variableControlContinuousAxis;
    image.containers[3].continuousRowCount = 2;
    image.containers[3].continuousRows = image.variableControlOverlayRows;
    image.containers[3].evaluationPeriodFrames = 64;
    image.containers[3].maxActiveRows = 2;
    image.containers[3].maxLiveRows = 2;
    image.world.playableOccurrenceCount = 6;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    const auto decisionBaseline = engine->decisions.LiveCount();
    engine->forceImmediateLaneReservationFailureForTest = true;
    VnActionFiringHandle refused = 0;
    ASSERT_EQ(VN_BACKPRESSURE, Vn_PostAction(&post, &refused));
    EXPECT_EQ(0u, refused);
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->initialQueueEntryDecisionOwnerCount);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    std::uint32_t queueRows = 0;
    std::uint32_t credits = 0;
    std::uint32_t pendingRows = 0;
    const harken::EnginePlayableServiceRow* root = nullptr;
    std::array<const harken::EnginePlayableServiceRow*, 2> queues{};
    for (const auto& row : engine->playableServices) {
        if (!row.InvocationValid() ||
            row.Invocation().actionFiring != firing) continue;
        if (row.pendingImmediateEntry) {
            ++pendingRows;
            root = &row;
        }
        if (!row.queueMode) continue;
        if (queueRows < queues.size()) queues[queueRows] = &row;
        ++queueRows;
        if (row.queueUnplacedCredit.Valid()) ++credits;
    }
    ASSERT_EQ(2u, queueRows);
    ASSERT_EQ(1u, pendingRows);
    ASSERT_NE(nullptr, root);
    ASSERT_NE(nullptr, queues[0]);
    ASSERT_NE(nullptr, queues[1]);
    EXPECT_NE(queues[0]->identity.slot, queues[1]->identity.slot);
    EXPECT_EQ(2u, credits);
    for (const auto* queue : queues) {
        EXPECT_TRUE(queue->queueTimingPending);
        EXPECT_TRUE(queue->queueDecision.Valid());
        EXPECT_TRUE(queue->initialQueueEntryDecision.Valid());
        EXPECT_NE(queue->queueDecision.slot,
                  queue->initialQueueEntryDecision.slot);
        EXPECT_NE(0u, queue->initialQueueEntryAttemptGeneration);
        EXPECT_TRUE(queue->queueUnplacedCredit.Valid());
        EXPECT_EQ(1u, queue->queueUnplacedTransactionCount);
        EXPECT_TRUE(queue->queueFirstContinuationLane);
        EXPECT_EQ(2u, queue->queueUnplacedGroupCount);
        EXPECT_EQ(2u, queue->queueUnplacedDemand.groupHeaders);
        EXPECT_EQ(queue->queueInitialCohortEntryFrame, queue->queueUnplacedGroupFrames[0]);
        EXPECT_EQ(queue->queueCompletionFrame, queue->queueUnplacedGroupFrames[1]);
        EXPECT_EQ(firing, queue->pendingImmediateCohortRoot);
        EXPECT_EQ(root->invocation, queue->invocation);
        EXPECT_EQ(root->invocationGeneration, queue->invocationGeneration);
        EXPECT_EQ(root->queueInitialCohortEntryFrame,
                  queue->queueInitialCohortEntryFrame);
    }
    const auto rootAttempts = std::count_if(
        engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() +
            engine->immediateEntryAttemptCapacity,
        [firing](const auto& attempt) {
            return attempt.active && attempt.root == firing &&
                   attempt.lane.Valid();
        });
    EXPECT_EQ(1, rootAttempts);
    const auto attempt = std::find_if(
        engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() +
            engine->immediateEntryAttemptCapacity,
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing &&
                   candidate.lane.Valid();
        });
    ASSERT_NE(engine->immediateEntryAttempts.get() +
                  engine->immediateEntryAttemptCapacity, attempt);
    EXPECT_NE(queues[0]->initialQueueEntryDecision.slot,
              queues[1]->initialQueueEntryDecision.slot);
    EXPECT_EQ(attempt->generation,
              queues[0]->initialQueueEntryAttemptGeneration);
    EXPECT_EQ(attempt->generation,
              queues[1]->initialQueueEntryAttemptGeneration);
    EXPECT_EQ(root->identity, attempt->initialService);
    EXPECT_EQ(root->invocationGeneration,
              attempt->initialInvocationGeneration);
    EXPECT_EQ(root->queueInitialCohortEntryFrame,
              attempt->initialEntryFrame);
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 16> groups{};
    const auto groupCount = engine->timelinePool.
        CaptureImmediateLaneCohortGroups(
            firing, groups.data(), groups.size());
    ASSERT_GT(groupCount, 0u);
    ASSERT_LE(groupCount, groups.size());
    const auto identity = groups[0].identity;
    EXPECT_FALSE(engine->timelinePool.BindImmediateLaneGroupOwner(
        identity, engine->immediateActionLane, firing + 1u,
        attempt->lane.slot, attempt->lane.generation));
    EXPECT_FALSE(engine->timelinePool.BindImmediateLaneGroupOwner(
        identity, engine->immediateActionLane, firing,
        attempt->lane.slot, attempt->lane.generation + 1u));
    auto stale = identity;
    ++stale.rowClaimGeneration;
    EXPECT_FALSE(engine->timelinePool.BindImmediateLaneGroupOwner(
        stale, engine->immediateActionLane, firing,
        attempt->lane.slot, attempt->lane.generation));
    auto malformed = identity;
    malformed.absoluteQuantum = 1;
    EXPECT_FALSE(engine->timelinePool.BindImmediateLaneGroupOwner(
        malformed, engine->immediateActionLane, firing,
        attempt->lane.slot, attempt->lane.generation));
    malformed = identity;
    malformed.pageGeneration = 2;
    EXPECT_FALSE(engine->timelinePool.BindImmediateLaneGroupOwner(
        malformed, engine->immediateActionLane, firing,
        attempt->lane.slot, attempt->lane.generation));
    ASSERT_TRUE(engine->timelinePool.BindImmediateLaneGroupOwner(
        identity, engine->immediateActionLane, firing,
        attempt->lane.slot, attempt->lane.generation));
    EXPECT_FALSE(engine->timelinePool.BindImmediateLaneGroupOwner(
        identity, engine->immediateActionLane, firing,
        attempt->lane.slot, attempt->lane.generation));
    harken::Plan03PageGroupView audioView{};
    EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceRt(
        identity, &audioView));
    ASSERT_EQ(groupCount, engine->timelinePool.
        CaptureImmediateLaneCohortGroups(
            firing, groups.data(), groups.size()));
    EXPECT_EQ(attempt->lane.slot, groups[0].laneSlot);
    EXPECT_EQ(attempt->lane.generation, groups[0].laneGeneration);
    for (std::size_t group = 1; group < groupCount; ++group)
        ASSERT_TRUE(engine->timelinePool.BindImmediateLaneGroupOwner(
            groups[group].identity, engine->immediateActionLane, firing,
            attempt->lane.slot, attempt->lane.generation));
    ASSERT_TRUE(engine->timelinePool.RebaseImmediateLaneGroups(
        firing, attempt->initialEntryFrame));
    ASSERT_EQ(groupCount, engine->timelinePool.
        CaptureImmediateLaneCohortGroups(
            firing, groups.data(), groups.size()));
    for (std::size_t group = 0; group < groupCount; ++group) {
        EXPECT_EQ(attempt->lane.slot, groups[group].laneSlot);
        EXPECT_EQ(attempt->lane.generation, groups[group].laneGeneration);
        EXPECT_NE(UINT64_MAX, groups[group].dueQuantum);
    }
    EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceRt(
        identity, &audioView));
    ASSERT_TRUE(engine->immediateActionLane.Cancel(attempt->lane));
    EXPECT_FALSE(engine->immediateActionLane.OwnsPrivate(
        attempt->lane, firing));
    EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceRt(
        identity, &audioView));
    const auto decisionsBeforePartialTransfer =
        engine->decisions.LiveCount();
    engine->forceInitialQueueEntryTransferFailureAfterForTest = 1;
    VnActionFiringHandle partial = 0;
    EXPECT_EQ(VN_OK, Vn_PostAction(&post, &partial));
    EXPECT_EQ(0u,
        engine->forceInitialQueueEntryTransferFailureAfterForTest);
    EXPECT_EQ(0u, engine->initialQueueEntryDecisionOwnerCount);
    EXPECT_EQ(decisionsBeforePartialTransfer,
              engine->decisions.LiveCount());
}

TEST(ActionFiringApi,
     TwoContinuousVariableControlQueuesRejectPartialGroupCredit) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(16, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(256, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateNestedQueueVariableControlPlayAction();
    image.variableControlChildren[1].playable =
        image.variableControlChildren[0].playable;
    image.occurrences[5].childPlayable =
        image.variableControlChildren[1].playable;
    image.occurrences[5].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[5]);
    image.containers[3].childCount = 2;
    image.containers[3].discreteAxisCount = 0;
    image.containers[3].discreteAxes = nullptr;
    image.containers[3].discreteRowCount = 0;
    image.containers[3].discreteRows = nullptr;
    image.variableControlContinuousAxis =
        {0, 0, image.variables[3].variableId};
    for (std::uint32_t index = 0; index < 2; ++index) {
        auto& cell = image.variableControlOverlayCells[index];
        cell.kind = harken::ContinuousCellKindV1::Interval;
        cell.lower = 0.0f;
        cell.upper = 8.0f;
        cell.lowerInclusive = 1;
        cell.upperInclusive = 1;
        auto& row = image.variableControlOverlayRows[index];
        row.stableRowOrdinal = index + 3u;
        row.authoredStableOrder = index;
        row.childStableOrdinal =
            image.variableControlChildren[index].stableChildOrdinal;
        row.cellCount = 1;
        row.cells = &cell;
    }
    image.containers[3].continuousAxisCount = 1;
    image.containers[3].continuousAxes =
        &image.variableControlContinuousAxis;
    image.containers[3].continuousRowCount = 2;
    image.containers[3].continuousRows = image.variableControlOverlayRows;
    image.containers[3].evaluationPeriodFrames = 64;
    image.containers[3].maxActiveRows = 2;
    image.containers[3].maxLiveRows = 2;
    image.world.playableOccurrenceCount = 6;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);

    harken::UnplacedBatchCreditRequest groupDemand{};
    groupDemand.groupHeaders = 1;
    std::vector<harken::UnplacedBatchCredit> externalCredits;
    for (;;) {
        harken::UnplacedBatchCredit credit{};
        if (!engine->timelinePool.ReserveUnplacedBatchCredit(
                groupDemand, &credit)) break;
        externalCredits.push_back(credit);
    }
    ASSERT_GT(externalCredits.size(), 1u);
    const auto availableSlot = externalCredits[externalCredits.size() - 2u].slot;
    const auto lastExternalGeneration = externalCredits[externalCredits.size() - 2u].generation;
    // The first holder needs its coordinator and conditional group headers.
    for (unsigned released = 0; released < 2u; ++released) {
        ASSERT_TRUE(engine->timelinePool.CancelUnplacedBatchCredit(
            &externalCredits.back()));
        externalCredits.pop_back();
    }
    for (const auto& credit : externalCredits)
        EXPECT_NE(availableSlot, credit.slot);
    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto decisionBaseline = engine->decisions.LiveCount();
    const auto armBaseline = engine->timelineArms.LiveCount();
    const auto firingBaseline = engine->actionFirings.LiveCount();
    const auto serviceBaseline = std::count_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [](const auto& service) {
            return service.phase != harken::EnginePlayableStartPhase::Free;
        });
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&post.emitter));
    VnActionFiringHandle rejected = 0;
    const auto result = Vn_PostAction(&post, &rejected);
    testing::Test::RecordProperty("constrained_result", result);
    testing::Test::RecordProperty("constrained_firing", rejected);
    EXPECT_EQ(VN_BACKPRESSURE, result);
    EXPECT_EQ(0u, rejected);
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(firingBaseline, engine->actionFirings.LiveCount());
    EXPECT_EQ(serviceBaseline, std::count_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [](const auto& service) {
            return service.phase != harken::EnginePlayableStartPhase::Free;
        }));
    EXPECT_EQ(0, std::count_if(engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() +
            engine->immediateEntryAttemptCapacity,
        [](const auto& attempt) { return attempt.active; }));
    harken::UnplacedBatchCredit rollbackProbe{};
    ASSERT_TRUE(engine->timelinePool.ReserveUnplacedBatchCredit(
        groupDemand, &rollbackProbe));
    EXPECT_EQ(availableSlot, rollbackProbe.slot);
    EXPECT_GT(rollbackProbe.generation,
              lastExternalGeneration + 1u);
    ASSERT_TRUE(engine->timelinePool.CancelUnplacedBatchCredit(
        &rollbackProbe));
    for (auto& credit : externalCredits)
        ASSERT_TRUE(engine->timelinePool.CancelUnplacedBatchCredit(&credit));
    VnActionFiringHandle replay = 0;
    EXPECT_EQ(VN_OK, Vn_PostAction(&post, &replay));
    EXPECT_NE(0u, replay);
}

TEST(ActionFiringApi,
     DelayedRandomContainerPlayRetainsItsAdmissionSeedAtMaterialization) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(2, 256, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateRandomContainerPlayAction();
    image.DelayCurrentSinglePlayAction(DelayNanosecondsForTargetFrame(
        *engine, engine->timelinePool.WindowEndFrame()));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.callerSeed = 12345;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    DrainActionDeferred(engine);

    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(VN_OK, step.result);
    EXPECT_NE(0u, step.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == step.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto root = engine->playableInstances.Classify(row->rootInstance);
    ASSERT_TRUE(root.live);
    EXPECT_EQ(harken::PlayableKind::Container, root.kind);
    EXPECT_EQ(0u, root.parent);
    ASSERT_NE(0u, root.firstChild);
    const auto leaf = engine->playableInstances.Classify(root.firstChild);
    ASSERT_TRUE(leaf.live);
    EXPECT_EQ(harken::PlayableKind::Sound, leaf.kind);
    EXPECT_EQ(row->rootInstance, leaf.parent);

    harken::PlayableRootMetadata metadata{};
    ASSERT_TRUE(engine->playableInstances.CaptureRootMetadata(
        row->rootInstance, &metadata));
    EXPECT_EQ(harken::PlayableKind::Container, metadata.definitionKind);
    EXPECT_EQ(image.containers[0].containerStableId,
              metadata.definitionStableId);
    EXPECT_EQ(image.containers[0].programSemanticFingerprint,
              metadata.programSemanticFingerprint);

    harken::ContainerPlaybackRow containerRow{};
    ASSERT_TRUE(engine->containerPlayback.Capture(row->rootInstance,
                                                  &containerRow));
    EXPECT_EQ(row->rootInstance, containerRow.instance);
    EXPECT_EQ(image.containers[0].containerStableId,
              containerRow.containerStableId);
    EXPECT_EQ(2u, engine->playableInstances.LiveCount());
    EXPECT_EQ(1u, engine->containerPlayback.LiveCount());
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi,
     ImmediateNestedContainerPlayBuildsAndReclaimsSharedTree) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(64, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));

    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateNestedContainerPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto voiceBaseline = engine->voices.ActiveCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    ASSERT_EQ(VN_OK, play.result);
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto root = engine->playableInstances.Classify(row->rootInstance);
    ASSERT_TRUE(root.live);
    EXPECT_EQ(harken::PlayableKind::Container, root.kind);
    EXPECT_EQ(0u, root.parent);
    ASSERT_NE(0u, root.firstChild);
    const auto inner = engine->playableInstances.Classify(root.firstChild);
    ASSERT_TRUE(inner.live);
    EXPECT_EQ(harken::PlayableKind::Container, inner.kind);
    EXPECT_EQ(row->rootInstance, inner.parent);
    ASSERT_NE(0u, inner.firstChild);
    const auto leaf = engine->playableInstances.Classify(inner.firstChild);
    ASSERT_TRUE(leaf.live);
    EXPECT_EQ(harken::PlayableKind::Sound, leaf.kind);
    EXPECT_EQ(root.firstChild, leaf.parent);

    harken::PlayableRootMetadata metadata{};
    ASSERT_TRUE(engine->playableInstances.CaptureRootMetadata(
        row->rootInstance, &metadata));
    EXPECT_EQ(harken::PlayableKind::Container, metadata.definitionKind);
    EXPECT_EQ(image.containers[0].containerStableId,
              metadata.definitionStableId);
    EXPECT_EQ(image.containers[0].programSemanticFingerprint,
              metadata.programSemanticFingerprint);

    harken::ContainerPlaybackRow outerRow{};
    harken::ContainerPlaybackRow innerRow{};
    ASSERT_TRUE(engine->containerPlayback.Capture(row->rootInstance,
                                                  &outerRow));
    ASSERT_TRUE(engine->containerPlayback.Capture(root.firstChild,
                                                  &innerRow));
    EXPECT_EQ(outerRow.instance, row->rootInstance);
    EXPECT_EQ(image.containers[0].containerStableId,
              outerRow.containerStableId);
    EXPECT_EQ(image.containers[1].containerStableId,
              innerRow.containerStableId);
    EXPECT_EQ(2u, engine->containerPlayback.LiveCount());

    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_FALSE(engine->playableInstances.Classify(row->rootInstance).live);
    EXPECT_FALSE(engine->playableInstances.Classify(root.firstChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(inner.firstChild).live);
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

TEST(ActionFiringApi,
     ImmediateNestedContainerPostTransferFailureReclaimsCommittedTree) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(64, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));

    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateNestedContainerPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto containerBaseline = engine->containerPlayback.LiveCount();
    const auto voiceBaseline = engine->voices.ActiveCount();
    const auto armBaseline = engine->timelineArms.LiveCount();
    const auto firingBaseline = engine->actionFirings.LiveCount();
    const auto selectionRowsBefore = engine->selectionMemory.RowCount();
    const auto selectionDeltasBefore = engine->selectionMemory.FreeDeltaCount();
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    engine->forceActionPlayPostTransferCommitFailureForTest = true;

    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    EXPECT_TRUE(engine->runtimeRecreateRequired);
    EXPECT_EQ(firingBaseline + 1u, engine->actionFirings.LiveCount());
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_EQ(containerBaseline, engine->containerPlayback.LiveCount());
    EXPECT_EQ(voiceBaseline, engine->voices.ActiveCount());
    EXPECT_EQ(armBaseline, engine->timelineArms.LiveCount());
    EXPECT_EQ(selectionRowsBefore, engine->selectionMemory.RowCount());
    EXPECT_EQ(selectionDeltasBefore, engine->selectionMemory.FreeDeltaCount());
    EXPECT_TRUE(std::all_of(
        engine->playableServices.begin(), engine->playableServices.end(),
        [](const harken::EnginePlayableServiceRow& row) {
            return row.phase == harken::EnginePlayableStartPhase::Free;
        }));

    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_FAILED, step.state);
    EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, step.result);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

