TEST(ActionFiringApi, DelayedStopStaleCaptureDoesNotRetargetLaterPlay) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(4, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(64, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAndSeparateStopActions();
    SetAbsoluteTime(&image.steps[10].delay,
                    DelayNanosecondsForTargetFrame(
                        *engine, engine->timelinePool.WindowEndFrame()));
    image.actions[8].directFeatureMask = 1;
    image.actions[8].transitiveFeatureMask = 1;
    image.actions[8].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[8]);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firstPlayFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firstPlayFiring));
    VnActionStepResult firstPlay{};
    firstPlay.structSize = sizeof(firstPlay);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firstPlayFiring, 0, &firstPlay));
    ASSERT_NE(0u, firstPlay.producedPlayableInstance);

    desc.actionId = image.actions[8].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &stopFiring));
    harken::ActionDeferredRecordToken recordToken{};
    harken::ActionDeferredRecord record{};
    harken::ActionDeferredRecordState recordState{};
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &recordToken, &record, &recordState));
    ASSERT_EQ(firstPlay.producedPlayableInstance, record.rootPlayable);

    ASSERT_TRUE(engine->playableInstances.AdvanceLifecycle(
        record.rootPlayable, harken::PlayableLifecycle::LogicalComplete));
    ASSERT_TRUE(engine->playableInstances.AdvanceLifecycle(
        record.rootPlayable, harken::PlayableLifecycle::AudibleRetiring));
    ASSERT_TRUE(engine->playableInstances.AdvanceLifecycle(
        record.rootPlayable, harken::PlayableLifecycle::Retired));
    ASSERT_FALSE(engine->playableInstances.Classify(record.rootPlayable).live);
    EXPECT_FALSE(engine->playableInstances.ValidateStamp(
        record.rootPlayable, record.rootScheduleEpoch));

    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle laterPlayFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &laterPlayFiring));
    VnActionStepResult laterPlay{};
    laterPlay.structSize = sizeof(laterPlay);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(laterPlayFiring, 0, &laterPlay));
    ASSERT_NE(0u, laterPlay.producedPlayableInstance);
    ASSERT_NE(record.rootPlayable, laterPlay.producedPlayableInstance);
    EXPECT_FALSE(engine->playableInstances.ValidateStamp(
        record.rootPlayable, record.rootScheduleEpoch));

    DrainActionDeferred(engine);
    ASSERT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_EQ(VN_ACTION_STEP_NO_OP, stop.state);
    EXPECT_EQ(0u, stop.capturedPlayableCount);
    EXPECT_TRUE(engine->playableInstances.Classify(
        laterPlay.producedPlayableInstance).live);
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(laterPlayFiring));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(stopFiring));
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firstPlayFiring));
}

