TEST(ActionFiringApi,
     TransportResetKeepsBackpressureUntilClaimedActionFinalizerDrains) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    image.MakeDelayedSetValueAction(1000000000);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());

    harken::DeferredIntentClaim claim{};
    ASSERT_EQ(1u, engine->timelineDeferred.ClaimDue(
                           UINT64_MAX, engine->playableInstances, &claim, 1,
                           nullptr, nullptr, UINT64_MAX));
    harken::ActionDeferredRecordToken recordToken{};
    harken::ActionDeferredRecord record{};
    ASSERT_TRUE(engine->actionDeferredRecords.Claim(
        claim, &recordToken, &record));
    EXPECT_EQ(harken::ActionDeferredRecordState::Claimed,
              engine->actionDeferredRecords.State(recordToken));

    EXPECT_EQ(harken::RuntimeTransportResetStatus::Backpressure,
              harken::BeginRuntimeTransportReset(*engine, 0));
    harken::ActionDeferredRecordState resetState =
        harken::ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        recordToken.slot, &recordToken, &record, &resetState));
    EXPECT_EQ(harken::ActionDeferredRecordState::CancelRequested, resetState);
    EXPECT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(1u, engine->actionFirings.OwnedDeferredCount(firing));

    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionFirings.OwnedDeferredCount(firing));
    EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete,
              harken::BeginRuntimeTransportReset(*engine, 0));
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi,
     CoordinatorSameDueActionRetryDoesNotLeapfrogTimeline) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    const std::uint64_t sameDue = engine->timelinePool.WindowEndFrame();
    image.MakeDelayedSetValueAction(
        DelayNanosecondsForTargetFrame(*engine, sameDue));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    harken::ActionDeferredRecordToken actionToken{};
    harken::ActionDeferredRecord actionRecord{};
    harken::ActionDeferredRecordState actionState =
        harken::ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &actionToken, &actionRecord, &actionState));
    ASSERT_EQ(sameDue, actionRecord.intendedBoundaryFrame);

    const harken::PlayableInstanceHandle owner =
        engine->playableInstances.Acquire(harken::PlayableKind::Piece, 0);
    ASSERT_NE(0u, owner);
    const std::uint64_t ownerEpoch =
        engine->playableInstances.Classify(owner).scheduleEpoch;
    harken::EventTemplate sameDueEvent{};
    sameDueEvent.logicCommitSequence = 20;
    sameDueEvent.payload = 0x91;
    harken::EventTemplate laterEvent{};
    laterEvent.logicCommitSequence = 21;
    laterEvent.payload = 0x92;
    harken::ProgramView sameDueProgram{};
    sameDueProgram.ownerInstance = owner;
    sameDueProgram.ownerInstanceScheduleEpoch = ownerEpoch;
    sameDueProgram.transactionId = 91;
    sameDueProgram.entryAnchorFrame = sameDue;
    sameDueProgram.events = &sameDueEvent;
    sameDueProgram.eventCount = 1;
    harken::ProgramView laterProgram = sameDueProgram;
    laterProgram.transactionId = 92;
    laterProgram.entryAnchorFrame = sameDue + 1u;
    laterProgram.events = &laterEvent;
    harken::PostInput post{};
    post.transportEpoch = engine->timelinePool.Epoch();
    post.logicCommitSequence = 20;
    ASSERT_EQ(harken::PostStatus::Deferred,
              engine->timelinePlanner.PostPlay(sameDueProgram, post).status);
    post.logicCommitSequence = 21;
    ASSERT_EQ(harken::PostStatus::Deferred,
              engine->timelinePlanner.PostPlay(laterProgram, post).status);
    ASSERT_EQ(3u, engine->timelineDeferred.Count());

    const harken::VariableCallObservation observed =
        harken::ObserveVariableCallAt(
            engine->variables.CurrentWorldGeneration(),
            engine->variables.CurrentTransportEpoch(),
            engine->config.blockFrames,
            engine->timelinePool.WindowStartFrame(),
            engine->timelinePool.PublishCutoffFrame());
    std::vector<harken::PreparedVariableWriteToken> occupied(
        engine->variables.PendingCapacity());
    for (std::uint32_t index = 0; index < occupied.size(); ++index) {
        ASSERT_EQ(VN_OK,
                  engine->variables
                      .PrepareGlobalWrite(image.variables[0].variableId,
                                          0.25f, observed, index,
                                          &occupied[index])
                      .result);
    }

    bool windowContainsSameDue = false;
    for (std::uint32_t step = 0; step < 128; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (engine->timelinePool.WindowEndFrame() > sameDue) {
            windowContainsSameDue = true;
            break;
        }
    }
    ASSERT_TRUE(windowContainsSameDue);
    ASSERT_LT(sameDue, engine->timelinePool.WindowEndFrame());
    ASSERT_GE(sameDue, engine->timelinePool.PublishCutoffFrame());

    std::array<harken::DeferredIntentClaim, 4> leftover{};
    const std::uint32_t claimed = engine->timelineDeferred.ClaimDue(
        UINT64_MAX, engine->playableInstances, leftover.data(),
        static_cast<std::uint32_t>(leftover.size()), nullptr, nullptr,
        engine->timelinePool.WindowStartQuantum() + 1u);
    bool sameDueActionHeld = false;
    bool sameDueTimelineHeld = false;
    for (std::uint32_t index = 0; index < claimed; ++index) {
        if (leftover[index].intent.dueFrame != sameDue) {
            continue;
        }
        sameDueActionHeld =
            sameDueActionHeld ||
            leftover[index].intent.ownerDomain ==
                harken::DeferredIntentOwnerDomain::Action;
        sameDueTimelineHeld =
            sameDueTimelineHeld ||
            leftover[index].intent.ownerDomain ==
                harken::DeferredIntentOwnerDomain::Playable;
    }
    EXPECT_TRUE(sameDueActionHeld);
    EXPECT_TRUE(sameDueTimelineHeld);
    for (std::uint32_t index = 0; index < claimed; ++index) {
        EXPECT_EQ(harken::DeferredIntentRefusal::None,
                  engine->timelineDeferred.Retry(leftover[index].token, 0));
    }
    for (auto& prepared : occupied) {
        engine->variables.CancelPreparedWrite(&prepared);
    }
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, StopDelayedSetValueReturnsOriginalDeferredPairBeforeDueQuantum) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    image.MakeDelayedSetValueAction(DelayNanosecondsForTargetFrame(
        *engine, engine->timelinePool.WindowEndFrame()));
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_EQ(1u, engine->actionDeferredRecords.LiveCount());
    ASSERT_EQ(1u, engine->timelineDeferred.Count());
    harken::ActionDeferredRecordToken token{};
    harken::ActionDeferredRecord record{};
    harken::ActionDeferredRecordState state =
        harken::ActionDeferredRecordState::Free;
    ASSERT_TRUE(engine->actionDeferredRecords.CaptureAt(
        0, &token, &record, &state));
    ASSERT_EQ(harken::ActionDeferredRecordState::Held, state);
    harken::DeferredIntentToken originalPool{};
    ASSERT_TRUE(engine->actionDeferredRecords.PoolToken(token, &originalPool));
    // The public cancellation owns and returns both original receivers. A
    // record-only RequestCancel is an unfinished internal protocol operation.
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (std::uint32_t step = 0; step < 64; ++step) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        if (engine->timelineDeferred.Count() == 0) {
            break;
        }
    }
    EXPECT_EQ(0u, engine->timelineDeferred.Count());
    EXPECT_EQ(0u, engine->actionDeferredRecords.LiveCount());
    EXPECT_EQ(harken::ActionDeferredRecordState::Free,
        engine->actionDeferredRecords.State(token));
    harken::ActionDeferredPairState returned{};
    ASSERT_TRUE(engine->actionDeferredRecords.InspectPair(
        engine->timelineDeferred, originalPool, token, &returned));
    EXPECT_EQ(harken::ActionDeferredRecordState::Free, returned.recordState);
    EXPECT_EQ(harken::DeferredIntentEntryState::Free, returned.poolState);
    EXPECT_NE(token.generation, returned.recordToken.generation);
    EXPECT_NE(originalPool.generation, returned.poolToken.generation);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_STOP_REQUESTED, info.terminalReason);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, PostCommitsOneImmediateSetValueAndRetainsItsResult) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    EXPECT_EQ(engine->config.maxDeferredIntents,
              engine->actionDeferredRecords.Capacity());
    CanonicalActionWorld image;
    const harken::WorldInstallResult installed =
        harken::InstallContainerWorldV1(*engine, image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, installed.status);

    VnPostActionDesc desc = ValidPostDesc();
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(desc.actionId, info.actionId);
    EXPECT_EQ(installed.resultGeneration, info.worldGeneration);
    harken::ActionFiringSnapshot snapshot{};
    ASSERT_TRUE(engine->actionFirings.Capture(firing, &snapshot));
    EXPECT_EQ(harken::ActionFiringOwnerKind::DirectWorld,
              snapshot.owner.kind);
    EXPECT_EQ(installed.resultGeneration, snapshot.owner.worldGeneration);
    EXPECT_NE(0u, info.acceptedLogicSequence);
    EXPECT_EQ(1u, info.directStepCount);
    EXPECT_EQ(1u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.childFiringCount);
    EXPECT_EQ(0u, info.livePlayableCount);

    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, step.state);
    EXPECT_EQ(VN_OK, step.result);
    EXPECT_EQ(VN_ACTION_OPCODE_SET_VARIABLE, step.opcode);
    EXPECT_EQ(desc.actionId, step.ownerActionId);
    EXPECT_EQ(image.variables[0].variableId, step.targetStableId);
    EXPECT_EQ(info.acceptedLogicSequence, step.logicCommitSequence);
    EXPECT_EQ(0u, step.authoredEventIndex);
    EXPECT_EQ(0u, step.executionOrdinal);
    EXPECT_EQ(1u, step.depth);
    EXPECT_EQ(VN_ACTION_TARGET_VARIABLE, step.targetKind);
    EXPECT_EQ(info.acceptedLogicSequence,
              engine->logicCommits.IssuedCount());

    harkentest::AdvanceVariableWrite(engine);
    float current = 0.0f;
    ASSERT_TRUE(engine->variables.CurrentValue(image.variables[0].variableId,
                                               &current));
    EXPECT_FLOAT_EQ(0.5f, current);

    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    info = {};
    info.structSize = sizeof(info);
    EXPECT_EQ(VN_STALE_HANDLE, Vn_QueryActionFiring(firing, &info));
}

TEST(ActionFiringContract, ImmediateSoundPlayPublishesOneActivePlayable) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(512, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    const harken::WorldInstallResult installed =
        harken::InstallContainerWorldV1(*engine, image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, installed.status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_PENDING, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NONE, info.terminalReason);
    EXPECT_EQ(image.actions[9].actionStableId, info.actionId);
    EXPECT_EQ(1u, info.directStepCount);
    EXPECT_EQ(0u, info.directStepTerminalCount);
    EXPECT_EQ(1u, info.livePlayableCount);

    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    EXPECT_EQ(VN_OK, step.result);
    EXPECT_EQ(VN_ACTION_OPCODE_PLAY, step.opcode);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, step.targetStableId);
    EXPECT_EQ(VN_ACTION_TARGET_SOUND, step.targetKind);
    EXPECT_EQ(info.acceptedLogicSequence, step.logicCommitSequence);
    EXPECT_NE(0u, step.producedPlayableInstance);
    EXPECT_TRUE(engine->playableInstances
                    .Classify(step.producedPlayableInstance)
                    .live);
    EXPECT_EQ(info.acceptedLogicSequence,
              engine->logicCommits.IssuedCount());
    EXPECT_EQ(VN_IN_USE, Vn_ReleaseActionFiring(firing));
}

