void ExpectImmediateVariableControlSameBucketProofFailureRejectsBothLeaves(
    bool stopAtFutureFrame) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const auto playableBaseline = engine->playableInstances.LiveCount();
    const auto decisionBaseline = engine->decisions.LiveCount();
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.75f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
        CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
        CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayAction();
    image.MakeFirstVariableControlChildCompositeTrack();
    image.trackPlacements[1].authoredStart =
        (32 * INT64_C(1000000000) + 47999) / 48000;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto row = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [firing](const auto& service) {
            return service.InvocationValid() &&
                service.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_TRUE(row->immediateLane.Valid());
    const auto failedLane = row->immediateLane;
    const auto base = row->scheduleStorageBase;
    const auto firstStart = engine->playableScheduleStartFrames[base];
    const auto secondStart = engine->playableScheduleStartFrames[base + 1u];
    ASSERT_EQ(32u, secondStart - firstStart);
    auto* futureArm = engine->timelineArms.Resolve(
        engine->playableScheduleArms[base + 1u]);
    ASSERT_NE(nullptr, futureArm);
    ASSERT_EQ(secondStart, futureArm->startFrame);
    auto* futureVoice = engine->voices.Resolve(
        engine->playableScheduleRenderHandles[base + 1u]);
    ASSERT_NE(nullptr, futureVoice);
    const auto originalStopFrame = futureVoice->authoredRootStopFrame;
    if (stopAtFutureFrame) {
        // Model a stop cutoff already visible to audio within this 64-frame block.
        futureVoice->authoredRootStopFrame = secondStart;
    } else {
        ++futureArm->startFrame;
    }
    const auto channels = engine->nullBackend.Channels();
    bool heard = false;
    for (std::uint32_t block = 0; block < 24; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        heard = heard || std::any_of(output,
            output + static_cast<std::size_t>(kBlockFrames) * channels,
            [](float sample) { return std::abs(sample) > 0.01f; });
        if (engine->mixer.BlocksRendered() * kBlockFrames > firstStart)
            break;
    }
    if (stopAtFutureFrame)
        futureVoice->authoredRootStopFrame = originalStopFrame;
    else
        futureArm->startFrame = secondStart;
    EXPECT_FALSE(heard);
    harken::ImmediateLaneObservation lane{};
    ASSERT_TRUE(engine->immediateActionLane.Observe(row->immediateLane, &lane));
    EXPECT_FALSE(lane.applied);
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        heard = heard || std::any_of(output,
            output + static_cast<std::size_t>(kBlockFrames) * channels,
            [](float sample) { return std::abs(sample) > 0.01f; });
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_FALSE(heard);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 64 &&
         row->phase != harken::EnginePlayableStartPhase::Free; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(harken::EnginePlayableStartPhase::Free, row->phase);
    for (std::uint32_t block = 0; block < 64 &&
         engine->decisions.LiveCount() != decisionBaseline; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    harken::ImmediateLaneObservation finalLane{};
    EXPECT_FALSE(engine->immediateActionLane.Observe(failedLane, &finalLane));
    EXPECT_EQ(decisionBaseline, engine->decisions.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);

    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &replay));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    bool replayHeard = false;
    for (std::uint32_t block = 0; block < 24; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        replayHeard = replayHeard || std::any_of(output,
            output + static_cast<std::size_t>(kBlockFrames) * channels,
            [](float sample) { return sample < -0.01f; });
    }
    EXPECT_TRUE(replayHeard);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto replayRow = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [replay](const auto& service) {
            return service.InvocationValid() &&
                service.Invocation().actionFiring == replay;
        });
    ASSERT_NE(engine->playableServices.end(), replayRow);
    VnActionFiringInfo replayInfo{};
    replayInfo.structSize = sizeof(replayInfo);
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalTreeCompletion(
        *engine, replay, replayRow->rootInstance, &replayInfo));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
}

