TEST(ActionFiringApi,
     ImmediateVariableControlSecondLaneBindFailureAbortsWholeTreeAndReplays) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const auto baselinePlayables = engine->playableInstances.LiveCount();
    const auto baselineDecisions = engine->decisions.LiveCount();
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayAction();
    image.MakeFirstVariableControlChildCompositeTrack();
    image.trackPlacements[1].authoredStart =
        (2 * kBlockFrames * INT64_C(1000000000) + 47999) / 48000;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto failedRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), failedRow);
    ASSERT_EQ(2u, failedRow->scheduleLeafCount);
    const std::array<VnVoiceHandle, 2> failedRenders{
        engine->playableScheduleRenderHandles[failedRow->scheduleStorageBase],
        engine->playableScheduleRenderHandles[failedRow->scheduleStorageBase + 1u]};
    engine->forceImmediateLaneBindLeafFailureForTest = 1;
    engine->nullBackend.Pump(3);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(UINT32_MAX, engine->forceImmediateLaneBindLeafFailureForTest);
    bool heard = false;
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        heard = heard || std::any_of(output, output + kBlockFrames,
            [](float sample) { return std::abs(sample) > 0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    EXPECT_FALSE(heard);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(baselinePlayables, engine->playableInstances.LiveCount());
    EXPECT_EQ(baselineDecisions, engine->decisions.LiveCount());
    for (std::uint32_t block = 0;
         block < 64 &&
             failedRow->phase != harken::EnginePlayableStartPhase::Free;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    ASSERT_EQ(harken::EnginePlayableStartPhase::Free, failedRow->phase);
    for (const auto render : failedRenders) {
        harken::EngineTimelineVoiceInstallIdentity stale{};
        EXPECT_FALSE(engine->CaptureTimelineVoiceInstallIdentity(
            render, &stale));
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));

    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &replay));
    VnActionStepResult replayStep{};
    replayStep.structSize = sizeof(replayStep);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(replay, 0, &replayStep));
    ASSERT_NE(0u, replayStep.producedPlayableInstance);
    const auto replayRoot = replayStep.producedPlayableInstance;
    bool replayHeard = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        replayHeard = replayHeard || std::any_of(
            output, output + kBlockFrames,
            [](float sample) { return sample < -0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(replayHeard);
    for (const auto render : failedRenders) {
        harken::EngineTimelineVoiceInstallIdentity stale{};
        EXPECT_FALSE(engine->CaptureTimelineVoiceInstallIdentity(
            render, &stale));
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalTreeCompletion(
        *engine, replay, replayRoot, &info));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
}

void ExpectImmediateVariableControlFutureManifestFaultRejected(
    std::uint32_t fault) {
    SCOPED_TRACE(fault);
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const auto baselinePlayables = engine->playableInstances.LiveCount();
    const auto baselineDecisions = engine->decisions.LiveCount();
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
        Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayAction();
    image.MakeFirstVariableControlChildCompositeTrack();
    image.trackPlacements[1].authoredStart =
        (2 * kBlockFrames * INT64_C(1000000000) + 47999) / 48000;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    engine->forceImmediateLaneFutureEventFaultForTest = fault;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto rejectedRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), rejectedRow);
    ASSERT_EQ(2u, rejectedRow->scheduleLeafCount);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->forceImmediateLaneFutureEventFaultForTest);

    bool heard = false;
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        heard = heard || std::any_of(output, output + kBlockFrames,
            [](float sample) { return std::abs(sample) > 0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            rejectedRow->phase == harken::EnginePlayableStartPhase::Free)
            break;
    }
    EXPECT_FALSE(heard);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    ASSERT_EQ(harken::EnginePlayableStartPhase::Free, rejectedRow->phase);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(baselinePlayables, engine->playableInstances.LiveCount());
    EXPECT_EQ(baselineDecisions, engine->decisions.LiveCount());
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));

    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &replay));
    VnActionStepResult replayStep{};
    replayStep.structSize = sizeof(replayStep);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(replay, 0, &replayStep));
    ASSERT_NE(0u, replayStep.producedPlayableInstance);
    const auto replayRoot = replayStep.producedPlayableInstance;
    bool heardFuture = false;
    for (std::uint32_t block = 0; block < 32; ++block) {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        heardFuture = heardFuture || std::any_of(
            output, output + kBlockFrames,
            [](float sample) { return sample < -0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_TRUE(heardFuture);
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalTreeCompletion(
        *engine, replay, replayRoot, &info));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
}

