enum class NestedQueueBatchCase {
    ExactFit, OneShort, LaterSiblingFailure, InitialVoiceCommitFailure,
    FinalOwnerCommitFailure, FinalOwnerCommitAndRollbackFailure,
    FinalOwnerCommitFailureWithStaleMapping, FinalOwnerCommitFailureWithExternalMapping
};

TEST(ActionFiringApi, NestedQueueAttemptReusesCompositeAsSingleAfterRejectedAdmission) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(256, 0.25f), second(256, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    const auto firstRevision = engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision;
    const auto secondRevision = engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision;
    CanonicalActionWorld composite(firstRevision, secondRevision), single(firstRevision, secondRevision);
    CanonicalActionWorld track(firstRevision, secondRevision);
    composite.MakeImmediateNestedQueueVariableControlPlayAction();
    single.MakeImmediateNestedQueueVariableControlPlayAction();
    track.MakeFirstQueueChildCompositeTrack();
    for (auto& property : track.properties) {
        if (property.contentPropertyKind != harken::playableproperties::ContentPropertyKindV1::Track) continue;
        property.authoredStableOrder = composite.world.playablePropertyCount;
        property.programSemanticFingerprint = harken::ComputePlayablePropertyFingerprintV1(property);
        track.track.rootDefinition.expectedProgramSemanticFingerprint = property.programSemanticFingerprint;
        track.queueChildren[0].playable = track.track.rootDefinition;
        for (auto& occurrence : track.occurrences) {
            if (occurrence.parentKind != harken::playableproperties::ContentPropertyKindV1::Track) continue;
            occurrence.parentProgramSemanticFingerprint = property.programSemanticFingerprint;
            occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        }
    }
    track.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(track.track);
    track.queueChildren[0].timingHint = harken::MakeScheduleReferenceTimingHint(
        harken::PlayableKindV1::Track, track.track.rootDefinition.stableId, track.track.scheduleSemanticFingerprint);
    std::vector<harken::PlayablePropertyProgramViewV1> properties(composite.world.playableProperties,
        composite.world.playableProperties + composite.world.playablePropertyCount);
    std::vector<harken::PlayableOccurrencePropertyViewV1> occurrences(composite.world.playableOccurrences,
        composite.world.playableOccurrences + composite.world.playableOccurrenceCount);
    for (const auto& property : track.properties)
        if (property.contentPropertyKind == harken::playableproperties::ContentPropertyKindV1::Track)
            properties.push_back(property);
    for (std::uint32_t index = 0; index < track.world.playableOccurrenceCount; ++index)
        if (track.occurrences[index].parentKind == harken::playableproperties::ContentPropertyKindV1::Track)
            occurrences.push_back(track.occurrences[index]);
    composite.queueChildren[0] = track.queueChildren[0];
    for (auto& occurrence : occurrences)
        if (occurrence.parentStableId == composite.containers[2].containerStableId &&
            occurrence.stableOccurrenceOrdinal == composite.queueChildren[0].stableChildOrdinal) {
            occurrence.childPlayable = composite.queueChildren[0].playable;
            occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        }
    std::sort(properties.begin(), properties.end(), [](const auto& a, const auto& b) {
        return std::pair(a.contentPropertyKind, a.stableId) < std::pair(b.contentPropertyKind, b.stableId);
    });
    std::sort(occurrences.begin(), occurrences.end(), [](const auto& a, const auto& b) {
        return std::tuple(a.parentKind, a.parentStableId, a.stableOccurrenceOrdinal) <
            std::tuple(b.parentKind, b.parentStableId, b.stableOccurrenceOrdinal);
    });
    composite.world.playableProperties = properties.data();
    composite.world.playablePropertyCount = static_cast<std::uint32_t>(properties.size());
    composite.world.playableOccurrences = occurrences.data();
    composite.world.playableOccurrenceCount = static_cast<std::uint32_t>(occurrences.size());
    composite.world.trackSchedules = &track.track;
    composite.world.trackScheduleCount = 1;
    composite.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(composite.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, composite.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::PlayableStartRequest request{};
    request.emitter = emitter;
    const auto& property = composite.properties[5];
    request.root = {harken::PlayableKindV1::Container, 0, property.stableId,
        property.programSemanticFingerprint, property.contentRevision, property.routeStableId,
        property.compatibilityFingerprint};
    const auto started = harken::StartPlayable(engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto scratch = std::find_if(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
        [](const auto& attempt) { return attempt.frontierQueueCount == 1 &&
            attempt.storage.frontierQueues[0].current.leafCount == 2; });
    ASSERT_NE(engine.actionPlayScratch.end(), scratch);
    ASSERT_TRUE(scratch->storage.frontierQueues[0].current.composite.Valid());
    const auto generation = scratch->storage.generation;
    FrontierTrace trace;
    bool stopped = false;
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        trace.Capture(engine);
        if (!stopped && trace.heard.size() >= 2u) {
            EXPECT_EQ(CanonicalActionWorld::kFirstSound, trace.heard[0].subject);
            EXPECT_EQ(CanonicalActionWorld::kSecondSound, trace.heard[1].subject);
            ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(engine, started.instance, 0));
            stopped = true;
        }
        if (engine.playableInstances.LiveCount() == 0 && engine.playablePartitions.OccupiedCount() == 0 &&
            engine.timelineArms.LiveCount() == 0 && engine.voices.ActiveCount() == 0) break;
    }
    ASSERT_TRUE(stopped);
    ASSERT_EQ(0u, engine.playableInstances.LiveCount());
    ASSERT_EQ(0u, engine.playablePartitions.OccupiedCount());
    ASSERT_EQ(0u, engine.timelineArms.LiveCount());
    ASSERT_EQ(0u, engine.compositeCompletionOwners.OccupiedCount());
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, single.world).status);
    harken::CommandRecord filler{};
    filler.opcode = harken::kOpcodeStop;
    filler.payload.stop.handle = UINT64_MAX;
    while (engine.commands.FreeSlots() > 5u) ASSERT_TRUE(engine.commands.TryPush(filler));
    const auto before = CaptureActionPreparationOwners(engine);
    ASSERT_EQ(harken::PlayableStartStatus::Backpressure, harken::StartPlayable(engine, request).status);
    ExpectActionPreparationOwnersUnchanged(engine, before);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    ASSERT_GT(scratch->storage.generation, generation);
    EXPECT_EQ(0u, scratch->storage.frontierQueues[0].current.leafCount);
    EXPECT_FALSE(scratch->storage.frontierQueues[0].current.composite.Valid());
    while (engine.commands.TryPop(filler)) ASSERT_EQ(harken::kOpcodeStop, filler.opcode);
    const auto retried = harken::StartPlayable(engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, retried.status);
    EXPECT_EQ(1u, scratch->storage.frontierQueues[0].current.leafCount);
    EXPECT_FALSE(scratch->storage.frontierQueues[0].current.composite.Valid());
    FrontierTrace retryTrace;
    bool retryStopped = false;
    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        retryTrace.Capture(engine);
        if (!retryStopped && retryTrace.heard.size() == 2u) {
            EXPECT_EQ(CanonicalActionWorld::kFirstSound, retryTrace.heard[0].subject);
            EXPECT_EQ(CanonicalActionWorld::kSecondSound, retryTrace.heard[1].subject);
            ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(engine, retried.instance, 0));
            retryStopped = true;
        }
        if (engine.playableInstances.LiveCount() == 0 && engine.playablePartitions.OccupiedCount() == 0 &&
            engine.timelineArms.LiveCount() == 0 && engine.voices.ActiveCount() == 0) break;
    }
    EXPECT_TRUE(retryStopped);
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.timelineArms.LiveCount());
    EXPECT_EQ(0u, engine.compositeCompletionOwners.OccupiedCount());
    EXPECT_EQ(0u, engine.queueInstances.LiveCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

void ExpectDeferredNestedQueueCompositeSuccessor(
    bool pieceChild, bool refuseSecondLeaf, bool singleLeaf = false,
    bool appendSound = false, bool logicalTrack = false) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(
        logicalTrack ? 1024u
                     : engine.timelinePool.WindowEndFrame() + 256u,
        0.25f);
    std::vector<float> second(logicalTrack ? 1024u : 256u, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    const auto firstRevision = engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision;
    const auto secondRevision = engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision;
    CanonicalActionWorld composite(firstRevision, secondRevision), donor(firstRevision, secondRevision);
    composite.MakeImmediateNestedQueueVariableControlPlayAction();
    auto finalSound = composite.queueChildren[1];
    if (pieceChild) donor.MakeSecondQueueChildCompositePiece();
    else donor.MakeSecondQueueChildCompositeTrack();
    if (singleLeaf) donor.track.placementCount = 1;
    if (logicalTrack) {
        ASSERT_FALSE(pieceChild);
        for (std::uint32_t index = 0;
             index < donor.track.placementCount; ++index) {
            donor.trackPlacements[index].authoredStart =
                INT64_C(10000000) * (index + 1u);
            donor.trackPlacements[index].authoredDuration = 1;
        }
    }
    std::vector<harken::PlayablePropertyProgramViewV1> properties(composite.world.playableProperties,
        composite.world.playableProperties + composite.world.playablePropertyCount);
    std::vector<harken::PlayableOccurrencePropertyViewV1> occurrences(composite.world.playableOccurrences,
        composite.world.playableOccurrences + composite.world.playableOccurrenceCount);
    for (auto& property : donor.properties) {
        const bool track = property.contentPropertyKind == harken::playableproperties::ContentPropertyKindV1::Track;
        const bool piece = property.contentPropertyKind == harken::playableproperties::ContentPropertyKindV1::Piece;
        if (!track && !piece) continue;
        property.authoredStableOrder = static_cast<std::uint32_t>(properties.size());
        property.programSemanticFingerprint = harken::ComputePlayablePropertyFingerprintV1(property);
        (track ? donor.track.rootDefinition : donor.piece.rootDefinition).expectedProgramSemanticFingerprint =
            property.programSemanticFingerprint;
        properties.push_back(property);
        for (std::uint32_t index = 0; index < donor.world.playableOccurrenceCount; ++index) {
            auto occurrence = donor.occurrences[index];
            if (occurrence.parentKind != property.contentPropertyKind) continue;
            if (singleLeaf && track && occurrence.stableOccurrenceOrdinal ==
                donor.trackPlacements[1].stableOccurrenceOrdinal) continue;
            occurrence.parentProgramSemanticFingerprint = property.programSemanticFingerprint;
            occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
            occurrences.push_back(occurrence);
        }
    }
    donor.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(donor.track);
    if (pieceChild) {
        donor.pieceTrackRef.trackDefinition = donor.track.rootDefinition;
        donor.pieceTrackRef.trackScheduleSemanticFingerprint = donor.track.scheduleSemanticFingerprint;
        donor.piece.scheduleSemanticFingerprint = harken::ComputePieceScheduleFingerprintV1(donor.piece);
    }
    composite.queueChildren[1].playable = pieceChild ? donor.piece.rootDefinition : donor.track.rootDefinition;
    composite.queueChildren[1].timingHint = harken::MakeScheduleReferenceTimingHint(
        composite.queueChildren[1].playable.kind, composite.queueChildren[1].playable.stableId,
        pieceChild ? donor.piece.scheduleSemanticFingerprint : donor.track.scheduleSemanticFingerprint);
    for (auto& occurrence : occurrences) {
        if (occurrence.parentStableId != composite.containers[2].containerStableId ||
            occurrence.stableOccurrenceOrdinal != composite.queueChildren[1].stableChildOrdinal) continue;
        occurrence.childPlayable = composite.queueChildren[1].playable;
        occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
    }
    std::array<harken::ContainerChildProgramViewV2, 3> queueChildren{};
    if (appendSound) {
        std::copy_n(composite.queueChildren, 2, queueChildren.begin());
        finalSound.stableChildOrdinal = 9;
        finalSound.authoredStableOrder = 2;
        queueChildren[2] = finalSound;
        composite.containers[2].children = queueChildren.data();
        composite.containers[2].childCount = 3;
        auto occurrence = *std::find_if(occurrences.begin(), occurrences.end(), [&](const auto& candidate) {
            return candidate.parentStableId == composite.containers[2].containerStableId &&
                candidate.stableOccurrenceOrdinal == composite.queueChildren[0].stableChildOrdinal;
        });
        occurrence.stableOccurrenceOrdinal = 9;
        occurrence.childPlayable = finalSound.playable;
        occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        occurrences.push_back(occurrence);
    }
    std::sort(properties.begin(), properties.end(), [](const auto& a, const auto& b) {
        return std::pair(a.contentPropertyKind, a.stableId) < std::pair(b.contentPropertyKind, b.stableId);
    });
    std::sort(occurrences.begin(), occurrences.end(), [](const auto& a, const auto& b) {
        return std::tuple(a.parentKind, a.parentStableId, a.stableOccurrenceOrdinal) <
            std::tuple(b.parentKind, b.parentStableId, b.stableOccurrenceOrdinal);
    });
    composite.world.playableProperties = properties.data();
    composite.world.playablePropertyCount = static_cast<std::uint32_t>(properties.size());
    composite.world.playableOccurrences = occurrences.data();
    composite.world.playableOccurrenceCount = static_cast<std::uint32_t>(occurrences.size());
    composite.world.trackSchedules = &donor.track;
    composite.world.trackScheduleCount = 1;
    composite.world.pieceSchedules = pieceChild ? &donor.piece : nullptr;
    composite.world.pieceScheduleCount = pieceChild ? 1u : 0u;
    composite.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(composite.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, composite.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    harken::PlayableStartRequest request{};
    request.emitter = emitter;
    const auto& property = composite.properties[5];
    request.root = {harken::PlayableKindV1::Container, 0, property.stableId,
        property.programSemanticFingerprint, property.contentRevision, property.routeStableId,
        property.compatibilityFingerprint};
    const auto started = harken::StartPlayable(engine, request);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    FrontierTrace trace;
    bool refused = false;
    bool retried = false;
    bool observedRefusal = false;
    const auto expectedHeard = logicalTrack
        ? 2u
        : (singleLeaf ? 2u : 3u) + (appendSound ? 1u : 0u);
    const auto budget = static_cast<std::uint32_t>(2u * first.size() / engine.config.blockFrames + 96u);
    bool observedLogicalTrack = false;
    for (std::uint32_t block = 0; block < budget; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
        trace.Capture(engine);
        ASSERT_FALSE(engine.runtimeRecreateRequired) << block;
        for (const auto& row : engine.playableServices) {
            if (row.queueMode && row.partition.Valid() &&
                row.controlReason == harken::PlayableControlReason::StartRefused) {
                observedRefusal = true;
                EXPECT_EQ(0u, row.variableControlNestedQueueSuccessorInstance);
                EXPECT_EQ(0u, row.queueSuccessorScheduleLeafCount);
            }
        }
        if (logicalTrack) {
            for (const auto& row : engine.playableServices) {
                if (!row.queueMode || !row.partition.Valid() ||
                    !row.parentService.Valid()) continue;
                if (row.hasZeroWorkCompletion &&
                    row.queueCurrentScheduleLeafCount == 0) {
                    observedLogicalTrack = true;
                    EXPECT_GT(row.scheduleLeafCount, 0u);
                }
            }
        }
        if (appendSound) {
            for (const auto& row : engine.playableServices) {
                if (row.queueMode && row.partition.Valid() && trace.heard.size() == expectedHeard &&
                    row.variableControlNestedQueueSuccessorInstance == 0)
                    EXPECT_EQ(1u, row.scheduleLeafCount);
                if (!row.queueMode || !row.partition.Valid() || row.scheduleLeafCount != 2 ||
                    row.variableControlNestedQueueSuccessorInstance == 0) continue;
                ASSERT_NE(row.variableControlNestedQueueSuccessorInstance,
                    engine.playableMemberReferences[row.scheduleStorageBase + 1u].leaf) << block;
            }
        }
        if (refuseSecondLeaf && !refused && trace.heard.size() == 1u) {
            ASSERT_EQ(VN_OK, Vn_UnregisterPCM(CanonicalActionWorld::kSecondSound));
            refused = true;
        }
        if (refused && !retried && block > first.size() / engine.config.blockFrames + 8u) {
            ASSERT_EQ(1u, trace.heard.size());
            ASSERT_TRUE(observedRefusal);
            const auto before = CaptureActionPreparationOwners(engine);
            ASSERT_EQ(VN_OK, Vn_Update());
            ExpectActionPreparationOwnersUnchanged(engine, before);
            for (std::uint32_t drain = 0; drain < 64u; ++drain) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine.nullBackend.Pump(1);
            }
            ASSERT_EQ(0u, engine.playableInstances.LiveCount());
            ASSERT_EQ(0u, engine.playablePartitions.OccupiedCount());
            ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
            const auto replayed = harken::StartPlayable(engine, request);
            ASSERT_EQ(harken::PlayableStartStatus::Accepted, replayed.status);
            trace = {};
            retried = true;
            block = 0;
        }
        if (trace.heard.size() >= expectedHeard && engine.voices.ActiveCount() == 0 &&
            engine.timelineArms.LiveCount() == 0) break;
    }
    ASSERT_EQ(expectedHeard, trace.heard.size());
    if (logicalTrack) EXPECT_TRUE(observedLogicalTrack);
    if (appendSound) EXPECT_EQ(CanonicalActionWorld::kSecondSound, trace.heard.back().subject);
    EXPECT_EQ(CanonicalActionWorld::kFirstSound, trace.heard[0].subject);
    if (!logicalTrack) {
        EXPECT_EQ(CanonicalActionWorld::kFirstSound, trace.heard[1].subject);
        EXPECT_NE(trace.heard[0].parent, trace.heard[1].parent);
    }
    if (!singleLeaf && !logicalTrack) {
        EXPECT_EQ(CanonicalActionWorld::kSecondSound, trace.heard[2].subject);
        EXPECT_NE(trace.heard[1].leaf, trace.heard[2].leaf);
        EXPECT_EQ(trace.heard[1].parent, trace.heard[2].parent);
    }
    for (const auto& heard : trace.heard) {
        EXPECT_EQ(heard.expectedStart, heard.start);
        heard.ExpectNaturalSourceReleased();
    }
    for (std::uint32_t drain = 0; drain < 64u; ++drain) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine.nullBackend.Pump(1);
    }
    EXPECT_EQ(0u, engine.playableInstances.LiveCount());
    EXPECT_EQ(0u, engine.playablePartitions.OccupiedCount());
    EXPECT_EQ(0u, engine.timelineArms.LiveCount());
    EXPECT_EQ(0u, engine.queueInstances.LiveCount());
    EXPECT_EQ(0u, engine.voices.ActiveCount());
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

