void ExpectImmediateNestedQueueActionBatch(NestedQueueBatchCase testCase, bool observeOriginalTree = false) {
    (void)Vn_Term();
    auto config = harkentest::MakeNullConfig(8, 64, 48000);
    config.commandQueueDepth = 15;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(1024, 0.25f), second(1024, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    CanonicalActionWorld sibling(engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    sibling.MakeImmediateCompositeTrackPlayAction();
    image.MakeImmediateNestedQueueVariableControlPlayAction();
    image.EnableNaturalEndQueueTransition(64, 128);
    for (auto& property : sibling.properties) {
        if (property.contentPropertyKind != harken::playableproperties::ContentPropertyKindV1::Track) continue;
        property.authoredStableOrder = image.world.playablePropertyCount;
        property.programSemanticFingerprint = harken::ComputePlayablePropertyFingerprintV1(property);
        sibling.track.rootDefinition.expectedProgramSemanticFingerprint = property.programSemanticFingerprint;
        sibling.steps[11].target.expectedProgramSemanticFingerprint = property.programSemanticFingerprint;
        for (auto& occurrence : sibling.occurrences) {
            if (occurrence.parentKind != harken::playableproperties::ContentPropertyKindV1::Track) continue;
            occurrence.parentProgramSemanticFingerprint = property.programSemanticFingerprint;
            occurrence.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(occurrence);
        }
    }
    sibling.track.scheduleSemanticFingerprint = harken::ComputeTrackScheduleFingerprintV1(sibling.track);
    std::vector<harken::PlayablePropertyProgramViewV1> combinedProperties(
        image.world.playableProperties, image.world.playableProperties + image.world.playablePropertyCount);
    std::vector<harken::PlayableOccurrencePropertyViewV1> combinedOccurrences(
        image.world.playableOccurrences, image.world.playableOccurrences + image.world.playableOccurrenceCount);
    for (std::uint32_t index = 0; index < sibling.world.playablePropertyCount; ++index) {
        const auto& property = sibling.world.playableProperties[index];
        if (property.contentPropertyKind == harken::playableproperties::ContentPropertyKindV1::Track)
            combinedProperties.push_back(property);
    }
    for (std::uint32_t index = 0; index < sibling.world.playableOccurrenceCount; ++index) {
        const auto& occurrence = sibling.world.playableOccurrences[index];
        if (occurrence.parentKind == harken::playableproperties::ContentPropertyKindV1::Track)
            combinedOccurrences.push_back(occurrence);
    }
    std::sort(combinedProperties.begin(), combinedProperties.end(), [](const auto& a, const auto& b) {
        return std::pair(a.contentPropertyKind, a.stableId) < std::pair(b.contentPropertyKind, b.stableId);
    });
    std::sort(combinedOccurrences.begin(), combinedOccurrences.end(), [](const auto& a, const auto& b) {
        return std::tuple(a.parentKind, a.parentStableId, a.stableOccurrenceOrdinal) <
            std::tuple(b.parentKind, b.parentStableId, b.stableOccurrenceOrdinal);
    });
    image.world.playableProperties = combinedProperties.data();
    image.world.playablePropertyCount = static_cast<std::uint32_t>(combinedProperties.size());
    image.world.playableOccurrences = combinedOccurrences.data();
    image.world.playableOccurrenceCount = static_cast<std::uint32_t>(combinedOccurrences.size());
    image.world.trackSchedules = &sibling.track;
    image.world.trackScheduleCount = 1;
    image.steps[12] = sibling.steps[11];
    if (testCase == NestedQueueBatchCase::FinalOwnerCommitAndRollbackFailure)
        std::swap(image.steps[11], image.steps[12]);
    image.steps[11].authoredEventIndex = 0;
    image.steps[12].authoredEventIndex = 1;
    image.actions[9].stepCount = 2;
    image.actions[9].expandedStepOccurrenceCount = 2;
    image.actions[9].programSemanticFingerprint = harken::ComputeActionProgramFingerprintV1(image.actions[9]);
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    ASSERT_EQ(16u, engine.commands.Capacity());
    ASSERT_EQ(engine.commands.Capacity(), engine.commands.FreeSlots());

    // Four voice batches plus the Queue's source-control arm are one admission.
    constexpr std::uint32_t commandCount = 4u * 3u + 1u;
    const bool oneShort = testCase == NestedQueueBatchCase::OneShort;
    const bool laterFailure = testCase == NestedQueueBatchCase::LaterSiblingFailure;
    const bool initialVoiceFailure = testCase == NestedQueueBatchCase::InitialVoiceCommitFailure;
    const bool finalOwnerFailure = testCase == NestedQueueBatchCase::FinalOwnerCommitFailure ||
        testCase == NestedQueueBatchCase::FinalOwnerCommitFailureWithStaleMapping ||
        testCase == NestedQueueBatchCase::FinalOwnerCommitFailureWithExternalMapping ||
        testCase == NestedQueueBatchCase::FinalOwnerCommitAndRollbackFailure;
    const bool rollbackFailure = testCase == NestedQueueBatchCase::FinalOwnerCommitAndRollbackFailure;
    const bool mappingFailure =
        testCase == NestedQueueBatchCase::FinalOwnerCommitFailureWithStaleMapping ||
        testCase == NestedQueueBatchCase::FinalOwnerCommitFailureWithExternalMapping;
    struct MappingFault {
        bool external = false;
        std::uint32_t calls = 0;
        harken::EnginePlayableMemberReference original{};
        std::size_t externalSlot = 0;
    } mappingFault;
    mappingFault.external = testCase == NestedQueueBatchCase::FinalOwnerCommitFailureWithExternalMapping;
#if defined(HARKEN_TEST_PACK_RESOURCE_OBSERVATION)
    struct SnapshotHookGuard {
        ~SnapshotHookGuard() { harken::detail::SetVariableRollbackSnapshotHookForTest(nullptr, nullptr); }
    } snapshotHookGuard;
    if (mappingFailure) {
        harken::detail::SetVariableRollbackSnapshotHookForTest([](
            harken::Engine& current, harken::EngineActionPlayScratch& scratch, void* context) {
            auto& fault = *static_cast<MappingFault*>(context);
            if (fault.calls != 0 || scratch.row == nullptr ||
                scratch.storage.variableControlRollbackEdgeCount != 1u) return;
            auto& edge = scratch.storage.variableControlRollbackEdges[0];
            ASSERT_FALSE(edge.detached);
            fault.original = edge.reference;
            if (fault.external) {
                fault.externalSlot = edge.logicalSlot + 1u;
                ASSERT_LT(fault.externalSlot, current.playableStorage.MemberBase(scratch.row->partition.slot) +
                    current.playableStorage.memberStride);
                ASSERT_LT(fault.externalSlot, current.playableMemberReferences.size());
                ASSERT_FALSE(current.playableMemberReferences[fault.externalSlot].service.Valid());
                current.playableMemberReferences[fault.externalSlot] = edge.reference;
            } else {
                ASSERT_NE(UINT32_MAX, edge.reference.service.token.generation);
                ++edge.reference.service.token.generation;
            }
            ++fault.calls;
        }, &mappingFault);
    }
#endif

    const auto available = commandCount - static_cast<std::uint32_t>(oneShort);
    harken::CommandRecord filler{};
    filler.opcode = harken::kOpcodeStop;
    filler.payload.stop.handle = UINT64_MAX;
    while (engine.commands.FreeSlots() > available) ASSERT_TRUE(engine.commands.TryPush(filler));
    const auto fillerCount = engine.commands.Capacity() - available;
    const auto before = CaptureActionPreparationOwners(engine);
    const auto partitionBefore = engine.playablePartitions.OccupiedCount();
    const auto containerBefore = engine.containerPlayback.LiveCount();
    const auto groupsBefore = engine.timelinePool.CaptureLivePlan03Groups(nullptr, 0);
    const auto sourceGenerations = CaptureSourceGenerations(engine);
    if (laterFailure) engine.forceActionPlayPostTransferCommitFailureForTest = true;
    engine.forceActionTimelineVoiceOwnerCommitFailureForTest = initialVoiceFailure;
    engine.forceActionFinalOwnerCommitFailureForTest = finalOwnerFailure;
    engine.forceActionTimelineVoiceOwnerRollbackFailureForTest = rollbackFailure;
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    QueueTreeOnlyFactoryObservation originalTree{};
    if (observeOriginalTree) ObserveQueueTreeOnlyFactory(engine, originalTree);
#endif
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle firing = 0;
    EXPECT_EQ(oneShort ? VN_BACKPRESSURE : VN_OK, Vn_PostAction(&desc, &firing));
#if defined(HARKEN_TEST_PACK_RESOURCE_OBSERVATION)
    harken::detail::SetVariableRollbackSnapshotHookForTest(nullptr, nullptr);
#endif
    if (mappingFailure) ASSERT_EQ(1u, mappingFault.calls);

#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
    if (observeOriginalTree) {
        ASSERT_NO_FATAL_FAILURE(FinishQueueTreeOnlyFactoryObservation(engine, originalTree));
        EXPECT_EQ(1u, originalTree.currentVoiceCount);
        EXPECT_EQ(0u, originalTree.successorVoiceCount);
        EXPECT_EQ(1u, originalTree.linkedFutureVoiceCount);
        EXPECT_GT(originalTree.count, 2u);
        for (const auto& holder : engine.originalSingleCurrentHolders) {
            EXPECT_EQ(harken::Engine::OriginalSingleCurrentHolder::State::Empty, holder.state);
            EXPECT_FALSE(holder.bundle.Valid());
        }
    }
#endif
    for (std::uint32_t index = 0; index < fillerCount; ++index) {
        harken::CommandRecord observed{};
        ASSERT_TRUE(engine.commands.PeekAt(index, observed));
        EXPECT_EQ(filler.opcode, observed.opcode);
        EXPECT_EQ(filler.payload.stop.handle, observed.payload.stop.handle);
    }
    if (oneShort) {
        EXPECT_EQ(0u, firing);
        ExpectActionPreparationOwnersUnchanged(engine, before);
        EXPECT_EQ(partitionBefore, engine.playablePartitions.OccupiedCount());
        EXPECT_EQ(containerBefore, engine.containerPlayback.LiveCount());
        EXPECT_EQ(groupsBefore, engine.timelinePool.CaptureLivePlan03Groups(nullptr, 0));
        ASSERT_NO_FATAL_FAILURE(ExpectBoundSourcesReleased(engine, sourceGenerations));
        EXPECT_FALSE(engine.runtimeRecreateRequired);
        return;
    }
    ASSERT_NE(0u, firing);
    if (laterFailure || initialVoiceFailure || finalOwnerFailure) {
        EXPECT_FALSE(engine.forceActionPlayPostTransferCommitFailureForTest);
        EXPECT_FALSE(engine.forceActionTimelineVoiceOwnerCommitFailureForTest);
        EXPECT_FALSE(engine.forceActionFinalOwnerCommitFailureForTest);
        EXPECT_FALSE(engine.forceActionTimelineVoiceOwnerRollbackFailureForTest);
        if (rollbackFailure) {
            // The first Track commits two voices before its final owner fails.
            // One rollback refuses once; the later VC Play must stay prepared.
            constexpr std::uint32_t committedPrefixVoices = 2u;
            constexpr std::uint32_t refusedRollbackRetry = 1u;
            EXPECT_EQ(committedPrefixVoices + refusedRollbackRetry,
                engine.actionTimelineVoiceOwnerRollbackAttemptsForTest);
        }
        EXPECT_TRUE(engine.runtimeRecreateRequired);
        EXPECT_EQ(before.commandHead, engine.commands.PublishedHead());
        EXPECT_EQ(before.commandFree, engine.commands.FreeSlots());
        if (mappingFailure) {
            auto pending = std::find_if(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
                [](const auto& scratch) {
                    return scratch.storage.variableControlRollbackSnapshotCaptured &&
                        scratch.storage.variableControlRollbackEdgeCount != 0;
                });
            ASSERT_NE(engine.actionPlayScratch.end(), pending);
            ASSERT_NE(nullptr, pending->row);
            ASSERT_EQ(1u, pending->storage.variableControlRollbackEdgeCount);
            auto edge = pending->storage.variableControlRollbackEdges[0];
            edge.reference = mappingFault.original;
            edge.detached = false;
            const auto parentIdentity = pending->row->identity;
            const auto parentPartition = pending->row->partition;
            const auto* child = engine.ResolvePlayableService(edge.reference.service);
            ASSERT_NE(nullptr, child);
            const auto childPartition = child->partition;
            // Inject against the real captured snapshot before its first release,
            // then require repeated normal updates to preserve the invalid owner.
            for (std::uint32_t block = 0; block < 3; ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine.nullBackend.Pump(1);
                ASSERT_NE(nullptr, pending->row);
                EXPECT_TRUE(pending->prepared);
                EXPECT_EQ(parentIdentity, pending->row->identity);
                EXPECT_EQ(child, engine.ResolvePlayableService(edge.reference.service));
                EXPECT_TRUE(engine.playablePartitions.Owns(parentPartition, parentIdentity));
                EXPECT_TRUE(engine.playablePartitions.Owns(childPartition, edge.reference.service.token));
                if (mappingFault.external) {
                    EXPECT_EQ(edge.reference.service.token,
                        engine.playableMemberReferences[mappingFault.externalSlot].service.token);
                } else {
                    EXPECT_FALSE(pending->storage.variableControlRollbackEdges[0].detached);
                    EXPECT_EQ(edge.reference.service.token.generation + 1u,
                        pending->storage.variableControlRollbackEdges[0].reference.service.token.generation);
                    EXPECT_EQ(edge.reference.service.token,
                        engine.playableMemberReferences[edge.logicalSlot].service.token);
                }
            }
            if (mappingFault.external) engine.playableMemberReferences[mappingFault.externalSlot] = {};
            else pending->storage.variableControlRollbackEdges[0] = edge;
            for (std::uint32_t block = 0; block < 16 && pending->row != nullptr; ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine.nullBackend.Pump(1);
            }
            EXPECT_EQ(nullptr, pending->row);
            EXPECT_EQ(nullptr, engine.ResolvePlayableService(edge.reference.service));
            EXPECT_TRUE(engine.runtimeRecreateRequired);
        }
        EXPECT_EQ(before.playableLive, engine.playableInstances.LiveCount());
        EXPECT_EQ(before.queueLive, engine.queueInstances.LiveCount());
        EXPECT_EQ(before.variableControlLive, engine.variableControlInstances.LiveCount());
        EXPECT_EQ(before.decisionLive, engine.decisions.LiveCount());
        EXPECT_EQ(before.armGroupLive, engine.armGroups.LiveCount());
        EXPECT_EQ(before.armLive, engine.timelineArms.LiveCount());
        EXPECT_EQ(before.voiceActive, engine.voices.ActiveCount());
        EXPECT_EQ(before.ledgerAvailable, engine.ledger.AvailableEntryCount());
        EXPECT_EQ(before.occurrenceOccupied, engine.timelineOccurrences.OccupiedCount());
        EXPECT_EQ(groupsBefore, engine.timelinePool.CaptureLivePlan03Groups(nullptr, 0));
        EXPECT_EQ(containerBefore, engine.containerPlayback.LiveCount());
        EXPECT_EQ(partitionBefore, engine.playablePartitions.OccupiedCount());
        ASSERT_NO_FATAL_FAILURE(ExpectBoundSourcesReleased(engine, sourceGenerations));
        for (const auto& scratch : engine.actionPlayScratch) {
            EXPECT_EQ(nullptr, scratch.row);
            EXPECT_FALSE(scratch.prepared);
            EXPECT_EQ(0u, scratch.playableTreeExecutor.OwnerTokenCount());
        }
        return;
    }
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    EXPECT_EQ(before.commandHead + commandCount, engine.commands.PublishedHead());
    EXPECT_EQ(0u, engine.commands.FreeSlots());
    std::uint32_t plays = 0, controls = 0, offset = fillerCount;
    while (offset < engine.commands.Capacity()) {
        harken::CommandRecord command{};
        ASSERT_TRUE(engine.commands.PeekAt(offset, command));
        ASSERT_EQ(harken::kOpcodePlay, command.opcode);
        const auto& batch = command.payload.play.batch;
        if (batch.batchKind == harken::PlayLedBatchKind::TimelineArm) {
            ++plays;
            EXPECT_EQ(3u, batch.batchCommandCount);
        } else {
            EXPECT_EQ(harken::PlayLedBatchKind::TimelineControlArm, batch.batchKind);
            ++controls;
            EXPECT_EQ(1u, batch.batchCommandCount);
        }
        ASSERT_NE(0u, batch.batchCommandCount);
        offset += batch.batchCommandCount;
    }
    EXPECT_EQ(4u, plays);
    EXPECT_EQ(1u, controls);
    EXPECT_EQ(engine.commands.Capacity(), offset);
}

TEST(ActionFiringApi, ImmediateNestedQueueActionBatchExactFitIncludesCompleteFrontierAndSibling) {
    ExpectImmediateNestedQueueActionBatch(NestedQueueBatchCase::ExactFit);
}

#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
TEST(ActionFiringApi, QueueNestedBoundSourcesOriginalTreePreservesExactMultiPlayBatch) {
    ExpectImmediateNestedQueueActionBatch(NestedQueueBatchCase::ExactFit, true);
}
#endif

TEST(ActionFiringApi, ImmediateNestedQueueActionBatchOneShortReclaimsPreparedOwners) {
    ExpectImmediateNestedQueueActionBatch(NestedQueueBatchCase::OneShort);
}

TEST(ActionFiringApi, ImmediateNestedQueueActionBatchLaterSiblingFailureRollsBackOwners) {
    ExpectImmediateNestedQueueActionBatch(NestedQueueBatchCase::LaterSiblingFailure);
}

