static void CheckPublishedImmediateValidationRefusal(bool afterFinish) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(4, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(512, 0.25f), second(512, -0.25f);
    auto firstPcm = harkentest::MonoDesc(first, 48000);
    auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateMixedVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto baseline = CaptureActionReclaimableOwners(*engine);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [firing](const auto& member) {
            return member.InvocationValid() && member.Invocation().actionFiring == firing &&
                !member.parentService.Valid();
        });
    ASSERT_NE(engine->playableServices.end(), row);
    const auto entry = row->frontierEntry;
    ASSERT_TRUE(entry.Valid());
    const auto lane = row->immediateLane;
    ASSERT_TRUE(lane.Valid());
    harken::TimelineTransactionProgramRef control{};
    ASSERT_TRUE(engine->decisions.CaptureFrontierControlProgram(entry.coordinator, &control));
    ASSERT_NE(nullptr, control.program);
    ASSERT_EQ(1u, control.program->payloadCount);
    const auto quantum = row->startFrame / engine->config.blockFrames;
    while (engine->mixer.BlocksRendered() < quantum) engine->nullBackend.Pump(1);
    ASSERT_EQ(quantum, engine->mixer.BlocksRendered());
    harken::FrontierActivationSidecarSnapshot before{};
    ASSERT_TRUE(engine->decisions.CaptureFrontierActivationSidecar(
        entry.coordinator, entry, quantum, &before));
    ASSERT_EQ(harken::FrontierReceiptRead::InFlight, before.receiptRead);
    ASSERT_TRUE(before.pagePinHeld);
    ASSERT_TRUE(before.observerPinHeld);
    const auto heldOwners = CaptureActionReclaimableOwners(*engine);
    const auto heldPhase = row->phase;
    struct Pause {
        std::atomic<bool> entered{false}, released{false}, done{false};
        std::uint64_t quantum = 0;
        static void Wait(void* context) {
            auto& pause = *static_cast<Pause*>(context);
            pause.entered.store(true, std::memory_order_release);
            while (!pause.released.load(std::memory_order_acquire))
                std::this_thread::yield();
        }
    } pause;
    pause.quantum = quantum;
    if (afterFinish) {
        engine->mixer.SetCurrentSliceFrontierHookForTest(
            +[](void* context, harken::MixerLoop::CurrentSliceHookPhaseForTest phase,
                std::uint64_t currentQuantum, std::size_t, std::uint32_t,
                harken::TimelinePagePrefixStopReason) noexcept {
                auto& pause = *static_cast<Pause*>(context);
                if (phase == harken::MixerLoop::CurrentSliceHookPhaseForTest::AfterExecuteBeforeApply &&
                    currentQuantum == pause.quantum) Pause::Wait(context);
            }, &pause);
    } else {
        engine->immediateActionLane.SetValidationRefusalHookForTest(&Pause::Wait, &pause);
    }
    auto* actualProgram = const_cast<harken::TimelineProgramView*>(control.program);
    actualProgram->payloadCount = 0;
    std::thread audio([&] {
        engine->nullBackend.Pump(1);
        pause.done.store(true, std::memory_order_release);
    });
    struct AudioScope {
        harken::Engine& engine;
        Pause& pause;
        std::thread& audio;
        harken::TimelineProgramView& program;
        ~AudioScope() {
            pause.released.store(true, std::memory_order_release);
            audio.join();
            program.payloadCount = 1;
            engine.immediateActionLane.SetValidationRefusalHookForTest(nullptr, nullptr);
            engine.mixer.SetCurrentSliceFrontierHookForTest(nullptr, nullptr);
        }
    };
    {
        AudioScope scope{*engine, pause, audio, *actualProgram};
        const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(10);
        while (!pause.entered.load(std::memory_order_acquire) &&
            !pause.done.load(std::memory_order_acquire) &&
            std::chrono::steady_clock::now() < deadline)
            std::this_thread::yield();
        ASSERT_TRUE(pause.entered.load(std::memory_order_acquire));
        actualProgram->payloadCount = 1;
        harken::ImmediateLaneObservation refused{};
        ASSERT_TRUE(engine->immediateActionLane.Observe(lane, &refused));
        ASSERT_TRUE(refused.protocolRefused);
        ASSERT_TRUE(refused.complete);
        ASSERT_TRUE(refused.missed);
        EXPECT_FALSE(refused.applied);
        EXPECT_FALSE(refused.claimed);
        ASSERT_EQ(quantum, engine->mixer.BlocksRendered());
        harken::ImmediateLaneValidationRefusalSnapshot unpublished{};
        EXPECT_FALSE(engine->immediateActionLane.CapturePublishedValidationRefusal(
            lane, engine->mixer.BlocksRendered(), &unpublished));
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_EQ(heldPhase, row->phase);
        EXPECT_FALSE(row->pendingImmediateRetry);
        EXPECT_EQ(heldOwners, CaptureActionReclaimableOwners(*engine));
        harken::FrontierActivationSidecarSnapshot retained{};
        ASSERT_TRUE(engine->decisions.CaptureFrontierActivationSidecar(
            entry.coordinator, entry, engine->mixer.BlocksRendered(), &retained));
        EXPECT_EQ(harken::FrontierReceiptRead::InFlight, retained.receiptRead);
        EXPECT_TRUE(retained.pagePinHeld);
        EXPECT_TRUE(retained.observerPinHeld);
    }
    ASSERT_EQ(quantum + 1u, engine->mixer.BlocksRendered());
    harken::FrontierActivationSidecarSnapshot published{};
    ASSERT_TRUE(engine->decisions.CaptureFrontierActivationSidecar(
        entry.coordinator, entry, engine->mixer.BlocksRendered(), &published));
    ASSERT_EQ(harken::FrontierReceiptRead::Ready, published.receiptRead);
    const auto* activation = engine->decisions.ResolveFrontierActivation(entry.coordinator);
    ASSERT_NE(nullptr, activation);
    harken::FrontierActivationReceipt receipt{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        activation->Read(entry, engine->mixer.BlocksRendered(), &receipt));
    EXPECT_EQ(harken::FrontierReceiptOutcome::DefinitivelyNotApplied, receipt.outcome);
    EXPECT_EQ(harken::FrontierReceiptReason::MissingMember, receipt.reason);
    EXPECT_EQ(quantum + 1u, receipt.audioSequence);
    bool heard = false;
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (unsigned block = 0; block < 96u; ++block) {
        const auto* pcm = engine->nullBackend.LastBlock();
        heard = heard || std::any_of(pcm, pcm + 64u * engine->nullBackend.Channels(),
            [](float sample) { return std::abs(sample) > 0.001f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
            engine->playablePartitions.OccupiedCount() == 0u) break;
        engine->nullBackend.Pump(1);
    }
    EXPECT_FALSE(heard);
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_TERMINAL_RUNTIME_ERROR, info.terminalReason);
    EXPECT_FALSE(row->pendingImmediateRetry);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(*engine));
}

TEST(ActionFiringApi, ImmediateValidationRefusalWaitsForCaptureRelease) {
    ASSERT_NO_FATAL_FAILURE(CheckPublishedImmediateValidationRefusal(false));
}

TEST(ActionFiringApi, ImmediateValidationRefusalWaitsForPublishedBlock) {
    ASSERT_NO_FATAL_FAILURE(CheckPublishedImmediateValidationRefusal(true));
}

static void CheckVariableControlRetargetFromSoundCompletesNestedQueueTree(
    bool continuous, bool nestedControl = false, bool emptyControl = false, bool shortSource = false,
    bool reactivateEmpty = false, bool reselectNonempty = false, bool weightCascade = false,
    bool repeatedSound = false, bool bothSides = false, std::uint32_t refusal = 0) {
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(shortSource ? 64 : (reselectNonempty || weightCascade || bothSides) ? 32768 : 1024, 0.25f),
        second((reselectNonempty || weightCascade || bothSides) ? 32768 : 1024, weightCascade ? -0.125f : -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    auto innerChild = image.queueChildren[0];
    image.MakeImmediateQueueNestedContainerPlayAction(false);
    innerChild.stableChildOrdinal = image.child.stableChildOrdinal;
    innerChild.frequencyWeight = 0;
    image.containers[0].mode = harken::ContainerModeV1::SequenceQueue;
    image.containers[0].memoryScope = harken::MemoryScopeV1::Emitter;
    image.containers[0].queueCycle = harken::QueueCycleV1::Once;
    image.containers[0].queueSplice = harken::QueueSpliceV1::Butt;
    image.containers[0].children = &innerChild;
    image.MakeImmediateVariableControlPlayAction();
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 64;
    auto outerDiscreteAxis = image.variableControlAxis;
    std::array<harken::VariableDefinitionV1, 5> variables{};
    if (bothSides) {
        std::copy(std::begin(image.variables), std::end(image.variables), variables.begin());
        variables.back() = image.variables[3];
        variables.back().variableId = harkentest::ObjectId(42);
        variables.back().defaultValue = 0.0f;
        image.world.variables = variables.data();
        image.world.variableCount = static_cast<std::uint32_t>(variables.size());
        outerDiscreteAxis.variableId = variables.back().variableId;
        image.containers[3].discreteAxes = &outerDiscreteAxis;
        image.variableControlCells[0].exactValue = 0;
    }
    const auto outerVariableId = bothSides ? variables.back().variableId
        : image.variables[continuous ? 0 : 3].variableId;
    if (continuous) {
        image.variableControlContinuousAxis = {0, 0, image.variables[0].variableId};
        for (std::uint32_t index = 0; index < 2; ++index) {
            auto& cell = image.variableControlOverlayCells[index];
            cell.kind = harken::ContinuousCellKindV1::Interval;
            cell.lower = index == 0 ? -1.0f : 0.0f;
            cell.upper = index == 0 ? 0.0f : 1.0f;
            cell.lowerInclusive = index == 0;
            cell.upperInclusive = 1;
            auto& control = image.variableControlOverlayRows[index];
            control.stableRowOrdinal = index + 3u;
            control.authoredStableOrder = index;
            control.childStableOrdinal = image.variableControlChildren[index].stableChildOrdinal;
            control.cellCount = 1;
            control.cells = &cell;
        }
        auto& program = image.containers[3];
        program.discreteTiming = 0;
        program.discreteAxisCount = 0;
        program.discreteAxes = nullptr;
        program.discreteRowCount = 0;
        program.discreteRows = nullptr;
        program.continuousAxisCount = 1;
        program.continuousAxes = &image.variableControlContinuousAxis;
        program.continuousRowCount = 2;
        program.continuousRows = image.variableControlOverlayRows;
        program.maxActiveRows = 2;
        program.maxLiveRows = 2;
    }
    auto& incoming = image.variableControlChildren[1].playable;
    incoming.kind = harken::PlayableKindV1::Container;
    incoming.stableId = image.properties[4].stableId;
    incoming.expectedProgramSemanticFingerprint = image.properties[4].programSemanticFingerprint;
    incoming.contentRevision = image.properties[4].contentRevision;
    incoming.routeStableId = image.properties[4].routeStableId;
    incoming.compatibilityFingerprint = image.properties[4].compatibilityFingerprint;
    image.occurrences[5].childPlayable = incoming;
    image.occurrences[5].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[5]);
    std::array<harken::ContainerChildProgramViewV2, 3> nestedChildren{innerChild, image.queueChildren[1], innerChild};
    std::array<harken::ContinuousGridRowViewV1, 2> nestedRows{};
    auto nestedDiscreteRow = image.variableControlRows[0];
    auto nestedDiscreteCell = image.variableControlCells[0];
    if (bothSides) nestedDiscreteCell.exactValue = 3;
    harken::ContinuousGridCellV1 nestedCell{};
    harken::ContinuousGridCellV1 nestedSecondCell{};
    const auto nestedVariableId = image.variables[weightCascade || bothSides ? 1 : 0].variableId;
    decltype(image.variableControlContinuousAxis) nestedAxis{0, 0, nestedVariableId};
    std::vector<harken::PlayableOccurrencePropertyViewV1> nestedOccurrences;
    if (nestedControl) {
        nestedChildren[1].stableChildOrdinal = nestedChildren[0].stableChildOrdinal + 1u;
        if (repeatedSound) nestedChildren[1].playable = nestedChildren[0].playable;
        nestedCell.kind = harken::ContinuousCellKindV1::Interval;
        nestedCell.lower = emptyControl ? 0.5f : reselectNonempty || bothSides ? -0.25f : -1.0f;
        nestedCell.upper = 1.0f;
        nestedCell.lowerInclusive = 1;
        nestedCell.upperInclusive = 1;
        for (std::uint32_t index = 0; index < 2; ++index) {
            nestedChildren[index].frequencyWeight = 0;
            nestedChildren[index].orderWeight = 0;
            nestedChildren[index].queueStopPolicy = harken::QueueStopPolicyV1::AbortOwningQueue;
            nestedChildren[index].timingHint = {};
            nestedRows[index].stableRowOrdinal = index + 1u;
            nestedRows[index].authoredStableOrder = index;
            nestedRows[index].childStableOrdinal = nestedChildren[index].stableChildOrdinal;
            nestedRows[index].cellCount = 1;
            nestedRows[index].cells = &nestedCell;
        }
        auto& nested = image.containers[0];
        nested.mode = harken::ContainerModeV1::VariableControl;
        nested.queueCycle = {};
        nested.queueSplice = {};
        nested.childCount = 2;
        nested.children = nestedChildren.data();
        nested.continuousAxisCount = 1;
        nested.continuousAxes = &nestedAxis;
        nested.continuousRowCount = 2;
        nested.continuousRows = nestedRows.data();
        nested.maxActiveRows = 2;
        nested.maxLiveRows = 2;
        nested.evaluationPeriodFrames = 64;
        if (continuous) image.containers[3].maxLiveRows = 3;
        if (bothSides) {
            nestedChildren[2] = nestedChildren[0];
            nestedChildren[2].stableChildOrdinal = nestedChildren[1].stableChildOrdinal + 1u;
            nestedChildren[2].authoredStableOrder = 2;
            nested.childCount = 3;
            nested.discreteTiming = 1;
            nested.discreteAxisCount = 1;
            nested.discreteAxes = &image.variableControlAxis;
            nested.discreteRowCount = 1;
            nestedDiscreteRow.childStableOrdinal = nestedChildren[2].stableChildOrdinal;
            nestedDiscreteRow.cells = &nestedDiscreteCell;
            nested.discreteRows = &nestedDiscreteRow;
            nested.maxLiveRows = 3;
            if (continuous) image.containers[3].maxLiveRows = 4;
        }
        if (weightCascade) {
            nested.continuousNormalization = 1;
            nestedCell.upper = 0.5f;
            nestedSecondCell = nestedCell;
            nestedSecondCell.lower = 0.0f;
            nestedSecondCell.upper = 1.0f;
            nestedRows[1].cells = &nestedSecondCell;
            image.containers[3].continuousNormalization = 1;
            image.containers[3].maxActiveRows = 2;
            image.variableControlOverlayCells[0].upper = 0.75f;
        }
        nestedOccurrences.assign(image.occurrences, image.occurrences + image.world.playableOccurrenceCount);
        auto extra = nestedOccurrences[0];
        extra.stableOccurrenceOrdinal = nestedChildren[1].stableChildOrdinal;
        extra.childPlayable = nestedChildren[1].playable;
        extra.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(extra);
        nestedOccurrences.insert(nestedOccurrences.begin() + 1, extra);
        if (bothSides) {
            extra.stableOccurrenceOrdinal = nestedChildren[2].stableChildOrdinal;
            extra.childPlayable = nestedChildren[2].playable;
            extra.occurrenceSemanticFingerprint = harken::ComputePlayableOccurrenceFingerprintV1(extra);
            nestedOccurrences.insert(nestedOccurrences.begin() + 2, extra);
        }
        image.world.playableOccurrences = nestedOccurrences.data();
        image.world.playableOccurrenceCount = static_cast<std::uint32_t>(nestedOccurrences.size());
    }
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    auto post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    post.emitter = emitter;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    std::vector<VnVoiceHandle> renders;
    std::vector<VnObjectId> starts;
    const auto observeStarts = [&] {
        for (const auto& installation : engine->timelineVoiceInstallIdentities) {
            if (installation.renderHandle == 0 ||
                std::find(renders.begin(), renders.end(), installation.renderHandle) != renders.end()) continue;
            harken::TimelineArmObservation arm{};
            if (!engine->timelineArms.Observe(installation.startArm, &arm) || arm.startedBlockSequence == 0) continue;
            EXPECT_EQ(installation.onsetFrame / engine->config.blockFrames + 1u, arm.startedBlockSequence)
                << "render=" << installation.renderHandle
                << " subject=" << installation.target.subjectId
                << " priorStarts=" << renders.size()
                << " onset=" << installation.onsetFrame
                << " observedBlock=" << engine->mixer.BlocksRendered();
            renders.push_back(installation.renderHandle);
            starts.push_back(installation.target.subjectId);
        }
    };
    for (std::uint32_t block = 0; block < 16 && starts.empty(); ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        observeStarts();
    }
    if (continuous) {
        ASSERT_EQ(nestedControl ? 3u : 2u, starts.size());
        EXPECT_EQ(nestedControl && repeatedSound ? 3u : 2u,
            std::count(starts.begin(), starts.end(), CanonicalActionWorld::kFirstSound));
    } else {
        ASSERT_EQ((std::vector<VnObjectId>{CanonicalActionWorld::kFirstSound}), starts);
    }
    std::vector<harken::PreparedDecisionReservation> heldDecisions;
    std::vector<VnVoiceHandle> heldVoices;
    if (refusal != 0) {
        for (std::uint32_t block = 0; block < 32; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        const auto decisionsBeforeRefusal = engine->decisions.LiveCount();
        const auto voicesBeforeRefusal = engine->voices.ActiveCount();
        if (refusal == 1) {
            heldDecisions.resize(engine->decisions.Capacity() - engine->decisions.LiveCount() - 1u);
            harken::DecisionReserveRequest request{};
            request.world = engine->variables.CurrentWorldGeneration();
            request.transport = engine->timelinePool.Epoch();
            request.expectedContinuationGeneration = 1;
            request.sliceCount = 1;
            for (auto& prepared : heldDecisions)
                ASSERT_TRUE(engine->decisions.PrepareReservation(request, &prepared));
        } else {
            heldVoices.resize(engine->voices.AvailableSlotCount() - 1u);
            const auto view = engine->registry.Lookup(CanonicalActionWorld::kFirstSound);
            for (auto& handle : heldVoices)
                ASSERT_EQ(VN_OK, engine->voices.Play(view, 0.0f, 1.0, 0, false, 0.0f, 0.0f, 0.0f,
                    harken::ResolvedPanGains{}, 0, view.frames, 1, harken::ResampleProfile::LegacyCompatibility,
                    &handle, 1, ~std::uint32_t{0}, 0, true));
        }
        const auto instances = engine->playableInstances.LiveCount();
        const auto partitions = engine->playablePartitions.OccupiedCount();
        const auto controls = engine->variableControlInstances.LiveCount();
        const auto decisions = engine->decisions.LiveCount();
        const auto voices = engine->voices.ActiveCount();
        ASSERT_EQ(VN_OK, Vn_SetValue(outerVariableId, 1.0f));
        for (std::uint32_t block = 0; block < 16; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(instances, engine->playableInstances.LiveCount());
            EXPECT_EQ(partitions, engine->playablePartitions.OccupiedCount());
            EXPECT_EQ(controls, engine->variableControlInstances.LiveCount());
            EXPECT_EQ(decisions, engine->decisions.LiveCount());
            EXPECT_EQ(voices, engine->voices.ActiveCount());
            EXPECT_NE(nullptr, engine->voices.Resolve(renders.front()));
            EXPECT_FALSE(engine->runtimeRecreateRequired);
            engine->nullBackend.Pump(1);
            observeStarts();
        }
        EXPECT_EQ(1u, starts.size());
        for (auto& prepared : heldDecisions) ASSERT_TRUE(engine->decisions.CancelPreparedReservation(&prepared));
        for (auto handle : heldVoices) ASSERT_TRUE(engine->voices.CancelPreparedVoice(handle));
        EXPECT_EQ(decisionsBeforeRefusal, engine->decisions.LiveCount());
        EXPECT_EQ(voicesBeforeRefusal, engine->voices.ActiveCount());
    }
    ASSERT_EQ(VN_OK, Vn_SetValue(outerVariableId,
        continuous && emptyControl ? 0.25f : 1.0f));
    bool nestedQueuesActivated = false;
    std::uint64_t nestedEntryQuantum = 0;
    bool observedPreparedControl = false;
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (nestedControl && !continuous) {
            for (const auto& control : engine->playableServices) {
                if (control.variableControlDiscreteRetargetIncomingNestedVariableControlCount != 0) {
                    nestedEntryQuantum = control.variableControlDiscreteRetargetEnteringSchedule.entryAnchorFrame /
                        engine->config.blockFrames + 1u;
                }
                if (control.variableControlRetargetIncomingNestedVariableControlCount != 0) {
                    nestedEntryQuantum = control.variableControlRetargetFrame / engine->config.blockFrames + 1u;
                }
            }
            if (nestedEntryQuantum > engine->mixer.BlocksRendered()) {
                for (const auto& child : engine->playableServices) {
                    if (!child.variableControlInstance.Valid() || !child.parentService.Valid()) continue;
                    EXPECT_NE(harken::PlayableControlLifecycle::Active, child.controlLifecycle);
                    observedPreparedControl = true;
                }
            }
        }
        engine->nullBackend.Pump(1);
        observeStarts();
        for (const auto& child : engine->playableServices) {
            if (!(nestedControl ? child.variableControlIndependentFrontier : child.queueInstance.Valid()) ||
                !child.parentService.Valid()) continue;
            const auto* parent = engine->ResolvePlayableService(child.parentService);
            if (nestedControl && child.controlLifecycle == harken::PlayableControlLifecycle::Active) {
                EXPECT_NE(0u, child.lastAppliedBlockSequence);
                EXPECT_LE(child.lastAppliedBlockSequence, engine->mixer.BlocksRendered());
                if (!continuous) EXPECT_EQ(nestedEntryQuantum, child.lastAppliedBlockSequence);
            }
            nestedQueuesActivated = nestedQueuesActivated ||
                (parent != nullptr && parent->queueInstance.Valid() &&
                 child.lastAppliedBlockSequence != 0 &&
                 child.controlLifecycle >= harken::PlayableControlLifecycle::Active);
        }
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    EXPECT_EQ(!shortSource, nestedQueuesActivated);
    if (refusal != 0) {
        for (const auto& service : engine->playableServices) {
            if (!service.variableControlInstance.Valid()) continue;
            harken::VariableControlInstanceSnapshot snapshot{};
            engine->variableControlInstances.Capture(service.variableControlInstance, &snapshot);
        }
    }
    if (nestedControl && !continuous) EXPECT_EQ(!shortSource, observedPreparedControl);
    auto expectedStarts = shortSource
        ? std::vector<VnObjectId>{CanonicalActionWorld::kFirstSound}
        : std::vector<VnObjectId>{CanonicalActionWorld::kFirstSound,
            CanonicalActionWorld::kFirstSound,
            repeatedSound ? CanonicalActionWorld::kFirstSound : CanonicalActionWorld::kSecondSound};
    if (nestedControl && !shortSource && !reselectNonempty && !weightCascade && !bothSides)
        expectedStarts.push_back(CanonicalActionWorld::kSecondSound);
    if (bothSides) {
        EXPECT_EQ(4u, starts.size());
        EXPECT_EQ(3u, std::count(starts.begin(), starts.end(), CanonicalActionWorld::kFirstSound));
        EXPECT_EQ(1u, std::count(starts.begin(), starts.end(), CanonicalActionWorld::kSecondSound));
    } else EXPECT_EQ(expectedStarts, starts);
    if (bothSides) {
        harken::EnginePlayableServiceReference inner{};
        for (const auto& controller : engine->playableServices)
            if (controller.variableControlInstance.Valid() && controller.parentService.Valid())
                inner = {controller.identity, controller.ownerInstance, controller.ownerEpoch, controller.invocationGeneration};
        ASSERT_TRUE(inner.Valid());
        const auto checkMembers = [&](std::uint32_t discrete, std::uint32_t continuousMembers) {
            const auto* controller = engine->ResolvePlayableService(inner);
            ASSERT_NE(nullptr, controller);
            EXPECT_EQ(discrete, controller->variableControlDiscreteMemberCount);
            EXPECT_EQ(continuousMembers, controller->variableControlContinuousMemberCount);
            harken::VariableControlInstanceSnapshot snapshot{};
            ASSERT_TRUE(engine->variableControlInstances.Capture(controller->variableControlInstance, &snapshot));
            EXPECT_EQ(harken::VariableControlSideState::Committed, snapshot.discrete.state);
            EXPECT_EQ(harken::VariableControlSideState::Committed, snapshot.continuous.state);
            EXPECT_FALSE(engine->runtimeRecreateRequired);
        };
        const auto pump = [&] {
            for (std::uint32_t block = 0; block < 48; ++block) {
                EXPECT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
                observeStarts();
                EXPECT_FALSE(engine->runtimeRecreateRequired);
            }
        };
        checkMembers(1, 2);
        ASSERT_EQ(VN_OK, Vn_SetValue(image.variables[3].variableId, 2.0f));
        pump();
        checkMembers(0, 2);
        EXPECT_EQ(2u, engine->voices.ActiveCount());
        ASSERT_EQ(VN_OK, Vn_SetValue(image.variables[3].variableId, 3.0f));
        pump();
        checkMembers(1, 2);
        ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, nestedVariableId, -0.5f));
        pump();
        checkMembers(1, 2);
        EXPECT_EQ(3u, engine->voices.ActiveCount());
        ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, nestedVariableId, 0.0f));
        pump();
        checkMembers(1, 2);
        EXPECT_EQ(3u, engine->voices.ActiveCount());
        EXPECT_EQ(5u, renders.size());
        ASSERT_EQ(VN_OK, Vn_SetValue(image.variables[3].variableId, 2.0f));
        pump();
        checkMembers(0, 2);
        ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, nestedVariableId, -0.5f));
        pump();
        EXPECT_TRUE(engine->playableInstances.Classify(inner.owner).live);
        EXPECT_EQ(2u, engine->voices.ActiveCount());
    }
    if (weightCascade) {
        harken::EnginePlayableServiceReference outer{}, inner{};
        for (const auto& controller : engine->playableServices) {
            if (!controller.variableControlInstance.Valid()) continue;
            const harken::EnginePlayableServiceReference reference{controller.identity, controller.ownerInstance,
                controller.ownerEpoch, controller.invocationGeneration};
            if (controller.parentService.Valid()) inner = reference;
            else outer = reference;
        }
        ASSERT_TRUE(outer.Valid());
        ASSERT_TRUE(inner.Valid());
        const auto pump = [&] {
            for (std::uint32_t block = 0; block < 32; ++block) {
                EXPECT_EQ(VN_OK, Vn_Update());
                EXPECT_FALSE(engine->runtimeRecreateRequired);
                engine->nullBackend.Pump(1);
                observeStarts();
            }
        };
        const auto freshOutput = [&] {
            const auto before = engine->mixer.BlocksRendered();
            engine->nullBackend.Pump(1);
            EXPECT_EQ(before + 1u, engine->mixer.BlocksRendered());
            return engine->nullBackend.LastBlock()[0];
        };
        const auto checkWeights = [&](VnVoiceHandle render, float outerWeight, float innerWeight) {
            const auto* voice = engine->voices.Resolve(render);
            ASSERT_NE(nullptr, voice);
            for (const auto& expected : std::array{
                    std::pair{outer, outerWeight}, std::pair{inner, innerWeight}}) {
                bool found = false;
                for (std::uint32_t index = 0; index < voice->variableWeightControlCount; ++index) {
                    const auto& binding = voice->variableWeightControls[index];
                    if (binding.owner.instance != expected.first.owner ||
                        binding.owner.scheduleEpoch != expected.first.epoch || binding.owner.side != 1) continue;
                    found = true;
                    EXPECT_TRUE(binding.active);
                    EXPECT_FLOAT_EQ(expected.second, binding.segment.endWeight);
                    EXPECT_LE(binding.segment.endFrame, engine->mixer.BlocksRendered() * engine->config.blockFrames);
                }
                EXPECT_TRUE(found);
            }
        };
        ASSERT_EQ(3u, renders.size());
        checkWeights(renders[1], 1.0f, 0.5f);
        checkWeights(renders[2], 1.0f, 0.5f);
        ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, nestedVariableId, 0.75f));
        pump();
        checkWeights(renders[1], 1.0f, 0.0f);
        checkWeights(renders[2], 1.0f, 1.0f);
        const auto innerOnlyOutput = freshOutput();
        EXPECT_GT(std::abs(innerOnlyOutput), 0.01f);
        ASSERT_EQ(VN_OK, Vn_SetEmitterValue(emitter, nestedVariableId, 0.0f));
        pump();
        ASSERT_EQ(3u, renders.size());
        const auto newRender = renders[1];
        checkWeights(newRender, 1.0f, 0.5f);
        EXPECT_NEAR(repeatedSound ? innerOnlyOutput : -0.5f * innerOnlyOutput, freshOutput(), 0.0001f);
        ASSERT_EQ(VN_OK, Vn_SetValue(image.variables[0].variableId, 0.5f));
        pump();
        checkWeights(newRender, 0.5f, 0.5f);
        EXPECT_NEAR(repeatedSound ? innerOnlyOutput : -1.25f * innerOnlyOutput, freshOutput(), 0.0001f);
        ASSERT_NE(nullptr, engine->ResolvePlayableService(inner));
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    if (reselectNonempty) {
        harken::EnginePlayableServiceReference originalController{};
        for (const auto& child : engine->playableServices)
            if (child.variableControlInstance.Valid() && child.parentService.Valid())
                originalController = {child.identity, child.ownerInstance, child.ownerEpoch, child.invocationGeneration};
        ASSERT_TRUE(originalController.Valid());
        ASSERT_EQ(VN_OK, Vn_SetValue(nestedVariableId, -0.5f));
        for (std::uint32_t block = 0; block < 32; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_TRUE(engine->playableInstances.Classify(originalController.owner).live);
        EXPECT_EQ(2u, engine->voices.ActiveCount());
        ASSERT_EQ(VN_OK, Vn_SetValue(nestedVariableId, 0.0f));
        for (std::uint32_t block = 0; block < 64; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            observeStarts();
        }
        EXPECT_EQ((std::vector<VnObjectId>{CanonicalActionWorld::kFirstSound,
            CanonicalActionWorld::kFirstSound, CanonicalActionWorld::kSecondSound}), starts);
        ASSERT_TRUE(engine->playableInstances.Classify(originalController.owner).live);
    }
    if (reactivateEmpty) {
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(*engine, firing, &info));
        const auto completedStarts = starts;
        ASSERT_EQ(VN_OK, Vn_SetValue(nestedVariableId, 1.0f));
        for (std::uint32_t block = 0; block < 64; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            observeStarts();
            EXPECT_FALSE(engine->runtimeRecreateRequired);
        }
        EXPECT_EQ(completedStarts, starts);
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
        for (std::uint32_t block = 0; block < 128; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            observeStarts();
        }
        EXPECT_EQ(continuous ? 8u : 7u, starts.size());
        EXPECT_EQ(continuous ? 4u : 3u,
            std::count(starts.begin(), starts.end(), CanonicalActionWorld::kFirstSound));
        EXPECT_EQ(4u, std::count(starts.begin(), starts.end(), CanonicalActionWorld::kSecondSound));
    }
    if (!reselectNonempty && !weightCascade && !bothSides) {
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(*engine, firing, &info));
    }
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    for (std::uint32_t block = 0; block < 64; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->variableControlInstances.LiveCount());
    EXPECT_EQ(0u, engine->decisions.LiveCount());
    EXPECT_EQ(0u, engine->armGroups.LiveCount());
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

