TEST(ActionFiringApi, ImmediateConsumerDebtArithmeticRejectsUnreachableOrWrappedInputs) {
    const auto reachable = harken::detail::ActionConsumerCanReachImmediateQuantum;
    EXPECT_TRUE(reachable(104, 100, 100, 256, 0, 8));
    EXPECT_TRUE(reachable(104, 101, 100, 256, 0, 8));
    EXPECT_FALSE(reachable(100, 101, 100, 256, 16, 8));
    EXPECT_FALSE(reachable(99, 99, 100, 256, 16, 8));
    EXPECT_TRUE(reachable(104, 99, 100, 256, 16, 8));
    EXPECT_TRUE(reachable(104, 97, 100, 256, 16, 8));
    EXPECT_FALSE(reachable(104, 96, 100, 256, 16, 8));
    EXPECT_FALSE(reachable(104, 99, 100, 256, 15, 8));
    EXPECT_FALSE(reachable(104, 97, 100, 2, 16, 8));
    EXPECT_TRUE(reachable(101, 100, 100, 256, 16, 8));
    EXPECT_FALSE(reachable(101, 99, 100, 256, 16, 8));
    EXPECT_FALSE(reachable(100, 99, 100, 256, 16, 8));
    EXPECT_FALSE(reachable(UINT64_MAX, UINT64_MAX - 2, UINT64_MAX - 1, 256, 16, 8));
    EXPECT_TRUE(reachable(UINT64_MAX, UINT64_MAX - 4, UINT64_MAX - 3, 256, 16, 8));
    EXPECT_FALSE(reachable(UINT64_MAX, 0, UINT64_MAX - 1, 256, 16, 8));
    EXPECT_FALSE(reachable(UINT64_MAX - 1, UINT64_MAX, UINT64_MAX - 1, 256, 16, 8));
}

class ImmediateConsumerDebtTest : public testing::TestWithParam<ImmediateConsumerDebtSetup> {};

TEST_P(ImmediateConsumerDebtTest, AdmissionPreservesOriginalOnsetOrRefusesBeforeAllocation) {
    const auto setup = GetParam();
    ExpectImmediateVariableControlNestedQueueInitialTreeStopsAndReclaims(false, false, 0, false, false, &setup);
}

