TEST(ActionFiringApi, ImmediateQueueDescendantKeepsExactLaneIdentity) {
    harken::Plan03GroupSliceIdentity lane{};
    lane.absoluteQuantum = 0;
    lane.pageGeneration = 1;
    lane.decision = {7, 11};
    lane.sliceIndex = 3;
    lane.committedRow = 17;
    lane.rowClaimGeneration = 19;
    lane.transportEpoch = 23;
    lane.backing = harken::Plan03GroupBacking::ImmediateLane;
    harken::FrontierImmediateLaneMemberIdentity compact{};
    ASSERT_TRUE(compact.Capture(lane));
    EXPECT_EQ(lane, compact.Expand());
    EXPECT_EQ(32u, sizeof(compact));
    harken::FrontierVariableSideIdentity side{};
    side.slot = 2;
    side.generation = 5;
    side.side = 1;
    side.sideGeneration = 29;
    side.bankSlot = 31;
    side.bankGeneration = 37;
    harken::FrontierQueueDescendantIdentity descendant{};
    ASSERT_TRUE(descendant.Freeze(lane, side));
    EXPECT_EQ(lane, descendant.selectedSideMember.Expand());
    EXPECT_EQ(side, descendant.selectedSide);
    EXPECT_EQ(64u, sizeof(descendant));
    EXPECT_FALSE(descendant.Empty());

    for (auto invalid : {
             [&] { auto value = lane; value.backing = harken::Plan03GroupBacking::Page; return value; }(),
             [&] { auto value = lane; value.absoluteQuantum = 1; return value; }(),
             [&] { auto value = lane; value.pageGeneration = 2; return value; }()}) {
        harken::FrontierImmediateLaneMemberIdentity rejected{};
        EXPECT_FALSE(rejected.Capture(invalid));
        EXPECT_TRUE(rejected.Empty());
    }
}

static void ExpectImmediateVariableControlNestedRetargetPromotesCompleteInstanceTree(
    std::uint32_t playableCapacity = 0, std::uint32_t modeCapacity = 0,
    bool holdPreparationScratch = false, bool stopAll = false) {
    (void)Vn_Term();
    harkentest::PlayableCapacityScope limits(playableCapacity, modeCapacity);
    VnConfig config = harkentest::MakeNullConfig(6, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(2048, 0.25f);
    std::vector<float> second(2048, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(
                         CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateNestedVariableControlRetargetPlayAction();
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 64;
    auto nestedSelection = image.variableControlRows[0];
    const auto nestedCell = image.variableControlCells[1];
    nestedSelection.cells = &nestedCell;
    image.containers[1].discreteRows = &nestedSelection;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto playableBaseline = engine->playableInstances.LiveCount();
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    harkentest::PlayableStorageObservation storage(*engine, playableCapacity != 0);
    const auto Vn_PostAction = [&](const VnPostActionDesc* post, VnActionFiringHandle* handle) {
        return storage.Measure([&] { return ::Vn_PostAction(post, handle); });
    };
    const auto Vn_Update = [&] { return storage.Measure([] { return ::Vn_Update(); }); };
    const auto Vn_StopActionFiring = [&](VnActionFiringHandle handle, std::uint32_t fade) {
        return storage.Measure([&] {
            return stopAll ? ::Vn_StopAll(fade) : ::Vn_StopActionFiring(handle, fade);
        });
    };
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    ASSERT_NE(0u, play.producedPlayableInstance);
    VnActionStepResult setValue{};
    setValue.structSize = sizeof(setValue);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    float currentVariableValue = 0.0f;
    ASSERT_TRUE(engine->variables.CurrentValue(
        image.variables[3].variableId, &currentVariableValue));
    EXPECT_FLOAT_EQ(3.0f, currentVariableValue);
    auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_NE(harken::EnginePlayableStartPhase::Free, row->phase)
        << "play state=" << play.state
        << " leaf=" << row->leaf.stableId
        << " root=" << row->rootInstance;
    const auto outgoingChild = row->variableControlChildInstances[0];
    ASSERT_NE(0u, outgoingChild);
    const auto original = CaptureOriginalSource(*engine, row->variableControlLeafInstances[0]);
    if (holdPreparationScratch) {
        engine->servicePreparedScheduleLeavesInUse = true;
        auto& sentinel = engine->servicePreparedScheduleLeaves[0].startOffsetFrames;
        sentinel = UINT64_C(0x12345678);
        for (std::uint32_t block = 0; block < 8; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            storage.Pump(1);
            EXPECT_FALSE(row->variableControlDiscreteRetargetPrepared);
            EXPECT_EQ(UINT64_C(0x12345678), sentinel);
            EXPECT_TRUE(engine->servicePreparedScheduleLeavesInUse);
        }
        engine->servicePreparedScheduleLeavesInUse = false;
    }
    bool prepared = false;
    for (std::uint32_t block = 0; block < 64 && !prepared; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        storage.Pump(1);
        prepared = row->variableControlDiscreteRetargetPrepared;
    }
    ASSERT_TRUE(prepared)
        << "phase=" << static_cast<int>(row->phase)
        << " lifecycle=" << static_cast<int>(row->controlLifecycle)
        << " leaf=" << row->leaf.stableId
        << " childOrdinal=" << row->variableControlDiscreteCurrentChildOrdinal
        << " nextFrame=" << row->variableControlDiscreteNextEvaluationFrame
        << " runtimeRecreate=" << engine->runtimeRecreateRequired;
    EXPECT_FALSE(engine->servicePreparedScheduleLeavesInUse);
    ASSERT_EQ(1u, row->variableControlDiscreteRetargetIncomingLeafCount);
    EXPECT_EQ(1u, row->variableControlDiscreteRetargetIncomingNestedCount);
    ASSERT_GE(row->variableControlDiscreteRetargetIncomingContainerCount, 2u);
    EXPECT_EQ(playableBaseline + 5u,
              engine->playableInstances.LiveCount());
    const auto incomingRoot = row->variableControlDiscreteRetargetIncomingChild;
    const auto nestedRoot =
        row->variableControlDiscreteRetargetIncomingContainers[0];
    const auto nestedChild =
        row->variableControlDiscreteRetargetIncomingContainers[1];
    ASSERT_EQ(incomingRoot, nestedRoot);
    ASSERT_EQ(row->rootInstance,
              engine->playableInstances.Classify(nestedRoot).parent);
    ASSERT_EQ(nestedRoot,
              engine->playableInstances.Classify(nestedChild).parent);
    const auto incomingLeaf =
        row->variableControlDiscreteRetargetIncomingLeaves[0];
    ASSERT_EQ(nestedChild,
              engine->playableInstances.Classify(incomingLeaf).parent);

    ASSERT_EQ(1u, row->variableControlDiscreteRetargetIncomingNestedVariableControlCount);
    auto* nestedControlService = engine->ResolvePlayableService(
        row->variableControlDiscreteRetargetIncomingNestedServices[0]);
    ASSERT_NE(nullptr, nestedControlService);
    EXPECT_EQ(nestedRoot, nestedControlService->ownerInstance);
    const auto resource = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [nestedChild](const auto& service) { return service.partition.Valid() && service.ownerInstance == nestedChild; });
    ASSERT_NE(engine->playableServices.end(), resource);
    auto* resourceService = &*resource;
    ASSERT_NE(nullptr, resourceService);
    EXPECT_EQ(nestedChild, resourceService->ownerInstance);
    EXPECT_NE(row->partition.slot, resourceService->partition.slot);
    const auto incomingSource = CaptureOriginalSource(*engine, incomingLeaf);
    const auto* sourceRecord = engine->sourceTerminals.Resolve(incomingSource.token);
    ASSERT_NE(nullptr, sourceRecord);
    EXPECT_EQ(resourceService, engine->ResolveSourceResourceOwner(sourceRecord->resourceOwner));
    const auto incomingReference = engine->playableMemberReferences[
        row->scheduleStorageBase + row->variableControlDiscreteTransitionOffset];
    harken::EnginePlayableServiceRow* referenceOwner = nullptr;
    std::size_t incomingPhysicalSlot = 0;
    ASSERT_TRUE(engine->ResolvePlayableMember(incomingReference, &referenceOwner, &incomingPhysicalSlot));
    EXPECT_EQ(resourceService, referenceOwner);
    EXPECT_EQ(incomingLeaf, engine->variableControlMemberCompletions[incomingPhysicalSlot].leafInstance);
    const auto programSlot = engine->playableStorage.InitialProgramBase(resourceService->partition.slot) +
        incomingReference.memberOffset;
    const auto& ownedProgram = engine->variableControlSchedules[programSlot];
    const auto* originalMember = &engine->variableControlMemberCompletions[incomingPhysicalSlot];
    const auto* originalRuntime = ownedProgram.runtimeProgram.program;
    const auto* originalEvents = ownedProgram.events;
    ASSERT_EQ(&engine->variableControlRuntimePrograms[programSlot], originalRuntime);
    ASSERT_NE(nullptr, originalRuntime);
    const auto* originalPayloads = originalRuntime->payloads;
    EXPECT_EQ(incomingLeaf, ownedProgram.ownerInstance);
    EXPECT_EQ(&engine->playableScheduleEvents[
        engine->playableStorage.CurrentEventBase(resourceService->partition.slot) +
        2u * incomingReference.memberOffset], originalEvents);
    EXPECT_EQ(&engine->playableSchedulePayloads[
        engine->playableStorage.CurrentEventBase(resourceService->partition.slot) +
        2u * incomingReference.memberOffset], originalPayloads);

    bool promoted = false;
    for (std::uint32_t block = 0; block < 96 && !promoted; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        storage.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        promoted = row->variableControlDiscreteRetargetSourceExited &&
            row->variableControlChildInstances[0] == incomingRoot;
    }
    ASSERT_TRUE(promoted);
    EXPECT_EQ(incomingRoot, row->variableControlChildInstances[0]);
    EXPECT_EQ(row->variableControlDiscreteRetargetIncomingContainerCount,
              row->variableControlNestedContainerCount);
    EXPECT_EQ(incomingRoot, row->variableControlNestedContainerInstances[0]);
    EXPECT_EQ(incomingLeaf, row->variableControlLeafInstances[0]);
    const auto promotedReference = engine->playableMemberReferences[row->scheduleStorageBase];
    EXPECT_EQ(incomingReference.service.token, promotedReference.service.token);
    EXPECT_EQ(incomingReference.partitionGeneration, promotedReference.partitionGeneration);
    EXPECT_EQ(incomingReference.memberOffset, promotedReference.memberOffset);
    EXPECT_EQ(incomingReference.leaf, promotedReference.leaf);
    EXPECT_EQ(incomingReference.leafEpoch, promotedReference.leafEpoch);
    EXPECT_EQ(originalRuntime, ownedProgram.runtimeProgram.program);
    EXPECT_EQ(originalEvents, ownedProgram.events);
    EXPECT_EQ(originalPayloads, ownedProgram.runtimeProgram.program->payloads);
    EXPECT_EQ(originalMember, &engine->variableControlMemberCompletions[incomingPhysicalSlot]);
    ASSERT_NO_FATAL_FAILURE(ExpectOriginalSourceRetiresAfterLaterBlock(*engine, original));
    EXPECT_FALSE(engine->playableInstances.Classify(outgoingChild).live);

    ASSERT_EQ(VN_OK, Vn_StopActionFiring(firing, 0));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        storage.Pump(1);
        if (engine->playablePartitions.Owns(resourceService->partition, resourceService->identity)) {
            EXPECT_EQ(originalRuntime, ownedProgram.runtimeProgram.program);
            EXPECT_EQ(originalEvents, ownedProgram.events);
            EXPECT_EQ(originalPayloads, ownedProgram.runtimeProgram.program->payloads);
            EXPECT_EQ(originalMember, &engine->variableControlMemberCompletions[incomingPhysicalSlot]);
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(playableBaseline, engine->playableInstances.LiveCount());
    EXPECT_FALSE(engine->playableInstances.Classify(incomingRoot).live);
    EXPECT_FALSE(engine->playableInstances.Classify(nestedChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(incomingLeaf).live);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (std::uint32_t block = 0; block < 16 && engine->playablePartitions.OccupiedCount() != 0; ++block) {
        storage.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    storage.Finish();
}

TEST(ActionFiringApi, ImmediateVariableControlNestedRetargetPromotesCompleteInstanceTree) {
    ExpectImmediateVariableControlNestedRetargetPromotesCompleteInstanceTree();
}

