void ExpectAuthoredStopOnlyMatchesNestedVariableControlOuterTarget(
    bool packEntry, bool cancelStopObserver) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(65536, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    if (!packEntry) {
        ASSERT_EQ(VN_OK,
                  Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    }
    const float* channels[] = {samples.data()};
    std::uint64_t contentRevision = 0;
    ASSERT_TRUE(harken::ComputeMediaPcmContentRevisionV1(
        48000, 1, samples.size(), channels, 1, &contentRevision));
    CanonicalActionWorld image(contentRevision, 1);
    image.MakeImmediateRandomToVariableControlPlayAction();

    // Build a second outer target around the same nested VariableControl.
    image.containers[2] = image.containers[0];
    image.containers[2].containerStableId = image.properties[4].stableId;
    image.containers[2].programSemanticFingerprint =
        image.properties[4].programSemanticFingerprint;
    image.containers[2].authoredStableOrder = 2;
    image.world.identity.capabilityMask &=
        ~harken::kWorldCapabilitySequenceQueue;
    image.occurrences[2].parentStableId = image.properties[4].stableId;
    image.occurrences[2].parentProgramSemanticFingerprint =
        image.properties[4].programSemanticFingerprint;
    image.occurrences[2].stableOccurrenceOrdinal =
        image.nestedVariableControlChild.stableChildOrdinal;
    image.occurrences[2].childPlayable =
        image.nestedVariableControlChild.playable;
    image.occurrences[2].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[2]);
    image.occurrences[3] = image.occurrences[4];
    image.occurrences[4] = image.occurrences[5];
    image.world.playableOccurrenceCount = 5;

    image.steps[12] = image.steps[11];
    image.steps[12].authoredEventIndex = 1;
    image.steps[12].target.stableId = image.containers[2].containerStableId;
    image.steps[12].target.expectedProgramSemanticFingerprint =
        image.containers[2].programSemanticFingerprint;
    image.actions[9].stepCount = 2;
    image.actions[9].expandedStepOccurrenceCount = 2;
    image.actions[9].expandedFiringCount = 1;
    image.actions[9].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[9]);

    image.steps[14] = image.steps[11];
    image.steps[14].opcode = harken::ActionOpcodeV1::Stop;
    image.steps[14].authoredEventIndex = 0;
    SetAbsoluteTime(&image.steps[14].delay);
    SetAbsoluteTime(&image.steps[14].fade);
    SetAbsoluteTime(&image.steps[14].cooldown);
    image.actions[10] = {};
    image.actions[10].actionStableId = harkentest::ObjectId(51);
    image.actions[10].steps = &image.steps[14];
    image.actions[10].stepCount = 1;
    image.actions[10].expandedStepOccurrenceCount = 1;
    image.actions[10].expandedFiringCount = 1;
    image.actions[10].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[10]);
    image.world.actions = &image.actions[9];
    image.world.actionCount = 2;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    EXPECT_EQ(harken::WorldInstallStatus::Ok,
              harken::ValidateCurrentWorldV1(image.world))
        << "actions";
    if (packEntry) {
        ASSERT_EQ(VN_OK, LoadAuthoredStopNestedVariableControlPackForTest(
                             image.world, CanonicalActionWorld::kFirstSound,
                             samples));
    } else {
        ASSERT_EQ(harken::WorldInstallStatus::Ok,
                  harken::InstallContainerWorldV1(*engine, image.world).status);
    }

    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = emitter;
    VnActionFiringHandle playFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &playFiring));

    VnActionStepResult firstPlay{};
    firstPlay.structSize = sizeof(firstPlay);
    VnActionStepResult secondPlay{};
    secondPlay.structSize = sizeof(secondPlay);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(playFiring, 0, &firstPlay));
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(playFiring, 1, &secondPlay));
    ASSERT_NE(0u, firstPlay.producedPlayableInstance);
    ASSERT_NE(0u, secondPlay.producedPlayableInstance);
    EXPECT_NE(firstPlay.producedPlayableInstance,
              secondPlay.producedPlayableInstance);

    const auto findRow = [engine](harken::PlayableInstanceHandle outerRoot) {
        return std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [outerRoot](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.InvocationValid() && candidate.Invocation().variableControlOuterRootInstance ==
                       outerRoot;
            });
    };
    const auto firstIt = findRow(firstPlay.producedPlayableInstance);
    const auto secondIt = findRow(secondPlay.producedPlayableInstance);
    ASSERT_NE(engine->playableServices.end(), firstIt);
    ASSERT_NE(engine->playableServices.end(), secondIt);
    EXPECT_EQ(harken::PlayableControlLifecycle::Preparing,
              firstIt->controlLifecycle);
    EXPECT_EQ(harken::PlayableControlLifecycle::Preparing,
              secondIt->controlLifecycle);

    const auto firstInnerRoot = firstIt->rootInstance;
    const auto secondInnerRoot = secondIt->rootInstance;
    std::vector<harken::VoiceReleaseObserver> firstObservers;
    std::vector<harken::VoiceReleaseObserver> secondObservers;
    for (const auto& identity : engine->timelineVoiceInstallIdentities) {
        if (identity.renderHandle == 0) {
            continue;
        }
        if (identity.rootInstance == firstInnerRoot) {
            firstObservers.push_back(identity.releaseObserver);
        } else if (identity.rootInstance == secondInnerRoot) {
            secondObservers.push_back(identity.releaseObserver);
        }
    }
    ASSERT_FALSE(firstObservers.empty());
    ASSERT_FALSE(secondObservers.empty());
    if (!cancelStopObserver) {
        const auto before = engine->mixer.BlocksRendered();
        for (std::uint32_t block = 0; block < 320; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_GT(engine->mixer.BlocksRendered(), before);
        for (const auto& observer : firstObservers) {
            ASSERT_FALSE(engine->voices.ReleaseObserved(observer));
        }
        for (const auto& observer : secondObservers) {
            ASSERT_FALSE(engine->voices.ReleaseObserved(observer));
        }
    }

    desc.actionId = image.actions[10].actionStableId;
    VnActionFiringHandle stopFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &stopFiring));
    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(1u, stop.remainingPlayableCount);
    EXPECT_EQ(harken::PlayableControlLifecycle::Cancelling,
              firstIt->controlLifecycle);
    if (cancelStopObserver) {
        EXPECT_EQ(harken::PlayableControlLifecycle::Preparing,
                  secondIt->controlLifecycle);
    }
    EXPECT_TRUE(engine->playableInstances.Classify(
                    secondPlay.producedPlayableInstance)
                    .live);
    EXPECT_FALSE(engine->runtimeRecreateRequired);

    VnActionFiringInfo stopInfo{};
    stopInfo.structSize = sizeof(stopInfo);
    if (!cancelStopObserver) {
        const auto before = engine->mixer.BlocksRendered();
        for (std::uint32_t block = 0; block < 64; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_GT(engine->mixer.BlocksRendered(), before);
        EXPECT_FALSE(engine->playableInstances.Classify(firstInnerRoot).live);
        EXPECT_FALSE(engine->playableInstances.Classify(
                         firstPlay.producedPlayableInstance).live);
        EXPECT_TRUE(engine->playableInstances.Classify(secondInnerRoot).live);
        EXPECT_TRUE(engine->playableInstances.Classify(
                        secondPlay.producedPlayableInstance).live);
        for (const auto& observer : firstObservers) {
            EXPECT_TRUE(engine->voices.ReleaseObserved(observer));
        }
        for (const auto& observer : secondObservers) {
            EXPECT_FALSE(engine->voices.ReleaseObserved(observer));
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(stopFiring, 0, &stop));
        EXPECT_EQ(0u, stop.remainingPlayableCount);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(stopFiring, &stopInfo));
        EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, stopInfo.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, stopInfo.outcome);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(stopFiring, 0));
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(stopFiring, &stopInfo));
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, stopInfo.state);
    if (cancelStopObserver) {
        EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, stopInfo.outcome);
    }
    ASSERT_EQ(VN_OK, Vn_StopActionFiring(playFiring, 0));
    VnActionFiringInfo playInfo{};
    playInfo.structSize = sizeof(playInfo);
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(playFiring, &playInfo));
        if (playInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, playInfo.state);
    EXPECT_FALSE(engine->playableInstances.Classify(
                     firstPlay.producedPlayableInstance)
                     .live);
    EXPECT_FALSE(engine->playableInstances.Classify(
                     secondPlay.producedPlayableInstance)
                     .live);

    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(stopFiring));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(playFiring));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(emitter));
}

