TEST(ActionFiringApi,
     ImmediateVariableControlPlayUsesEarlierPreparedSetValue) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(2, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeSetValueThenImmediateVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const VnVariableId axis = image.variables[3].variableId;
    float committedValue = 0.0f;
    harken::BankVersionToken committedBank{};
    ASSERT_TRUE(engine->variables.CaptureCurrentBank(
        0, &axis, 1, &committedValue, &committedBank));
    ASSERT_FLOAT_EQ(3.0f, committedValue);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_TRUE(engine->variables.CaptureCurrentBank(
        0, &axis, 1, &committedValue, &committedBank));
    EXPECT_FLOAT_EQ(3.0f, committedValue);

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &play));
    EXPECT_EQ(VN_ACTION_OPCODE_PLAY, play.opcode);
    ASSERT_NE(0u, play.producedPlayableInstance);
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound, row->leaf.stableId);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

static harken::EngineActionPlayScratch* FindScratchForOriginalPreparedVoice(
    harken::Engine& engine, const harken::EnginePreparedTimelineVoiceStart& voice) {
    for (auto& scratch : engine.actionPlayScratch)
        for (auto& original : scratch.voiceStarts)
            if (&original == &voice) return &scratch;
    return nullptr;
}

static void ExpectActualParentLinkHoldGuards(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) {
    auto& executor = scratch.playableTreeExecutor;
    ASSERT_TRUE(executor.ParentLinkProofHeld());
    ASSERT_TRUE(executor.InstanceCommitProofsHeld());
    ASSERT_TRUE(executor.Validate());
    const auto root = scratch.instance.Handle();
    ASSERT_TRUE(engine.playableInstances.ParentLinksHeld(root));
    const auto baseline = CaptureActionReclaimableOwners(engine);
    unsigned children = 0;
    for (const auto& original : scratch.variableControlChildren) {
        if (!original.Valid()) continue;
        ++children;
        EXPECT_TRUE(engine.playableInstances.ParentLinksHeld(original.Handle()));
        EXPECT_FALSE(engine.playableInstances.Classify(original.Handle()).live);
    }
    for (const auto& original : scratch.variableControlLeafChildren) {
        if (!original.Valid()) continue;
        ++children;
        EXPECT_TRUE(engine.playableInstances.ParentLinksHeld(original.Handle()));
        EXPECT_FALSE(engine.playableInstances.Classify(original.Handle()).live);
    }
    EXPECT_GT(children, 0u);
    EXPECT_FALSE(harken::detail::CanResetActionPlayScratchForTests(scratch));
    executor.ReleaseParentLinkProof();
    EXPECT_FALSE(executor.ParentLinkProofHeld());
    EXPECT_FALSE(engine.playableInstances.ParentLinksHeld(root));
    EXPECT_FALSE(executor.Validate());
    EXPECT_TRUE(executor.InstanceCommitProofsHeld());
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
    ASSERT_TRUE(executor.ProveParentLinks(engine.playableInstances, &scratch.instance));
    EXPECT_TRUE(executor.ParentLinkProofHeld());
    EXPECT_TRUE(executor.Validate());
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
}

static void ExpectActualServicePartitionHoldGuards(harken::Engine& engine,
    harken::EngineActionPlayScratch& scratch) {
    auto& context = scratch.variableControlOwnerContext;
    auto* original = context.OriginalService();
    ASSERT_EQ(scratch.row, original);
    ASSERT_TRUE(context.ServiceCommitProofRequired());
    ASSERT_TRUE(context.serviceCommitProof.Associated(context.OriginalServiceInput()));
    ASSERT_TRUE(engine.playablePartitions.CommitProofHeld(original->partition, original->identity));
    const auto baseline = CaptureActionReclaimableOwners(engine);
    const auto identity = original->identity;
    const auto partition = original->partition;
    auto& row = *scratch.row;
    EXPECT_TRUE(harken::detail::ResetPlayableServiceDeferredForTests(engine, row));
    EXPECT_FALSE(harken::detail::CanResetActionPlayScratchForTests(scratch));
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
    EXPECT_EQ(identity, row.identity);
    EXPECT_EQ(partition.generation, row.partition.generation);
    EXPECT_TRUE(context.serviceCommitProof.Valid());
    ++row.identity.generation;
    row.partition = {};
    EXPECT_FALSE(engine.playablePartitions.CommitProofHeld(row.partition, row.identity));
    EXPECT_TRUE(harken::detail::ResetPlayableServiceDeferredForTests(engine, row));
    EXPECT_TRUE(context.serviceCommitProof.Valid());
    row.identity = identity;
    row.partition = partition;
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
    EXPECT_TRUE(context.OriginalServiceAssociationMatches(&engine, &row));
    harken::EngineActionPlayScratch::PreparedVariableControlOwnerContext empty;
    empty = std::move(context);
    EXPECT_EQ(nullptr, empty.OriginalService());
    context = std::move(empty);
    EXPECT_EQ(original, context.OriginalService());
    EXPECT_FALSE(context.RecordOriginalServiceAssociation());
    EXPECT_FALSE(context.ReserveOriginalService(engine.playablePartitions, &engine, row).Valid());
    context.serviceCommitProof.Release();
    EXPECT_TRUE(context.ServiceCommitProofRequired());
    EXPECT_FALSE(harken::detail::CommitPreparedVariableControlOwnerForTests(&context));
    EXPECT_FALSE(context.committed);
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
    empty = std::move(context);
    context = std::move(empty);
    EXPECT_EQ(original, context.OriginalService());
    EXPECT_TRUE(context.OriginalServiceAssociationMatches(&engine, &row));
    ASSERT_TRUE(engine.playablePartitions.ProvePreparedCommit(context.OriginalServiceInput(), &context.serviceCommitProof));
    EXPECT_EQ(baseline, CaptureActionReclaimableOwners(engine));
}

void ExpectSetValueImmediateVariableControlFinalOwnerSeal(bool injectFault, bool mixed = false,
    bool firstVoiceFault = false, bool revokePreparedLedger = false,
    std::uint32_t alterPreparedVoice = 0) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(2, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                    &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                    &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision, false, alterPreparedVoice == 3);
    if (mixed) image.MakeSetValueThenImmediateTwoMemberVariableControlPlayAction();
    else image.MakeSetValueThenImmediateVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto before = CaptureActionReclaimableOwners(*engine);
    const auto commandHead = engine->commands.PublishedHead();
    const auto accepted = engine->variables.AcceptedCount();
    const auto pending = engine->variables.PendingCount();
    const auto groups = engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0);
    const auto sources = CaptureSourceGenerations(*engine);
    engine->forceActionFinalOwnerCommitFailureForTest = injectFault;
    engine->forceActionTimelineVoiceOwnerCommitFailureForTest = firstVoiceFault;
    struct LedgerRevocationProbe {
        std::uint32_t firstSlot = UINT32_MAX;
        std::uint32_t secondSlot = UINT32_MAX;
        std::uint32_t preparedCount = 0;
        bool revoked = false;
        std::uint32_t alterVoice = 0;
        VnVoiceHandle firstRender = 0;
        VnVoiceHandle secondRender = 0;
        harken::VoicePool::PreparedRoutingV1 firstRouting{};
        harken::EffectInstanceRef firstEffect{};
        harken::DecisionToken firstDecision{};
        harken::CompletionProgressRow replacementProgress{};
        unsigned partitionHolds = 0;
        unsigned parentLinkHolds = 0;
        unsigned laneHolds = 0;
        unsigned laneMappings = 0;
        harken::ImmediateLaneHandle mappedLane{};
        harken::FrontierEntryReceiptRef mappedEntry{};
        std::uint64_t mappedRoot = 0;
    } ledgerProbe;
    ledgerProbe.alterVoice = alterPreparedVoice;
    if (revokePreparedLedger || alterPreparedVoice != 0) {
        engine->timelineVoicePreparedContextForTest = &ledgerProbe;
        engine->timelineVoicePreparedHookForTest = [](harken::Engine& current,
            const harken::EnginePreparedTimelineVoiceStart& voice, void* opaque) {
            auto& probe = *static_cast<LedgerRevocationProbe*>(opaque);
            ++probe.preparedCount;
            if (probe.preparedCount == 1) {
                probe.firstSlot = voice.ledgerSlot;
                probe.firstRender = voice.renderHandle;
                probe.firstRouting = voice.voicePreparation.routing;
                probe.firstDecision = voice.armPreparation.parentGroup.decision;
                if (probe.alterVoice == 3) {
                    ASSERT_EQ(1u, voice.effectCount);
                    ASSERT_EQ(VN_EFFECT_GAIN, voice.effects[0].type);
                    probe.firstEffect = voice.effects[0];
                }
                return;
            }
            if (probe.preparedCount != 2) return;
            probe.secondSlot = voice.ledgerSlot;
            probe.secondRender = voice.renderHandle;
            ASSERT_NE(probe.firstSlot, probe.secondSlot);
            ASSERT_NE(probe.firstRender, probe.secondRender);
            if (probe.alterVoice == 1) {
                probe.revoked = current.voices.CancelPreparedVoice(probe.firstRender);
            } else if (probe.alterVoice == 2) {
                const auto* original = current.voices.Resolve(probe.firstRender);
                ASSERT_NE(nullptr, original);
                harken::CompletionProgressSnapshot replacement{};
                replacement.occurrence = original->completionOccurrence.generation != 0
                    ? original->completionOccurrence : harken::OccurrenceToken{11, 17};
                replacement.renderGeneration = static_cast<std::uint32_t>(probe.firstRender >> 32);
                replacement.playbackFactsRevision = original->playbackFactsRevision + 1u;
                ASSERT_TRUE(harken::InitializeCompletionProgress(probe.replacementProgress, replacement));
                probe.revoked = current.voices.BindCompletionProgress(probe.firstRender,
                    &probe.replacementProgress, replacement.occurrence, replacement.playbackFactsRevision);
                harken::VoicePool::PreparedRoutingV1 stillValidRouting{};
                ASSERT_TRUE(current.voices.CapturePreparedRoutingV1(probe.firstRender, &stillValidRouting));
                EXPECT_EQ(probe.firstRouting, stillValidRouting);
            } else if (probe.alterVoice == 3) {
                ASSERT_EQ(1u, voice.effectCount);
                probe.revoked = current.effectBank.CancelPrepared(probe.firstEffect);
                harken::VoicePool::PreparedRoutingV1 routing{};
                ASSERT_TRUE(current.voices.CapturePreparedRoutingV1(probe.firstRender, &routing));
                EXPECT_EQ(probe.firstRouting, routing);
            } else if (probe.alterVoice == 4) {
                ASSERT_TRUE(probe.firstDecision.Valid());
                probe.revoked = current.decisions.Cancel(probe.firstDecision);
                EXPECT_TRUE(current.decisions.IsCancelled(probe.firstDecision));
                harken::VoicePool::PreparedRoutingV1 routing{};
                ASSERT_TRUE(current.voices.CapturePreparedRoutingV1(probe.firstRender, &routing));
                EXPECT_EQ(probe.firstRouting, routing);
            } else if (probe.alterVoice == 5) {
                std::uint32_t originalCount = 0;
                for (auto& scratch : current.actionPlayScratch) {
                    if (!scratch.variableControlInstance.Valid()) continue;
                    ++originalCount;
                    probe.revoked = current.variableControlInstances.CancelPreparedAcquire(
                        &scratch.variableControlInstance);
                    EXPECT_TRUE(probe.revoked);
                }
                ASSERT_EQ(1u, originalCount);
                harken::VoicePool::PreparedRoutingV1 routing{};
                ASSERT_TRUE(current.voices.CapturePreparedRoutingV1(probe.firstRender, &routing));
                EXPECT_EQ(probe.firstRouting, routing);
            } else if (probe.alterVoice == 6) {
                std::uint32_t originalCount = 0;
                for (auto& scratch : current.actionPlayScratch) {
                    if (!scratch.variableControlControllerRow.Valid()) continue;
                    ++originalCount;
                    probe.revoked = current.containerPlayback.Cancel(&scratch.variableControlControllerRow);
                    EXPECT_TRUE(probe.revoked);
                }
                ASSERT_EQ(1u, originalCount);
                harken::VoicePool::PreparedRoutingV1 routing{};
                ASSERT_TRUE(current.voices.CapturePreparedRoutingV1(probe.firstRender, &routing));
                EXPECT_EQ(probe.firstRouting, routing);
            } else if (probe.alterVoice == 7) {
                std::uint32_t originalCount = 0;
                for (auto& scratch : current.actionPlayScratch) {
                    if (!scratch.variableControlControllerRow.Valid()) continue;
                    ++originalCount;
                    probe.revoked = harken::detail::ContainerPlaybackPreparationTestAccess::ChangeOriginalFingerprint(
                        current.containerPlayback, scratch.variableControlControllerRow);
                    EXPECT_TRUE(probe.revoked);
                    EXPECT_TRUE(scratch.variableControlControllerRow.Valid());
                }
                ASSERT_EQ(1u, originalCount);
                harken::VoicePool::PreparedRoutingV1 routing{};
                ASSERT_TRUE(current.voices.CapturePreparedRoutingV1(probe.firstRender, &routing));
                EXPECT_EQ(probe.firstRouting, routing);
            } else if (probe.alterVoice == 8) {
                std::uint32_t originalCount = 0;
                for (auto& scratch : current.actionPlayScratch) {
                    if (!scratch.variableControlControllerRow.Valid()) continue;
                    ++originalCount;
                    probe.revoked = harken::detail::PlayableInstanceDeadlineTestAccess::ChangeOriginalKind(
                        current.playableInstances, scratch.instance);
                    EXPECT_TRUE(probe.revoked);
                    EXPECT_TRUE(scratch.instance.Valid());
                    EXPECT_TRUE(scratch.variableControlControllerRow.Valid());
                }
                ASSERT_EQ(1u, originalCount);
                harken::VoicePool::PreparedRoutingV1 routing{};
                ASSERT_TRUE(current.voices.CapturePreparedRoutingV1(probe.firstRender, &routing));
                EXPECT_EQ(probe.firstRouting, routing);
            } else if (probe.alterVoice == 9 || probe.alterVoice == 10) {
                auto* scratch = FindScratchForOriginalPreparedVoice(current, voice);
                ASSERT_NE(nullptr, scratch);
                auto& context = scratch->variableControlOwnerContext;
                auto& row = *scratch->row;
                ASSERT_TRUE(context.OriginalServiceAssociationMatches(&current, &row));
                const auto originalEpoch = row.ownerEpoch;
                ++row.ownerEpoch;
                EXPECT_FALSE(context.OriginalServiceAssociationMatches(&current, &row));
                EXPECT_FALSE(context.RecordOriginalServiceAssociation());
                row.ownerEpoch = originalEpoch;
                ASSERT_TRUE(context.OriginalServiceAssociationMatches(&current, &row));
                if (probe.alterVoice == 9) {
                    ASSERT_TRUE(current.playablePartitions.Commit(row.partition, row.identity));
                    ASSERT_TRUE(current.playablePartitions.RollbackCommit(row.partition, row.identity));
                    ASSERT_TRUE(current.playablePartitions.Owns(row.partition, row.identity));
                    EXPECT_EQ(&row, current.ResolvePlayableService(
                        row.identity, row.ownerInstance, row.ownerEpoch));
                }
                probe.revoked = true;
            } else if (probe.alterVoice == 11 || probe.alterVoice >= 12) {
                probe.revoked = FindScratchForOriginalPreparedVoice(current, voice) != nullptr;
            } else {
                probe.revoked = current.ledger.CancelPreparedPlayableOwned(probe.firstSlot);
            }
            EXPECT_TRUE(probe.revoked);
        };
    }
    if (alterPreparedVoice == 10 || alterPreparedVoice == 11 || alterPreparedVoice == 12) {
        engine->servicePartitionProvedContextForTest = &ledgerProbe;
        engine->servicePartitionProvedHookForTest = [](harken::Engine& current,
            harken::EngineActionPlayScratch& scratch, void* opaque) {
            auto& probe = *static_cast<LedgerRevocationProbe*>(opaque);
            ++probe.partitionHolds;
            if (probe.alterVoice == 10) {
                ASSERT_NO_FATAL_FAILURE(ExpectActualServicePartitionHoldGuards(current, scratch));
            } else {
                ++probe.parentLinkHolds;
                ASSERT_NO_FATAL_FAILURE(ExpectActualParentLinkHoldGuards(current, scratch));
                if (probe.alterVoice == 12) {
                    scratch.playableTreeExecutor.ReleaseParentLinkProof();
                    EXPECT_FALSE(scratch.playableTreeExecutor.Validate());
                }
            }
        };
    }
    if (alterPreparedVoice >= 13 && alterPreparedVoice <= 17) {
        engine->privateInitialVcLaneTransferContextForTest = &ledgerProbe;
        engine->privateInitialVcLaneTransferHookForTest = [](harken::Engine& current,
            harken::EngineActionPlayScratch& scratch, std::uint32_t position, void* opaque) {
            auto& probe = *static_cast<LedgerRevocationProbe*>(opaque);
            auto& held = scratch.privateInitialVcPageCohort;
            if (position == 4) {
                ++probe.laneMappings;
                const auto baseline = CaptureActionReclaimableOwners(current);
                harken::ImmediateLanePrivateVariableControlEntryMapping mapping{};
                const auto& entry = scratch.frontierDescriptor.entry;
                const auto capture = [&](harken::ImmediateLaneHandle lane, std::uint64_t root,
                    std::uint32_t ordinal, const harken::FrontierEntryReceiptRef& actual,
                    const harken::ScheduledTransactionPool& pool, const harken::TimelineArmTable& arms,
                    const harken::DecisionTable& decisions,
                    harken::ImmediateLanePrivateVariableControlEntryMapping* out) {
                    return current.immediateActionLane.CapturePrivateVariableControlEntryMapping(
                        lane, root, ordinal, actual, pool, arms, decisions, out);
                };
                ASSERT_TRUE(capture(held.originalLane, held.cohortRoot, held.laneEntryOrdinal,
                    entry, current.timelinePool, current.timelineArms, current.decisions, &mapping));
                EXPECT_NE(UINT32_MAX, mapping.coordinatorBucket);
                for (std::size_t group = 0; group < mapping.groups.size(); ++group) {
                    harken::Plan03GroupSliceIdentity actual{};
                    ASSERT_TRUE(current.immediateActionLane.CapturePrivatePinGroup(
                        held.originalLane, mapping.groups[group], &actual));
                    EXPECT_EQ(group < 2 ? held.laneMemberManifests[group].group :
                        scratch.frontierDescriptor.primary, actual);
                    if (group < 2) EXPECT_FALSE(held.laneSides[group].Exact());
                }
                for (std::size_t local = 0; local < mapping.events.size(); ++local) {
                    EXPECT_NE(UINT32_MAX, mapping.events[local]);
                    for (std::size_t other = 0; other < local; ++other)
                        EXPECT_NE(mapping.events[local], mapping.events[other]);
                }
                auto output = mapping;
                output.coordinatorBucket = 4242;
                const auto sentinel = output;
                auto wrongEntry = entry;
                ++wrongEntry.owner.serviceGeneration;
                EXPECT_FALSE(capture(held.originalLane, held.cohortRoot, held.laneEntryOrdinal,
                    wrongEntry, current.timelinePool, current.timelineArms, current.decisions, &output));
                ++wrongEntry.coordinator.generation;
                EXPECT_FALSE(capture(held.originalLane, held.cohortRoot, held.laneEntryOrdinal,
                    wrongEntry, current.timelinePool, current.timelineArms, current.decisions, &output));
                auto wrongLane = held.originalLane;
                ++wrongLane.generation;
                EXPECT_FALSE(capture(wrongLane, held.cohortRoot, held.laneEntryOrdinal,
                    entry, current.timelinePool, current.timelineArms, current.decisions, &output));
                EXPECT_FALSE(capture(held.originalLane, held.cohortRoot + 1, held.laneEntryOrdinal,
                    entry, current.timelinePool, current.timelineArms, current.decisions, &output));
                EXPECT_FALSE(capture(held.originalLane, held.cohortRoot, held.laneEntryOrdinal + 1,
                    entry, current.timelinePool, current.timelineArms, current.decisions, &output));
                harken::ScheduledTransactionPool foreignPool;
                harken::TimelineArmTable foreignArms{1};
                harken::DecisionTable foreignDecisions{1, 2};
                EXPECT_FALSE(capture(held.originalLane, held.cohortRoot, held.laneEntryOrdinal,
                    entry, foreignPool, current.timelineArms, current.decisions, &output));
                EXPECT_FALSE(capture(held.originalLane, held.cohortRoot, held.laneEntryOrdinal,
                    entry, current.timelinePool, foreignArms, current.decisions, &output));
                EXPECT_FALSE(capture(held.originalLane, held.cohortRoot, held.laneEntryOrdinal,
                    entry, current.timelinePool, current.timelineArms, foreignDecisions, &output));
                EXPECT_EQ(sentinel, output);
                EXPECT_FALSE(current.immediateActionLane.MatchesReservedMemberSpan(held.originalLane,
                    held.cohortRoot, held.originalLaneDemand, held.laneFirstMemberOrdinal,
                    held.laneMemberManifests.data(), 2));
                EXPECT_FALSE(held.LaneTransferHeld());
                std::uint32_t publishedCount = 4242;
                EXPECT_FALSE(current.immediateActionLane.CapturePublishedGroupCount(
                    held.originalLane, &publishedCount));
                EXPECT_EQ(4242u, publishedCount);
                EXPECT_EQ(baseline, CaptureActionReclaimableOwners(current));
                probe.mappedLane = held.originalLane;
                probe.mappedEntry = entry;
                probe.mappedRoot = held.cohortRoot;
                return;
            }
            if (position == 1 && probe.alterVoice == 13) {
                ASSERT_TRUE(held.laneTransferProofs[0].Valid());
                ASSERT_TRUE(current.timelinePool.PrivateImmediateLaneGroupTransferHeld(held.laneSides[0]));
                EXPECT_FALSE(held.laneTransferProofs[1].Valid());
                ASSERT_TRUE(current.timelinePool.CancelPrivateImmediateLaneGroup(
                    &held.laneOriginals[1], &held.laneSides[1]));
                EXPECT_FALSE(held.laneSides[1].Exact());
                EXPECT_FALSE(held.laneOriginals[1].Valid());
                ++probe.laneHolds;
            }
            if (position != 3) return;
            ++probe.laneHolds;
            const auto baseline = CaptureActionReclaimableOwners(current);
            EXPECT_TRUE(held.laneTransferRequired);
            EXPECT_TRUE(held.laneMembersDeclared);
            EXPECT_EQ(0u, held.laneFirstMemberOrdinal);
            EXPECT_EQ(0u, held.laneEntryOrdinal);
            EXPECT_TRUE(current.immediateActionLane.MatchesReservedMemberSpan(held.originalLane,
                held.cohortRoot, held.originalLaneDemand, held.laneFirstMemberOrdinal,
                held.laneMemberManifests.data(), 2));
            EXPECT_FALSE(current.immediateActionLane.MatchesReservedMemberSpan(held.originalLane,
                held.cohortRoot, held.originalLaneDemand, held.laneFirstMemberOrdinal + 1u,
                held.laneMemberManifests.data(), 2));
            EXPECT_FALSE(harken::detail::CanResetActionPlayScratchForTests(scratch));
            EXPECT_TRUE(current.immediateActionLane.MatchesReservedMembers(held.originalLane,
                held.cohortRoot, held.originalLaneDemand, held.laneMemberManifests.data(), 2));
            for (std::uint32_t index = 0; index < 3; ++index) {
                const auto identity = held.laneOriginals[index].Identity();
                ASSERT_TRUE(held.laneTransferProofs[index].Valid());
                EXPECT_FALSE(current.timelinePool.CancelPrivateImmediateLaneGroup(held.cohortRoot, identity));
                harken::Plan03PageGroupView view{};
                ASSERT_TRUE(current.timelinePool.ResolvePlan03GroupSliceProducer(identity, &view));
                ASSERT_NE(nullptr, view.lease);
                EXPECT_EQ(harken::AudioSliceInvalidateDisposition::PrivateTransferHeld,
                    view.lease->Invalidate(harken::AudioSliceInvalidateReason::Cancel));
                EXPECT_EQ(harken::AudioSliceState::PrivateTransferReserved, view.lease->Capture().state);
            }
            EXPECT_FALSE(current.timelinePool.CancelImmediateLaneGroups(held.cohortRoot, 0));
            EXPECT_FALSE(current.timelinePool.RebaseImmediateLaneGroups(held.cohortRoot, held.frame + 64));
            EXPECT_FALSE(current.timelinePool.PublishImmediateLaneGroups(held.cohortRoot));
            EXPECT_FALSE(current.timelinePool.ResetForEpoch(0, current.timelinePool.Epoch() + 1));
            EXPECT_EQ(baseline, CaptureActionReclaimableOwners(current));
            if (probe.alterVoice == 16) {
                const auto originalEntry = held.laneEntryOrdinal;
                ++held.laneEntryOrdinal;
                EXPECT_FALSE(scratch.playableTreeExecutor.Validate());
                held.laneEntryOrdinal = originalEntry;
                const auto originalContinuation = held.coordinatorRequest.expectedContinuationGeneration;
                ++held.coordinatorRequest.expectedContinuationGeneration;
                EXPECT_FALSE(scratch.playableTreeExecutor.Validate());
                held.coordinatorRequest.expectedContinuationGeneration = originalContinuation;
                const auto originalFirst = held.laneFirstMemberOrdinal;
                ++held.laneFirstMemberOrdinal;
                EXPECT_FALSE(scratch.playableTreeExecutor.Validate());
                held.laneFirstMemberOrdinal = originalFirst;
                auto changed = held.laneMemberManifests;
                ++changed[1].ownerEpoch;
                EXPECT_FALSE(current.immediateActionLane.MatchesReservedMembers(held.originalLane,
                    held.cohortRoot, held.originalLaneDemand, changed.data(), 2));
                EXPECT_TRUE(current.immediateActionLane.MatchesReservedMembers(held.originalLane,
                    held.cohortRoot, held.originalLaneDemand, held.laneMemberManifests.data(), 2));
            }
            EXPECT_FALSE(harken::detail::ProvePrivateInitialVcLaneTransferForTests(current, scratch));
            EXPECT_TRUE(held.LaneTransferHeld());
            for (const auto& proof : held.laneTransferProofs) EXPECT_TRUE(proof.Valid());
            held.ReleaseLaneTransferProofs();
            EXPECT_TRUE(held.laneTransferRequired);
            EXPECT_FALSE(held.LaneTransferHeld());
            if (probe.alterVoice == 15) return;
            const auto hook = current.privateInitialVcLaneTransferHookForTest;
            current.privateInitialVcLaneTransferHookForTest = nullptr;
            if (probe.alterVoice == 17) {
                const auto originalLane = held.originalLane;
                const auto originalDemand = held.originalLaneDemand;
                const auto originalFirst = held.laneFirstMemberOrdinal;
                held.originalLane = {};
                EXPECT_FALSE(harken::detail::ProvePrivateInitialVcLaneTransferForTests(current, scratch));
                EXPECT_TRUE(held.laneTransferRequired);
                EXPECT_TRUE(held.laneMembersDeclared);
                EXPECT_EQ(UINT32_MAX, held.originalLane.slot);
                EXPECT_EQ(0u, held.originalLane.generation);
                EXPECT_EQ(originalFirst, held.laneFirstMemberOrdinal);
                EXPECT_EQ(originalDemand.events, held.originalLaneDemand.events);
                EXPECT_EQ(originalDemand.groups, held.originalLaneDemand.groups);
                EXPECT_EQ(originalDemand.members, held.originalLaneDemand.members);
                EXPECT_EQ(originalDemand.buckets, held.originalLaneDemand.buckets);
                EXPECT_FALSE(held.LaneTransferHeld());
                for (const auto& proof : held.laneTransferProofs) EXPECT_FALSE(proof.Valid());
                EXPECT_FALSE(scratch.playableTreeExecutor.Validate());
                held.originalLane = originalLane;
            }
            const bool reproved = harken::detail::ProvePrivateInitialVcLaneTransferForTests(current, scratch);
            current.privateInitialVcLaneTransferHookForTest = hook;
            ASSERT_TRUE(reproved);
            for (const auto& proof : held.laneTransferProofs) EXPECT_TRUE(proof.Valid());
            EXPECT_EQ(baseline, CaptureActionReclaimableOwners(current));
            EXPECT_TRUE(current.immediateActionLane.MatchesReservedMembers(held.originalLane,
                held.cohortRoot, held.originalLaneDemand, held.laneMemberManifests.data(), 2));
        };
    }
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    const auto originalSequence = engine->logicCommits.Current();
    const auto result = Vn_PostAction(&desc, &firing);
    engine->timelineVoicePreparedHookForTest = nullptr;
    engine->timelineVoicePreparedContextForTest = nullptr;
    engine->servicePartitionProvedHookForTest = nullptr;
    engine->servicePartitionProvedContextForTest = nullptr;
    if (alterPreparedVoice != 14 && alterPreparedVoice != 16) {
        engine->privateInitialVcLaneTransferHookForTest = nullptr;
        engine->privateInitialVcLaneTransferContextForTest = nullptr;
    }
    if (revokePreparedLedger || alterPreparedVoice != 0) {
        EXPECT_TRUE(ledgerProbe.revoked);
        EXPECT_EQ(2u, ledgerProbe.preparedCount);
        EXPECT_NE(ledgerProbe.firstSlot, ledgerProbe.secondSlot);
    }
    if (revokePreparedLedger || (alterPreparedVoice != 0 && alterPreparedVoice != 10 && alterPreparedVoice != 11 && alterPreparedVoice != 14 && alterPreparedVoice != 16)) {
        ASSERT_EQ(alterPreparedVoice == 1 ? VN_BACKPRESSURE :
            (alterPreparedVoice == 6 ? VN_NO_VOICE : VN_RUNTIME_RECREATE_REQUIRED), result);
        EXPECT_EQ(0u, firing);
        EXPECT_EQ(alterPreparedVoice != 1 && alterPreparedVoice != 6, engine->runtimeRecreateRequired);
        EXPECT_EQ(commandHead, engine->commands.PublishedHead());
        EXPECT_EQ(accepted, engine->variables.AcceptedCount());
        EXPECT_EQ(pending, engine->variables.PendingCount());
        EXPECT_EQ(before, CaptureActionReclaimableOwners(*engine));
        EXPECT_EQ(groups, engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0));
        ASSERT_NO_FATAL_FAILURE(ExpectBoundSourcesReleased(*engine, sources));
        if (alterPreparedVoice == 8 || alterPreparedVoice == 9 || alterPreparedVoice == 12 || alterPreparedVoice == 13 || alterPreparedVoice == 15 || alterPreparedVoice == 17) {
            if (alterPreparedVoice == 13 || alterPreparedVoice == 15 || alterPreparedVoice == 17) EXPECT_EQ(1u, ledgerProbe.laneHolds);
            if (alterPreparedVoice == 12) EXPECT_EQ(1u, ledgerProbe.parentLinkHolds);
            EXPECT_EQ(originalSequence, engine->logicCommits.Current());
            for (const auto& scratch : engine->actionPlayScratch) {
                EXPECT_FALSE(scratch.privateInitialVcPageCohort.LaneTransferHeld());
                EXPECT_FALSE(scratch.playableTreeExecutor.InstanceCommitProofsHeld());
                EXPECT_FALSE(scratch.playableTreeExecutor.ParentLinkProofHeld());
                EXPECT_FALSE(scratch.playableTreeExecutor.ContainerCommitProofsHeld());
                EXPECT_FALSE(scratch.variableControlDiscreteDecisionOwnerContext.ticketCommitProof.Valid());
                EXPECT_FALSE(scratch.variableControlContinuousDecisionOwnerContext.ticketCommitProof.Valid());
                EXPECT_FALSE(scratch.variableControlOwnerContext.commitProof.Valid());
                EXPECT_FALSE(scratch.variableControlOwnerContext.serviceCommitProof.Valid());
                for (const auto& owner : scratch.voiceOwnerContexts) {
                    EXPECT_FALSE(owner.armCommitProof.Valid());
                    EXPECT_FALSE(owner.ledgerCommitProof.Valid());
                    EXPECT_FALSE(owner.voiceCommitProof.Valid());
                    EXPECT_FALSE(owner.HasEffectCommitProofs());
                }
            }
        }
        engine->nullBackend.Pump(2);
        const auto* output = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        for (std::uint32_t sample = 0; sample < engine->config.blockFrames *
             engine->nullBackend.Channels(); ++sample) EXPECT_FLOAT_EQ(0.0f, output[sample]);
        return;
    }
    if (firstVoiceFault) {
        ASSERT_EQ(VN_OK, result);
        ASSERT_NE(0u, firing);
        EXPECT_TRUE(engine->runtimeRecreateRequired);
        EXPECT_FALSE(engine->forceActionTimelineVoiceOwnerCommitFailureForTest);
        EXPECT_EQ(accepted + 1u, engine->variables.AcceptedCount());
        VnActionStepResult play{};
        play.structSize = sizeof(play);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &play));
        EXPECT_EQ(VN_ACTION_STEP_FAILED, play.state);
        EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, play.result);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        EXPECT_EQ(before, CaptureActionReclaimableOwners(*engine));
        EXPECT_EQ(groups, engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0));
        ASSERT_NO_FATAL_FAILURE(ExpectBoundSourcesReleased(*engine, sources));
        engine->nullBackend.Pump(2);
        const auto* output = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        for (std::uint32_t sample = 0; sample < engine->config.blockFrames *
             engine->nullBackend.Channels(); ++sample) EXPECT_FLOAT_EQ(0.0f, output[sample]);
        return;
    }
    if (injectFault) {
        EXPECT_EQ(VN_RUNTIME_RECREATE_REQUIRED, result);
        EXPECT_EQ(0u, firing);
        EXPECT_TRUE(engine->runtimeRecreateRequired);
        EXPECT_FALSE(engine->forceActionFinalOwnerCommitFailureForTest);
        EXPECT_EQ(commandHead, engine->commands.PublishedHead());
        EXPECT_EQ(accepted, engine->variables.AcceptedCount());
        EXPECT_EQ(pending, engine->variables.PendingCount());
        EXPECT_EQ(before, CaptureActionReclaimableOwners(*engine));
        EXPECT_EQ(groups,
                  engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0));
        ASSERT_NO_FATAL_FAILURE(ExpectBoundSourcesReleased(*engine, sources));
        return;
    }
    ASSERT_EQ(VN_OK, result);
    ASSERT_NE(0u, firing);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(accepted + 1u, engine->variables.AcceptedCount());
    EXPECT_GT(engine->commands.PublishedHead(), commandHead);
    if (alterPreparedVoice == 10 || alterPreparedVoice == 11 || alterPreparedVoice == 14 || alterPreparedVoice == 16) {
        if (alterPreparedVoice < 13) EXPECT_EQ(1u, ledgerProbe.partitionHolds);
        else EXPECT_EQ(1u, ledgerProbe.laneHolds);
        bool pcm = false;
        if (alterPreparedVoice == 11 || alterPreparedVoice == 14 || alterPreparedVoice == 16) {
            if (alterPreparedVoice == 11) EXPECT_EQ(1u, ledgerProbe.parentLinkHolds);
            for (unsigned block = 0; block < 12; ++block) {
                engine->nullBackend.Pump(1);
                const auto* output = engine->nullBackend.LastBlock();
                ASSERT_NE(nullptr, output);
                for (unsigned sample = 0; sample < engine->nullBackend.BlockFrames() *
                        engine->nullBackend.Channels(); ++sample) EXPECT_FLOAT_EQ(0.0f, output[sample]);
            }
            ASSERT_EQ(VN_OK, Vn_Update());
            if (alterPreparedVoice == 14 || alterPreparedVoice == 16) {
                EXPECT_EQ(1u, ledgerProbe.laneMappings);
                harken::ImmediateLanePrivateVariableControlEntryMapping mapping{};
                mapping.coordinatorBucket = 4242;
                const auto sentinel = mapping;
                EXPECT_FALSE(engine->immediateActionLane.CapturePrivateVariableControlEntryMapping(
                    ledgerProbe.mappedLane, ledgerProbe.mappedRoot, 0,
                    ledgerProbe.mappedEntry, engine->timelinePool, engine->timelineArms,
                    engine->decisions, &mapping));
                EXPECT_EQ(sentinel, mapping);
                engine->privateInitialVcLaneTransferHookForTest = nullptr;
                engine->privateInitialVcLaneTransferContextForTest = nullptr;
            }
            bool firstUpdatePcm = false;
            for (unsigned block = 0; block < 16; ++block) {
                engine->nullBackend.Pump(1);
                const auto* output = engine->nullBackend.LastBlock();
                ASSERT_NE(nullptr, output);
                for (unsigned sample = 0; sample < engine->nullBackend.BlockFrames() *
                        engine->nullBackend.Channels(); ++sample) {
                    firstUpdatePcm = firstUpdatePcm || output[sample] < -0.01f;
                }
            }
            EXPECT_TRUE(firstUpdatePcm);
            pcm = firstUpdatePcm;
        }
        const auto service = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
            [firing](const auto& row) { return row.InvocationValid() && row.Invocation().actionFiring == firing; });
        ASSERT_NE(engine->playableServices.end(), service);
        const auto instance = service->rootInstance;
        for (unsigned block = 0; block < 32; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            for (unsigned sample = 0; sample < engine->nullBackend.BlockFrames() *
                    engine->nullBackend.Channels(); ++sample) pcm = pcm || output[sample] < -0.01f;
        }
        EXPECT_TRUE(pcm);
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalTreeCompletion(*engine, firing, instance, &info));
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        for (unsigned block = 0; block < 96 && CaptureActionReclaimableOwners(*engine) != before; ++block) {
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
        }
        EXPECT_EQ(before, CaptureActionReclaimableOwners(*engine));
        EXPECT_EQ(groups, engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0));
    }
}

