// Each stage uses the original Post producer and real audio progress. No
// receipt, source release, lane sequence, or activation state is fabricated.
static void CheckPrivateEntryReceiverStopStage(unsigned stage, bool inspectProducerChain = false) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(2, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    // Unequal levels keep the first mixed block audible in the started case.
    std::vector<float> first(64, stage == 3 ? 0.125f : 0.25f), second(128, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeSetValueThenImmediateTwoMemberVariableControlPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto owners = CaptureActionReclaimableOwners(*engine);
    const auto sources = CaptureSourceGenerations(*engine);
    const auto groupCount = engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &play));
    const auto root = play.producedPlayableInstance;
    ASSERT_NE(0u, root);
    const auto rowIt = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [root](const auto& row) { return row.rootInstance == root; });
    ASSERT_NE(engine->playableServices.end(), rowIt);
    auto& row = *rowIt;
    ASSERT_TRUE(row.privateImmediateEntry.Valid());
    const auto originalReceiver = row.privateImmediateEntry;
    if (inspectProducerChain) {
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
        harken::EngineImmediateEntryAttempt* actual = nullptr;
        for (unsigned index = 0; index < engine->immediateEntryAttemptCapacity; ++index) {
            auto& candidate = engine->immediateEntryAttempts[index];
            if (candidate.active && candidate.root == firing) {
                ASSERT_EQ(nullptr, actual);
                actual = &candidate;
            }
        }
        ASSERT_NE(nullptr, actual);
        ASSERT_EQ(1u, actual->privateVcProducerCount);
        const auto head = actual->privateVcProducerHead;
        ASSERT_EQ(actual->producerSlot, head.slot);
        ASSERT_EQ(actual->producerGeneration, head.generation);
        ASSERT_LT(head.slot, engine->actionPlayScratch.size());
        auto& held = engine->actionPlayScratch[head.slot].privateInitialVcPageCohort;
        const auto matches = [&]() {
            return harken::detail::MatchesPrivateImmediateVcProducerChainForTests(*engine, *actual);
        };
        ASSERT_TRUE(matches());
        harken::EngineImmediateEntryAttempt detached;
        detached.active = actual->active;
        detached.lane = actual->lane;
        detached.root = actual->root;
        detached.generation = actual->generation;
        detached.originalLaneDemand = actual->originalLaneDemand;
        detached.privateVcProducerHead = head;
        detached.privateVcProducerCount = actual->privateVcProducerCount;
        detached.producerSlot = actual->producerSlot;
        detached.producerGeneration = actual->producerGeneration;
        EXPECT_FALSE(harken::detail::MatchesPrivateImmediateVcProducerChainForTests(*engine, detached));
        ++actual->privateVcProducerHead.generation;
        ++actual->producerGeneration;
        EXPECT_FALSE(matches());
        actual->privateVcProducerHead = head;
        actual->producerGeneration = head.generation;
        const auto rootGeneration = held.rootProducerGeneration;
        ++held.rootProducerGeneration;
        EXPECT_FALSE(matches());
        held.rootProducerGeneration = rootGeneration;
        held.rootProducerNext = head;
        EXPECT_FALSE(matches());
        held.rootProducerNext = {};
        const auto partition = held.rootProducerPartition;
        ++held.rootProducerPartition.generation;
        EXPECT_FALSE(matches());
        held.rootProducerPartition = partition;
        const auto invocationGeneration = held.rootProducerInvocationGeneration;
        ++held.rootProducerInvocationGeneration;
        EXPECT_FALSE(matches());
        held.rootProducerInvocationGeneration = invocationGeneration;
        actual->privateVcProducerCount = 2;
        EXPECT_FALSE(matches());
        actual->privateVcProducerCount = 1;
        ASSERT_TRUE(matches());
#else
        GTEST_SKIP() << "Requires the qualified-out association accessor";
#endif
    }
    std::array<harken::TimelineArmToken, 2> originalArms{};
    unsigned originalMembers = 0;
    for (const auto& scratch : engine->actionPlayScratch) {
        const auto& held = scratch.privateInitialVcPageCohort;
        if (!(held.laneEntry == originalReceiver.entry)) continue;
        for (const auto& member : held.laneMemberManifests) {
            ASSERT_LT(originalMembers, originalArms.size());
            originalArms[originalMembers++] = member.arm;
        }
    }
    ASSERT_EQ(2u, originalMembers);
    for (const auto& arm : originalArms) {
        harken::TimelineArmObservation observation{};
        ASSERT_TRUE(engine->timelineArms.Observe(arm, &observation));
        ASSERT_EQ(harken::ArmState::PendingApply, observation.state);
        ASSERT_EQ(0u, observation.armedCompletionSequence);
    }
    const auto pumpSilent = [&]() {
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        for (unsigned sample = 0; sample < engine->config.blockFrames *
            engine->nullBackend.Channels(); ++sample) EXPECT_FLOAT_EQ(0.0f, output[sample]);
    };
    if (stage == 1 || stage == 2 || stage == 3 || stage >= 6) {
        for (unsigned block = 0; block < 12; ++block) pumpSilent();
        ASSERT_EQ(originalReceiver.lane.slot, row.privateImmediateEntry.lane.slot);
        ASSERT_EQ(originalReceiver.lane.generation, row.privateImmediateEntry.lane.generation);
        for (const auto& arm : originalArms) {
            harken::TimelineArmObservation observation{};
            ASSERT_TRUE(engine->timelineArms.Observe(arm, &observation));
            ASSERT_EQ(harken::ArmState::Armed, observation.state);
            ASSERT_GT(observation.armedCompletionSequence, 0u);
            ASSERT_LE(observation.armedCompletionSequence, engine->mixer.BlocksRendered());
        }
    }
    std::uint64_t entryQuantum = UINT64_MAX;
    if (stage == 2 || stage == 3 || stage >= 6) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_GT(row.privateImmediateEntry.shape.count, 0u);
        harken::ImmediateLaneObservation observation{};
        ASSERT_TRUE(engine->immediateActionLane.Observe(originalReceiver.lane, &observation));
        ASSERT_TRUE(observation.committed);
        for (unsigned index = 0; index < engine->immediateEntryAttemptCapacity; ++index) {
            const auto& attempt = engine->immediateEntryAttempts[index];
            if (attempt.active && attempt.root == firing) entryQuantum = attempt.entryQuantum;
        }
        ASSERT_NE(UINT64_MAX, entryQuantum);
        ASSERT_LE(engine->mixer.BlocksRendered(), entryQuantum);
    }
    if (stage == 3) {
        while (engine->mixer.BlocksRendered() < entryQuantum) pumpSilent();
        bool negative = false;
        bool started = false;
        for (unsigned block = 0; block < 32 && !started; ++block) {
            engine->nullBackend.Pump(1);
            const auto* output = engine->nullBackend.LastBlock();
            for (unsigned sample = 0; sample < engine->config.blockFrames *
                engine->nullBackend.Channels(); ++sample) negative = negative || output[sample] < -0.01f;
            for (const auto& arm : originalArms) {
                harken::TimelineArmObservation observation{};
                ASSERT_TRUE(engine->timelineArms.Observe(arm, &observation));
                started = started || observation.startedBlockSequence != 0;
            }
        }
        ASSERT_TRUE(started);
        ASSERT_TRUE(negative);
        harken::ImmediateLaneEntryOutcomeSnapshot actual{};
        ASSERT_TRUE(engine->immediateActionLane.CapturePrivateEntryOutcome(originalReceiver.lane,
            originalReceiver.root, originalReceiver.ordinal, originalReceiver.entry,
            row.privateImmediateEntry.shape.coordinator, engine->mixer.BlocksRendered(), &actual));
        ASSERT_EQ(harken::ImmediateLaneEntryOutcome::Applied, actual.outcome);
        ASSERT_FALSE(row.privateImmediateEntry.commonPinsRetired);
    }
    auto resetStatus = harken::RuntimeTransportResetStatus::Backpressure;
    const auto commandsBeforeStop = engine->commands.PublishedHead();
    if (stage == 4) {
        resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
        ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure, resetStatus);
    } else if (stage == 5) {
        CanonicalActionWorld replacement(
            engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
            engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
        replacement.variables[0].defaultValue = 0.25f;
        replacement.world.identity.runtimeSemanticFingerprint =
            harken::ComputeCurrentWorldFingerprintV4(replacement.world);
        ASSERT_EQ(harken::WorldInstallStatus::Backpressure,
            harken::InstallContainerWorldV1(*engine, replacement.world).status);
        EXPECT_TRUE(engine->currentWorldReplacementAdmissionClosed);
        ASSERT_EQ(VN_OK, Vn_Update());
    } else if (stage >= 6) {
#if defined(HARKEN_TEST_TIMELINE_CAPACITY_OVERRIDE)
        struct Probe { std::uint64_t quantum; unsigned calls = 0; bool missed = false; } probe{entryQuantum};
        struct HookCleanup {
            ~HookCleanup() { harken::test::SetPrivateEntryStopPreflightHookForTest(nullptr, nullptr); }
        } cleanup;
        harken::test::SetPrivateEntryStopPreflightHookForTest(
            [](harken::Engine& current, harken::EnginePlayableServiceRow& actualRow, void* context) {
                auto& probe = *static_cast<Probe*>(context);
                ++probe.calls;
                const auto capacity = current.mixer.Arena().CapacityBytes();
                const auto required = current.voices.ScratchBytesBeforeTimeline(current.config.blockFrames);
                ASSERT_GT(required, 0u);
                const auto busBytes = 2u * current.config.blockFrames * sizeof(float);
                current.mixer.ArenaForTests().SetCapacityForTests(
                    static_cast<std::uint32_t>(busBytes + required - 1u));
                while (current.mixer.BlocksRendered() <= probe.quantum) current.nullBackend.Pump(1);
                current.mixer.ArenaForTests().SetCapacityForTests(capacity);
                harken::ImmediateLaneObservation observation{};
                ASSERT_TRUE(current.immediateActionLane.Observe(actualRow.privateImmediateEntry.lane, &observation));
                probe.missed = observation.missed && observation.arenaCapacityMissed;
            }, &probe);
        ASSERT_EQ(VN_OK, stage == 6 ? Vn_StopActionFiring(firing, 0) : Vn_StopAll(0));
        harken::test::SetPrivateEntryStopPreflightHookForTest(nullptr, nullptr);
        ASSERT_EQ(1u, probe.calls);
        ASSERT_TRUE(probe.missed);
        EXPECT_FALSE(row.privateImmediateEntry.stopAccepted);
        EXPECT_EQ(1u, row.pendingCancellationIntent);
#else
        GTEST_SKIP() << "Requires the qualified-out admission probe";
#endif
    } else {
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, root, 0));
        EXPECT_TRUE(row.privateImmediateEntry.stopAccepted);
        EXPECT_EQ(1u, row.pendingCancellationIntent);
        ASSERT_EQ(harken::PlayableControlStatus::Ok, harken::StopPlayable(*engine, root, 77));
        EXPECT_EQ(0u, row.pendingCancellationFadeMs);
        if (stage == 3) {
            EXPECT_GT(engine->commands.PublishedHead(), commandsBeforeStop);
            unsigned terminating = 0;
            for (const auto& arm : originalArms) {
                const auto render = (static_cast<std::uint64_t>(arm.renderGeneration) << 32) | arm.renderSlot;
                terminating += engine->ledger.IsTerminating(render) ? 1u : 0u;
            }
            EXPECT_GT(terminating, 0u);
        }
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (unsigned block = 0; block < 96; ++block) {
        pumpSilent();
        ASSERT_EQ(VN_OK, Vn_Update());
        if (stage == 4) {
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
            ASSERT_NE(harken::RuntimeTransportResetStatus::RuntimeRecreateRequired, resetStatus);
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    if (stage == 4) EXPECT_EQ(VN_ACTION_TERMINAL_TRANSPORT_RESET, info.terminalReason);
    if (stage == 5) EXPECT_EQ(VN_ACTION_TERMINAL_WORLD_REPLACED, info.terminalReason);
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    for (unsigned block = 0; block < 96 && CaptureActionReclaimableOwners(*engine) != owners; ++block) {
        pumpSilent();
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(*engine));
    EXPECT_EQ(groupCount, engine->timelinePool.CaptureLivePlan03Groups(nullptr, 0));
    ASSERT_NO_FATAL_FAILURE(ExpectBoundSourcesReleased(*engine, sources));
    if (stage == 4) {
        for (unsigned block = 0; block < 96 && resetStatus != harken::RuntimeTransportResetStatus::Complete; ++block) {
            pumpSilent();
            ASSERT_EQ(VN_OK, Vn_Update());
            resetStatus = harken::BeginRuntimeTransportReset(*engine, 0);
            ASSERT_NE(harken::RuntimeTransportResetStatus::RuntimeRecreateRequired, resetStatus);
        }
        EXPECT_EQ(harken::RuntimeTransportResetStatus::Complete, resetStatus);
        EXPECT_FALSE(engine->runtimeRecreateRequired);
    }
}

