void ExpectImmediateVariableControlTransitionCompletesForCompositeTarget(
    bool pieceTarget) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(6, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(768, 0.25f);
    std::vector<float> second(1536, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                             &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayThenSetValueAction();
    if (pieceTarget) {
        image.MakeFirstVariableControlChildCompositePiece();
    } else {
        image.MakeFirstVariableControlChildCompositeTrack();
    }
    std::swap(image.variableControlCells[0].exactValue,
              image.variableControlCells[1].exactValue);
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 64;
    image.EnableImmediateVariableControlTransition(128, 192);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const std::uint32_t playablesBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t variableControlsBefore =
        engine->variableControlInstances.LiveCount();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();
    const std::uint32_t transitionsBefore =
        engine->transitionInstances.LiveCount();
    const std::uint32_t firingsBefore = engine->actionFirings.LiveCount();

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    EXPECT_EQ(playablesBefore + 2u,
              engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlsBefore + 1u,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore + 1u, engine->voices.ActiveCount());

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(0u, play.executionOrdinal);
    VnActionStepResult setValue{};
    setValue.structSize = sizeof(setValue);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    EXPECT_EQ(1u, setValue.executionOrdinal);
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(1u, row->variableControlDiscreteMemberCount);
    EXPECT_EQ(1u, row->scheduleLeafCount);
    EXPECT_EQ(CanonicalActionWorld::kSecondSound, row->leaf.stableId);
    const std::size_t base = row->scheduleStorageBase;
    const VnVoiceHandle sourceVoice =
        engine->playableScheduleRenderHandles[base];
    ASSERT_NE(0u, sourceVoice);

    for (std::uint32_t block = 0;
         block < 64 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    EXPECT_EQ(1u,
              row->variableControlDiscreteRetargetSourceMemberCount);
    EXPECT_EQ(2u,
              row->variableControlDiscreteRetargetTargetMemberCount);
    EXPECT_EQ(3u,
              row->variableControlDiscreteRetargetGroupMemberCount);
    ASSERT_TRUE(row->variableControlDiscreteRetargetTransition.Valid());
    ExpectVariableControlRetargetTree(
        *engine, *row,
        pieceTarget ? harken::PlayableKind::Piece : harken::PlayableKind::Track,
        2u);
    EXPECT_EQ(transitionsBefore + 1u,
              engine->transitionInstances.LiveCount());

    const std::array<VnVoiceHandle, 2> targetVoices = {
        engine->playableScheduleRenderHandles[
            base + row->variableControlDiscreteTransitionOffset],
        engine->playableScheduleRenderHandles[
            base + row->variableControlDiscreteTransitionOffset + 1u]};
    ASSERT_NE(0u, targetVoices[0]);
    ASSERT_NE(0u, targetVoices[1]);
    EXPECT_NE(sourceVoice, targetVoices[0]);
    EXPECT_NE(sourceVoice, targetVoices[1]);
    EXPECT_NE(targetVoices[0], targetVoices[1]);
    EXPECT_NE(nullptr, engine->voices.Resolve(targetVoices[0]));
    EXPECT_NE(nullptr, engine->voices.Resolve(targetVoices[1]));

    harken::Plan03PageGroupView group{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        row->variableControlDiscreteRetargetSlice, &group));
    EXPECT_EQ(1u, group.sourceControlCount);

    bool sourceExited = false;
    for (std::uint32_t block = 0; block < 32 && !sourceExited; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        sourceExited =
            engine->voices.Resolve(sourceVoice) == nullptr &&
            engine->voices.Resolve(targetVoices[0]) != nullptr &&
            engine->voices.Resolve(targetVoices[1]) != nullptr &&
            row->variableControlDiscreteMemberCount == 2u;
    }
    ASSERT_TRUE(sourceExited);
    EXPECT_EQ(voicesBefore + 2u, engine->voices.ActiveCount());

    bool firstTargetRetired = false;
    for (std::uint32_t block = 0; block < 64 && !firstTargetRetired;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        firstTargetRetired =
            engine->voices.Resolve(targetVoices[0]) == nullptr &&
            engine->voices.Resolve(targetVoices[1]) != nullptr;
    }
    ASSERT_TRUE(firstTargetRetired);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);

    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    ExpectVariableControlRetargetTreeRetired(*engine, *row);
    EXPECT_EQ(playablesBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlsBefore,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_EQ(transitionsBefore,
              engine->transitionInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(firingsBefore, engine->actionFirings.LiveCount());
}

TEST(ActionFiringApi,
     ImmediateVariableControlTransitionStartsEveryCompositeTrackTargetLeafAndCompletesAfterBothRetire) {
    ExpectImmediateVariableControlTransitionCompletesForCompositeTarget(
        false);
}

TEST(ActionFiringApi,
     ImmediateVariableControlTransitionStartsEveryCompositePieceTargetLeafAndCompletesAfterBothRetire) {
    ExpectImmediateVariableControlTransitionCompletesForCompositeTarget(
        true);
}

void ExpectImmediateVariableControlTransitionCompletesForCompositeSource(
    bool pieceSource) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(6, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(1536, 0.25f);
    std::vector<float> second(2304, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                             &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayThenSetValueAction();
    if (pieceSource) {
        image.MakeFirstVariableControlChildCompositePiece();
    } else {
        image.MakeFirstVariableControlChildCompositeTrack();
    }
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 64;
    image.EnableImmediateVariableControlTransition(128, 192);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const std::uint32_t playablesBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t variableControlsBefore =
        engine->variableControlInstances.LiveCount();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();
    const std::uint32_t transitionsBefore =
        engine->transitionInstances.LiveCount();
    const std::uint32_t firingsBefore = engine->actionFirings.LiveCount();

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    EXPECT_EQ(playablesBefore + 4u,
              engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlsBefore + 1u,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore + 2u, engine->voices.ActiveCount());

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(0u, play.executionOrdinal);
    VnActionStepResult setValue{};
    setValue.structSize = sizeof(setValue);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    EXPECT_EQ(1u, setValue.executionOrdinal);
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(2u, row->variableControlDiscreteMemberCount);
    EXPECT_EQ(2u, row->scheduleLeafCount);
    const std::size_t base = row->scheduleStorageBase;
    const std::array<VnVoiceHandle, 2> sourceVoices = {
        engine->playableScheduleRenderHandles[base],
        engine->playableScheduleRenderHandles[base + 1u]};
    ASSERT_NE(0u, sourceVoices[0]);
    ASSERT_NE(0u, sourceVoices[1]);
    EXPECT_NE(sourceVoices[0], sourceVoices[1]);
    EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoices[0]));
    EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoices[1]));

    for (std::uint32_t block = 0;
         block < 64 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    EXPECT_EQ(2u,
              row->variableControlDiscreteRetargetSourceMemberCount);
    EXPECT_EQ(1u,
              row->variableControlDiscreteRetargetTargetMemberCount);
    EXPECT_EQ(3u,
              row->variableControlDiscreteRetargetGroupMemberCount);
    ASSERT_TRUE(row->variableControlDiscreteRetargetTransition.Valid());
    ExpectVariableControlRetargetTree(*engine, *row,
                                      harken::PlayableKind::Sound, 1u);
    EXPECT_EQ(transitionsBefore + 1u,
              engine->transitionInstances.LiveCount());

    const VnVoiceHandle targetVoice =
        engine->playableScheduleRenderHandles[
            base + row->variableControlDiscreteTransitionOffset];
    ASSERT_NE(0u, targetVoice);
    EXPECT_NE(sourceVoices[0], targetVoice);
    EXPECT_NE(sourceVoices[1], targetVoice);
    EXPECT_NE(nullptr, engine->voices.Resolve(targetVoice));

    harken::Plan03PageGroupView group{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        row->variableControlDiscreteRetargetSlice, &group));
    EXPECT_EQ(2u, group.sourceControlCount);
    const std::uint64_t decisionFrame =
        row->variableControlDiscreteRetargetFrame;
    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           decisionFrame) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    for (VnVoiceHandle sourceVoice : sourceVoices) {
        const harken::VoiceRenderContext* source =
            engine->voices.Resolve(sourceVoice);
        ASSERT_NE(nullptr, source);
        EXPECT_TRUE(source->timelineEnvelopes[1].active);
        EXPECT_TRUE(source->timelineEnvelopes[1].fadeOut);
    }
    const harken::VoiceRenderContext* target =
        engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, target);
    EXPECT_FALSE(target->timelineGated);
    EXPECT_TRUE(target->timelineEnvelopes[0].active);
    EXPECT_FALSE(target->timelineEnvelopes[0].fadeOut);

    bool handedOff = false;
    for (std::uint32_t block = 0; block < 32 && !handedOff; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        std::size_t currentMemberSlot = 0;
        ASSERT_TRUE(engine->ResolvePlayableMemberSlot(base, &currentMemberSlot));
        handedOff =
            engine->voices.Resolve(sourceVoices[0]) == nullptr &&
            engine->voices.Resolve(sourceVoices[1]) == nullptr &&
            engine->voices.Resolve(targetVoice) != nullptr &&
            row->variableControlDiscreteMemberCount == 1u &&
            engine->playableScheduleRenderHandles[currentMemberSlot] == targetVoice;
    }
    ASSERT_TRUE(handedOff);
    EXPECT_EQ(voicesBefore + 1u, engine->voices.ActiveCount());
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);

    for (std::uint32_t block = 0; block < 64; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    ExpectVariableControlRetargetTreeRetired(*engine, *row);
    EXPECT_EQ(playablesBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlsBefore,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_EQ(transitionsBefore,
              engine->transitionInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(firingsBefore, engine->actionFirings.LiveCount());
}

TEST(ActionFiringApi,
     ImmediateVariableControlTransitionFadesEveryCompositeTrackSourceLeafAndCompletesAfterTargetRetires) {
    ExpectImmediateVariableControlTransitionCompletesForCompositeSource(
        false);
}

TEST(ActionFiringApi,
     ImmediateVariableControlTransitionFadesEveryCompositePieceSourceLeafAndCompletesAfterTargetRetires) {
    ExpectImmediateVariableControlTransitionCompletesForCompositeSource(
        true);
}

void ExpectNaturalEndVariableControlTransitionUsesLatestCompositeSourceLeaf(
    bool pieceSource) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(6, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4608, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                             &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateVariableControlPlayThenSetValueAction();
    if (pieceSource) {
        image.MakeFirstVariableControlChildCompositePiece();
    } else {
        image.MakeFirstVariableControlChildCompositeTrack();
    }
    image.containers[3].discreteTiming = 1;
    image.containers[3].evaluationPeriodFrames = 64;
    image.EnableNaturalEndVariableControlTransition(1024, 192);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const std::uint32_t playablesBefore =
        engine->playableInstances.LiveCount();
    const std::uint32_t variableControlsBefore =
        engine->variableControlInstances.LiveCount();
    const std::uint32_t voicesBefore = engine->voices.ActiveCount();
    const std::uint32_t decisionsBefore = engine->decisions.LiveCount();
    const std::uint32_t armGroupsBefore = engine->armGroups.LiveCount();
    const std::uint32_t transitionsBefore =
        engine->transitionInstances.LiveCount();
    const std::uint32_t firingsBefore = engine->actionFirings.LiveCount();

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    EXPECT_EQ(playablesBefore + 4u,
              engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlsBefore + 1u,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore + 2u, engine->voices.ActiveCount());

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(0u, play.executionOrdinal);
    VnActionStepResult setValue{};
    setValue.structSize = sizeof(setValue);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &setValue));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, setValue.state);
    EXPECT_EQ(1u, setValue.executionOrdinal);
    ASSERT_NE(0u, play.producedPlayableInstance);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(2u, row->variableControlDiscreteMemberCount);
    EXPECT_EQ(2u, row->scheduleLeafCount);
    const std::size_t base = row->scheduleStorageBase;
    const std::array<VnVoiceHandle, 2> sourceVoices = {
        engine->playableScheduleRenderHandles[base],
        engine->playableScheduleRenderHandles[base + 1u]};
    ASSERT_NE(0u, sourceVoices[0]);
    ASSERT_NE(0u, sourceVoices[1]);
    EXPECT_NE(sourceVoices[0], sourceVoices[1]);
    EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoices[0]));
    EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoices[1]));
    const std::uint64_t firstEnd =
        engine->playableScheduleStartFrames[base] + first.size();
    const std::uint64_t secondEnd =
        engine->playableScheduleStartFrames[base + 1u] + second.size();
    const std::uint64_t latestNaturalEnd =
        std::max(firstEnd, secondEnd);
    ASSERT_LT(firstEnd, latestNaturalEnd);
    ASSERT_TRUE(row->frontierLifetimeEntry.Valid());
    ASSERT_EQ(row->ownerInstance, row->frontierLifetimeEntry.owner.child);
    ASSERT_EQ(row->ownerEpoch, row->frontierLifetimeEntry.owner.childEpoch);
    const auto initialCoordinator = row->frontierLifetimeEntry.coordinator;

    for (std::uint32_t block = 0;
         block < 64 && !row->variableControlDiscreteRetargetPrepared;
         ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!row->variableControlDiscreteRetargetPrepared) {
            engine->nullBackend.Pump(1);
        }
    }
    ASSERT_TRUE(row->variableControlDiscreteRetargetPrepared);
    EXPECT_EQ(latestNaturalEnd - 1024u,
              row->variableControlDiscreteRetargetFrame);
    EXPECT_EQ(latestNaturalEnd + 192u,
              row->variableControlDiscreteRetargetEndFrame);
    EXPECT_EQ(2u,
              row->variableControlDiscreteRetargetSourceMemberCount);
    EXPECT_EQ(1u,
              row->variableControlDiscreteRetargetTargetMemberCount);
    EXPECT_EQ(3u,
              row->variableControlDiscreteRetargetGroupMemberCount);
    ASSERT_TRUE(row->variableControlDiscreteRetargetTransition.Valid());
    ExpectVariableControlRetargetTree(*engine, *row,
                                      harken::PlayableKind::Sound, 1u);
    EXPECT_EQ(transitionsBefore + 1u,
              engine->transitionInstances.LiveCount());

    const VnVoiceHandle targetVoice =
        engine->playableScheduleRenderHandles[
            base + row->variableControlDiscreteTransitionOffset];
    ASSERT_NE(0u, targetVoice);
    EXPECT_NE(sourceVoices[0], targetVoice);
    EXPECT_NE(sourceVoices[1], targetVoice);
    const harken::VoiceRenderContext* preparedTarget =
        engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, preparedTarget);

    harken::Plan03PageGroupView group{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
        row->variableControlDiscreteRetargetSlice, &group));
    EXPECT_EQ(2u, group.sourceControlCount);

    const std::uint64_t fadeStart = latestNaturalEnd - 1024u;
    for (std::uint32_t index = 0; index < sourceVoices.size(); ++index) {
        const auto& runtime =
            row->variableControlDiscreteRetargetRuntimePrograms[index];
        ASSERT_EQ(1u, runtime.payloadCount);
        EXPECT_EQ(harken::TimelineEventKind::Envelope,
                  runtime.payloads[0].kind);
        EXPECT_EQ(harken::TimelineEnvelopeDirection::FadeOut,
                  runtime.payloads[0].envelopeDirection);
        EXPECT_EQ(fadeStart,
                  runtime.payloads[0].envelopeStartFrame);
        EXPECT_EQ(latestNaturalEnd,
                  runtime.payloads[0].envelopeEndFrame);
    }

    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           fadeStart) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    for (VnVoiceHandle sourceVoice : sourceVoices) {
        const harken::VoiceRenderContext* source =
            engine->voices.Resolve(sourceVoice);
        ASSERT_NE(nullptr, source);
        EXPECT_TRUE(source->timelineEnvelopes[1].active);
        EXPECT_TRUE(source->timelineEnvelopes[1].fadeOut);
    }
    const harken::VoiceRenderContext* gatedTarget =
        engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, gatedTarget);
    EXPECT_TRUE(gatedTarget->timelineGated);

    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           firstEnd) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_LT(engine->mixer.BlocksRendered() * engine->config.blockFrames,
              latestNaturalEnd);
    const harken::VoiceRenderContext* targetBeforeLatest =
        engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, targetBeforeLatest);
    EXPECT_TRUE(targetBeforeLatest->timelineGated);
    EXPECT_NE(nullptr, engine->voices.Resolve(sourceVoices[1]));
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);

    while (engine->mixer.BlocksRendered() * engine->config.blockFrames <=
           latestNaturalEnd) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(nullptr, engine->voices.Resolve(sourceVoices[0]));
    EXPECT_EQ(nullptr, engine->voices.Resolve(sourceVoices[1]));
    const harken::VoiceRenderContext* releasedTarget =
        engine->voices.Resolve(targetVoice);
    ASSERT_NE(nullptr, releasedTarget);
    EXPECT_FALSE(releasedTarget->timelineGated);
    EXPECT_TRUE(releasedTarget->timelineEnvelopes[0].active);
    EXPECT_EQ(1u, row->variableControlDiscreteMemberCount);
    std::size_t currentMemberSlot = 0;
    ASSERT_TRUE(engine->ResolvePlayableMemberSlot(base, &currentMemberSlot));
    EXPECT_EQ(targetVoice,
              engine->playableScheduleRenderHandles[currentMemberSlot]);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);

    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }
    ASSERT_NO_FATAL_FAILURE(ExpectVariableControlNaturalCompletion(
            *engine, firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    ExpectVariableControlRetargetTreeRetired(*engine, *row);
    ASSERT_FALSE(row->frontierLifetimePin.Valid());
    ASSERT_FALSE(engine->decisions.Contains(initialCoordinator));
    const auto releasedAt = engine->mixer.BlocksRendered();
    engine->nullBackend.Pump(1);
    ASSERT_GT(engine->mixer.BlocksRendered(), releasedAt);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    EXPECT_EQ(playablesBefore, engine->playableInstances.LiveCount());
    EXPECT_EQ(variableControlsBefore,
              engine->variableControlInstances.LiveCount());
    EXPECT_EQ(voicesBefore, engine->voices.ActiveCount());
    EXPECT_EQ(decisionsBefore, engine->decisions.LiveCount());
    EXPECT_EQ(armGroupsBefore, engine->armGroups.LiveCount());
    EXPECT_EQ(transitionsBefore,
              engine->transitionInstances.LiveCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    EXPECT_EQ(firingsBefore, engine->actionFirings.LiveCount());
}

