TEST(ActionFiringApi, CurrentWorldReplacementCancelsActiveActionFiring) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(4096, 0.25f);
    std::vector<float> second(4096, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    CanonicalActionWorld replacement(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    replacement.variables[0].defaultValue = 0.25f;
    replacement.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(replacement.world);
    ASSERT_EQ(harken::WorldInstallStatus::Backpressure,
              harken::InstallContainerWorldV1(*engine, replacement.world)
                  .status);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, info.state);
    EXPECT_EQ(VN_ACTION_TERMINAL_WORLD_REPLACED, info.terminalReason);
    for (std::uint32_t block = 0; block < 96; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_WORLD_REPLACED, info.terminalReason);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_CANCELLED, play.state);
    EXPECT_EQ(VN_OK, play.result);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, TransportResetCancelsActiveActionFiring) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(1, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_EQ(VN_OK, Vn_Update());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());

    harken::RuntimeTransportResetStatus reset =
        harken::BeginRuntimeTransportReset(*engine, 0);
    ASSERT_EQ(harken::RuntimeTransportResetStatus::Backpressure, reset);
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_STOPPING, info.state);
    EXPECT_EQ(VN_ACTION_TERMINAL_TRANSPORT_RESET, info.terminalReason);
    for (std::uint32_t block = 0;
         block < 96 &&
         reset == harken::RuntimeTransportResetStatus::Backpressure;
         ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        reset = harken::BeginRuntimeTransportReset(*engine, 0);
    }

    ASSERT_EQ(harken::RuntimeTransportResetStatus::Complete, reset);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_CANCELLED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_TRANSPORT_RESET, info.terminalReason);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_CANCELLED, play.state);
    EXPECT_EQ(VN_OK, play.result);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, AuthoredStopCompletesCapturedSameFiringPlay) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(1, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(4096, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision);
    image.MakeImmediateSoundPlayThenStopAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(0u, info.directStepTerminalCount);
    EXPECT_EQ(1u, info.livePlayableCount);

    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);

    VnActionStepResult stop{};
    stop.structSize = sizeof(stop);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, stop.state);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(1u, stop.remainingPlayableCount);

    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(2u, info.directStepTerminalCount);
    EXPECT_EQ(0u, info.livePlayableCount);

    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_EQ(VN_OK, play.result);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 1, &stop));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, stop.state);
    EXPECT_EQ(VN_OK, stop.result);
    EXPECT_EQ(1u, stop.capturedPlayableCount);
    EXPECT_EQ(0u, stop.remainingPlayableCount);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

