TEST(ActionFiringApi, ImmediateCompositeTrackUsesLaneWhenItsPageIsFull) {
    (void)Vn_Term();
    constexpr std::uint32_t kBlockFrames = 64;
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, kBlockFrames, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> first(kBlockFrames, 0.25f);
    std::vector<float> second(kBlockFrames, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateCompositeTrackPlayAction(
        (2 * kBlockFrames * INT64_C(1000000000) + 47999) / 48000);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto pageFrame = ImmediateActionStartFrame(*engine);
    const auto capacity = engine->timelinePool.MaxEventsPerQuantum();
    const auto perTransaction = engine->timelinePool.MaxTransactionEvents();
    for (std::uint32_t filled = 0, transaction = 1; filled < capacity; ++transaction) {
        const auto count = std::min(perTransaction, capacity - filled);
        ASSERT_EQ(harken::ReserveStatus::Committed,
            ReserveActionPreparationTransaction(
                *engine, 2000u + transaction, pageFrame, count).status);
        filled += count;
    }
    ASSERT_EQ(harken::ReserveRefusal::PageEventCapacity,
        engine->timelinePool.PreflightSingleEvent(
            pageFrame, engine->timelinePool.PublishCutoffFrame()));
    VnPostActionDesc post = ValidPostDesc();
    post.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&post, &firing));
    const auto row = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [firing](const auto& candidate) {
            return candidate.InvocationValid() &&
                candidate.Invocation().actionFiring == firing;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->pendingImmediateEntry);
    ASSERT_EQ(2u, row->scheduleLeafCount);
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    const auto secondStart =
        engine->playableScheduleStartFrames[row->scheduleStorageBase + 1u] /
        kBlockFrames;
    bool heardFirst = false;
    bool heardSecondAtExpectedBlock = false;
    for (std::uint32_t block = 0; block < 8; ++block) {
        engine->nullBackend.Pump(1);
        const float* output = engine->nullBackend.LastBlock();
        heardFirst = heardFirst || std::any_of(output, output + kBlockFrames,
            [](float sample) { return sample > 0.01f; });
        if (engine->mixer.BlocksRendered() == secondStart + 1u)
            heardSecondAtExpectedBlock = std::any_of(
                output, output + kBlockFrames,
                [](float sample) { return sample < -0.01f; });
    }
    EXPECT_TRUE(heardFirst);
    EXPECT_TRUE(heardSecondAtExpectedBlock);
}

