TEST(ActionFiringApi, MultiLeafLateNormalUpdateKeepsOriginalSourcesAndAuthoredOffsets) {
    for (const bool track : {false, true}) {
        for (const std::int64_t secondLeafStartNanoseconds :
             {INT64_C(0), INT64_C(128) * INT64_C(1000000000) / 48000}) {
            (void)Vn_Term();
            constexpr std::uint32_t kBlockFrames = 64;
            harkentest::EngineSession session(harkentest::MakeNullConfig(8, kBlockFrames, 48000));
            ASSERT_EQ(VN_OK, session.InitResult());
            auto* engine = session.Engine();
            std::vector<float> first(1024, 0.25f);
            std::vector<float> second(1024, 0.125f);
            const auto firstPcm = harkentest::MonoDesc(first, 48000);
            const auto secondPcm = harkentest::MonoDesc(second, 48000);
            ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
            ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
            CanonicalActionWorld image(
                engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
                engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
            if (track)
                image.MakeImmediateCompositeTrackPlayAction(secondLeafStartNanoseconds);
            else
                image.MakeImmediateCompositeContainerPlayAction(secondLeafStartNanoseconds);
            ASSERT_EQ(harken::WorldInstallStatus::Ok,
                      harken::InstallContainerWorldV1(*engine, image.world).status);
            VnPostActionDesc desc = ValidPostDesc();
            desc.actionId = image.actions[9].actionStableId;
            VnActionFiringHandle firing = 0;
            ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
            auto row = std::find_if(engine->playableServices.begin(),
                                    engine->playableServices.end(), [firing](const auto& member) {
                                        return member.InvocationValid() &&
                                               member.Invocation().actionFiring == firing;
                                    });
            ASSERT_NE(engine->playableServices.end(), row);
            ASSERT_EQ(2u, row->scheduleLeafCount);
            const auto base = row->scheduleStorageBase;
            const auto firstArm = engine->playableScheduleArms[base];
            const auto secondArm = engine->playableScheduleArms[base + 1u];
            const std::array<VnVoiceHandle, 2> originalRenders{
                engine->playableScheduleRenderHandles[base],
                engine->playableScheduleRenderHandles[base + 1u]};
            // Audio advances before normal service; Source identity must survive.
            engine->nullBackend.Pump(3);
            ASSERT_EQ(VN_OK, Vn_Update());
            VnActionFiringInfo info{};
            info.structSize = sizeof(info);
            bool audible = false;
            std::array<bool, 2> originalStarted{};
            std::array<std::uint64_t, 2> actualOnsets{};
            const std::array<harken::TimelineArmToken, 2> originalArms{firstArm, secondArm};
            for (std::uint32_t block = 0; block < 64; ++block) {
                ASSERT_EQ(VN_OK, Vn_Update());
                engine->nullBackend.Pump(1);
                for (std::size_t member = 0; member < originalArms.size(); ++member) {
                    harken::TimelineArmObservation actual{};
                    if (!originalStarted[member] &&
                        engine->timelineArms.Observe(originalArms[member], &actual) &&
                        actual.startedBlockSequence != 0) {
                        harken::EngineTimelineVoiceInstallIdentity installation{};
                        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(
                            originalRenders[member], &installation));
                        ASSERT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(
                            originalArms[member], installation.startArm));
                        originalStarted[member] = true;
                        actualOnsets[member] = installation.onsetFrame;
                    }
                }
                const float* output = engine->nullBackend.LastBlock();
                audible = audible || std::any_of(output, output + kBlockFrames, [](float sample) {
                              return std::abs(sample) > 0.001f;
                          });
                ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
                if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED &&
                    engine->playableInstances.LiveCount() == 0 &&
                    engine->playablePartitions.OccupiedCount() == 0)
                    break;
            }
            EXPECT_TRUE(audible);
            EXPECT_NE(VN_ACTION_TERMINAL_DEADLINE, info.terminalReason);
            EXPECT_TRUE(originalStarted[0]);
            EXPECT_TRUE(originalStarted[1]);
            ASSERT_GE(actualOnsets[1], actualOnsets[0]);
            const auto authoredOffset = static_cast<std::uint64_t>(secondLeafStartNanoseconds) *
                UINT64_C(48000) / UINT64_C(1000000000);
            EXPECT_EQ(authoredOffset, actualOnsets[1] - actualOnsets[0]);
            EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
            EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
            EXPECT_EQ(0u, engine->playableInstances.LiveCount());
            EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
            EXPECT_FALSE(engine->runtimeRecreateRequired);
            ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
            EXPECT_EQ(0u, engine->voices.ActiveCount());
        }
    }
}

TEST(ActionFiringApi, ImmediateNestedSequenceContainerTrackChildBuildsCompleteTree) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(64, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateNestedCompositeContainerPlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    ASSERT_EQ(VN_ACTION_STEP_ACTIVE, step.state);
    ASSERT_NE(0u, step.producedPlayableInstance);

    const auto outer = engine->playableInstances.Classify(step.producedPlayableInstance);
    ASSERT_TRUE(outer.live);
    ASSERT_EQ(harken::PlayableKind::Container, outer.kind);
    ASSERT_NE(0u, outer.firstChild);
    const auto inner = engine->playableInstances.Classify(outer.firstChild);
    ASSERT_TRUE(inner.live);
    ASSERT_EQ(harken::PlayableKind::Container, inner.kind);
    EXPECT_EQ(step.producedPlayableInstance, inner.parent);
    ASSERT_NE(0u, inner.firstChild);
    const auto track = engine->playableInstances.Classify(inner.firstChild);
    ASSERT_TRUE(track.live);
    ASSERT_EQ(harken::PlayableKind::Track, track.kind);
    EXPECT_EQ(outer.firstChild, track.parent);
    ASSERT_NE(0u, track.firstChild);
    EXPECT_EQ(harken::PlayableKind::Sound,
              engine->playableInstances.Classify(track.firstChild).kind);
    EXPECT_EQ(2u, engine->containerPlayback.LiveCount());

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(0u, info.livePlayableCount);
    EXPECT_EQ(0u, engine->containerPlayback.LiveCount());
    EXPECT_FALSE(engine->playableInstances.Classify(outer.firstChild).live);
    EXPECT_FALSE(engine->playableInstances.Classify(inner.firstChild).live);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

TEST(ActionFiringApi, InitialQueueTimingCandidateRetainsCompositeOffsetsAndPrivateBank) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(128, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.MakeFirstQueueChildCompositeTrack();
    image.trackPlacements[1].authoredStart = 2000000;
    image.track.scheduleSemanticFingerprint =
        harken::ComputeTrackScheduleFingerprintV1(image.track);
    image.queueChildren[0].timingHint =
        harken::MakeScheduleReferenceTimingHint(
            harken::PlayableKindV1::Track,
            image.track.rootDefinition.stableId,
            image.track.scheduleSemanticFingerprint);
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto* attempt = std::find_if(
        engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() +
            engine->immediateEntryAttemptCapacity,
        [firing](const auto& candidate) {
            return candidate.active && candidate.root == firing;
        });
    ASSERT_NE(engine->immediateEntryAttempts.get() +
                  engine->immediateEntryAttemptCapacity, attempt);
    ASSERT_TRUE(attempt->initialService.Valid());
    ASSERT_LE(attempt->initialEntryFrame, UINT64_MAX - 64u);
    std::size_t memberCount = 0;
    std::size_t programCount = 0;
    std::size_t eventCount = 0;
    std::size_t leafCount = 0;
    std::size_t groupCount = 0;
    std::size_t holderCount = 0;
    ASSERT_TRUE(harken::test::CollectInitialQueueTimingMembersForTest(
        *engine, firing, attempt->initialEntryFrame + 64u,
        &memberCount, &programCount, &eventCount, &leafCount,
        &groupCount, &holderCount));
    ASSERT_GE(memberCount, 1u);
    ASSERT_GE(leafCount, 2u);
    ASSERT_GE(groupCount, 1u);
    ASSERT_GE(holderCount, 1u);
    const auto composite = std::find_if(
        engine->initialQueueTimingMembersScratch.begin(),
        engine->initialQueueTimingMembersScratch.begin() + memberCount,
        [](const auto& candidate) {
            return candidate.currentLeafCount == 2u &&
                   candidate.conditional.Valid();
        });
    ASSERT_NE(engine->initialQueueTimingMembersScratch.begin() + memberCount,
              composite);
    EXPECT_EQ(composite->oldEntryFrame + 64u, composite->newEntryFrame);
    EXPECT_EQ(0u, composite->conditionalLogicalStartFrame);
    EXPECT_EQ(0u, composite->conditionalLogicalCompletionFrame);
    const auto& first = engine->initialQueueTimingLeavesScratch[
        composite->firstCurrentLeaf];
    const auto& second = engine->initialQueueTimingLeavesScratch[
        composite->firstCurrentLeaf + 1u];
    ASSERT_EQ(96u, second.absoluteLeafStartFrame -
                       first.absoluteLeafStartFrame);
    harken::KnownScheduleLeafV1 originalFirst{};
    harken::KnownScheduleLeafV1 originalSecond{};
    ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(
        engine->playableServices[composite->service.slot]
            .queueCurrentCompositeOwner, 0, &originalFirst));
    ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(
        engine->playableServices[composite->service.slot]
            .queueCurrentCompositeOwner, 1, &originalSecond));
    EXPECT_EQ(originalFirst.absoluteLeafStartFrame + 64u,
              first.absoluteLeafStartFrame);
    EXPECT_EQ(originalSecond.absoluteLeafStartFrame + 64u,
              second.absoluteLeafStartFrame);
    EXPECT_EQ(originalSecond.predicate.progressBaselineRevision,
              second.predicate.progressBaselineRevision);
    ASSERT_NE(nullptr, composite->successorBank);
    ASSERT_FALSE(composite->successorBank->published);
    ASSERT_GT(composite->transactionCount, 0u);
    ASSERT_LT(composite->firstProgram, programCount);
    const auto& stagedProgram = engine->initialQueueTimingProgramsScratch[
        composite->firstProgram];
    ASSERT_GT(stagedProgram.eventCount, 0u);
    ASSERT_LT(stagedProgram.firstEvent, eventCount);
    const auto& staged = engine->initialQueueTimingEventsScratch[
        stagedProgram.firstEvent];
    const auto& request = engine->initialQueueTimingRequestsScratch[
        composite->firstProgram];
    const auto& scheduled = engine->initialQueueTimingScheduledEventsScratch[
        stagedProgram.firstEvent];
    ASSERT_EQ(stagedProgram.eventCount, request.eventCount);
    ASSERT_EQ(&scheduled, request.events);
    EXPECT_EQ(staged.newExecuteFrame, scheduled.executeFrame);
    EXPECT_EQ(composite->service, staged.holder);
    EXPECT_EQ(composite->firstProgram, staged.programIndex);
    EXPECT_EQ(staged.newExecuteFrame - (attempt->initialEntryFrame + 64u),
              staged.relativeFrame);
    EXPECT_EQ(stagedProgram.frozen->ownerInstance,
              request.ownerInstanceHandle);
    EXPECT_EQ(stagedProgram.frozen->ownerInstanceScheduleEpoch,
              request.ownerInstanceScheduleEpoch);
    EXPECT_EQ(stagedProgram.frozen->transactionId,
              request.transactionId);
    EXPECT_EQ(stagedProgram.frozen->runtimeProgram.program,
              request.program.program);
    ASSERT_LT(composite->firstGroup, groupCount);
    const auto& queueHolder = engine->playableServices[composite->service.slot];
    ASSERT_FALSE(queueHolder.queueFirstContinuationLane);
    EXPECT_EQ(queueHolder.queueDecision.slot, composite->decision.slot);
    EXPECT_EQ(queueHolder.queueDecision.generation,
              composite->decision.generation);
    ASSERT_GT(composite->groupCount, 0u);
    ASSERT_LE(composite->groupCount, composite->newGroupFrames.size());
    ASSERT_LE(composite->firstGroup + composite->groupCount, groupCount);
    for (std::uint32_t index = 0; index < composite->groupCount; ++index) {
        const auto& expected = engine->initialQueueTimingGroupsScratch[
            composite->firstGroup + index];
        EXPECT_EQ(composite->newGroupFrames[index], expected.executeFrame);
        EXPECT_EQ(queueHolder.initialQueueEntryDecision.slot,
                  expected.decision.slot);
        EXPECT_EQ(queueHolder.initialQueueEntryDecision.generation,
                  expected.decision.generation);
        EXPECT_EQ(index, expected.sliceIndex);
    }
    const auto& group = engine->initialQueueTimingGroupsScratch[
        composite->firstGroup];
    const auto holder = std::find_if(
        engine->initialQueueTimingCohortScratch.begin(),
        engine->initialQueueTimingCohortScratch.begin() + holderCount,
        [composite](const auto& candidate) {
            return candidate.credit != nullptr &&
                candidate.credit->slot == composite->credit.slot &&
                candidate.credit->generation ==
                    composite->credit.generation;
        });
    ASSERT_NE(engine->initialQueueTimingCohortScratch.begin() +
                  holderCount, holder);
    EXPECT_EQ(composite->transactionCount, holder->requestCount);
    EXPECT_EQ(composite->groupCount, holder->groupCount);
    EXPECT_EQ(&request, holder->requests);
    EXPECT_EQ(&group, holder->groups);
    std::uint32_t groupPage = UINT32_MAX;
    ASSERT_TRUE(engine->timelinePool.PageForFrame(
        group.executeFrame, &groupPage));
    const auto beforePage = *engine->timelinePool.Page(groupPage);
    {
        harken::ScheduledTransactionPool::PrivateMaterializationTransaction
            failedPage{};
        harken::ReserveRefusal transactionRefusal =
            harken::ReserveRefusal::None;
        harken::Plan03GroupReserveStatus groupStatus =
            harken::Plan03GroupReserveStatus::Committed;
        engine->timelinePool.SetPrivateMaterializationFaultStepForTest(2u);
        EXPECT_FALSE(engine->timelinePool.TryMaterializeUnplacedCohort(
            engine->initialQueueTimingCohortScratch.data(), holderCount,
            engine->timelineArms, engine->timelinePool.PublishCutoffFrame(),
            &failedPage, &transactionRefusal, &groupStatus));
        EXPECT_FALSE(failedPage.Valid());
    }
    const auto afterFailure = *engine->timelinePool.Page(groupPage);
    EXPECT_EQ(beforePage.committedTransactionCount,
              afterFailure.committedTransactionCount);
    EXPECT_EQ(beforePage.plan03GroupCount,
              afterFailure.plan03GroupCount);
    {
        harken::ScheduledTransactionPool::PrivateMaterializationTransaction
            privatePage{};
        harken::ReserveRefusal transactionRefusal =
            harken::ReserveRefusal::None;
        harken::Plan03GroupReserveStatus groupStatus =
            harken::Plan03GroupReserveStatus::Committed;
        ASSERT_TRUE(engine->timelinePool.TryMaterializeUnplacedCohort(
            engine->initialQueueTimingCohortScratch.data(), holderCount,
            engine->timelineArms, engine->timelinePool.PublishCutoffFrame(),
            &privatePage, &transactionRefusal, &groupStatus));
        ASSERT_TRUE(privatePage.Valid());
        EXPECT_EQ(groupCount, privatePage.GroupCount());
    }
    EXPECT_TRUE(engine->playableServices[composite->service.slot]
                    .queueUnplacedCredit.Valid());
    ASSERT_NE(nullptr, staged.frozen);
    ASSERT_NE(nullptr, staged.payload);
    ASSERT_EQ(&composite->successorBank->schedules[0],
              stagedProgram.frozen);
    ASSERT_EQ(stagedProgram.frozen->events, staged.frozen);
    EXPECT_EQ(stagedProgram.frozen->entryAnchorFrame +
                  static_cast<std::uint64_t>(
                      staged.frozen->frameOffsetFromEntry) + 64u,
              staged.newExecuteFrame);
    EXPECT_FALSE(composite->successorBank->published);
    EXPECT_FALSE(harken::test::CollectInitialQueueTimingMembersForTest(
        *engine, firing, UINT64_MAX, &memberCount, &programCount,
        &eventCount, &leafCount, &groupCount, &holderCount));
    auto& groupOnlyRow = engine->playableServices[composite->service.slot];
    ASSERT_TRUE(engine->timelinePool.CancelUnplacedBatchCredit(
        &groupOnlyRow.queueUnplacedCredit));
    harken::UnplacedBatchCreditRequest groupOnlyDemand{};
    groupOnlyDemand.groupHeaders = groupOnlyRow.queueUnplacedGroupCount;
    ASSERT_GT(groupOnlyDemand.groupHeaders, 0u);
    ASSERT_TRUE(engine->timelinePool.ReserveUnplacedBatchCredit(
        groupOnlyDemand, &groupOnlyRow.queueUnplacedCredit));
    groupOnlyRow.queueUnplacedDemand = groupOnlyDemand;
    groupOnlyRow.queueUnplacedDemandCredit =
        groupOnlyRow.queueUnplacedCredit;
    groupOnlyRow.queueUnplacedTransactionCount = 0;
    ASSERT_TRUE(harken::test::CollectInitialQueueTimingMembersForTest(
        *engine, firing, attempt->initialEntryFrame + 64u,
        &memberCount, &programCount, &eventCount, &leafCount,
        &groupCount, &holderCount));
    const auto groupOnly = std::find_if(
        engine->initialQueueTimingCohortScratch.begin(),
        engine->initialQueueTimingCohortScratch.begin() + holderCount,
        [&groupOnlyRow](const auto& candidate) {
            return candidate.credit == &groupOnlyRow.queueUnplacedCredit;
        });
    ASSERT_NE(engine->initialQueueTimingCohortScratch.begin() +
                  holderCount, groupOnly);
    EXPECT_EQ(0u, groupOnly->requestCount);
    EXPECT_EQ(nullptr, groupOnly->requests);
    EXPECT_EQ(groupOnlyDemand.groupHeaders, groupOnly->groupCount);
    EXPECT_NE(nullptr, groupOnly->groups);
}

void AddIndependentSecondSoundPlayAction(CanonicalActionWorld& image) {
    image.steps[14] = image.steps[11];
    image.steps[14].target.kind = harken::ActionTargetKindV1::Sound;
    image.steps[14].target.stableId = CanonicalActionWorld::kSecondSound;
    image.steps[14].target.expectedProgramSemanticFingerprint =
        image.properties[1].programSemanticFingerprint;
    image.actions[10] = image.actions[9];
    image.actions[10].actionStableId = harkentest::ObjectId(51);
    image.actions[10].steps = &image.steps[14];
    image.actions[10].programSemanticFingerprint =
        harken::ComputeActionProgramFingerprintV1(image.actions[10]);
    image.world.actionCount = 11;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
}

TEST(ActionFiringApi, IndependentSoundInQueueWorldBaseline) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> samples(128, 0.25f);
    const VnPCMDesc pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    AddIndependentSecondSoundPlayAction(image);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc independent = ValidPostDesc();
    independent.actionId = image.actions[10].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&independent.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&independent, &firing));
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 8; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
    }
    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome)
        << "terminalReason=" << info.terminalReason
        << " stepState=" << step.state
        << " stepResult=" << step.result;
}

void CheckInitialQueueLanePrepareFaultLeavesIndependentActionLive(
    bool yieldAfterFirstRootReader, bool blockSecondStop = false,
    bool repeatExternalStop = false, bool dropNotification = false) {
    (void)Vn_Term();
    auto config = harkentest::MakeNullConfig(8, 64, 48000);
    if (dropNotification) config.notificationQueueDepth = 32;
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> firstSamples(128, 0.25f);
    std::vector<float> secondSamples(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(firstSamples, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(secondSamples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound,
                                   &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                                   &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    AddIndependentSecondSoundPlayAction(image);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnPostActionDesc queue = ValidPostDesc();
    queue.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&queue.emitter));
    VnActionFiringHandle queueFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&queue, &queueFiring));
    const auto queueRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [queueFiring](const auto& row) {
            return row.queueTimingPending && row.InvocationValid() &&
                row.Invocation().actionFiring == queueFiring;
        });
    ASSERT_NE(engine->playableServices.end(), queueRow);
    ASSERT_TRUE(queueRow->queueUnplacedCredit.Valid());
    const auto queueArm = queueRow->arm;
    const auto queueDecision = queueRow->queueDecision;
    const auto queueCredit = queueRow->queueUnplacedCredit;
    ASSERT_TRUE(queueDecision.Valid());
    const auto queueAttempt = std::find_if(
        engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() +
            engine->immediateEntryAttemptCapacity,
        [queueFiring](const auto& candidate) {
            return candidate.active && candidate.root == queueFiring;
        });
    ASSERT_NE(engine->immediateEntryAttempts.get() +
                  engine->immediateEntryAttemptCapacity, queueAttempt);
    const auto queueAttemptGeneration = queueAttempt->generation;
    const auto queueLane = queueAttempt->lane;
    ASSERT_TRUE(queueLane.Valid());
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> queueGroups{};
    const auto queueGroupCount = engine->timelinePool.
        CaptureImmediateLaneCohortGroups(
            queueFiring, queueGroups.data(), queueGroups.size());
    ASSERT_GT(queueGroupCount, 0u);
    ASSERT_LE(queueGroupCount, queueGroups.size());
    for (std::size_t index = 0; index < queueGroupCount; ++index)
        EXPECT_TRUE(queueGroups[index].identity.Exact());
    std::vector<harken::HorizonPageHeader> before;
    for (std::uint32_t page = 0;
         page < engine->timelinePool.PageCount(); ++page)
        before.push_back(*engine->timelinePool.Page(page));
    const auto baselineAudioSequence = engine->mixer.BlocksRendered();
    const auto commandBackpressureBefore = engine->commands.BackpressureCount();
    if (yieldAfterFirstRootReader)
        engine->forceInitialQueuePrivateRootReaderYieldAfterForTest = 0;
    if (blockSecondStop)
        engine->forceInitialQueuePrivateStopPushFailureAtForTest = 1;
    engine->forceImmediateLaneFutureEventFaultForTest = 3u;
    VnPostActionDesc independent = queue;
    independent.actionId = image.actions[10].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&independent.emitter));
    VnActionFiringHandle independentFiring = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&independent, &independentFiring));
    const auto privateBefore = engine->timelinePool
        .CapturePrivateMaterializationSnapshotForTest();
    VnActionFiringInfo independentInfo{};
    independentInfo.structSize = sizeof(independentInfo);
    bool observedFault = false;
    bool observedHeldArmAfterAudioBlock = false;
    bool observedSecondStopRetry = false;
    bool droppedExactTerminal = false;
    bool observedExactLedgerSweep = false;
    std::uint64_t faultAudioSequence = 0;
    int faultCoordinatorState = -1;
    std::uint32_t faultBoundFrontierGroups = 0;
    bool heardQueue = false;
    bool heardIndependent = false;
    for (std::uint32_t block = 0; block < 16; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (blockSecondStop && observedFault && !observedSecondStopRetry &&
            engine->forceInitialQueuePrivateStopPushFailureAtForTest == UINT32_MAX) {
            const auto secondRender = queueAttempt->privateVoices[1].render;
            std::uint32_t secondStopCount = 0;
            harken::CommandRecord queued{};
            for (std::uint32_t index = 0;
                 index < engine->commands.Capacity() - engine->commands.FreeSlots();
                 ++index) {
                ASSERT_TRUE(engine->commands.PeekAt(index, queued));
                if (queued.opcode == harken::kOpcodeStop &&
                    queued.payload.stop.handle == secondRender)
                    ++secondStopCount;
            }
            EXPECT_EQ(1u, secondStopCount);
            EXPECT_TRUE(queueAttempt->privateVoices[1].stopQueued);
            observedSecondStopRetry = true;
        }
        if (!observedFault &&
            engine->forceImmediateLaneFutureEventFaultForTest == 0) {
            observedFault = true;
            faultAudioSequence = engine->mixer.BlocksRendered();
            if (yieldAfterFirstRootReader) {
                ASSERT_EQ(UINT32_MAX - 1u,
                    engine->forceInitialQueuePrivateRootReaderYieldAfterForTest);
                ASSERT_GE(queueAttempt->privateVoiceCount, 2u);
                const auto& first = queueAttempt->privateVoices[0];
                const auto* firstArm = engine->timelineArms.Resolve(first.startArm);
                ASSERT_NE(nullptr, firstArm);
                EXPECT_TRUE(first.rootReaderReleased);
                EXPECT_TRUE(first.rootArmComplete);
                EXPECT_EQ(0u, firstArm->frontierReaderPins.load());
                EXPECT_TRUE(firstArm->frontierAdmissionFinished.load());
                EXPECT_EQ(nullptr, firstArm->frontierActiveLease.load());
            }
            if (blockSecondStop) {
                ASSERT_EQ(UINT32_MAX - 1u,
                    engine->forceInitialQueuePrivateStopPushFailureAtForTest);
                ASSERT_EQ(2u, queueAttempt->privateVoiceCount);
                EXPECT_EQ(harken::InitialQueuePrivateCleanupPhase::StopQueued,
                    queueAttempt->privateCleanupPhase);
                EXPECT_TRUE(queueAttempt->privateVoices[0].stopQueued);
                EXPECT_FALSE(queueAttempt->privateVoices[1].stopQueued);
                EXPECT_TRUE(engine->ledger.IsTerminating(
                    queueAttempt->privateVoices[0].render));
                EXPECT_FALSE(engine->ledger.IsTerminating(
                    queueAttempt->privateVoices[1].render));
                EXPECT_TRUE(engine->ledger.OwnerForRender(
                    queueAttempt->privateVoices[1].render).live);
                EXPECT_TRUE(engine->commands.Full());
                EXPECT_GT(engine->commands.BackpressureCount(),
                          commandBackpressureBefore);
                std::uint32_t firstStopCount = 0;
                std::uint32_t secondStopCount = 0;
                harken::CommandRecord queued{};
                for (std::uint32_t index = 0;
                     index < engine->commands.Capacity() -
                         engine->commands.FreeSlots(); ++index) {
                    ASSERT_TRUE(engine->commands.PeekAt(index, queued));
                    if (queued.opcode != harken::kOpcodeStop) continue;
                    firstStopCount += queued.payload.stop.handle ==
                        queueAttempt->privateVoices[0].render;
                    secondStopCount += queued.payload.stop.handle ==
                        queueAttempt->privateVoices[1].render;
                }
                EXPECT_EQ(1u, firstStopCount);
                EXPECT_EQ(0u, secondStopCount);
            }
            if (repeatExternalStop) {
                ASSERT_EQ(VN_OK, Vn_StopActionFiring(queueFiring, 0));
                ASSERT_EQ(VN_OK, Vn_StopActionFiring(queueFiring, 0));
                EXPECT_NE(0u, queueRow->pendingCancellationIntent);
            }
            auto* coordinator = engine->decisions.ResolveFrontierActivation(
                queueAttempt->initialQueueCoordinator);
            if (coordinator != nullptr)
                faultCoordinatorState = static_cast<int>(coordinator->State());
            for (std::size_t index = 0; index < queueGroupCount; ++index) {
                harken::Plan03PageGroupView group{};
                if (!engine->timelinePool.ResolvePlan03GroupSliceProducer(
                        queueGroups[index].identity, &group) ||
                    group.frontier == nullptr) continue;
                const auto& owner = group.frontier->operation.owner;
                if (owner.serviceSlot == queueRow->identity.slot &&
                    owner.serviceGeneration == queueRow->identity.generation)
                    ++faultBoundFrontierGroups;
            }
            const auto snapshot = engine->timelinePool
                .CapturePrivateMaterializationSnapshotForTest();
            EXPECT_LE(snapshot.preparedEvents,
                      privateBefore.preparedEvents);
            EXPECT_LE(snapshot.preparedGroups,
                      privateBefore.preparedGroups);
            EXPECT_LE(snapshot.publicationHolds,
                      privateBefore.publicationHolds);
            EXPECT_FALSE(snapshot.active);
            EXPECT_FALSE(queueRow->queueTimingFinalized);
            EXPECT_NE(harken::ImmediateEntryAttemptState::Committed,
                      queueAttempt->gate.Observe(queueAttemptGeneration));
            harken::ImmediateLaneObservation lane{};
            if (engine->immediateActionLane.Observe(
                    queueLane, &lane))
                EXPECT_FALSE(lane.committed);
            for (std::size_t index = 0; index < queueGroupCount; ++index) {
                harken::Plan03PageGroupView audioGroup{};
                EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceRt(
                    queueGroups[index].identity, &audioGroup));
            }
            harken::ArmState armState = harken::ArmState::Free;
            if (engine->timelineArms.State(queueArm, &armState)) {
                EXPECT_NE(harken::ArmState::Published, armState);
                EXPECT_NE(harken::ArmState::Started, armState);
            }
            testing::Test::RecordProperty(
                "fault_decision_open",
                engine->decisions.IsOpen(queueDecision) ? 1 : 0);
            testing::Test::RecordProperty(
                "fault_decision_cancelled",
                engine->decisions.IsCancelled(queueDecision) ? 1 : 0);
            testing::Test::RecordProperty(
                "fault_credit_exact",
                queueRow->queueUnplacedCredit.Valid() &&
                    queueRow->queueUnplacedCredit.slot == queueCredit.slot &&
                    queueRow->queueUnplacedCredit.generation ==
                        queueCredit.generation ? 1 : 0);
        }
        engine->nullBackend.Pump(1);
        if (dropNotification && observedFault && !droppedExactTerminal) {
            const auto& first = queueAttempt->privateVoices[0];
            std::array<VnNotification, 32> preserved{};
            std::size_t preservedCount = 0;
            VnNotification event{};
            while (engine->notifications.TryPop(event)) {
                if (event.voiceHandle == first.render &&
                    (event.type == VN_NOTIFY_VOICE_ENDED ||
                     event.type == VN_NOTIFY_VOICE_STOPPED_BY_FADE ||
                     event.type == VN_NOTIFY_VOICE_STOLEN)) {
                    EXPECT_FALSE(droppedExactTerminal);
                    droppedExactTerminal = true;
                    continue;
                }
                ASSERT_LT(preservedCount, preserved.size());
                preserved[preservedCount++] = event;
            }
            for (std::size_t index = 0; index < preservedCount; ++index)
                ASSERT_TRUE(engine->notifications.Push(preserved[index]));
            if (droppedExactTerminal) {
                EXPECT_TRUE(engine->voices.ReleaseObserved(first.release));
                EXPECT_EQ(nullptr, engine->voices.Resolve(first.render));
                EXPECT_TRUE(engine->ledger.OwnerForRender(first.render).live);
            }
        }
        if (yieldAfterFirstRootReader && observedFault &&
            engine->forceInitialQueuePrivateRootReaderYieldAfterForTest ==
                UINT32_MAX - 1u &&
            engine->mixer.BlocksRendered() >
                engine->forceInitialQueuePrivateRootReaderYieldSequenceForTest) {
            const auto& first = queueAttempt->privateVoices[0];
            const auto* firstArm = engine->timelineArms.Resolve(first.startArm);
            ASSERT_NE(nullptr, firstArm);
            ASSERT_LT(first.startArm.slot, engine->initialFrontierArmPins.size());
            EXPECT_FALSE(engine->initialFrontierArmPins[first.startArm.slot].pin.Valid());
            EXPECT_TRUE(first.rootReaderReleased);
            EXPECT_TRUE(first.rootArmComplete);
            EXPECT_EQ(0u, firstArm->frontierReaderPins.load());
            observedHeldArmAfterAudioBlock = true;
        }
        const auto* output = engine->nullBackend.LastBlock();
        heardQueue = heardQueue || std::any_of(output, output + 64,
            [](float sample) { return sample > 0.01f; });
        heardIndependent = heardIndependent || std::any_of(output, output + 64,
            [](float sample) { return sample < -0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        if (dropNotification && droppedExactTerminal && !observedExactLedgerSweep) {
            EXPECT_FALSE(engine->ledger.OwnerForRender(
                queueAttempt->privateVoices[0].render).live);
            observedExactLedgerSweep = true;
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(
            independentFiring, &independentInfo));
        if (independentInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED)
            break;
    }
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED,
              independentInfo.state);
    VnActionStepResult independentStep{};
    independentStep.structSize = sizeof(independentStep);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(
        independentFiring, 0, &independentStep));
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, independentInfo.outcome)
        << "terminalReason=" << independentInfo.terminalReason
        << " stepState=" << independentStep.state
        << " stepResult=" << independentStep.result;
    EXPECT_TRUE(observedFault);
    EXPECT_EQ(0u, engine->forceImmediateLaneFutureEventFaultForTest);
    EXPECT_TRUE(heardIndependent);
    for (std::uint32_t page = 0; page < before.size(); ++page) {
        const auto after = *engine->timelinePool.Page(page);
        EXPECT_EQ(before[page].committedTransactionCount,
                  after.committedTransactionCount);
        EXPECT_EQ(before[page].plan03GroupCount,
                  after.plan03GroupCount);
    }
    EXPECT_FALSE(queueRow->queueTimingFinalized);
    VnActionFiringInfo queueInfo{};
    queueInfo.structSize = sizeof(queueInfo);
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(queueFiring, &queueInfo));
        if (queueInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED)
            break;
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        heardQueue = heardQueue || std::any_of(output, output + 64,
            [](float sample) { return sample > 0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    harken::ImmediateLaneObservation laneAtRetirement{};
    const bool laneObservedAtRetirement =
        engine->immediateActionLane.Observe(queueLane, &laneAtRetirement);
    harken::FrontierActivationReceipt frontierReceipt{};
    auto* frontier = queueRow->frontierEntry.Valid()
        ? engine->decisions.ResolveFrontierActivation(
              queueRow->frontierEntry.coordinator)
        : nullptr;
    const auto frontierRead = frontier != nullptr
        ? frontier->Read(queueRow->frontierEntry,
              engine->mixer.BlocksRendered(), &frontierReceipt)
        : harken::FrontierReceiptRead::Stale;
    harken::ArmState rootArmState = harken::ArmState::Free;
    const bool rootArmObserved =
        engine->timelineArms.State(queueArm, &rootArmState);
    harken::TimelineArmObservation rootArmObservation{};
    (void)engine->timelineArms.Observe(queueArm, &rootArmObservation);
    const auto finalAudioSequence = engine->mixer.BlocksRendered();
    auto* finalCoordinator = engine->decisions.ResolveFrontierActivation(
        queueAttempt->initialQueueCoordinator);
    SCOPED_TRACE(::testing::Message()
        << "queue state=" << queueInfo.state
        << " live=" << queueInfo.livePlayableCount
        << " phase=" << static_cast<int>(queueRow->phase)
        << " lifecycle=" << static_cast<int>(queueRow->controlLifecycle)
        << " reason=" << static_cast<int>(queueRow->controlReason)
        << " timing pending=" << queueRow->queueTimingPending
        << " credit=" << queueRow->queueUnplacedCredit.Valid()
        << " voices=" << engine->voices.ActiveCount()
        << " queue instances=" << engine->queueInstances.LiveCount()
        << " playables=" << engine->playableInstances.LiveCount()
        << " frontier=" << queueRow->frontierEntry.Valid()
        << " frontier read=" << static_cast<int>(frontierRead)
        << " frontier outcome=" << static_cast<int>(frontierReceipt.outcome)
        << " frontier pin=" << queueRow->frontierArmPin.Valid()
        << " lane observed=" << laneObservedAtRetirement
        << " lane cancelled=" << laneAtRetirement.cancelled
        << " lane complete=" << laneAtRetirement.complete
        << " root arm observed=" << rootArmObserved
        << " root arm state=" << static_cast<int>(rootArmState)
        << " root arm started=" << rootArmObservation.startedBlockSequence
        << " root arm logical=" << rootArmObservation.logicalCompletionSequence
        << " root arm tombstone=" << rootArmObservation.tombstoneAudioSequence
        << " parent=" << queueRow->parentService.Valid()
        << " zero work=" << queueRow->zeroWorkMarker
        << " has zero completion=" << queueRow->hasZeroWorkCompletion
        << " deferred cancellation=" << queueRow->variableControlDeferredCancellation
        << " pending cancellation=" << queueRow->pendingCancellationIntent
        << " pending entry=" << queueRow->pendingImmediateEntry
        << " producer slot=" << queueAttempt->producerSlot
        << " queue cleanup=" << queueRow->queueCleanupStarted
        << " queue decision committed=" << queueRow->queueDecisionCommitted
        << " queue natural end=" << queueRow->queueNaturalEnd
        << " queue deferred full=" << queueRow->queueDeferredNeedsFullPreparation
        << " queue final tomb=" << queueRow->queueFinalSourceTombstoned
        << " firing=" << queueFiring
        << " row slot=" << queueRow->identity.slot
        << " row generation=" << queueRow->identity.generation
        << " attempt generation=" << queueAttemptGeneration
        << " attempt active=" << queueAttempt->active
        << " private phase=" << static_cast<int>(queueAttempt->privateCleanupPhase)
        << " private voices=" << queueAttempt->privateVoiceCount
        << " gate state=" << static_cast<int>(queueAttempt->gate.Observe(queueAttemptGeneration))
        << " coordinator slot=" << queueAttempt->initialQueueCoordinator.slot
        << " coordinator generation=" << queueAttempt->initialQueueCoordinator.generation
        << " coordinator state=" << (finalCoordinator != nullptr
            ? static_cast<int>(finalCoordinator->State()) : -1)
        << " bound frontier groups=" << faultBoundFrontierGroups
        << " baseline audio seq=" << baselineAudioSequence
        << " fault audio seq=" << faultAudioSequence
        << " fault coordinator state=" << faultCoordinatorState
        << " final audio seq=" << finalAudioSequence
        << " initial decision=" << queueRow->initialQueueEntryDecision.Valid()
        << " initial group=" << queueRow->queueInitialLaneArmGroup.Valid());
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, queueInfo.state);
    EXPECT_FALSE(heardQueue);
    EXPECT_EQ(0u, queueInfo.livePlayableCount);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->playableInstances.LiveCount());
    if (dropNotification) {
        EXPECT_TRUE(droppedExactTerminal);
        EXPECT_TRUE(observedExactLedgerSweep);
    }
    if (yieldAfterFirstRootReader) {
        EXPECT_TRUE(observedHeldArmAfterAudioBlock);
        EXPECT_EQ(UINT32_MAX,
            engine->forceInitialQueuePrivateRootReaderYieldAfterForTest);
        EXPECT_GT(finalAudioSequence,
            engine->forceInitialQueuePrivateRootReaderYieldSequenceForTest);
    }
    if (blockSecondStop) {
        EXPECT_TRUE(observedSecondStopRetry);
        EXPECT_EQ(UINT32_MAX,
            engine->forceInitialQueuePrivateStopPushFailureAtForTest);
        EXPECT_GT(finalAudioSequence,
            engine->forceInitialQueuePrivateStopRetrySequenceForTest);
    }
    ASSERT_EQ(2u, queueAttempt->privateVoiceCount);
    std::array<std::pair<VnVoiceHandle, harken::VoiceReleaseObserver>, 2>
        retiredVoices{};
    for (std::uint32_t index = 0; index < queueAttempt->privateVoiceCount; ++index) {
        const auto& voice = queueAttempt->privateVoices[index];
        retiredVoices[index] = {voice.render, voice.release};
        EXPECT_TRUE(voice.rootReaderReleased);
        EXPECT_TRUE(voice.rootArmComplete);
        EXPECT_TRUE(engine->voices.ReleaseObserved(voice.release));
        EXPECT_EQ(nullptr, engine->voices.Resolve(voice.render));
        EXPECT_GT(finalAudioSequence, voice.stopQueued
            ? voice.stopQueuedAudioSequence : voice.capturedAudioSequence);
        EXPECT_FALSE(engine->ledger.OwnerForRender(voice.render).live);
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(queueFiring));
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(independentFiring));
    VnActionFiringHandle replay = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&queue, &replay));
    for (std::size_t index = 0; index < queueGroupCount; ++index) {
        harken::Plan03PageGroupView staleGroup{};
        harken::ImmediateLaneFrontierClaim staleClaim{};
        EXPECT_FALSE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
            queueGroups[index].identity, &staleGroup));
        EXPECT_FALSE(engine->timelinePool.ClaimPrivateImmediateLaneFrontier(
            queueGroups[index].identity, &staleClaim));
    }
    for (const auto& [oldRender, oldRelease] : retiredVoices) {
        const auto slot = static_cast<std::uint32_t>(oldRender);
        ASSERT_LT(slot, engine->timelineVoiceInstallIdentities.size());
        const auto& replacement = engine->timelineVoiceInstallIdentities[slot];
        ASSERT_NE(0u, replacement.renderHandle);
        EXPECT_EQ(slot, static_cast<std::uint32_t>(replacement.renderHandle));
        EXPECT_NE(oldRender, replacement.renderHandle);
        EXPECT_NE(static_cast<std::uint32_t>(oldRender >> 32),
                  static_cast<std::uint32_t>(replacement.renderHandle >> 32));
        EXPECT_TRUE(engine->voices.ReleaseObserved(oldRelease));
        EXPECT_EQ(nullptr, engine->voices.Resolve(oldRender));
        EXPECT_FALSE(engine->ledger.OwnerForRender(oldRender).live);
        EXPECT_FALSE(engine->voices.ReleaseObserved(replacement.releaseObserver));
        EXPECT_NE(nullptr, engine->voices.Resolve(replacement.renderHandle));
        EXPECT_TRUE(engine->ledger.OwnerForRender(replacement.renderHandle).live);
    }
    bool replayHeard = false;
    VnActionFiringInfo replayInfo{};
    replayInfo.structSize = sizeof(replayInfo);
    for (std::uint32_t block = 0; block < 32; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        const auto* output = engine->nullBackend.LastBlock();
        replayHeard = replayHeard || std::any_of(output, output + 64,
            [](float sample) { return sample > 0.01f; });
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(replay, &replayInfo));
        if (replayInfo.state == VN_ACTION_FIRING_TERMINAL_RETAINED)
            break;
    }
    EXPECT_TRUE(replayHeard);
    EXPECT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, replayInfo.state);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, replayInfo.outcome);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(replay));
}

