TEST(ActionFiringApi,
     DirectSequenceQueueDefaultIdentityAndRetirement) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));

    CanonicalActionWorld emitterSequence(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    emitterSequence.MakeImmediateSequenceQueuePlayAction();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, emitterSequence.world)
                  .status);
    const auto emitterStarted = harken::StartCurrentPlayableByIdentity(
        harken::PlayableKindV1::Container,
        emitterSequence.containers[2].containerStableId, 0);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, emitterStarted.status);
    ASSERT_NE(0u, emitterStarted.instance);
    const auto emitterRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == emitterStarted.instance;
        });
    ASSERT_NE(engine->playableServices.end(), emitterRow);
    harken::QueueInstanceSnapshot emitterQueue{};
    ASSERT_TRUE(engine->queueInstances.Capture(
        emitterRow->queueInstance, &emitterQueue));
    const auto defaultState = engine->emitters.DefaultState();
    EXPECT_EQ(static_cast<std::uint32_t>(defaultState), emitterQueue.emitterSlot);
    EXPECT_EQ(static_cast<std::uint32_t>(defaultState >> 32), emitterQueue.emitterGeneration);
    EXPECT_EQ(emitterQueue.emitterSlot, emitterRow->queueCheckpointKey.emitterSlot);
    EXPECT_EQ(emitterQueue.emitterGeneration, emitterRow->queueCheckpointKey.emitterGeneration);
    ASSERT_EQ(harken::PlayableControlStatus::Ok,
              harken::StopPlayable(*engine, emitterStarted.instance, 0));
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!engine->playableInstances.Classify(emitterStarted.instance).live) {
            break;
        }
    }
    ASSERT_FALSE(
        engine->playableInstances.Classify(emitterStarted.instance).live);
    ASSERT_EQ(0u, engine->queueInstances.LiveCount());

    ASSERT_TRUE(emitterRow->partitionRetiring);
    const auto retirementStart = engine->mixer.BlocksRendered();
    for (std::uint32_t block = 0; block < 128 &&
         emitterRow->phase != harken::EnginePlayableStartPhase::Free; ++block) {
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    testing::Test::RecordProperty("actual_partition_retirement_blocks",
        std::to_string(engine->mixer.BlocksRendered() - retirementStart));
    ASSERT_EQ(harken::EnginePlayableStartPhase::Free, emitterRow->phase);
    EXPECT_EQ(0u, engine->timelineArms.LiveCount());
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
    EXPECT_FALSE(engine->runtimeRecreateRequired);
}

namespace {
void CheckDirectQueueContext(bool randomQueue, bool invalidIdentity) {
    SCOPED_TRACE(randomQueue);
    SCOPED_TRACE(invalidIdentity);
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const std::vector<float> first(64, 0.25f), second(128, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    if (randomQueue) image.MakeImmediateRandomQueuePlayAction();
    else image.MakeImmediateSequenceQueuePlayAction();
    image.containers[2].resumePosition = 1;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    harken::PlayableStartRequest request{};
    request.root.kind = harken::PlayableKindV1::Container;
    request.root.stableId = image.containers[2].containerStableId;
    request.root.expectedProgramSemanticFingerprint = image.containers[2].programSemanticFingerprint;
    request.root.contentRevision = image.properties[4].contentRevision;
    request.root.routeStableId = image.properties[4].routeStableId;
    request.root.compatibilityFingerprint = image.properties[4].compatibilityFingerprint;
    if (invalidIdentity) {
        // Internal callers must carry the normalized state; public callers cannot forge it.
        auto rejected = harken::StartPlayable(*engine, request);
        EXPECT_NE(harken::PlayableStartStatus::Accepted, rejected.status);
        EXPECT_EQ(0u, rejected.instance);
        request.emitter = engine->emitters.DefaultState();
        rejected = harken::StartCurrentPlayable(request);
        EXPECT_EQ(harken::PlayableStartStatus::InvalidInput, rejected.status);
        EXPECT_EQ(0u, rejected.instance);
        VnEmitterHandle stale = 0;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&stale));
        ASSERT_EQ(VN_OK, Vn_DestroyEmitter(stale));
        request.emitter = stale;
        rejected = harken::StartCurrentPlayable(request);
        EXPECT_EQ(harken::PlayableStartStatus::InvalidInput, rejected.status);
        EXPECT_EQ(0u, rejected.instance);
        rejected = harken::StartPlayable(*engine, request);
        EXPECT_EQ(harken::PlayableStartStatus::InvalidInput, rejected.status);
        EXPECT_EQ(0u, rejected.instance);
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
        return;
    }
    const auto started = harken::StartCurrentPlayableByIdentity(
        request.root.kind, request.root.stableId, 0);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    ASSERT_NE(0u, started.instance);
    const auto row = std::find_if(engine->playableServices.begin(), engine->playableServices.end(),
        [&](const auto& candidate) { return candidate.rootInstance == started.instance; });
    ASSERT_NE(engine->playableServices.end(), row);
    harken::QueueInstanceSnapshot queue{};
    ASSERT_TRUE(engine->queueInstances.Capture(row->queueInstance, &queue));
    const auto state = engine->emitters.DefaultState();
    EXPECT_EQ(static_cast<std::uint32_t>(state), queue.emitterSlot);
    EXPECT_EQ(static_cast<std::uint32_t>(state >> 32), queue.emitterGeneration);
    EXPECT_EQ(queue.emitterSlot, row->queueCheckpointKey.emitterSlot);
    EXPECT_EQ(queue.emitterGeneration, row->queueCheckpointKey.emitterGeneration);
    harkentest::Capture capture;
    for (unsigned block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        harkentest::PumpAndCapture(engine, 1, capture);
        ASSERT_EQ(VN_OK, Vn_Update());
        if (row->phase == harken::EnginePlayableStartPhase::Free) break;
    }
    EXPECT_TRUE(std::any_of(capture.left.begin(), capture.left.end(), [](float value) { return value > 0.001f; }));
    EXPECT_TRUE(std::any_of(capture.left.begin(), capture.left.end(), [](float value) { return value < -0.001f; }));
    EXPECT_FALSE(engine->playableInstances.Classify(started.instance).live);
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(0u, engine->playablePartitions.OccupiedCount());
}
}

TEST(ActionFiringApi, DirectSequenceQueueResumeUsesDefaultContext) { CheckDirectQueueContext(false, false); }
TEST(ActionFiringApi, DirectRandomQueueUsesDefaultContext) { CheckDirectQueueContext(true, false); }
TEST(ActionFiringApi, DirectSequenceQueueRejectsUnnormalizedOrStaleContext) { CheckDirectQueueContext(false, true); }
TEST(ActionFiringApi, DirectRandomQueueRejectsUnnormalizedOrStaleContext) { CheckDirectQueueContext(true, true); }

TEST(ActionFiringApi, DynamicQueueCycleKeepsOrdinaryPagePreparation) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    std::vector<float> samples(512, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(*engine, image.world).status);
    const auto started = harken::StartCurrentPlayableByIdentity(
        harken::PlayableKindV1::Container,
        image.containers[2].containerStableId, 0);
    ASSERT_EQ(harken::PlayableStartStatus::Accepted, started.status);
    const auto row = std::find_if(engine->playableServices.begin(),
        engine->playableServices.end(), [&](const auto& candidate) {
            return candidate.rootInstance == started.instance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_FALSE(row->queueTimingPending);
    ASSERT_FALSE(row->queueUnplacedCredit.Valid());
    ASSERT_EQ(0u, row->pendingImmediateCohortRoot);
    ASSERT_TRUE(row->queuePreparedPages.Valid());
    bool observedLaterCycle = false;
    for (std::uint32_t block = 0; block < 128; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        engine->nullBackend.Pump(1);
        ASSERT_EQ(VN_OK, Vn_Update());
        harken::QueueInstanceSnapshot queue{};
        if (!engine->queueInstances.Capture(row->queueInstance, &queue))
            continue;
        if (queue.logicMirror.cycleOrdinal == 0) continue;
        observedLaterCycle = true;
        EXPECT_FALSE(row->queueTimingPending);
        EXPECT_FALSE(row->queueUnplacedCredit.Valid());
        EXPECT_EQ(0u, row->pendingImmediateCohortRoot);
        EXPECT_TRUE(row->queuePreparedPages.Valid());
        break;
    }
    EXPECT_TRUE(observedLaterCycle);
}

