TEST(ActionFiringApi,
     ImmediateSequenceQueueContinuationUsesSingleMaximumActionSequence) {
    (void)Vn_Term();
    harkentest::EngineSession session(
        harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.MakeSecondQueueChildCompositeTrack();
    image.containers[2].queueCycle = harken::QueueCycleV1::Loop;
    image.EnableNaturalEndQueueTransition(64, 128);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    constexpr std::uint64_t acceptedSequence = UINT64_MAX;
    engine->logicCommits.SetCurrentForTests(UINT64_MAX - 1u);

    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_NE(0u, firing);
    EXPECT_EQ(acceptedSequence, engine->logicCommits.Current());
    EXPECT_FALSE(engine->runtimeRecreateRequired);

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(acceptedSequence, info.acceptedLogicSequence);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(acceptedSequence, play.logicCommitSequence);

    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    EXPECT_EQ(acceptedSequence, row->ticket);
    EXPECT_EQ(acceptedSequence, row->queueTicket);
    EXPECT_EQ(acceptedSequence, row->queueSuccessorTicket);
    EXPECT_EQ(acceptedSequence, row->event.logicCommitSequence);
    EXPECT_EQ(acceptedSequence, row->schedule.transactionId);
    ASSERT_EQ(1u, row->queueSourceControlArmCount);
    ASSERT_EQ(2u, row->queueSuccessorScheduleLeafCount);
    const std::size_t rowIndex = row->partition.slot;
    const std::size_t targetEventBase =
        row->queueSuccessorProgramPlane == 0
            ? engine->playableStorage.CurrentEventBase(rowIndex)
            : engine->playableStorage.PairedBase(rowIndex);
    auto& targetEvents = row->queueSuccessorProgramPlane == 0
        ? engine->playableScheduleEvents
        : engine->playableSuccessorEvents;
    auto& targetSchedules = row->queueSuccessorProgramPlane == 0
        ? engine->playableSchedules
        : engine->playableSuccessorSchedules;
    for (std::uint32_t index = 0; index < 4; ++index) {
        EXPECT_EQ(acceptedSequence,
                  targetEvents[targetEventBase + index].
                      logicCommitSequence);
    }
    for (std::uint32_t index = 0; index < 2; ++index) {
        EXPECT_EQ(acceptedSequence,
                  targetSchedules[
                      row->queueSuccessorScheduleBase + index].
                      transactionId);
    }
    ASSERT_EQ(1u, row->queueSourceSchedule.eventCount);
    for (std::uint32_t index = 0;
         index < row->queueSourceSchedule.eventCount; ++index) {
        EXPECT_EQ(acceptedSequence,
                  row->queueSourceEvents[index].logicCommitSequence);
    }
    for (std::uint32_t index = 0;
         index < row->queueSourceControlArmCount; ++index) {
        EXPECT_EQ(acceptedSequence,
                  row->queueSourceSchedules[index].transactionId);
    }
}

std::string CaptureImmediateQueueContinuationState(harken::Engine& engine,
    VnActionFiringHandle firing) {
    ::testing::Message message;
    message << "Observed after real service, block=" << engine.mixer.BlocksRendered();
    for (const auto& row : engine.playableServices) {
        if (!row.InvocationValid() || row.Invocation().actionFiring != firing) continue;
        message << "\nrow=" << row.identity.slot << ":" << row.identity.generation
            << " phase=" << static_cast<unsigned>(row.phase)
            << " pending=" << row.pendingImmediateEntry
            << " timing=" << row.queueTimingPending << "/" << row.queueTimingFinalized
            << " c1=" << row.queueFirstContinuationLane
            << " same=" << row.queueSameProgramKey
            << " leaves=" << row.queueCurrentScheduleLeafCount << "/" << row.queueSuccessorScheduleLeafCount
            << " unplaced=" << row.queueUnplacedGroupCount << "/" << row.queueUnplacedTransactionCount
            << " completion=" << row.queueCompletionFrame
            << " currentDecision=" << row.queueDecision.slot << ":" << row.queueDecision.generation
            << " initialDecision=" << row.initialQueueEntryDecision.slot << ":"
            << row.initialQueueEntryDecision.generation
            << " completionOwner=" << static_cast<unsigned>(row.queueCurrentCompletion.owner.kind)
            << " composite=" << row.queueCurrentCompositeOwner.Valid();
        harken::QueueInstanceSnapshot queue{};
        if (engine.queueInstances.Capture(row.queueInstance, &queue))
            message << " queueVersion=" << queue.logicMirror.version << "/" << queue.pendingVersion
                << " activation=" << static_cast<unsigned>(queue.pendingActivation);
        harken::TimelineArmObservation arm{};
        if (engine.timelineArms.Observe(row.arm, &arm))
            message << " arm=" << static_cast<unsigned>(arm.state);
        for (std::uint32_t leaf = 0; leaf < row.scheduleLeafCount; ++leaf) {
            if (!row.partition.Valid()) break;
            const auto slot = engine.playableStorage.MemberBase(row.partition.slot) + leaf;
            if (slot >= engine.playableScheduleArms.size()) break;
            if (engine.timelineArms.Observe(engine.playableScheduleArms[slot], &arm))
                message << " memberArm[" << leaf << "]=" << static_cast<unsigned>(arm.state);
        }
    }
    for (std::uint32_t index = 0; index < engine.immediateEntryAttemptCapacity; ++index) {
        const auto& attempt = engine.immediateEntryAttempts[index];
        if (!attempt.active || attempt.root != firing) continue;
        message << "\nattempt=" << index << ":" << attempt.generation
            << " producer=" << attempt.producerSlot << ":" << attempt.producerGeneration
            << " coordinator=" << attempt.initialQueueCoordinator.slot << ":"
            << attempt.initialQueueCoordinator.generation
            << " c1Coordinator=" << attempt.queueContinuationCoordinator.slot << ":"
            << attempt.queueContinuationCoordinator.generation
            << " abort=" << attempt.producerAbortPending
            << " entry=" << attempt.entryQuantum << " last=" << attempt.lastQuantum;
        harken::ImmediateLaneObservation observation{};
        if (engine.immediateActionLane.Observe(attempt.lane, &observation))
            message << " lane committed=" << observation.committed << " applied=" << observation.applied
                << " missed=" << observation.missed << " cancelled=" << observation.cancelled
                << " refused=" << observation.protocolRefused;
    }
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 16> groups{};
    const auto count = engine.timelinePool.CaptureLiveImmediateLaneCohortGroups(firing,
        groups.data(), groups.size());
    message << "\nliveGroupCount=" << count;
    for (std::size_t index = 0; index < std::min(count, groups.size()); ++index) {
        const auto& group = groups[index];
        message << "\ngroup=" << group.identity.decision.slot << ":"
            << group.identity.decision.generation << "/" << group.identity.sliceIndex
            << " due=" << group.dueQuantum << " lane=" << group.laneSlot << ":" << group.laneGeneration;
        harken::Plan03PageGroupView view{};
        if (engine.timelinePool.ResolvePlan03GroupSliceProducer(group.identity, &view)) {
            message << " members=" << view.memberCount << " controls=" << view.sourceControlCount;
            if (view.frontier != nullptr)
                message << " role=" << static_cast<unsigned>(view.frontier->role)
                    << " initial=" << view.frontier->queueInitial.Valid()
                    << " conditional=" << view.frontier->queueConditional.Valid();
        }
    }
    return message.GetString();
}

void ExpectImmediateSequenceQueueCompositeChildCompletes(bool pieceChild) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(64, 0.25f);
    std::vector<float> second(128, -0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    if (pieceChild) {
        image.MakeFirstQueueChildCompositePiece();
    } else {
        image.MakeFirstQueueChildCompositeTrack();
    }
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    const auto beforePostSequence = engine->mixer.BlocksRendered();
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    ASSERT_EQ(beforePostSequence, engine->mixer.BlocksRendered());

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    EXPECT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    EXPECT_EQ(1u, info.livePlayableCount);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_ACTIVE, play.state);
    EXPECT_EQ(VN_ACTION_TARGET_CONTAINER, play.targetKind);
    ASSERT_NE(0u, play.producedPlayableInstance);
    EXPECT_EQ(4u, engine->playableInstances.LiveCount());

    const auto rootInstance =
        engine->playableInstances.Classify(play.producedPlayableInstance);
    ASSERT_TRUE(rootInstance.live);
    EXPECT_EQ(harken::PlayableKind::Container, rootInstance.kind);
    ASSERT_NE(0u, rootInstance.firstChild);
    const auto compositeInstance =
        engine->playableInstances.Classify(rootInstance.firstChild);
    ASSERT_TRUE(compositeInstance.live);
    EXPECT_EQ(pieceChild ? harken::PlayableKind::Piece
                         : harken::PlayableKind::Track,
              compositeInstance.kind);
    EXPECT_EQ(play.producedPlayableInstance, compositeInstance.parent);
    ASSERT_NE(0u, compositeInstance.firstChild);
    const auto soundInstance =
        engine->playableInstances.Classify(compositeInstance.firstChild);
    ASSERT_TRUE(soundInstance.live);
    EXPECT_EQ(harken::PlayableKind::Sound, soundInstance.kind);
    EXPECT_EQ(rootInstance.firstChild, soundInstance.parent);

    const auto initialRow = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), initialRow);
    ASSERT_EQ(2u, initialRow->scheduleLeafCount);
    ASSERT_EQ(2u, initialRow->queueCurrentScheduleLeafCount);
    ASSERT_TRUE(initialRow->queueFirstContinuationLane);
    ASSERT_TRUE(initialRow->queueCurrentCompositeOwner.Valid());
    ASSERT_EQ(2u, initialRow->queueUnplacedGroupCount);
    EXPECT_EQ(initialRow->startFrame, initialRow->queueUnplacedGroupFrames[0]);
    EXPECT_EQ(initialRow->queueCompletionFrame, initialRow->queueUnplacedGroupFrames[1]);
    harken::CompositeCompletionOwnerInfo composite{};
    ASSERT_TRUE(engine->compositeCompletionOwners.Capture(
        initialRow->queueCurrentCompositeOwner, &composite));
    EXPECT_EQ(initialRow->queueCurrentOccurrence.slot, composite.composedOccurrence.slot);
    EXPECT_EQ(initialRow->queueCurrentOccurrence.generation, composite.composedOccurrence.generation);
    EXPECT_EQ(1u, composite.aggregateRevision);
    EXPECT_EQ(2u, composite.leafCount);
    EXPECT_EQ(composite.absoluteLogicalCompleteFrame, initialRow->queueCompletionFrame);
    const std::size_t base = initialRow->scheduleStorageBase;
    ASSERT_LT(base + 1u, engine->playableScheduleLeaves.size());
    bool observedFirstLeaf = false;
    bool observedSecondLeaf = false;
    for (std::uint32_t index = 0; index < initialRow->scheduleLeafCount;
         ++index) {
        const VnSoundId sound =
            engine->playableScheduleLeaves[base + index].stableId;
        EXPECT_NE(0u,
                  engine->playableScheduleRenderHandles[base + index]);
        EXPECT_NE(nullptr,
                  engine->voices.Resolve(
                      engine->playableScheduleRenderHandles[base + index]));
        observedFirstLeaf = observedFirstLeaf ||
            sound == CanonicalActionWorld::kFirstSound;
        observedSecondLeaf = observedSecondLeaf ||
            sound == CanonicalActionWorld::kSecondSound;
    }
    EXPECT_TRUE(observedFirstLeaf);
    EXPECT_TRUE(observedSecondLeaf);
    EXPECT_GE(engine->voices.ActiveCount(), 2u);

    // Save actual factory identities before the first callback can acknowledge them.
    ASSERT_TRUE(initialRow->InvocationValid());
    ASSERT_EQ(firing, initialRow->Invocation().actionFiring);
    const harken::EnginePlayableServiceReference savedService{
        initialRow->identity, initialRow->ownerInstance,
        initialRow->ownerEpoch, initialRow->invocationGeneration};
    ASSERT_TRUE(savedService.Valid());
    const auto savedPartition = initialRow->partition;
    const auto* savedInvocation = initialRow->invocation;
    const auto savedInvocationSlot = initialRow->Invocation().slot;
    const auto savedRoot = initialRow->rootInstance;
    const auto savedTicket = initialRow->ticket;
    const auto ownerView = engine->playableInstances.Classify(savedService.owner);
    const auto parentView = engine->playableInstances.Classify(ownerView.parent);
    const auto invocationView = engine->playableInstances.Classify(savedRoot);
    const harken::FrontierOwnerIdentity savedOwner{
        savedService.owner, savedService.epoch, ownerView.parent,
        ownerView.parent == 0 ? 0 : parentView.scheduleEpoch,
        savedRoot, invocationView.scheduleEpoch,
        savedService.token.slot, savedService.token.generation};
    ASSERT_TRUE(savedOwner.Valid());
    const auto savedQueue = initialRow->queueInstance;
    const auto savedConditional = initialRow->queueConditional;
    const auto savedCurrentOccurrence = initialRow->queueCurrentOccurrence;
    const auto savedSuccessorOccurrence = initialRow->queueSuccessorOccurrence;
    const auto savedAggregate = initialRow->queueCurrentCompositeOwner;
    ASSERT_TRUE(savedQueue.Valid());
    ASSERT_TRUE(savedConditional.Valid());
    ASSERT_NE(0u, savedSuccessorOccurrence.generation);
    harken::QueueInstanceSnapshot savedQueueSnapshot{};
    ASSERT_TRUE(engine->queueInstances.Capture(savedQueue, &savedQueueSnapshot));
    const auto sameArm = [](harken::TimelineArmToken a, harken::TimelineArmToken b) {
        return a.slot == b.slot && a.generation == b.generation &&
            a.renderSlot == b.renderSlot && a.renderGeneration == b.renderGeneration;
    };
    const auto sameOccurrence = [](harken::OccurrenceToken a, harken::OccurrenceToken b) {
        return a.slot == b.slot && a.generation == b.generation;
    };
    const auto matchesDescriptor = [](const harken::FrontierActivationDescriptor& a,
                                      const harken::FrontierActivationDescriptor& b) {
        return a.entry == b.entry && a.primary == b.primary && a.order == b.order &&
            a.worldGeneration == b.worldGeneration &&
            a.worldSemanticFingerprint == b.worldSemanticFingerprint &&
            a.expectedMemberCount == b.expectedMemberCount &&
            a.expectedEntryEventCount == b.expectedEntryEventCount &&
            a.programGeneration == b.programGeneration;
    };
    const auto resolveSavedService = [&]() -> harken::EnginePlayableServiceRow* {
        auto* row = engine->ResolvePlayableService(savedService);
        if (row == nullptr || row->partition.slot != savedPartition.slot ||
            row->partition.generation != savedPartition.generation ||
            !row->InvocationValid() || row->invocation != savedInvocation ||
            row->Invocation().slot != savedInvocationSlot ||
            row->Invocation().actionFiring != firing || row->rootInstance != savedRoot ||
            row->ticket != savedTicket || row->queueInstance.slot != savedQueue.slot ||
            row->queueInstance.generation != savedQueue.generation) return nullptr;
        return row;
    };
    ASSERT_EQ(&*initialRow, resolveSavedService());
    const auto* originalAttempt = std::find_if(engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() + engine->immediateEntryAttemptCapacity,
        [firing](const auto& candidate) { return candidate.active && candidate.root == firing; });
    ASSERT_NE(engine->immediateEntryAttempts.get() + engine->immediateEntryAttemptCapacity,
        originalAttempt);
    const auto savedAttemptSlot = static_cast<std::size_t>(
        originalAttempt - engine->immediateEntryAttempts.get());
    const auto savedAttemptGeneration = originalAttempt->generation;
    const auto savedLane = originalAttempt->lane;
    const auto savedC0 = originalAttempt->initialQueueCoordinator;
    const auto savedC1 = originalAttempt->queueContinuationCoordinator;
    const auto savedC0Primary = originalAttempt->initialQueuePrimaryGroup;
    const auto savedC1Primary = originalAttempt->queueContinuationPrimaryGroup;
    ASSERT_NE(0u, savedAttemptGeneration);
    ASSERT_TRUE(savedLane.Valid());
    ASSERT_TRUE(savedC0.Valid());
    ASSERT_TRUE(savedC1.Valid());
    ASSERT_TRUE(savedC0Primary.Exact());
    ASSERT_TRUE(savedC1Primary.Exact());
    const auto savedInitialMemberDecision = initialRow->initialQueueEntryDecision;
    const auto savedConditionalMemberDecision = initialRow->queueDecision;
    ASSERT_TRUE(savedInitialMemberDecision.Valid());
    ASSERT_TRUE(savedConditionalMemberDecision.Valid());
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 8> originalGroups{};
    const auto privateGroupCount = engine->timelinePool.CaptureImmediateLaneCohortGroups(
        firing, originalGroups.data(), originalGroups.size());
    ASSERT_GT(privateGroupCount, 0u);
    ASSERT_LE(privateGroupCount, originalGroups.size());
    harken::Plan03GroupSliceIdentity savedInitialMember{}, savedConditionalMember{};
    std::size_t initialMemberMatches = 0, conditionalMemberMatches = 0;
    for (std::size_t index = 0; index < privateGroupCount; ++index) {
        const auto& identity = originalGroups[index].identity;
        if (identity.sliceIndex != 0u) continue;
        if (identity.decision.slot == savedInitialMemberDecision.slot &&
            identity.decision.generation == savedInitialMemberDecision.generation) {
            savedInitialMember = identity;
            ++initialMemberMatches;
        }
        if (identity.decision.slot == savedConditionalMemberDecision.slot &&
            identity.decision.generation == savedConditionalMemberDecision.generation) {
            savedConditionalMember = identity;
            ++conditionalMemberMatches;
        }
    }
    ASSERT_EQ(1u, initialMemberMatches);
    ASSERT_EQ(1u, conditionalMemberMatches);
    ASSERT_TRUE(savedInitialMember.Exact());
    ASSERT_TRUE(savedConditionalMember.Exact());
    EXPECT_FALSE(savedConditionalMember == savedC1Primary);
    ASSERT_EQ(savedService.token, originalAttempt->initialService);
    ASSERT_EQ(savedService.invocationGeneration, originalAttempt->initialInvocationGeneration);
    const auto resolveSavedAttempt = [&]() -> const harken::EngineImmediateEntryAttempt* {
        const auto& actual = engine->immediateEntryAttempts[savedAttemptSlot];
        if (!actual.active || actual.generation != savedAttemptGeneration ||
            actual.root != firing || actual.initialService != savedService.token ||
            actual.initialInvocationGeneration != savedService.invocationGeneration ||
            actual.lane.slot != savedLane.slot || actual.lane.generation != savedLane.generation ||
            actual.initialQueueCoordinator.slot != savedC0.slot ||
            actual.initialQueueCoordinator.generation != savedC0.generation ||
            actual.queueContinuationCoordinator.slot != savedC1.slot ||
            actual.queueContinuationCoordinator.generation != savedC1.generation ||
            !(actual.initialQueuePrimaryGroup == savedC0Primary) ||
            !(actual.queueContinuationPrimaryGroup == savedC1Primary)) return nullptr;
        return &actual;
    };
    struct SavedSourceObservation {
        harken::TimelineArmToken arm{};
        VnVoiceHandle render = 0;
        const harken::OriginalSourceSubmissionRegistry::Record* submission = nullptr;
        harken::EngineTimelineVoiceInstallIdentity installation{};
        harken::SourceTerminalToken terminal{};
        const harken::SourceTerminalRecord* terminalRecord = nullptr;
        std::uint64_t terminalLeaf = 0;
        std::uint64_t terminalEpoch = 0;
        std::uint64_t terminalBeforeSequence = 0;
        std::uint64_t terminalController = 0;
        harken::SourceTerminalResourceOwner terminalOwner{};
        harken::TimelineArmObservation before{};
        std::uint64_t acknowledgedSequence = 0;
    };
    std::array<SavedSourceObservation, 3> sources{};
    std::array<harken::KnownScheduleLeafV1, 2> originalLeaves{};
    std::array<harken::CompletionProgressSnapshot, 2> originalProgress{};
    const auto captureSource = [&](harken::TimelineArmToken arm, VnVoiceHandle render,
                                   SavedSourceObservation* out) {
        ASSERT_TRUE(arm.Valid());
        ASSERT_NE(0u, render);
        out->arm = arm;
        out->render = render;
        ASSERT_TRUE(engine->timelineArms.Observe(arm, &out->before));
        EXPECT_EQ(0u, out->before.startedBlockSequence);
        EXPECT_EQ(0u, out->before.armedCompletionSequence);
        out->submission = engine->originalSourceSubmissions.Find(arm);
        ASSERT_NE(nullptr, out->submission);
        EXPECT_TRUE(sameArm(arm, out->submission->Token()));
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(render, &out->installation));
        EXPECT_TRUE(sameArm(arm, out->installation.startArm));
        EXPECT_EQ(render, out->installation.renderHandle);
        EXPECT_EQ(savedRoot, out->installation.rootInstance);
        EXPECT_EQ(out->submission, engine->timelineArms.RowAt(arm.slot)->originalSourceSubmission);
        const auto* voice = engine->voices.Resolve(render);
        ASSERT_NE(nullptr, voice);
        out->terminal = voice->sourceTerminalToken;
        out->terminalRecord = voice->sourceTerminal;
        if (out->terminal.Valid()) {
            ASSERT_EQ(out->terminalRecord, engine->sourceTerminals.Resolve(out->terminal));
            ASSERT_NE(nullptr, out->terminalRecord);
            EXPECT_EQ(render, out->terminalRecord->render);
            EXPECT_EQ(out->installation.releaseObserver.slot, out->terminalRecord->release.slot);
            EXPECT_EQ(out->installation.releaseObserver.targetSequence,
                out->terminalRecord->release.targetSequence);
            out->terminalLeaf = out->terminalRecord->leaf;
            out->terminalEpoch = out->terminalRecord->acceptedEpoch;
            out->terminalController = out->terminalRecord->controller;
            out->terminalOwner = out->terminalRecord->resourceOwner;
            out->terminalBeforeSequence = out->terminalRecord->completedSequence.load(
                std::memory_order_acquire);
        } else {
            EXPECT_EQ(nullptr, out->terminalRecord);
        }
    };
    for (std::size_t index = 0; index < originalLeaves.size(); ++index) {
        ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(
            savedAggregate, static_cast<std::uint32_t>(index), &originalLeaves[index]));
        ASSERT_NO_FATAL_FAILURE(captureSource(engine->playableScheduleArms[base + index],
            engine->playableScheduleRenderHandles[base + index], &sources[index]));
        EXPECT_EQ(sources[index].arm.renderGeneration, originalLeaves[index].renderGeneration);
        const auto* voice = engine->voices.Resolve(sources[index].render);
        ASSERT_NE(nullptr, voice);
        EXPECT_TRUE(sameOccurrence(originalLeaves[index].occurrence, voice->completionOccurrence));
        EXPECT_EQ(originalLeaves[index].renderGeneration, voice->completionRenderGeneration);
        const auto* progress = engine->timelineOccurrences.CompletionProgressOf(originalLeaves[index].occurrence);
        ASSERT_NE(nullptr, progress);
        EXPECT_EQ(progress, voice->completionProgress);
        ASSERT_TRUE(harken::CaptureCompletionProgressExact(*progress, originalLeaves[index].occurrence,
            originalLeaves[index].renderGeneration, &originalProgress[index]));
    }
    ASSERT_NO_FATAL_FAILURE(captureSource(initialRow->queueSuccessorArm,
        initialRow->queueSuccessorRenderHandle, &sources[2]));
    harken::FrontierActivationDescriptor boundC0{}, boundC1{};
    std::uint64_t entryQuantum = UINT64_MAX;
    std::uint64_t boundaryQuantum = UINT64_MAX;
    bool observedBoundGeometry = false;
    bool observedCurrentStarts = false;
    bool observedC0Applied = false;
    bool observedC1Applied = false;
    bool observedSuccessorStart = false;
    bool observedCurrentPcm = false;
    bool observedSuccessorPcm = false;
    const auto checkQueueIdentity = [&](const harken::QueueInstanceSnapshot& actual) {
        EXPECT_EQ(savedQueueSnapshot.world, actual.world);
        EXPECT_EQ(savedQueueSnapshot.rootInstance, actual.rootInstance);
        EXPECT_EQ(savedQueueSnapshot.programSemanticFingerprint, actual.programSemanticFingerprint);
        const auto& expected = savedQueueSnapshot.logicMirror;
        EXPECT_EQ(expected.version, actual.logicMirror.version);
        EXPECT_EQ(expected.cursor, actual.logicMirror.cursor);
        EXPECT_EQ(expected.currentChildOrdinal, actual.logicMirror.currentChildOrdinal);
        EXPECT_EQ(expected.cycleOrdinal, actual.logicMirror.cycleOrdinal);
        EXPECT_EQ(expected.selectionOrdinal, actual.logicMirror.selectionOrdinal);
        EXPECT_EQ(expected.randomInitialRecentCount, actual.logicMirror.randomInitialRecentCount);
        EXPECT_EQ(expected.randomInitialRecent, actual.logicMirror.randomInitialRecent);
    };
    const auto checkApplied = [&](harken::DecisionToken coordinator,
                                  const harken::FrontierActivationDescriptor& descriptor,
                                  std::uint64_t sequence) {
        const auto* activation = engine->decisions.ResolveFrontierActivation(coordinator);
        ASSERT_NE(nullptr, activation);
        ASSERT_TRUE(matchesDescriptor(activation->Descriptor(), descriptor));
        harken::FrontierActivationReceipt receipt{};
        ASSERT_EQ(harken::FrontierReceiptRead::Ready,
            activation->Read(descriptor.entry, sequence, &receipt));
        EXPECT_TRUE(receipt.entry == descriptor.entry);
        EXPECT_TRUE(receipt.order == descriptor.order);
        EXPECT_EQ(harken::FrontierReceiptOrigin::Audio, receipt.origin);
        ASSERT_EQ(harken::FrontierReceiptOutcome::Applied, receipt.outcome);
        EXPECT_EQ(harken::FrontierReceiptReason::None, receipt.reason);
        EXPECT_EQ(sequence, receipt.audioSequence);
    };
    bool observedSecondChild = false;
    for (std::uint32_t block = 0; block < 96; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        if (!observedBoundGeometry) {
            const auto* attempt = resolveSavedAttempt();
            ASSERT_NE(nullptr, attempt);
            harken::ImmediateLaneObservation lane{};
            ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
            if (lane.committed) {
                ASSERT_FALSE(lane.missed);
                ASSERT_FALSE(lane.cancelled);
                ASSERT_FALSE(lane.protocolRefused);
                const auto* actual = resolveSavedService();
                ASSERT_NE(nullptr, actual);
                boundC0 = attempt->initialQueueDescriptor;
                boundC1 = attempt->queueContinuationDescriptor;
                ASSERT_TRUE(boundC0.Valid());
                ASSERT_TRUE(boundC1.Valid());
                EXPECT_EQ(savedC0.slot, boundC0.entry.coordinator.slot);
                EXPECT_EQ(savedC0.generation, boundC0.entry.coordinator.generation);
                EXPECT_EQ(savedC1.slot, boundC1.entry.coordinator.slot);
                EXPECT_EQ(savedC1.generation, boundC1.entry.coordinator.generation);
                EXPECT_EQ(savedAttemptGeneration, boundC0.entry.attempt);
                EXPECT_EQ(savedAttemptGeneration, boundC1.entry.attempt);
                EXPECT_TRUE(boundC0.primary == savedC0Primary);
                EXPECT_TRUE(boundC1.primary == savedC1Primary);
                EXPECT_TRUE(boundC0.entry.owner == savedOwner);
                EXPECT_TRUE(boundC1.entry.owner == savedOwner);
                EXPECT_EQ(savedService.owner, boundC0.entry.owner.child);
                EXPECT_EQ(savedService.epoch, boundC0.entry.owner.childEpoch);
                EXPECT_EQ(savedService.token.slot, boundC0.entry.owner.serviceSlot);
                EXPECT_EQ(savedService.token.generation, boundC0.entry.owner.serviceGeneration);
                entryQuantum = attempt->entryQuantum;
                ASSERT_LE(entryQuantum, UINT64_MAX / config.blockFrames);
                EXPECT_EQ(entryQuantum * config.blockFrames, boundC0.order.executeFrame);
                EXPECT_EQ(info.acceptedLogicSequence, boundC0.order.logicCommitSequence);
                EXPECT_EQ(info.acceptedLogicSequence, boundC1.order.logicCommitSequence);
                harken::CompositeCompletionOwnerInfo actualComposite{};
                ASSERT_TRUE(engine->compositeCompletionOwners.Capture(savedAggregate, &actualComposite));
                EXPECT_TRUE(sameOccurrence(savedCurrentOccurrence, actualComposite.composedOccurrence));
                EXPECT_EQ(composite.aggregateRevision, actualComposite.aggregateRevision);
                EXPECT_EQ(composite.leafCount, actualComposite.leafCount);
                EXPECT_EQ(actual->queueCompletionFrame, actualComposite.absoluteLogicalCompleteFrame);
                EXPECT_EQ(boundC1.order.executeFrame, actualComposite.absoluteLogicalCompleteFrame);
                ASSERT_EQ(0u, boundC1.order.executeFrame % config.blockFrames);
                boundaryQuantum = boundC1.order.executeFrame / config.blockFrames;
                ASSERT_LT(entryQuantum, boundaryQuantum);
                ASSERT_LE(engine->mixer.BlocksRendered(), entryQuantum);
                for (std::size_t index = 0; index < originalLeaves.size(); ++index) {
                    harken::KnownScheduleLeafV1 leaf{};
                    ASSERT_TRUE(engine->compositeCompletionOwners.CaptureLeaf(
                        savedAggregate, static_cast<std::uint32_t>(index), &leaf));
                    EXPECT_EQ(originalLeaves[index].stableLeafOrdinal, leaf.stableLeafOrdinal);
                    EXPECT_TRUE(sameOccurrence(originalLeaves[index].occurrence, leaf.occurrence));
                    EXPECT_EQ(originalLeaves[index].renderGeneration, leaf.renderGeneration);
                    EXPECT_TRUE(harken::SameCompletionOwner(originalLeaves[index].predicate.owner,
                        leaf.predicate.owner));
                    EXPECT_EQ(boundC0.order.executeFrame, leaf.absoluteLeafStartFrame);
                    EXPECT_EQ(boundC0.order.executeFrame, leaf.predicate.absoluteLogicalStartFrame);
                    harken::EngineTimelineVoiceInstallIdentity installation{};
                    ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(sources[index].render, &installation));
                    EXPECT_TRUE(sameArm(sources[index].arm, installation.startArm));
                    EXPECT_TRUE(installation.target == sources[index].installation.target);
                    EXPECT_EQ(boundC0.order.executeFrame, installation.onsetFrame);
                }
                harken::Plan03PageGroupView c1Coordinator{};
                ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(savedC1Primary, &c1Coordinator));
                EXPECT_TRUE(c1Coordinator.identity == savedC1Primary);
                ASSERT_NE(nullptr, c1Coordinator.frontier);
                EXPECT_EQ(harken::FrontierGroupRole::Coordinator, c1Coordinator.frontier->role);
                EXPECT_TRUE(c1Coordinator.frontier->entry == boundC1.entry);
                EXPECT_TRUE(c1Coordinator.frontier->primary == boundC1.primary);
                EXPECT_TRUE(c1Coordinator.frontier->operation.group == savedC1Primary);
                EXPECT_TRUE(c1Coordinator.frontier->operation.owner == savedOwner);
                EXPECT_TRUE(c1Coordinator.frontier->prerequisite == boundC0.entry);
                EXPECT_TRUE(c1Coordinator.frontier->prerequisiteMember == savedInitialMember);
                EXPECT_FALSE(c1Coordinator.frontier->queueConditional.Valid());
                harken::Plan03PageGroupView c1Slice{};
                ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(savedConditionalMember, &c1Slice));
                EXPECT_TRUE(c1Slice.identity == savedConditionalMember);
                EXPECT_EQ(savedConditionalMemberDecision.slot, c1Slice.identity.decision.slot);
                EXPECT_EQ(savedConditionalMemberDecision.generation, c1Slice.identity.decision.generation);
                ASSERT_NE(nullptr, c1Slice.frontier);
                EXPECT_EQ(harken::FrontierGroupRole::EntryMember, c1Slice.frontier->role);
                EXPECT_TRUE(c1Slice.frontier->entry == boundC1.entry);
                EXPECT_TRUE(c1Slice.frontier->primary == savedC1Primary);
                EXPECT_TRUE(c1Slice.frontier->operation.group == savedConditionalMember);
                EXPECT_TRUE(c1Slice.frontier->operation.owner == savedOwner);
                EXPECT_EQ(harken::FrontierOperationKind::Dependent, c1Slice.frontier->operation.kind);
                EXPECT_EQ(boundC1.order.executeFrame, c1Slice.frontier->operation.order.executeFrame);
                EXPECT_EQ(info.acceptedLogicSequence, c1Slice.frontier->operation.order.logicCommitSequence);
                EXPECT_EQ(boundC1.worldGeneration, c1Slice.frontier->operation.world);
                EXPECT_EQ(savedConditionalMember.transportEpoch, c1Slice.frontier->operation.transport);
                ASSERT_EQ(1u, c1Slice.memberCount);
                ASSERT_NE(nullptr, c1Slice.members);
                EXPECT_TRUE(sameArm(sources[2].arm, c1Slice.members[0]));
                ASSERT_TRUE(c1Slice.frontier->queueConditional.Valid());
                EXPECT_EQ(savedQueue.slot, c1Slice.frontier->queueConditional.slot);
                EXPECT_EQ(savedQueue.generation, c1Slice.frontier->queueConditional.generation);
                EXPECT_EQ(savedQueueSnapshot.logicMirror.version, c1Slice.frontier->queueConditional.currentVersion);
                EXPECT_EQ(savedConditional.version, c1Slice.frontier->queueConditional.pendingVersion);
                EXPECT_TRUE(sameOccurrence(savedCurrentOccurrence, c1Slice.frontier->queueConditional.current));
                EXPECT_TRUE(sameOccurrence(savedSuccessorOccurrence, c1Slice.frontier->queueConditional.successor));
                observedBoundGeometry = true;
            }
        }
        const auto beforeCallback = engine->mixer.BlocksRendered();
        engine->nullBackend.Pump(1);
        const auto afterCallback = engine->mixer.BlocksRendered();
        ASSERT_EQ(beforeCallback + 1u, afterCallback);
        // Observe every new ACK before logic can reclaim a same-quantum completed Source.
        if (!observedC1Applied) {
            for (auto& source : sources) {
                if (source.acknowledgedSequence != 0) continue;
                harken::TimelineArmObservation actual{};
                ASSERT_TRUE(engine->timelineArms.Observe(source.arm, &actual));
                if (source.acknowledgedSequence == 0 &&
                    actual.armedCompletionSequence > source.before.armedCompletionSequence) {
                    EXPECT_EQ(afterCallback, actual.armedCompletionSequence);
                    source.acknowledgedSequence = actual.armedCompletionSequence;
                }
            }
        }
        if (observedBoundGeometry && beforeCallback == entryQuantum) {
            ASSERT_NE(nullptr, resolveSavedService());
            ASSERT_NE(nullptr, resolveSavedAttempt());
            ASSERT_NO_FATAL_FAILURE(checkApplied(savedC0, boundC0, afterCallback));
            observedC0Applied = true;
            harken::QueueInstanceSnapshot entered{};
            ASSERT_TRUE(engine->queueInstances.Capture(savedQueue, &entered));
            ASSERT_NO_FATAL_FAILURE(checkQueueIdentity(entered));
            EXPECT_EQ(afterCallback, entered.initialActivationSequence);
            for (std::size_t index = 0; index < originalLeaves.size(); ++index) {
                const auto& source = sources[index];
                harken::TimelineArmObservation actual{};
                ASSERT_TRUE(engine->timelineArms.Observe(source.arm, &actual));
                ASSERT_GT(source.acknowledgedSequence, source.before.armedCompletionSequence);
                EXPECT_EQ(source.acknowledgedSequence, actual.armedCompletionSequence);
                EXPECT_EQ(afterCallback, actual.startedBlockSequence);
                EXPECT_EQ(source.submission, engine->originalSourceSubmissions.Find(source.arm));
                EXPECT_TRUE(sameArm(source.arm, source.submission->Token()));
                EXPECT_EQ(source.submission,
                    engine->timelineArms.RowAt(source.arm.slot)->originalSourceSubmission);
                const auto* progress = engine->timelineOccurrences.CompletionProgressOf(originalLeaves[index].occurrence);
                ASSERT_NE(nullptr, progress);
                harken::CompletionProgressSnapshot rendered{};
                ASSERT_TRUE(harken::CaptureCompletionProgressExact(*progress, originalLeaves[index].occurrence,
                    originalLeaves[index].renderGeneration, &rendered));
                EXPECT_EQ(afterCallback, rendered.completedThroughBlockSequence);
                EXPECT_GT(rendered.progressRevision, originalProgress[index].progressRevision);
                EXPECT_GT(rendered.logicalOutputFramesProduced,
                    originalProgress[index].logicalOutputFramesProduced);
                if (source.terminal.Valid()) {
                    ASSERT_EQ(source.terminalRecord, engine->sourceTerminals.Resolve(source.terminal));
                    EXPECT_EQ(source.terminalLeaf, source.terminalRecord->leaf);
                    EXPECT_EQ(source.terminalEpoch, source.terminalRecord->acceptedEpoch);
                    EXPECT_EQ(source.render, source.terminalRecord->render);
                    EXPECT_EQ(source.terminalController, source.terminalRecord->controller);
                    EXPECT_EQ(source.installation.releaseObserver.slot, source.terminalRecord->release.slot);
                    EXPECT_EQ(source.installation.releaseObserver.targetSequence,
                        source.terminalRecord->release.targetSequence);
                    const auto& actualOwner = source.terminalRecord->resourceOwner;
                    EXPECT_EQ(source.terminalOwner.serviceSlot, actualOwner.serviceSlot);
                    EXPECT_EQ(source.terminalOwner.serviceGeneration, actualOwner.serviceGeneration);
                    EXPECT_EQ(source.terminalOwner.instance, actualOwner.instance);
                    EXPECT_EQ(source.terminalOwner.epoch, actualOwner.epoch);
                    EXPECT_EQ(source.terminalOwner.invocationSlot, actualOwner.invocationSlot);
                    EXPECT_EQ(source.terminalOwner.invocationGeneration, actualOwner.invocationGeneration);
                    const auto terminalSequence = source.terminalRecord->completedSequence.load(
                        std::memory_order_acquire);
                    if (terminalSequence > source.terminalBeforeSequence) EXPECT_EQ(afterCallback, terminalSequence);
                }
            }
            observedCurrentStarts = true;
        }
        if (observedBoundGeometry && beforeCallback == entryQuantum + 1u) {
            // The entry block cancels (+0.25 and -0.25); this new block has the long leaf.
            EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(),
                engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()),
                harkentest::kSilenceFloor);
            observedCurrentPcm = true;
        }
        if (observedBoundGeometry && beforeCallback == boundaryQuantum) {
            ASSERT_NE(nullptr, resolveSavedService());
            ASSERT_NE(nullptr, resolveSavedAttempt());
            ASSERT_NO_FATAL_FAILURE(checkApplied(savedC1, boundC1, afterCallback));
            observedC1Applied = true;
            harken::QueueInstanceSnapshot activated{};
            ASSERT_TRUE(engine->queueInstances.Capture(savedQueue, &activated));
            ASSERT_NO_FATAL_FAILURE(checkQueueIdentity(activated));
            EXPECT_EQ(savedConditional.version, activated.pendingVersion);
            EXPECT_EQ(harken::ConditionalQueueActivation::Activated, activated.pendingActivation);
            EXPECT_EQ(harken::QueueFailurePhase::Healthy, activated.failurePhase);
            const auto& source = sources[2];
            harken::TimelineArmObservation started{};
            ASSERT_TRUE(engine->timelineArms.Observe(source.arm, &started));
            ASSERT_GT(source.acknowledgedSequence, source.before.armedCompletionSequence);
            EXPECT_EQ(source.acknowledgedSequence, started.armedCompletionSequence);
            EXPECT_EQ(afterCallback, started.startedBlockSequence);
            EXPECT_EQ(source.submission, engine->originalSourceSubmissions.Find(source.arm));
            EXPECT_TRUE(sameArm(source.arm, source.submission->Token()));
            EXPECT_EQ(source.submission,
                engine->timelineArms.RowAt(source.arm.slot)->originalSourceSubmission);
            const auto* successorVoice = engine->voices.Resolve(source.render);
            ASSERT_NE(nullptr, successorVoice);
            EXPECT_EQ(source.arm.slot, successorVoice->timelineArmSlot);
            EXPECT_EQ(source.arm.generation, successorVoice->timelineArmGeneration);
            EXPECT_EQ(source.terminal.slot, successorVoice->sourceTerminalToken.slot);
            EXPECT_EQ(source.terminal.generation, successorVoice->sourceTerminalToken.generation);
            EXPECT_EQ(source.terminalRecord, successorVoice->sourceTerminal);
            if (source.terminal.Valid()) {
                ASSERT_EQ(source.terminalRecord, engine->sourceTerminals.Resolve(source.terminal));
                EXPECT_EQ(source.terminalLeaf, source.terminalRecord->leaf);
                EXPECT_EQ(source.terminalEpoch, source.terminalRecord->acceptedEpoch);
                EXPECT_EQ(source.render, source.terminalRecord->render);
            }
            observedSuccessorStart = true;
            EXPECT_GT(harkentest::Peak(engine->nullBackend.LastBlock(),
                engine->nullBackend.BlockFrames() * engine->nullBackend.Channels()),
                harkentest::kSilenceFloor);
            observedSuccessorPcm = true;
        }
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto row = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance ==
                       play.producedPlayableInstance;
            });
        if (row != engine->playableServices.end() &&
            row->queueCurrentScheduleLeafCount == 0 &&
            row->leaf.stableId == CanonicalActionWorld::kSecondSound) {
            observedSecondChild = true;
        }
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
            break;
        }
    }

    EXPECT_TRUE(observedBoundGeometry);
    EXPECT_TRUE(observedCurrentStarts);
    EXPECT_TRUE(observedC0Applied);
    EXPECT_TRUE(observedC1Applied);
    EXPECT_TRUE(observedSuccessorStart);
    EXPECT_TRUE(observedCurrentPcm);
    EXPECT_TRUE(observedSuccessorPcm);
    EXPECT_TRUE(observedSecondChild) << CaptureImmediateQueueContinuationState(*engine, firing);
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state)
        << CaptureImmediateQueueContinuationState(*engine, firing);
    EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome);
    EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, info.terminalReason);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, play.state);
    EXPECT_FALSE(engine->playableInstances
                     .Classify(play.producedPlayableInstance)
                     .live);
    EXPECT_EQ(0u, engine->voices.ActiveCount());
    EXPECT_EQ(0u, engine->queueInstances.LiveCount());
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

