void CaptureCanonicalResetProjection(harken::Engine& engine,
    const harken::EnginePlayableServiceRow& row, const CanonicalActionWorld& image,
    harken::EffectiveQueueState* final) {
    harken::EffectiveQueueState current{};
    harken::EffectiveQueueState first{};
    ASSERT_TRUE(engine.queueInstances.ResolveResetSelection(row.queueInstance, &current, &first));
    EXPECT_EQ(image.queueChildren[0].stableChildOrdinal, first.currentChildOrdinal);
    ASSERT_EQ(harken::QueueSequenceStepStatus::Successor,
        harken::ResolveSequenceQueueStep(image.containers[2], first, final));
    EXPECT_EQ(image.queueChildren[1].stableChildOrdinal, final->currentChildOrdinal);
}

void ExpectActualSameKeyC1CoreNegativeControls(
    harken::Engine& engine, harken::ImmediateLaneHandle handle,
    std::uint64_t quantum, std::uint32_t frames) {
    ASSERT_EQ(quantum, engine.mixer.BlocksRendered());
    ASSERT_FALSE(engine.immediateActionLane.HasRegisteredEntries(
        handle.slot, handle.generation));
    // Registered entry captures intentionally terminalize on ReleaseCapture;
    // this fixture is the actual unregistered Queue factory lane only.
    const auto* bucket = engine.immediateActionLane.CaptureDue(handle.slot, quantum);
    ASSERT_NE(nullptr, bucket);
    struct CaptureReturn {
        harken::ImmediateActionLane& lane;
        std::uint32_t slot;
        const harken::ImmediateLaneBucket* bucket;
        ~CaptureReturn() { EXPECT_TRUE(lane.ReleaseCapture(slot, bucket)); }
    } captureReturn{engine.immediateActionLane, handle.slot, bucket};
    ASSERT_EQ(handle.generation, bucket->attemptGeneration);
    ASSERT_EQ(2u, bucket->groupCount);
    ASSERT_EQ(1u, bucket->eventCount);
    ASSERT_EQ(0u, bucket->memberCount);
    const auto* groups = engine.immediateActionLane.Groups(handle.slot, bucket);
    const auto* events = engine.immediateActionLane.Events(handle.slot, bucket);
    ASSERT_NE(nullptr, groups);
    ASSERT_NE(nullptr, events);
    std::array<harken::Plan03PageGroupView, 2> originals{};
    std::uint32_t coordinator = UINT32_MAX;
    std::uint32_t conditional = UINT32_MAX;
    for (std::uint32_t index = 0; index < originals.size(); ++index) {
        ASSERT_TRUE(engine.timelinePool.ResolvePlan03GroupSliceRt(
            groups[index].identity, &originals[index]));
        ASSERT_NE(nullptr, originals[index].frontier);
        ASSERT_NE(nullptr, originals[index].lease);
        ASSERT_EQ(0u, originals[index].memberCount);
        ASSERT_EQ(0u, originals[index].sourceControlCount);
        if (originals[index].frontier->role == harken::FrontierGroupRole::Coordinator)
            coordinator = index;
        if (originals[index].frontier->role == harken::FrontierGroupRole::EntryMember)
            conditional = index;
    }
    ASSERT_LT(coordinator, originals.size());
    ASSERT_LT(conditional, originals.size());
    ASSERT_NE(coordinator, conditional);
    const auto& identity = originals[conditional].frontier->queueConditional;
    ASSERT_TRUE(identity.Valid());
    ASSERT_EQ(identity.current.slot, identity.successor.slot);
    ASSERT_EQ(identity.current.generation, identity.successor.generation);
    const auto& event = events[0].event;
    ASSERT_NE(nullptr, event.program.program);
    const auto* program = event.program.program;
    ASSERT_NE(nullptr, program->payloads);
    ASSERT_LT(event.payload, program->payloadCount);
    const auto* payload = &program->payloads[event.payload];
    ASSERT_EQ(harken::TimelineEventKind::ControllerActivation, payload->kind);

    // A different occurrence is factory issued by the SAME native pool.
    // It is never bound, published, or used to create a proof.
    const auto* key = engine.timelineOccurrences.KeyOf(identity.current);
    ASSERT_NE(nullptr, key);
    auto foreignKey = *key;
    ASSERT_NE(UINT32_MAX, foreignKey.occurrenceOrdinal);
    ++foreignKey.occurrenceOrdinal;
    harken::OccurrenceToken foreign{};
    ASSERT_TRUE(engine.timelineOccurrences.PrepareAcquire(foreignKey, &foreign));
    struct PreparedOccurrenceReturn {
        harken::OccurrenceStatePool& pool;
        harken::OccurrenceToken token;
        ~PreparedOccurrenceReturn() { EXPECT_TRUE(pool.CancelPreparedAcquire(token)); }
    } preparedReturn{engine.timelineOccurrences, foreign};
    ASSERT_TRUE(foreign.slot != identity.current.slot ||
        foreign.generation != identity.current.generation);

    enum class Fault { MissingCoordinator, DuplicateController,
        DifferentSuccessor, WrongPendingVersion };
    for (const auto fault : {Fault::MissingCoordinator, Fault::DuplicateController,
            Fault::DifferentSuccessor, Fault::WrongPendingVersion}) {
        SCOPED_TRACE(static_cast<unsigned>(fault));
        auto malformed = *originals[conditional].frontier;
        harken::FrontierTimelineFinalizer finalizer(engine.voices, engine.timelineArms);
        ASSERT_TRUE(finalizer.Attach(engine.decisions, engine.timelinePool, true));
        finalizer.AttachVariableControls(engine.variableControlInstances);
        finalizer.AttachQueues(engine.queueInstances);
        finalizer.AttachQueueCompletion(engine.timelineOccurrences,
            &engine.compositeCompletionOwners);
        finalizer.AttachArmGroups(engine.armGroups);
        finalizer.AttachTransitions(engine.transitionInstances);
        finalizer.Begin(quantum, frames);

        // These copies corrupt only observations handed to Core. Original
        // factory backing, native Queue state, bindings and leases are immutable.
        // Neither a copied binding nor a syntactic identity can mint rights.
        if (fault == Fault::DifferentSuccessor)
            malformed.queueConditional.successor = foreign;
        if (fault == Fault::WrongPendingVersion) {
            ASSERT_NE(UINT64_MAX, malformed.queueConditional.pendingVersion);
            ++malformed.queueConditional.pendingVersion;
        }
        for (std::uint32_t index = 0; index < originals.size(); ++index) {
            if (fault == Fault::MissingCoordinator && index == coordinator) continue;
            auto view = originals[index];
            if (index == conditional &&
                (fault == Fault::DifferentSuccessor ||
                 fault == Fault::WrongPendingVersion))
                view.frontier = &malformed;
            ASSERT_TRUE(finalizer.CollectGroup(view));
        }
        ASSERT_TRUE(finalizer.CollectEvent(event, payload,
            harken::kTimelineDispositionApplied));
        if (fault == Fault::DuplicateController)
            ASSERT_TRUE(finalizer.CollectEvent(event, payload,
                harken::kTimelineDispositionApplied));
        std::uint32_t claimCalls = 0u;
        EXPECT_FALSE(finalizer.FinishLaneContinuationBucket(
            [](void* context, harken::ImmediateLaneBucketClaimReceipt*) noexcept {
                ++*static_cast<std::uint32_t*>(context);
                return false;
            }, &claimCalls, &engine.immediateActionLane, bucket,
            handle.slot, handle.generation));
        EXPECT_EQ(0u, claimCalls);
        harken::QueueInstanceSnapshot unchanged{};
        ASSERT_TRUE(engine.queueInstances.Capture(
            {identity.slot, identity.generation}, &unchanged));
        EXPECT_EQ(identity.currentVersion, unchanged.logicMirror.version);
        EXPECT_EQ(identity.pendingVersion, unchanged.pendingVersion);
        EXPECT_EQ(harken::ConditionalQueueActivation::Waiting,
            unchanged.pendingActivation);
        EXPECT_EQ(harken::AudioSliceState::Ready, originals[coordinator].lease->Capture().state);
        const auto& entry = originals[coordinator].frontier->entry;
        const auto* activation = engine.decisions.ResolveFrontierActivation(entry.coordinator);
        ASSERT_NE(nullptr, activation);
        harken::FrontierActivationReceipt receipt{};
        EXPECT_EQ(harken::FrontierReceiptRead::InFlight,
            activation->Read(entry, engine.mixer.BlocksRendered(), &receipt));
    }
    // CaptureReturn releases only the genuine borrow. The real next callback
    // consumes the ORIGINAL bucket. Its existing Applied/Audio assertions and
    // strict-later native fence cleanup remain mandatory.
}

void CheckImmediateSameProgramQueue(bool restartCycle, bool requireTerminalC1 = false) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(512, 0.25f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &firstPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    image.queueChildren[1].playable = image.queueChildren[0].playable;
    image.queueCompletionLeaves[1].content = image.queueChildren[1].playable;
    image.occurrences[3].childPlayable = image.queueChildren[1].playable;
    image.occurrences[3].occurrenceSemanticFingerprint =
        harken::ComputePlayableOccurrenceFingerprintV1(image.occurrences[3]);
    image.containers[2].queueCycle = restartCycle ? harken::QueueCycleV1::Loop : harken::QueueCycleV1::Once;
    image.world.identity.runtimeSemanticFingerprint =
        harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    const auto beforePostSequence = engine->mixer.BlocksRendered();
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
    ASSERT_EQ(VN_ACTION_FIRING_ACTIVE, info.state);
    ASSERT_EQ(1u, info.livePlayableCount);
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    const auto row = std::find_if(
        engine->playableServices.begin(), engine->playableServices.end(),
        [&](const harken::EnginePlayableServiceRow& candidate) {
            return candidate.rootInstance == play.producedPlayableInstance;
        });
    ASSERT_NE(engine->playableServices.end(), row);
    ASSERT_TRUE(row->InvocationValid());
    ASSERT_EQ(firing, row->Invocation().actionFiring);
    ASSERT_TRUE(row->identity.Valid());
    ASSERT_TRUE(row->partition.Valid());
    const harken::EnginePlayableServiceReference savedService{
        row->identity, row->ownerInstance, row->ownerEpoch, row->invocationGeneration};
    const auto savedPartition = row->partition;
    const auto* savedInvocation = row->invocation;
    const auto savedInvocationSlot = row->Invocation().slot;
    const auto savedQueue = row->queueInstance;
    const bool actualC1Route = row->queueFirstContinuationLane;
    if (requireTerminalC1) {
        ASSERT_FALSE(restartCycle);
        ASSERT_TRUE(actualC1Route)
            << CaptureImmediateQueueContinuationState(*engine, firing);
    }
    const auto savedConditional = row->queueConditional;
    const auto savedCurrentOccurrence = row->queueCurrentOccurrence;
    const auto savedSuccessorOccurrence = row->queueSuccessorOccurrence;
    const auto savedCurrentRender = row->renderHandle;
    ASSERT_TRUE(savedConditional.Valid());
    ASSERT_NE(0u, savedCurrentOccurrence.generation);
    const auto savedSuccessorArm = row->queueSuccessorArm;
    const auto savedSuccessorRender = row->queueSuccessorRenderHandle;
    const auto* savedSuccessorBank = row->queueSuccessorProgramBank;
    const auto savedSuccessorBankGeneration = savedSuccessorBank == nullptr
        ? 0u : savedSuccessorBank->Generation();
    const auto savedSuccessorPlane = row->queueSuccessorProgramPlane;
    const auto savedSuccessorMirrorSlot = static_cast<std::size_t>(row->queueSuccessorScheduleBase);
    const auto savedSuccessorSoundId = row->queueSuccessorVoice.soundId;
    const auto sameArm = [](harken::TimelineArmToken a, harken::TimelineArmToken b) {
        return a.slot == b.slot && a.generation == b.generation &&
            a.renderSlot == b.renderSlot && a.renderGeneration == b.renderGeneration;
    };
    harken::EngineTimelineVoiceInstallIdentity savedSuccessorInstallation{};
    if (restartCycle) {
        ASSERT_TRUE(savedSuccessorArm.Valid());
        ASSERT_NE(nullptr, savedSuccessorBank);
        ASSERT_NE(0u, savedSuccessorRender);
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(
            savedSuccessorRender, &savedSuccessorInstallation));
        EXPECT_TRUE(sameArm(savedSuccessorArm, savedSuccessorInstallation.startArm));
    }
    const auto savedRoot = row->rootInstance;
    const auto savedTicket = row->ticket;
    const auto ownerView = engine->playableInstances.Classify(row->ownerInstance);
    const auto parentView = engine->playableInstances.Classify(ownerView.parent);
    const auto invocationView = engine->playableInstances.Classify(savedRoot);
    const harken::FrontierOwnerIdentity savedOwner{
        row->ownerInstance, row->ownerEpoch, ownerView.parent,
        ownerView.parent == 0 ? 0 : parentView.scheduleEpoch,
        savedRoot, invocationView.scheduleEpoch,
        row->identity.slot, row->identity.generation};
    ASSERT_TRUE(savedOwner.Valid());
    const auto resolveSavedService = [&]() -> harken::EnginePlayableServiceRow* {
        auto* current = engine->ResolvePlayableService(savedService);
        if (current == nullptr || current->partition.slot != savedPartition.slot ||
            current->partition.generation != savedPartition.generation ||
            current->invocation != savedInvocation ||
            current->Invocation().slot != savedInvocationSlot ||
            current->Invocation().actionFiring != firing ||
            current->rootInstance != savedRoot || current->ticket != savedTicket ||
            current->queueInstance.slot != savedQueue.slot ||
            current->queueInstance.generation != savedQueue.generation)
            return nullptr;
        return current;
    };
    ASSERT_EQ(&*row, resolveSavedService());

    EXPECT_EQ(!restartCycle, row->queueSameProgramKey);
    EXPECT_TRUE(row->queueContinuationPrepared);
    EXPECT_TRUE(row->queueDecision.Valid());
    EXPECT_EQ(restartCycle, row->queueSuccessorDecision.Valid());
    EXPECT_TRUE(row->queueConditional.Valid());
    EXPECT_TRUE(row->queueArmGroup.Valid());
    EXPECT_EQ(restartCycle ? 1u : 0u, row->queueTransitionGroupArmCount);
    EXPECT_EQ(restartCycle, row->queueSuccessorRenderHandle != 0);
    EXPECT_EQ(restartCycle, row->queueSuccessorOccurrence.generation != 0);
    EXPECT_EQ(0u, row->queueSuccessorScheduleLeafCount);
    EXPECT_EQ(restartCycle ? 2u : 1u, engine->voices.ActiveCount());
    EXPECT_EQ(info.acceptedLogicSequence, row->ticket);
    EXPECT_EQ(info.acceptedLogicSequence, row->queueTicket);
    EXPECT_EQ(restartCycle ? info.acceptedLogicSequence : 0u, row->queueSuccessorTicket);
    harken::QueueInstanceSnapshot queue{};
    ASSERT_TRUE(engine->queueInstances.Capture(savedQueue, &queue));
    harken::EffectiveQueueState sameWithinCycle{};
    ASSERT_EQ(harken::QueueSequenceStepStatus::Successor,
        harken::ResolveSequenceQueueStep(image.containers[2], queue.logicMirror, &sameWithinCycle));
    harken::EffectiveQueueState following{};
    EXPECT_EQ(restartCycle ? harken::QueueSequenceStepStatus::Successor : harken::QueueSequenceStepStatus::NaturalEnd,
        harken::ResolveSequenceQueueStep(image.containers[2], sameWithinCycle, &following));
    ExpectEffectiveQueueState(restartCycle ? following : sameWithinCycle, row->queueNextState);

    const auto* attempt = std::find_if(
        engine->immediateEntryAttempts.get(),
        engine->immediateEntryAttempts.get() + engine->immediateEntryAttemptCapacity,
        [firing](const auto& candidate) { return candidate.active && candidate.root == firing; });
    ASSERT_NE(engine->immediateEntryAttempts.get() + engine->immediateEntryAttemptCapacity, attempt);
    ASSERT_TRUE(attempt->lane.Valid());
    ASSERT_EQ(savedService.token, attempt->initialService);
    ASSERT_EQ(savedService.invocationGeneration, attempt->initialInvocationGeneration);
    const auto savedAttemptSlot = static_cast<std::size_t>(
        attempt - engine->immediateEntryAttempts.get());
    const auto savedAttemptGeneration = attempt->generation;
    const auto savedLane = attempt->lane;
    const auto savedInitialCoordinator = attempt->initialQueueCoordinator;
    const auto savedInitialPrimary = attempt->initialQueuePrimaryGroup;
    const auto savedContinuationCoordinator = attempt->queueContinuationCoordinator;
    const auto savedContinuationPrimary = attempt->queueContinuationPrimaryGroup;
    ASSERT_NE(0u, savedAttemptGeneration);
    ASSERT_TRUE(savedInitialCoordinator.Valid());
    ASSERT_TRUE(savedInitialPrimary.Exact());
    EXPECT_EQ(actualC1Route, savedContinuationCoordinator.Valid());
    const auto resolveSavedAttempt = [&]() -> const harken::EngineImmediateEntryAttempt* {
        const auto& current = engine->immediateEntryAttempts[savedAttemptSlot];
        if (!current.active || current.generation != savedAttemptGeneration ||
            current.root != firing || current.initialService != savedService.token ||
            current.initialInvocationGeneration != savedService.invocationGeneration ||
            current.lane.slot != savedLane.slot || current.lane.generation != savedLane.generation ||
            current.initialQueueCoordinator.slot != savedInitialCoordinator.slot ||
            current.initialQueueCoordinator.generation != savedInitialCoordinator.generation ||
            !(current.initialQueuePrimaryGroup == savedInitialPrimary))
            return nullptr;
        return &current;
    };

    const auto savedCurrentArm = row->arm;
    ASSERT_TRUE(savedCurrentArm.Valid());
    harken::TimelineArmObservation beforeAck{};
    ASSERT_TRUE(engine->timelineArms.Observe(savedCurrentArm, &beforeAck));
    EXPECT_EQ(0u, beforeAck.startedBlockSequence);
    const auto expectedDecision = actualC1Route ? row->queueDecision : row->initialQueueEntryDecision;
    ASSERT_TRUE(expectedDecision.Valid());
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> groups{};
    const auto privateCount = engine->timelinePool.CaptureImmediateLaneCohortGroups(
        firing, groups.data(), groups.size());
    ASSERT_GT(privateCount, 0u);
    ASSERT_LE(privateCount, groups.size());
    harken::Plan03GroupSliceIdentity sliceIdentity{};
    std::size_t privateMatches = 0;
    for (std::size_t index = 0; index < privateCount; ++index) {
        const auto& identity = groups[index].identity;
        if (identity.decision.slot != expectedDecision.slot ||
            identity.decision.generation != expectedDecision.generation || identity.sliceIndex != 0u)
            continue;
        sliceIdentity = identity;
        ++privateMatches;
    }
    ASSERT_EQ(1u, privateMatches);
    ASSERT_TRUE(sliceIdentity.Exact());

    // Source installation acknowledges on audio; the next Update binds and publishes.
    engine->nullBackend.Pump(1);
    ASSERT_EQ(VN_OK, Vn_Update());
    auto* current = resolveSavedService();
    ASSERT_NE(nullptr, current) << CaptureImmediateQueueContinuationState(*engine, firing);
    attempt = resolveSavedAttempt();
    ASSERT_NE(nullptr, attempt) << CaptureImmediateQueueContinuationState(*engine, firing);
    harken::ImmediateLaneObservation lane{};
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    ASSERT_TRUE(lane.committed) << CaptureImmediateQueueContinuationState(*engine, firing);
    ASSERT_FALSE(lane.missed);
    ASSERT_FALSE(lane.cancelled);
    ASSERT_FALSE(lane.protocolRefused);
    harken::TimelineArmObservation acknowledged{};
    ASSERT_TRUE(engine->timelineArms.Observe(savedCurrentArm, &acknowledged));
    EXPECT_GT(acknowledged.armedCompletionSequence, beforeAck.armedCompletionSequence);
    EXPECT_EQ(harken::ArmState::Published, acknowledged.state);
    EXPECT_EQ(0u, acknowledged.startedBlockSequence);

    const auto boundary = current->queueCompletionFrame;
    ASSERT_EQ(0u, boundary % config.blockFrames);
    const auto boundaryQuantum = boundary / config.blockFrames;
    const auto liveCount = engine->timelinePool.CaptureLiveImmediateLaneCohortGroups(
        firing, groups.data(), groups.size());
    ASSERT_LE(liveCount, groups.size());
    ASSERT_GT(liveCount, 0u);
    auto wholeLaneLastQuantum = std::max(attempt->entryQuantum, attempt->lastQuantum);
    std::size_t liveMatches = 0;
    for (std::size_t index = 0; index < liveCount; ++index) {
        const auto& actual = groups[index];
        ASSERT_EQ(savedLane.slot, actual.laneSlot);
        ASSERT_EQ(savedLane.generation, actual.laneGeneration);
        ASSERT_LT(actual.dueQuantum, UINT64_MAX);
        wholeLaneLastQuantum = std::max(wholeLaneLastQuantum, actual.dueQuantum);
        if (!(actual.identity == sliceIdentity)) continue;
        EXPECT_EQ(savedLane.slot, actual.laneSlot);
        EXPECT_EQ(savedLane.generation, actual.laneGeneration);
        EXPECT_EQ(boundaryQuantum, actual.dueQuantum);
        ++liveMatches;
    }
    ASSERT_EQ(1u, liveMatches) << CaptureImmediateQueueContinuationState(*engine, firing);
    ASSERT_LE(wholeLaneLastQuantum, UINT64_MAX - 2u);
    ASSERT_LE(boundaryQuantum, wholeLaneLastQuantum);
    harken::Plan03PageGroupView slice{};
    ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(sliceIdentity, &slice));
    EXPECT_EQ(0u, slice.sourceControlCount);
    ASSERT_EQ(restartCycle ? 1u : 0u, slice.memberCount);
    ASSERT_NE(nullptr, slice.frontier);
    EXPECT_EQ(harken::FrontierGroupRole::EntryMember, slice.frontier->role);
    EXPECT_TRUE(slice.frontier->operation.group == sliceIdentity);
    EXPECT_EQ(boundary, slice.frontier->operation.order.executeFrame);

    const auto initial = attempt->initialQueueDescriptor;
    const auto continuation = attempt->queueContinuationDescriptor;
    const auto entryQuantum = attempt->entryQuantum;
    ASSERT_TRUE(initial.Valid());
    EXPECT_EQ(savedInitialCoordinator.slot, initial.entry.coordinator.slot);
    EXPECT_EQ(savedInitialCoordinator.generation, initial.entry.coordinator.generation);
    EXPECT_EQ(savedAttemptGeneration, initial.entry.attempt);
    EXPECT_TRUE(initial.entry.owner == savedOwner);
    EXPECT_TRUE(initial.primary == savedInitialPrimary);
    ASSERT_LT(entryQuantum, UINT64_MAX);
    ASSERT_LE(entryQuantum, UINT64_MAX / config.blockFrames);
    EXPECT_EQ(entryQuantum * config.blockFrames, initial.order.executeFrame);
    EXPECT_EQ(info.acceptedLogicSequence, initial.order.logicCommitSequence);
    ASSERT_GT(entryQuantum + 1u, beforePostSequence);
    ASSERT_LT(entryQuantum, boundaryQuantum);

    const auto checkCycleGeometry = [&](const harken::EnginePlayableServiceRow& observed,
                                        bool promoted) {
        SCOPED_TRACE("Cycle original successor geometry");
        ASSERT_TRUE(restartCycle);
        ASSERT_NE(nullptr, savedSuccessorBank);
        ASSERT_EQ(savedSuccessorBank, promoted
            ? observed.queueCurrentProgramBank : observed.queueSuccessorProgramBank);
        ASSERT_EQ(savedSuccessorPlane, promoted
            ? observed.queueCurrentProgramPlane : observed.queueSuccessorProgramPlane);
        const auto& bank = *savedSuccessorBank;
        ASSERT_NE(0u, savedSuccessorBankGeneration);
        ASSERT_EQ(savedSuccessorBankGeneration, bank.Generation());
        ASSERT_TRUE(bank.occupied);
        ASSERT_LE(bank.programCount, bank.schedules.size());
        ASSERT_LE(bank.aggregateCount, bank.aggregateSchedules.size());
        const harken::ProgramView* frozen = nullptr;
        for (std::size_t index = 0; index < bank.programCount; ++index) {
            if (!sameArm(bank.schedules[index].armToken, savedSuccessorArm)) continue;
            ASSERT_EQ(nullptr, frozen);
            frozen = &bank.schedules[index];
        }
        ASSERT_NE(nullptr, frozen);
        const auto& schedules = savedSuccessorPlane == 0
            ? engine->playableSchedules : engine->playableSuccessorSchedules;
        ASSERT_LT(savedSuccessorMirrorSlot, schedules.size());
        const auto& copied = schedules[savedSuccessorMirrorSlot];
        const auto& aggregate = savedSuccessorPlane == 0
            ? observed.schedule : observed.queueSuccessorSchedule;
        EXPECT_TRUE(sameArm(copied.armToken, savedSuccessorArm));
        EXPECT_EQ(frozen->ownerInstance, copied.ownerInstance);
        EXPECT_EQ(frozen->ownerInstanceScheduleEpoch, copied.ownerInstanceScheduleEpoch);
        EXPECT_EQ(frozen->transactionId, copied.transactionId);
        EXPECT_EQ(frozen->runtimeProgram.program, copied.runtimeProgram.program);
        EXPECT_EQ(frozen->runtimeProgram.programGeneration, copied.runtimeProgram.programGeneration);
        EXPECT_EQ(boundary, copied.entryAnchorFrame);
        EXPECT_EQ(boundary, frozen->entryAnchorFrame);
        EXPECT_EQ(boundary, aggregate.entryAnchorFrame);
        const auto checkStart = [&](const harken::ProgramView& program) {
            ASSERT_NE(nullptr, program.events);
            ASSERT_NE(nullptr, program.runtimeProgram.program);
            const auto& runtime = *program.runtimeProgram.program;
            ASSERT_NE(nullptr, runtime.payloads);
            std::size_t matches = 0;
            for (std::size_t event = 0; event < program.eventCount; ++event) {
                const auto& entry = program.events[event];
                if (!sameArm(entry.armToken, savedSuccessorArm)) continue;
                ASSERT_LT(entry.payload, runtime.payloadCount);
                const auto& payload = runtime.payloads[entry.payload];
                if (payload.kind != harken::TimelineEventKind::Start) continue;
                ASSERT_GE(entry.frameOffsetFromEntry, 0);
                const auto offset = static_cast<std::uint64_t>(entry.frameOffsetFromEntry);
                ASSERT_LE(offset, UINT64_MAX - program.entryAnchorFrame);
                EXPECT_EQ(boundary, program.entryAnchorFrame + offset);
                EXPECT_TRUE(payload.target == savedSuccessorInstallation.target);
                ++matches;
            }
            ASSERT_EQ(1u, matches);
        };
        ASSERT_NO_FATAL_FAILURE(checkStart(*frozen));
        ASSERT_NO_FATAL_FAILURE(checkStart(copied));
        ASSERT_NO_FATAL_FAILURE(checkStart(aggregate));
        const harken::ProgramView* frozenAggregate = nullptr;
        for (std::size_t index = 0; index < bank.aggregateCount; ++index) {
            const auto& candidate = bank.aggregateSchedules[index];
            for (std::size_t event = 0; candidate.events != nullptr &&
                 event < candidate.eventCount; ++event) {
                if (&candidate.events[event] != &frozen->events[0]) continue;
                ASSERT_EQ(nullptr, frozenAggregate);
                frozenAggregate = &candidate;
            }
        }
        ASSERT_NE(nullptr, frozenAggregate);
        EXPECT_EQ(boundary, frozenAggregate->entryAnchorFrame);
        EXPECT_EQ(aggregate.ownerInstance, frozenAggregate->ownerInstance);
        EXPECT_EQ(aggregate.ownerInstanceScheduleEpoch, frozenAggregate->ownerInstanceScheduleEpoch);
        EXPECT_EQ(aggregate.transactionId, frozenAggregate->transactionId);
        ASSERT_NO_FATAL_FAILURE(checkStart(*frozenAggregate));
        harken::EngineTimelineVoiceInstallIdentity installation{};
        ASSERT_TRUE(engine->CaptureTimelineVoiceInstallIdentity(savedSuccessorRender, &installation));
        EXPECT_EQ(savedSuccessorRender, installation.renderHandle);
        EXPECT_EQ(savedRoot, installation.rootInstance);
        EXPECT_TRUE(sameArm(savedSuccessorArm, installation.startArm));
        EXPECT_TRUE(installation.target == savedSuccessorInstallation.target);
        EXPECT_EQ(savedSuccessorInstallation.releaseObserver.slot, installation.releaseObserver.slot);
        EXPECT_EQ(savedSuccessorInstallation.releaseObserver.targetSequence,
            installation.releaseObserver.targetSequence);
        EXPECT_EQ(boundary, installation.onsetFrame);
        if (!promoted) {
            ASSERT_LT(savedSuccessorMirrorSlot, engine->playableSuccessorStartFrames.size());
            ASSERT_LT(savedSuccessorMirrorSlot, engine->playableSuccessorArms.size());
            ASSERT_LT(savedSuccessorMirrorSlot, engine->playableSuccessorRenderHandles.size());
            EXPECT_EQ(boundary, engine->playableSuccessorStartFrames[savedSuccessorMirrorSlot]);
            EXPECT_TRUE(sameArm(savedSuccessorArm,
                engine->playableSuccessorArms[savedSuccessorMirrorSlot]));
            EXPECT_EQ(savedSuccessorRender,
                engine->playableSuccessorRenderHandles[savedSuccessorMirrorSlot]);
        } else {
            EXPECT_TRUE(sameArm(savedSuccessorArm, observed.arm));
            EXPECT_EQ(savedSuccessorRender, observed.renderHandle);
            EXPECT_EQ(savedSuccessorOccurrence.slot, observed.queueCurrentOccurrence.slot);
            EXPECT_EQ(savedSuccessorOccurrence.generation, observed.queueCurrentOccurrence.generation);
            EXPECT_EQ(savedSuccessorSoundId, observed.voice.soundId);
            EXPECT_EQ(boundary, observed.startFrame);
            harken::TimelineArmObservation promotedArm{};
            ASSERT_TRUE(engine->timelineArms.Observe(savedSuccessorArm, &promotedArm));
            EXPECT_EQ(harken::ArmState::Started, promotedArm.state);
            EXPECT_EQ(boundaryQuantum + 1u, promotedArm.startedBlockSequence);
        }
    };

    const auto matchesDescriptor = [](const harken::FrontierActivationDescriptor& actual,
                                      const harken::FrontierActivationDescriptor& saved) {
        return actual.entry == saved.entry && actual.primary == saved.primary &&
            actual.order == saved.order && actual.worldGeneration == saved.worldGeneration &&
            actual.worldSemanticFingerprint == saved.worldSemanticFingerprint &&
            actual.expectedMemberCount == saved.expectedMemberCount &&
            actual.expectedEntryEventCount == saved.expectedEntryEventCount &&
            actual.programGeneration == saved.programGeneration;
    };
    const auto* initialActivation = engine->decisions.ResolveFrontierActivation(savedInitialCoordinator);
    ASSERT_NE(nullptr, initialActivation);
    ASSERT_TRUE(matchesDescriptor(initialActivation->Descriptor(), initial));
    harken::FrontierActivationReceipt beforeEntry{};
    ASSERT_EQ(harken::FrontierReceiptRead::InFlight,
        initialActivation->Read(initial.entry, engine->mixer.BlocksRendered(), &beforeEntry));

    const auto successorArm = current->queueSuccessorArm;
    EXPECT_EQ(actualC1Route, continuation.Valid());
    if (actualC1Route) {
        ASSERT_TRUE(continuation.Valid());
        EXPECT_EQ(savedContinuationCoordinator.slot, continuation.entry.coordinator.slot);
        EXPECT_EQ(savedContinuationCoordinator.generation, continuation.entry.coordinator.generation);
        EXPECT_EQ(savedAttemptGeneration, continuation.entry.attempt);
        EXPECT_TRUE(continuation.entry.owner == savedOwner);
        EXPECT_TRUE(continuation.primary == savedContinuationPrimary);
        EXPECT_EQ(boundary, continuation.order.executeFrame);
        EXPECT_EQ(info.acceptedLogicSequence, continuation.order.logicCommitSequence);
        ASSERT_TRUE(slice.frontier->queueConditional.Valid());
        EXPECT_TRUE(slice.frontier->entry == continuation.entry);
        EXPECT_TRUE(slice.frontier->primary == continuation.primary);
        EXPECT_EQ(savedQueue.slot, slice.frontier->queueConditional.slot);
        EXPECT_EQ(savedQueue.generation, slice.frontier->queueConditional.generation);
        EXPECT_EQ(queue.logicMirror.version, slice.frontier->queueConditional.currentVersion);
        EXPECT_EQ(queue.pendingVersion, slice.frontier->queueConditional.pendingVersion);
        EXPECT_EQ(savedConditional.version, slice.frontier->queueConditional.pendingVersion);
        EXPECT_EQ(savedCurrentOccurrence.slot, slice.frontier->queueConditional.current.slot);
        EXPECT_EQ(savedCurrentOccurrence.generation, slice.frontier->queueConditional.current.generation);
        const auto expectedSuccessor = restartCycle
            ? savedSuccessorOccurrence : savedCurrentOccurrence;
        EXPECT_EQ(expectedSuccessor.slot, slice.frontier->queueConditional.successor.slot);
        EXPECT_EQ(expectedSuccessor.generation, slice.frontier->queueConditional.successor.generation);
    } else {
        ASSERT_TRUE(slice.frontier->queueInitial.Valid());
        EXPECT_TRUE(slice.frontier->entry == initial.entry);
        EXPECT_TRUE(slice.frontier->primary == initial.primary);
        EXPECT_EQ(savedQueue.slot, slice.frontier->queueInitial.slot);
        EXPECT_EQ(savedQueue.generation, slice.frontier->queueInitial.generation);
        EXPECT_EQ(queue.logicMirror.version, slice.frontier->queueInitial.version);
        EXPECT_EQ(queue.programSemanticFingerprint, slice.frontier->queueInitial.programSemanticFingerprint);
    }
    if (restartCycle) {
        EXPECT_TRUE(harken::QueueSuccessorRestartsCycle(sameWithinCycle, following));
        EXPECT_NE(current->renderHandle, current->queueSuccessorRenderHandle);
        EXPECT_EQ(current->voice.soundId, current->queueSuccessorVoice.soundId);
        ASSERT_TRUE(successorArm.Valid());
        ASSERT_NE(nullptr, slice.members);
        EXPECT_EQ(successorArm.slot, slice.members[0].slot);
        EXPECT_EQ(successorArm.generation, slice.members[0].generation);
        EXPECT_EQ(successorArm.renderSlot, slice.members[0].renderSlot);
        EXPECT_EQ(successorArm.renderGeneration, slice.members[0].renderGeneration);
        EXPECT_EQ(boundary, current->queueSuccessorSchedule.entryAnchorFrame);
        EXPECT_TRUE(sameArm(savedSuccessorArm, successorArm));
        ASSERT_NO_FATAL_FAILURE(checkCycleGeometry(*current, false));
    } else {
        EXPECT_TRUE(current->queueSameProgramKey);
        EXPECT_EQ(0u, current->queueSuccessorRenderHandle);
        EXPECT_EQ(0u, current->queueSuccessorOccurrence.generation);
        EXPECT_FALSE(successorArm.Valid());
        EXPECT_EQ(savedCurrentRender, current->renderHandle);
        EXPECT_EQ(savedCurrentOccurrence.slot, current->queueCurrentOccurrence.slot);
        EXPECT_EQ(savedCurrentOccurrence.generation, current->queueCurrentOccurrence.generation);
    }

    // Consume the actual entry quantum, without a retry or extra wait budget.
    ASSERT_LE(engine->mixer.BlocksRendered(), entryQuantum);
    while (engine->mixer.BlocksRendered() < entryQuantum) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_NE(nullptr, resolveSavedService()) << CaptureImmediateQueueContinuationState(*engine, firing);
        ASSERT_NE(nullptr, resolveSavedAttempt()) << CaptureImmediateQueueContinuationState(*engine, firing);
        engine->nullBackend.Pump(1);
    }
    ASSERT_EQ(entryQuantum, engine->mixer.BlocksRendered());
    engine->nullBackend.Pump(1);
    ASSERT_EQ(entryQuantum + 1u, engine->mixer.BlocksRendered());
    ASSERT_NE(nullptr, resolveSavedService());
    ASSERT_NE(nullptr, resolveSavedAttempt());
    initialActivation = engine->decisions.ResolveFrontierActivation(savedInitialCoordinator);
    ASSERT_NE(nullptr, initialActivation);
    ASSERT_TRUE(matchesDescriptor(initialActivation->Descriptor(), initial));
    harken::FrontierActivationReceipt initialApplied{};
    ASSERT_EQ(harken::FrontierReceiptRead::Ready,
        initialActivation->Read(initial.entry, engine->mixer.BlocksRendered(), &initialApplied))
        << CaptureImmediateQueueContinuationState(*engine, firing);
    EXPECT_TRUE(initialApplied.entry == initial.entry);
    EXPECT_TRUE(initialApplied.order == initial.order);
    EXPECT_EQ(harken::FrontierReceiptOrigin::Audio, initialApplied.origin);
    ASSERT_EQ(harken::FrontierReceiptOutcome::Applied, initialApplied.outcome)
        << CaptureImmediateQueueContinuationState(*engine, firing);
    EXPECT_EQ(harken::FrontierReceiptReason::None, initialApplied.reason);
    EXPECT_EQ(entryQuantum + 1u, initialApplied.audioSequence);
    harken::TimelineArmObservation currentStarted{};
    ASSERT_TRUE(engine->timelineArms.Observe(savedCurrentArm, &currentStarted));
    EXPECT_EQ(harken::ArmState::Started, currentStarted.state);
    EXPECT_EQ(entryQuantum + 1u, currentStarted.startedBlockSequence);

    // The initial receipt was read before this Update can reconcile its owner.
    ASSERT_EQ(VN_OK, Vn_Update());
    current = resolveSavedService();
    ASSERT_NE(nullptr, current) << CaptureImmediateQueueContinuationState(*engine, firing);
    EXPECT_FALSE(current->queueTimingFinalized);
    EXPECT_TRUE(current->queueTimingPending);
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    EXPECT_TRUE(lane.committed);
    EXPECT_TRUE(lane.applied);
    EXPECT_FALSE(lane.complete);
    EXPECT_FALSE(lane.missed);
    EXPECT_FALSE(lane.cancelled);
    EXPECT_FALSE(lane.protocolRefused);
    EXPECT_EQ(restartCycle ? 2u : 1u, engine->voices.ActiveCount());
    if (actualC1Route || restartCycle) {
        ASSERT_LE(engine->mixer.BlocksRendered(), boundaryQuantum);
        while (engine->mixer.BlocksRendered() < boundaryQuantum) {
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_NE(nullptr, resolveSavedService()) << CaptureImmediateQueueContinuationState(*engine, firing);
            engine->nullBackend.Pump(1);
        }
        ASSERT_EQ(boundaryQuantum, engine->mixer.BlocksRendered());
        current = resolveSavedService();
        ASSERT_NE(nullptr, current);
        if (restartCycle) {
            harken::TimelineArmObservation beforeBoundary{};
            ASSERT_TRUE(engine->timelineArms.Observe(successorArm, &beforeBoundary));
            EXPECT_EQ(0u, beforeBoundary.startedBlockSequence);
            EXPECT_EQ(harken::ArmState::Published, beforeBoundary.state);
        } else {
            EXPECT_TRUE(current->queueSameProgramKey);
            EXPECT_EQ(savedCurrentRender, current->renderHandle);
            EXPECT_EQ(savedCurrentOccurrence.slot, current->queueCurrentOccurrence.slot);
            EXPECT_EQ(savedCurrentOccurrence.generation, current->queueCurrentOccurrence.generation);
            EXPECT_EQ(0u, current->queueSuccessorRenderHandle);
            EXPECT_EQ(0u, current->queueSuccessorOccurrence.generation);
            EXPECT_FALSE(current->queueSuccessorArm.Valid());
            EXPECT_EQ(0u, current->queueTransitionGroupArmCount);
        }
        if (actualC1Route) {
            const auto* activation = engine->decisions.ResolveFrontierActivation(savedContinuationCoordinator);
            ASSERT_NE(nullptr, activation);
            ASSERT_TRUE(matchesDescriptor(activation->Descriptor(), continuation));
            harken::FrontierActivationReceipt beforeContinuation{};
            ASSERT_EQ(harken::FrontierReceiptRead::InFlight,
                activation->Read(continuation.entry, boundaryQuantum, &beforeContinuation));
            harken::QueueInstanceSnapshot waiting{};
            ASSERT_TRUE(engine->queueInstances.Capture(savedQueue, &waiting));
            EXPECT_EQ(queue.world, waiting.world);
            EXPECT_EQ(queue.rootInstance, waiting.rootInstance);
            EXPECT_EQ(queue.programSemanticFingerprint, waiting.programSemanticFingerprint);
            ExpectEffectiveQueueState(queue.logicMirror, waiting.logicMirror);
            EXPECT_EQ(savedConditional.version, waiting.pendingVersion);
            EXPECT_EQ(harken::ConditionalQueueActivation::Waiting, waiting.pendingActivation);
        }

        if (requireTerminalC1 && actualC1Route && !restartCycle)
            ASSERT_NO_FATAL_FAILURE(ExpectActualSameKeyC1CoreNegativeControls(
                *engine, savedLane, boundaryQuantum,
                static_cast<std::uint32_t>(engine->config.blockFrames)));

        // Read the genuine boundary result before Update can settle or retire C1.
        engine->nullBackend.Pump(1);
        ASSERT_EQ(boundaryQuantum + 1u, engine->mixer.BlocksRendered());
        current = resolveSavedService();
        ASSERT_NE(nullptr, current);
        if (restartCycle) {
            harken::TimelineArmObservation started{};
            ASSERT_TRUE(engine->timelineArms.Observe(successorArm, &started));
            EXPECT_EQ(harken::ArmState::Started, started.state);
            EXPECT_EQ(boundaryQuantum + 1u, started.startedBlockSequence);
        } else {
            // SameKey C1 progresses the original Current without a new start.
            EXPECT_TRUE(current->queueSameProgramKey);
            EXPECT_EQ(savedCurrentRender, current->renderHandle);
            EXPECT_EQ(savedCurrentOccurrence.slot, current->queueCurrentOccurrence.slot);
            EXPECT_EQ(savedCurrentOccurrence.generation, current->queueCurrentOccurrence.generation);
            EXPECT_EQ(0u, current->queueSuccessorRenderHandle);
            EXPECT_EQ(0u, current->queueSuccessorOccurrence.generation);
            EXPECT_FALSE(current->queueSuccessorArm.Valid());
            EXPECT_EQ(0u, current->queueTransitionGroupArmCount);
            harken::TimelineArmObservation originalCurrent{};
            ASSERT_TRUE(engine->timelineArms.Observe(savedCurrentArm, &originalCurrent));
            EXPECT_EQ(entryQuantum + 1u, originalCurrent.startedBlockSequence);
        }
        if (actualC1Route) {
            const auto* activation = engine->decisions.ResolveFrontierActivation(savedContinuationCoordinator);
            ASSERT_NE(nullptr, activation);
            ASSERT_TRUE(matchesDescriptor(activation->Descriptor(), continuation));
            harken::FrontierActivationReceipt applied{};
            ASSERT_EQ(harken::FrontierReceiptRead::Ready,
                activation->Read(continuation.entry, engine->mixer.BlocksRendered(), &applied))
                << CaptureImmediateQueueContinuationState(*engine, firing);
            EXPECT_TRUE(applied.entry == continuation.entry);
            EXPECT_TRUE(applied.order == continuation.order);
            EXPECT_EQ(harken::FrontierReceiptOrigin::Audio, applied.origin);
            EXPECT_EQ(harken::FrontierReceiptOutcome::Applied, applied.outcome);
            EXPECT_EQ(harken::FrontierReceiptReason::None, applied.reason);
            EXPECT_EQ(boundaryQuantum + 1u, applied.audioSequence);
            harken::QueueInstanceSnapshot activated{};
            ASSERT_TRUE(engine->queueInstances.Capture(savedQueue, &activated));
            EXPECT_EQ(queue.world, activated.world);
            EXPECT_EQ(queue.rootInstance, activated.rootInstance);
            EXPECT_EQ(queue.programSemanticFingerprint, activated.programSemanticFingerprint);
            ExpectEffectiveQueueState(queue.logicMirror, activated.logicMirror);
            EXPECT_EQ(savedConditional.version, activated.pendingVersion);
            EXPECT_EQ(harken::ConditionalQueueActivation::Activated, activated.pendingActivation);
            EXPECT_EQ(harken::QueueFailurePhase::Healthy, activated.failurePhase);
        }
    }
    // Complete the original whole Lane at its actual last declared quantum.
    ASSERT_LE(engine->mixer.BlocksRendered(), wholeLaneLastQuantum + 1u);
    while (engine->mixer.BlocksRendered() <= wholeLaneLastQuantum) {
        ASSERT_EQ(VN_OK, Vn_Update());
        ASSERT_NE(nullptr, resolveSavedService())
            << CaptureImmediateQueueContinuationState(*engine, firing);
        ASSERT_NE(nullptr, resolveSavedAttempt())
            << CaptureImmediateQueueContinuationState(*engine, firing);
        engine->nullBackend.Pump(1);
    }
    const auto wholeLaneCompleteSequence = wholeLaneLastQuantum + 1u;
    ASSERT_EQ(wholeLaneCompleteSequence, engine->mixer.BlocksRendered());
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    ASSERT_TRUE(lane.complete) << CaptureImmediateQueueContinuationState(*engine, firing);
    ASSERT_TRUE(lane.committed);
    ASSERT_TRUE(lane.applied);
    ASSERT_FALSE(lane.missed);
    ASSERT_FALSE(lane.cancelled);
    ASSERT_FALSE(lane.protocolRefused);
    current = resolveSavedService();
    ASSERT_NE(nullptr, current);
    EXPECT_FALSE(current->queueTimingFinalized);
    EXPECT_TRUE(current->queueTimingPending);

    // Readers at the last quantum forbid retirement in this same audio sequence.
    ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(wholeLaneCompleteSequence, engine->mixer.BlocksRendered());
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    ASSERT_TRUE(lane.complete);
    ASSERT_FALSE(lane.missed);
    ASSERT_FALSE(lane.cancelled);
    ASSERT_FALSE(lane.protocolRefused);
    current = resolveSavedService();
    ASSERT_NE(nullptr, current);
    EXPECT_FALSE(current->queueTimingFinalized);
    EXPECT_TRUE(current->queueTimingPending);

    // One strictly later callback returns the genuine last-quantum readers.
    engine->nullBackend.Pump(1);
    ASSERT_EQ(wholeLaneCompleteSequence + 1u, engine->mixer.BlocksRendered());
    ASSERT_TRUE(engine->immediateActionLane.Observe(savedLane, &lane));
    ASSERT_TRUE(lane.complete);
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_FALSE(engine->immediateActionLane.Observe(savedLane, &lane))
        << CaptureImmediateQueueContinuationState(*engine, firing);
    EXPECT_EQ(nullptr, resolveSavedAttempt());

    // Resolve the original full service again; a natural release can reuse its address.
    auto* remaining = engine->ResolvePlayableService(savedService);
    if (remaining != nullptr) {
        ASSERT_EQ(remaining, resolveSavedService());
        EXPECT_TRUE(remaining->queueTimingFinalized);
        EXPECT_FALSE(remaining->queueTimingPending);
        if (restartCycle) {
            ASSERT_NO_FATAL_FAILURE(checkCycleGeometry(*remaining, true));
        }
    } else {
        ASSERT_FALSE(restartCycle)
            << CaptureImmediateQueueContinuationState(*engine, firing);
        VnActionFiringInfo natural{};
        natural.structSize = sizeof(natural);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &natural));
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, natural.state);
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, natural.outcome);
        EXPECT_EQ(VN_ACTION_TERMINAL_NATURAL, natural.terminalReason);
        EXPECT_EQ(0u, natural.livePlayableCount);
        VnActionStepResult naturalPlay{};
        naturalPlay.structSize = sizeof(naturalPlay);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &naturalPlay));
        EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, naturalPlay.state);
        EXPECT_EQ(savedRoot, naturalPlay.producedPlayableInstance);
        EXPECT_FALSE(engine->playableInstances.Classify(savedRoot).live);
        EXPECT_EQ(0u, engine->voices.ActiveCount());
    }
}

TEST(ActionFiringApi, ImmediateSequenceQueueSameProgramTerminalPreparesWithoutAnotherVoice) {
    CheckImmediateSameProgramQueue(false, true);
}

TEST(ActionFiringApi, ImmediateSequenceQueueSameProgramCycleRestartPreparesOneNewVoice) {
    CheckImmediateSameProgramQueue(true);
}

void ExpectImmediateActionQueueTransitionPrepared(
    bool naturalEnd, bool compositeSource, bool compositeTarget, bool targetFade = true,
    std::uint32_t replayCount = 1u) {
    (void)Vn_Term();
    VnConfig config = harkentest::MakeNullConfig(8, 64, 48000);
    harkentest::EngineSession session(config);
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    std::vector<float> first(512, 0.25f);
    std::vector<float> second(512, -0.5f);
    const VnPCMDesc firstPcm = harkentest::MonoDesc(first, 48000);
    const VnPCMDesc secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK,
              Vn_RegisterPCM(CanonicalActionWorld::kSecondSound,
                             &secondPcm));
    CanonicalActionWorld image(
        engine->registry.Lookup(CanonicalActionWorld::kFirstSound)
            .contentRevision,
        engine->registry.Lookup(CanonicalActionWorld::kSecondSound)
            .contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    if (compositeSource) {
        image.MakeFirstQueueChildCompositeTrack();
    }
    if (compositeTarget) {
        image.MakeSecondQueueChildCompositeTrack();
    }
    if (naturalEnd) {
        image.EnableNaturalEndQueueTransition(64, targetFade ? 128u : 0u);
    } else {
        image.EnableImmediateQueueTransition(64, targetFade ? 128u : 0u);
    }
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    for (std::uint32_t replay = 0; replay < replayCount; ++replay) {
        VnPostActionDesc desc = ValidPostDesc();
        desc.actionId = image.actions[9].actionStableId;
        ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
        VnActionFiringHandle firing = 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));

        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        VnActionStepResult play{};
        play.structSize = sizeof(play);
        ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
        const auto row = std::find_if(
            engine->playableServices.begin(), engine->playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& candidate) {
                return candidate.rootInstance == play.producedPlayableInstance;
            });
        ASSERT_NE(engine->playableServices.end(), row);
        ASSERT_TRUE(row->queueContinuationPrepared);
        ASSERT_TRUE(row->queueTransition.Valid());
        const std::uint32_t expectedSourceCount = naturalEnd
            ? (compositeSource ? 2u : 1u)
            : 0u;
        const std::uint32_t expectedTargetCount = compositeTarget ? 2u : 1u;
        EXPECT_EQ(expectedSourceCount, row->queueSourceControlArmCount);
        EXPECT_EQ(expectedSourceCount + expectedTargetCount,
                  row->queueTransitionGroupArmCount);
        EXPECT_EQ(compositeTarget ? expectedTargetCount : 0u,
                  row->queueSuccessorScheduleLeafCount);
        EXPECT_EQ(info.acceptedLogicSequence, row->ticket);
        EXPECT_EQ(info.acceptedLogicSequence, row->queueTicket);
        harken::TransitionInstanceSnapshot transition{};
        ASSERT_TRUE(engine->transitionInstances.Capture(
            row->queueTransition, &transition));
        EXPECT_EQ(harken::TransitionAudibleGateState::Replaceable,
                  transition.state);
        harken::DecisionCommittedSnapshot decision{};
        EXPECT_TRUE(engine->decisions.IsOpen(row->queueDecision));
        EXPECT_FALSE(engine->decisions.CaptureCommitted(
            row->queueDecision, &decision));
        EXPECT_FALSE(row->queueDecisionCommitted);

        const std::size_t rowIndex = row->partition.slot;
        const std::size_t targetEventBase =
            row->queueSuccessorProgramPlane == 0
                ? engine->playableStorage.CurrentEventBase(rowIndex)
                : engine->playableStorage.PairedBase(rowIndex);
        auto& targetEvents = row->queueSuccessorProgramPlane == 0
            ? engine->playableScheduleEvents
            : engine->playableSuccessorEvents;
        auto& targetSchedules = row->queueSuccessorProgramPlane == 0
            ? engine->playableSchedules
            : engine->playableSuccessorSchedules;
        const std::size_t targetScheduleBase =
            row->queueSuccessorScheduleBase;
        for (std::uint32_t index = 0;
             index < (targetFade ? 2u : 1u) * expectedTargetCount; ++index) {
            EXPECT_EQ(info.acceptedLogicSequence,
                      targetEvents[targetEventBase + index].
                          logicCommitSequence);
        }
        for (std::uint32_t index = 0;
             index < expectedTargetCount; ++index) {
            EXPECT_EQ(info.acceptedLogicSequence,
                      targetSchedules[targetScheduleBase + index].
                          transactionId);
        }
        const std::uint32_t sourceEventsPerLeaf = naturalEnd ? 1u : 2u;
        EXPECT_EQ(sourceEventsPerLeaf * expectedSourceCount,
                  row->queueSourceSchedule.eventCount);
        for (std::uint32_t index = 0;
             index < row->queueSourceSchedule.eventCount; ++index) {
            EXPECT_EQ(info.acceptedLogicSequence,
                      row->queueSourceEvents[index].logicCommitSequence);
        }
        for (std::uint32_t index = 0;
             index < expectedSourceCount; ++index) {
            EXPECT_EQ(info.acceptedLogicSequence,
                      row->queueSourceSchedules[index].transactionId);
        }

        const std::array<std::uint64_t, 2> sliceFrames = {
            naturalEnd ? row->queueSourceSchedule.entryAnchorFrame
                       : row->queueCompletionFrame,
            row->queueCompletionFrame};
        const std::uint32_t expectedSliceCount = naturalEnd ? 2u : 1u;
        for (std::uint16_t sliceIndex = 0;
             sliceIndex < expectedSliceCount; ++sliceIndex) {
            harken::Plan03GroupSliceIdentity identity{};
            if (row->queueTimingPending) {
                std::array<harken::Plan03ImmediateLaneGroupDescriptor, 8> actualGroups{};
                const auto count = engine->timelinePool.CaptureImmediateLaneCohortGroups(
                    firing, actualGroups.data(), actualGroups.size());
                ASSERT_GT(count, 0u);
                ASSERT_LE(count, actualGroups.size());
                std::uint32_t matches = 0;
                for (std::size_t index = 0; index < count; ++index) {
                    const auto& candidate = actualGroups[index].identity;
                    harken::Plan03PageGroupView actual{};
                    if (candidate.sliceIndex != sliceIndex ||
                        !engine->timelinePool.ResolvePlan03GroupSliceProducer(candidate, &actual)) continue;
                    const bool decisionMatches =
                        (candidate.decision.slot == row->queueDecision.slot &&
                         candidate.decision.generation == row->queueDecision.generation) ||
                        (candidate.decision.slot == row->initialQueueEntryDecision.slot &&
                         candidate.decision.generation == row->initialQueueEntryDecision.generation);
                    if (!decisionMatches || actual.sourceControlCount != expectedSourceCount ||
                        actual.memberCount != expectedSourceCount + expectedTargetCount) continue;
                    identity = candidate;
                    ++matches;
                }
                ASSERT_EQ(1u, matches);
                EXPECT_EQ(harken::Plan03GroupBacking::ImmediateLane, identity.backing);
            } else {
                std::uint32_t page = 0;
                ASSERT_TRUE(engine->timelinePool.PageForFrame(sliceFrames[sliceIndex], &page));
                const auto* header = engine->timelinePool.Page(page);
                ASSERT_NE(nullptr, header);
                identity = {sliceFrames[sliceIndex] / engine->config.blockFrames,
                    header->pageGeneration, row->queueDecision, sliceIndex};
            }
            harken::Plan03PageGroupView slice{};
            ASSERT_TRUE(engine->timelinePool.ResolvePlan03GroupSliceProducer(
                identity, &slice));
            EXPECT_EQ(expectedSourceCount, slice.sourceControlCount);
            EXPECT_EQ(expectedSourceCount + expectedTargetCount,
                      slice.memberCount);
        }

        if (row->queueTimingPending) {
            std::ostringstream actualServiceTrace;
            actualServiceTrace << StaggeredCurrentActualCleanupDiagnostic(*engine, firing);
            for (std::uint32_t block = 0; block < 16u &&
                 row->phase == harken::EnginePlayableStartPhase::PendingImmediateEntry; ++block) {
                engine->nullBackend.Pump(1);
                actualServiceTrace << "\nAfter real audio: "
                    << StaggeredCurrentActualCleanupDiagnostic(*engine, firing);
                ASSERT_EQ(VN_OK, Vn_Update());
                actualServiceTrace << "\nAfter normal Update: "
                    << StaggeredCurrentActualCleanupDiagnostic(*engine, firing);
            }
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            actualServiceTrace << "\nPublic firing=" << info.state
                << " outcome=" << info.outcome << " reason=" << info.terminalReason;
            ASSERT_EQ(harken::EnginePlayableStartPhase::Filed, row->phase)
                << actualServiceTrace.str();
            ASSERT_TRUE(engine->transitionInstances.Capture(row->queueTransition, &transition));
        }
        while (engine->mixer.BlocksRendered() *
                   engine->config.blockFrames <= transition.audibleFrame) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
        }
        ASSERT_TRUE(engine->decisions.CaptureCommitted(
            row->queueDecision, &decision));
        EXPECT_TRUE(row->queueDecisionCommitted);
        EXPECT_EQ(naturalEnd ? 2u : 1u, decision.sliceCount);
        EXPECT_EQ(row->queueTransition.slot, decision.transitionGate.slot);
        EXPECT_EQ(row->queueTransition.generation,
                  decision.transitionGate.generation);

        std::ostringstream naturalEntryTrace;
        for (std::uint32_t index = 0; index < engine->immediateEntryAttemptCapacity; ++index) {
            const auto& attempt = engine->immediateEntryAttempts[index];
            if (attempt.root != firing || !attempt.queueContinuationCoordinator.Valid()) continue;
            const auto* activation = engine->decisions.ResolveFrontierActivation(attempt.queueContinuationCoordinator);
            harken::FrontierActivationReceipt receipt{};
            if (activation != nullptr && activation->Read(attempt.queueContinuationDescriptor.entry,
                    engine->mixer.BlocksRendered(), &receipt) == harken::FrontierReceiptRead::Ready)
                naturalEntryTrace << "\nC1 actual receipt outcome=" << static_cast<unsigned>(receipt.outcome)
                    << " reason=" << static_cast<unsigned>(receipt.reason)
                    << " member=" << receipt.failingMember << " sequence=" << receipt.audioSequence;
        }
        const auto targetStartFrame = row->queueCompletionFrame;
        bool heardTarget = false;
        for (std::uint32_t block = 0; block < 128; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            const auto completedBeforePump = engine->mixer.BlocksRendered();
            engine->nullBackend.Pump(1);
            ASSERT_EQ(completedBeforePump + 1u, engine->mixer.BlocksRendered());
            const auto* output = engine->nullBackend.LastBlock();
            ASSERT_NE(nullptr, output);
            heardTarget = heardTarget || (completedBeforePump * engine->config.blockFrames >= targetStartFrame && std::any_of(output,
                output + static_cast<std::size_t>(engine->nullBackend.BlockFrames()) * engine->nullBackend.Channels(),
                [](float sample) { return sample < -0.1f; }));
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) {
                break;
            }
        }
        std::ostringstream completedTrace;
        completedTrace << naturalEntryTrace.str() << '\n' << StaggeredCurrentActualCleanupDiagnostic(*engine, firing);
        completedTrace << "\nactual voices=" << engine->voices.ActiveCount()
            << " blocks=" << engine->mixer.BlocksRendered();
        harken::DecisionCommittedSnapshot completedDecision{};
        if (engine->decisions.CaptureCommitted(row->queueDecision, &completedDecision))
            completedTrace << " slices=" << completedDecision.sliceCount
                << " consumed=" << completedDecision.consumedSlices
                << " lastAudio=" << completedDecision.lastAudioSequence;
        std::array<harken::Plan03ImmediateLaneGroupDescriptor, 8> completedGroups{};
        const auto completedGroupCount = engine->timelinePool.CaptureImmediateLaneCohortGroups(
            firing, completedGroups.data(), completedGroups.size());
        for (std::size_t index = 0; index < completedGroupCount && index < completedGroups.size(); ++index) {
            harken::Plan03PageGroupView group{};
            if (engine->timelinePool.ResolvePlan03GroupSliceRt(completedGroups[index].identity, &group) && group.lease != nullptr) {
                const auto lease = group.lease->Capture();
                completedTrace << "\ngroup " << group.identity.decision.slot << '/' << group.identity.sliceIndex
                    << " lease=" << static_cast<unsigned>(lease.state);
            }
        }
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state) << completedTrace.str();
        EXPECT_EQ(VN_ACTION_OUTCOME_SUCCEEDED, info.outcome) << completedTrace.str();
        EXPECT_TRUE(heardTarget) << "Target PCM was not present in any freshly rendered block" << completedTrace.str();
        EXPECT_EQ(0u, info.livePlayableCount);
        EXPECT_EQ(0u, engine->voices.ActiveCount());
        EXPECT_EQ(0u, engine->queueInstances.LiveCount());
        EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        EXPECT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    }
}

