TEST(ActionFiringApi, GlobalResetCommitsExistingRandomSelectionMemory) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);

    const auto& program = engine->variables.ContainerProgramAt(0);
    harken::SelectionMemoryKeyV1 key{};
    key.world = engine->variables.CurrentWorldGeneration();
    key.containerStableId = program.containerStableId;
    key.programSemanticFingerprint = program.programSemanticFingerprint;
    key.memoryScope = harken::MemoryScopeV1::Global;
    harken::SelectionPlayRequestV1 selection{};
    selection.key = key;
    selection.program = &program;
    selection.worldSemanticFingerprint =
        engine->variables.CurrentWorldIdentity()->runtimeSemanticFingerprint;
    selection.rootStableId = program.containerStableId;
    selection.ticket = engine->logicCommits.Issue();
    selection.acceptedPostOrdinal = selection.ticket;
    const auto selected = engine->selectionMemory.AppendPlay(selection);
    ASSERT_EQ(harken::SelectionMemoryStatusV1::Ok, selected.status);
    ASSERT_EQ(harken::SelectionMemoryStatusV1::Ok,
              engine->selectionMemory.CommitHead(selected.delta));
    EXPECT_EQ(1u, engine->selectionMemory.Snapshot(key).selectionOrdinal);

    VnPostActionDesc desc = ValidPostDesc();
    desc.actionId = harkentest::ObjectId(47);
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    const auto reset = engine->selectionMemory.Snapshot(key);
    EXPECT_EQ(1u, reset.resetEpoch);
    EXPECT_EQ(0u, reset.selectionOrdinal);

    VnActionStepResult step{};
    step.structSize = sizeof(step);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &step));
    EXPECT_EQ(VN_ACTION_STEP_SUCCEEDED, step.state);
    EXPECT_EQ(VN_ACTION_OPCODE_RESET, step.opcode);
    EXPECT_EQ(program.containerStableId, step.targetStableId);
    EXPECT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
}

