TEST(ActionFiringApi,
     PreparationMatrixQueueInstanceResetConflictReturnsBackpressure) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig());
    ASSERT_EQ(VN_OK, session.InitResult());
    harken::Engine* engine = session.Engine();
    CanonicalActionWorld image;
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
              harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterHandle emitter = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&emitter));

    harken::QueueInstanceCreateRequest request{};
    request.world = engine->variables.CurrentWorldGeneration();
    request.rootInstance = 1;
    request.containerStableId = image.containers[2].containerStableId;
    request.programSemanticFingerprint =
        image.containers[2].programSemanticFingerprint;
    request.childCount = image.containers[2].childCount;
    request.resetEpoch = engine->variables.CurrentTransportEpoch();
    request.emitterSlot = static_cast<std::uint32_t>(emitter);
    request.emitterGeneration = static_cast<std::uint32_t>(emitter >> 32);
    request.initial.version = 1;
    request.initial.currentChildOrdinal =
        image.queueChildren[0].stableChildOrdinal;
    request.initial.selectionOrdinal = 1;
    request.resetInitial = request.initial;
    harken::QueueInstanceToken queue{};
    ASSERT_TRUE(engine->queueInstances.Acquire(request, &queue));
    harken::PreparedQueueResetSetV1 occupied{};
    ASSERT_EQ(harken::QueueResetStatusV1::Ok,
              engine->queueInstances.PrepareReset(
                  CanonicalQueueResetTarget(*engine, image, emitter),
                  &occupied));
    ASSERT_TRUE(occupied.Valid());
    harken::QueueInstanceSnapshot queueBefore{};
    ASSERT_TRUE(engine->queueInstances.Capture(queue, &queueBefore));
    const auto before = CaptureActionPreparationOwners(*engine);

    ExpectPublicActionPreparationRefusal(
        *engine, harkentest::ObjectId(49), emitter, VN_BACKPRESSURE, before);

    harken::QueueInstanceSnapshot queueAfter{};
    ASSERT_TRUE(engine->queueInstances.Capture(queue, &queueAfter));
    EXPECT_EQ(queueBefore.pendingVersion, queueAfter.pendingVersion);
    EXPECT_EQ(queueBefore.resetPending, queueAfter.resetPending);
    EXPECT_EQ(harken::QueueResetStatusV1::Ok,
              engine->queueInstances.CancelPreparedReset(&occupied));
    EXPECT_TRUE(engine->queueInstances.Release(queue));
}

