static void CheckNativeQueueOriginalLoansDuringRealPrivatePublicationRefusal(std::uint32_t refusedPublication,
    bool holdOriginalReader = false) {
    SCOPED_TRACE(refusedPublication);
    SCOPED_TRACE(holdOriginalReader);
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    std::vector<float> first(64, 0.25f), second(128, -0.25f);
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    MakeOriginalQueueCurrentTrackWith17FrameOffset(image);
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(engine, image.world).status);
    const auto ownersBefore = CaptureActionReclaimableOwners(engine);
    const auto sourceGenerationsBefore = CaptureSourceGenerations(engine);
    const auto sourcesBefore = CountStaggeredCurrentOriginalSourceOwners(engine);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    VnActionStepResult play{};
    play.structSize = sizeof(play);
    ASSERT_EQ(VN_OK, Vn_QueryActionStep(firing, 0, &play));
    auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
        [&](const auto& actual) { return actual.rootInstance == play.producedPlayableInstance; });
    ASSERT_NE(engine.playableServices.end(), row);
    ASSERT_TRUE(row->queueFirstContinuationLane);
    ASSERT_EQ(2u, row->queueCurrentScheduleLeafCount);
    ASSERT_EQ(1u, row->queueInitialCurrentDelayedCount);
    ASSERT_TRUE(row->queueSuccessorArm.Valid());
    ASSERT_NE(0u, row->queueSuccessorRenderHandle);
    const auto originalQueue = row->queueInstance;
    const auto originalComposite = row->queueCurrentCompositeOwner;
    const auto base = static_cast<std::size_t>(row->scheduleStorageBase);
    ASSERT_LT(base + 1u, engine.playableScheduleRenderHandles.size());
    struct Observation {
        VnActionFiringHandle firing = 0;
        harken::EnginePlayableServiceReference service{};
        std::array<harken::EngineTimelineVoiceInstallIdentity, 3> installs{};
        std::array<const harken::OriginalSourceSubmissionRegistry::Record*, 3> submissions{};
        std::uint32_t refused = 0;
        bool holdReader = false;
        bool called = false;
        harken::TimelineArmReaderPin foreignReader;
        harken::ImmediateLaneHandle lane{};
        std::uint64_t attemptGeneration = 0;
        harken::FrontierActivationDescriptor c0{};
        harken::FrontierActivationDescriptor c1{};
        std::array<harken::Plan03GroupSliceIdentity, 4> groups{};
        std::uint32_t groupCount = 0u;
    } observed;
    observed.firing = firing;
    observed.service = {row->identity, row->ownerInstance, row->ownerEpoch, row->invocationGeneration};
    observed.refused = refusedPublication;
    observed.holdReader = holdOriginalReader;

    harken::QueueInstanceTable::OriginalLifetimePin nativeQueueLoan;
    harken::EngineQueueProgramBank::OriginalLifetimePin nativeCurrentLoan, nativeSuccessorLoan;
    ASSERT_TRUE(engine.BorrowOriginalQueueLifetime(observed.service, &nativeQueueLoan));
    ASSERT_TRUE(engine.BorrowOriginalQueueCurrentBank(observed.service, &nativeCurrentLoan));
    ASSERT_TRUE(engine.BorrowOriginalQueueSuccessorBank(observed.service, &nativeSuccessorLoan));
    std::array<harken::Plan03ImmediateLaneGroupDescriptor, 4> nativeGroups{};
    ASSERT_EQ(4u, engine.timelinePool.CaptureLiveImmediateLaneCohortGroups(
        firing, nativeGroups.data(), nativeGroups.size()));
    std::array<harken::OriginalQueueFutureGroupLifetimePin, 2> nativeMemberLoans;
    std::size_t nativeMemberCount = 0;
    for (const auto& group : nativeGroups) {
        const auto decision = group.identity.decision;
        const bool initial = decision.slot == row->initialQueueEntryDecision.slot &&
            decision.generation == row->initialQueueEntryDecision.generation;
        const bool conditional = decision.slot == row->queueDecision.slot &&
            decision.generation == row->queueDecision.generation;
        if (!initial && !conditional) continue;
        ASSERT_LT(nativeMemberCount, nativeMemberLoans.size());
        ASSERT_TRUE(engine.BorrowOriginalQueueFutureGroup(observed.service, group.identity,
            &nativeMemberLoans[nativeMemberCount++]));
    }
    ASSERT_EQ(2u, nativeMemberCount);

    // The ORIGINAL publication loop emits successor first, then Current 0/1.
    const std::array<std::uint64_t, 3> publicationRenders{
        row->queueSuccessorRenderHandle,
        engine.playableScheduleRenderHandles[base],
        engine.playableScheduleRenderHandles[base + 1u]};
    for (std::size_t index = 0; index < observed.installs.size(); ++index) {
        ASSERT_TRUE(engine.CaptureTimelineVoiceInstallIdentity(publicationRenders[index], &observed.installs[index]));
        observed.submissions[index] = engine.originalSourceSubmissions.Find(observed.installs[index].startArm);
        ASSERT_NE(nullptr, observed.submissions[index]);
        EXPECT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(
            observed.installs[index].startArm, observed.submissions[index]->Token()));
        EXPECT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Published, observed.submissions[index]->State());
    }
    struct HookReturn {
        harken::Engine& engine;
        Observation& observation;
        ~HookReturn() {
            if (observation.foreignReader.Valid())
                EXPECT_TRUE(observation.foreignReader.Release(engine.mixer.BlocksRendered()));
            engine.forceImmediateQueueArmPublishFailureAtForTest = UINT32_MAX;
            engine.initialQueuePartialPublishAbortHookForTest = nullptr;
            engine.initialQueuePartialPublishAbortContextForTest = nullptr;
        }
    } hookReturn{engine, observed};
    engine.initialQueuePartialPublishAbortContextForTest = &observed;
    engine.initialQueuePartialPublishAbortHookForTest = +[](
        harken::Engine& actual, harken::EngineImmediateEntryAttempt& attempt, void* context) {
        auto& observation = *static_cast<Observation*>(context);
        if (attempt.root != observation.firing || observation.called) return;
        observation.called = true;
        EXPECT_EQ(UINT32_MAX, actual.forceImmediateQueueArmPublishFailureAtForTest);
        auto* retained = actual.ResolvePlayableService(observation.service);
        ASSERT_NE(nullptr, retained);
        ASSERT_TRUE(retained->queueFirstContinuationLane);
        ASSERT_EQ(1u, retained->queueInitialCurrentDelayedCount);
        for (std::size_t index = 0; index < observation.installs.size(); ++index) {
            const auto& installed = observation.installs[index];
            harken::TimelineArmObservation arm{};
            ASSERT_TRUE(actual.timelineArms.Observe(installed.startArm, &arm));
            EXPECT_EQ(index < observation.refused ? harken::ArmState::Published : harken::ArmState::Armed, arm.state);
            EXPECT_GT(arm.armedCompletionSequence, 0u);
            EXPECT_EQ(0u, arm.startedBlockSequence);
            EXPECT_FALSE(actual.voices.ReleaseObserved(installed.releaseObserver));
        }
        observation.lane = attempt.lane;
        observation.attemptGeneration = attempt.generation;
        observation.c0 = attempt.initialQueueDescriptor;
        observation.c1 = attempt.queueContinuationDescriptor;
        ASSERT_TRUE(observation.c0.Valid());
        ASSERT_TRUE(observation.c1.Valid());
        EXPECT_EQ(2u, observation.c0.expectedEntryEventCount);
        EXPECT_EQ(observation.c0.order.executeFrame + 145u, observation.c1.order.executeFrame);
        harken::CompositeCompletionOwnerInfo currentCompletion{};
        ASSERT_TRUE(actual.compositeCompletionOwners.Capture(retained->queueCurrentCompositeOwner, &currentCompletion));
        EXPECT_EQ(observation.c1.order.executeFrame, currentCompletion.absoluteLogicalCompleteFrame);
        for (std::uint32_t leaf = 0; leaf < 2u; ++leaf) {
            harken::EngineTimelineVoiceInstallIdentity currentInstall{};
            ASSERT_TRUE(actual.CaptureTimelineVoiceInstallIdentity(observation.installs[leaf + 1u].renderHandle, &currentInstall));
            EXPECT_TRUE(harken::OriginalSourceSubmissionRegistry::SameToken(
                currentInstall.startArm, observation.installs[leaf + 1u].startArm));
            EXPECT_EQ(observation.c0.order.executeFrame + (leaf == 0u ? 0u : 17u), currentInstall.onsetFrame);
        }
        observation.groupCount = actual.immediateActionLane.PrivatePinGroupCount(attempt.lane);
        ASSERT_EQ(4u, observation.groupCount);
        std::uint32_t conditionals = 0u;
        for (std::uint32_t index = 0; index < observation.groupCount; ++index) {
            ASSERT_TRUE(actual.immediateActionLane.CapturePrivatePinGroup(attempt.lane,
                index, &observation.groups[index]));
            harken::Plan03PageGroupView group{};
            ASSERT_TRUE(actual.timelinePool.ResolvePlan03GroupSliceProducer(observation.groups[index], &group));
            ASSERT_NE(nullptr, group.frontier);
            ASSERT_NE(nullptr, group.lease);
            EXPECT_EQ(harken::AudioSliceState::Ready, group.lease->Capture().state);
            conditionals += group.frontier->queueConditional.Valid() ? 1u : 0u;
        }
        EXPECT_EQ(1u, conditionals);
        if (observation.holdReader) {
            ASSERT_EQ(1u, observation.refused);
            const auto delayed = observation.installs[2].startArm;
            const auto* original = actual.timelineArms.RowAt(delayed.slot);
            ASSERT_NE(nullptr, original);
            const auto before = original->frontierReaderPins.load(std::memory_order_acquire);
            ASSERT_GT(before, 0u);
            ASSERT_TRUE(actual.timelineArms.PinFrontierReader(delayed, &observation.foreignReader));
            EXPECT_EQ(before + 1u, original->frontierReaderPins.load(std::memory_order_acquire));
        }
    };
    engine.forceImmediateQueueArmPublishFailureAtForTest = refusedPublication;
    const auto beforeAck = engine.mixer.BlocksRendered();
    engine.nullBackend.Pump(2);
    ASSERT_EQ(beforeAck + 2u, engine.mixer.BlocksRendered());
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_TRUE(observed.called);
    EXPECT_EQ(UINT32_MAX, engine.forceImmediateQueueArmPublishFailureAtForTest);
    EXPECT_FALSE(engine.runtimeRecreateRequired);
    const auto expectOriginalNoWork = [&]() {
        for (const auto& installed : observed.installs) {
            harken::TimelineArmObservation original{};
            if (engine.timelineArms.Observe(installed.startArm, &original))
                EXPECT_EQ(0u, original.startedBlockSequence);
        }
        // LastBlock follows this helper's real Pump, never a cached publication.
        const auto* output = engine.nullBackend.LastBlock();
        ASSERT_NE(nullptr, output);
        EXPECT_FALSE(std::any_of(output, output + static_cast<std::size_t>(engine.nullBackend.BlockFrames()) *
                engine.nullBackend.Channels(),
            [](float sample) { return std::abs(sample) > 0.01f; }));
    };
    ASSERT_NO_FATAL_FAILURE(expectOriginalNoWork());
    if (holdOriginalReader) {
        ASSERT_TRUE(observed.foreignReader.Valid());
        const auto sequenceWhileHeld = engine.mixer.BlocksRendered();
        const auto assertActualOriginalRetained = [&]() {
            const auto* attempt = std::find_if(engine.immediateEntryAttempts.get(),
                engine.immediateEntryAttempts.get() + engine.immediateEntryAttemptCapacity,
                [&](const auto& actual) { return actual.active && actual.root == firing &&
                    actual.generation == observed.attemptGeneration; });
            ASSERT_NE(engine.immediateEntryAttempts.get() + engine.immediateEntryAttemptCapacity, attempt);
            EXPECT_EQ(observed.lane.slot, attempt->lane.slot);
            EXPECT_EQ(observed.lane.generation, attempt->lane.generation);
            EXPECT_EQ(harken::InitialQueuePrivateCleanupPhase::RootReaders, attempt->privateCleanupPhase);
            EXPECT_TRUE(engine.immediateActionLane.OwnsNeverCommitted(attempt->lane, firing));
            EXPECT_EQ(4u, engine.immediateActionLane.PrivatePinGroupCount(attempt->lane));
            for (std::uint32_t index = 0; index < observed.groupCount; ++index) {
                harken::Plan03GroupSliceIdentity unchanged{};
                ASSERT_TRUE(engine.immediateActionLane.CapturePrivatePinGroup(attempt->lane, index, &unchanged));
                EXPECT_EQ(observed.groups[index], unchanged);
                harken::Plan03PageGroupView group{};
                ASSERT_TRUE(engine.timelinePool.ResolvePlan03GroupSliceProducer(unchanged, &group));
                ASSERT_NE(nullptr, group.lease);
                EXPECT_EQ(harken::AudioSliceState::Ready, group.lease->Capture().state);
            }
            const auto* c0 = engine.decisions.ResolveFrontierActivation(observed.c0.entry.coordinator);
            const auto* c1 = engine.decisions.ResolveFrontierActivation(observed.c1.entry.coordinator);
            ASSERT_NE(nullptr, c0);
            ASSERT_NE(nullptr, c1);
            EXPECT_EQ(harken::FrontierReceiptState::Prepared, c0->State());
            EXPECT_EQ(harken::FrontierReceiptState::Prepared, c1->State());
            EXPECT_EQ(observed.c0.entry, c0->Descriptor().entry);
            EXPECT_EQ(observed.c1.entry, c1->Descriptor().entry);
            EXPECT_EQ(observed.c0.order, c0->Descriptor().order);
            EXPECT_EQ(observed.c1.order, c1->Descriptor().order);
            const auto delayed = observed.installs[2].startArm;
            const auto* native = engine.timelineArms.RowAt(delayed.slot);
            ASSERT_NE(nullptr, native);
            EXPECT_EQ(delayed.generation, native->generation);
            EXPECT_EQ(delayed.renderSlot, native->renderSlot);
            EXPECT_EQ(delayed.renderGeneration, native->renderGeneration);
            EXPECT_EQ(1u, native->frontierReaderPins.load(std::memory_order_acquire));
            EXPECT_TRUE(native->nativePrivateWithdrawn.load(std::memory_order_acquire));
            EXPECT_TRUE(native->frontierAdmissionFinished.load(std::memory_order_acquire));
            EXPECT_EQ(nullptr, native->frontierActiveLease.load(std::memory_order_acquire));
            EXPECT_FALSE(engine.initialFrontierArmPins[delayed.slot].pin.Valid());
            harken::TimelineArmObservation withdrawn{};
            ASSERT_TRUE(engine.timelineArms.Observe(delayed, &withdrawn));
            EXPECT_EQ(harken::ArmState::CancelRequested, withdrawn.state);
            EXPECT_EQ(0u, withdrawn.startedBlockSequence);
            EXPECT_EQ(0u, withdrawn.tombstoneAudioSequence);
        };
        ASSERT_NO_FATAL_FAILURE(assertActualOriginalRetained());
        const auto delayed = observed.installs[2].startArm;
        EXPECT_FALSE(engine.timelineArms.ClaimAudioSlice(delayed));
        engine.timelineArms.ApplyClaimedAudioSlice(delayed);
        EXPECT_FALSE(engine.timelineArms.Start(delayed, sequenceWhileHeld));
        ASSERT_NO_FATAL_FAILURE(assertActualOriginalRetained());
        for (std::uint32_t retry = 0; retry < 2u; ++retry) {
            ASSERT_EQ(VN_OK, Vn_Update());
            EXPECT_EQ(sequenceWhileHeld, engine.mixer.BlocksRendered());
            ASSERT_NO_FATAL_FAILURE(assertActualOriginalRetained());
        }

        EXPECT_TRUE(nativeQueueLoan.Valid());
        EXPECT_TRUE(nativeCurrentLoan.Valid());
        EXPECT_TRUE(nativeSuccessorLoan.Valid());
        for (auto& loan : nativeMemberLoans) { EXPECT_TRUE(loan.Valid()); loan.Release(); }
        nativeQueueLoan.Release();
        nativeCurrentLoan.Release();
        nativeSuccessorLoan.Release();
        // Native storage baselines remain; only these actual external loans returned.

        ASSERT_TRUE(observed.foreignReader.Release(sequenceWhileHeld));
        EXPECT_FALSE(observed.foreignReader.Valid());
    }
    VnActionFiringInfo info{};
    info.structSize = sizeof(info);
    for (std::uint32_t block = 0; block < 192u; ++block) {
        ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
        if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        const auto callbackBefore = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(callbackBefore + 1u, engine.mixer.BlocksRendered());
        ASSERT_NO_FATAL_FAILURE(expectOriginalNoWork());
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine.runtimeRecreateRequired);
    }
    ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state)
        << NativeQueueOriginalLoanCleanupDiagnostic(engine, firing);
    EXPECT_EQ(0u, info.livePlayableCount);
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    for (std::uint32_t block = 0; block < 192u &&
         CaptureActionReclaimableOwners(engine) != ownersBefore; ++block) {
        const auto callbackBefore = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(callbackBefore + 1u, engine.mixer.BlocksRendered());
        ASSERT_NO_FATAL_FAILURE(expectOriginalNoWork());
        ASSERT_EQ(VN_OK, Vn_Update());
        EXPECT_FALSE(engine.runtimeRecreateRequired);
    }
    ASSERT_NO_FATAL_FAILURE(ExpectStaggeredCurrentOriginalTailReleased(engine,
        ownersBefore, sourceGenerationsBefore, sourcesBefore, observed.installs,
        observed.submissions, originalQueue, originalComposite, 1u));
}


TEST(ActionFiringApi, NativeQueueOriginalLoansReturnThroughRealPrivatePartialPublicationAbort) {
    CheckNativeQueueOriginalLoansDuringRealPrivatePublicationRefusal(1u, true);
}

static void CheckQueueSourceFactoryStaging(bool composite, bool joinedTerm, bool retainComposite = false,
    bool retainCompositeLedger = false, bool retainOccurrences = false, bool retainPreparedLeaf = false,
    bool retainDecisions = false, bool retainTrees = false) {
    (void)Vn_Term();
    std::vector<float> first(512, 0.25f), second(512, 0.125f);
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto firstPcm = harkentest::MonoDesc(first, 48000);
    const auto secondPcm = harkentest::MonoDesc(second, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &firstPcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &secondPcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    if (composite) image.MakeFirstQueueChildCompositeTrack();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(engine, image.world).status);
    const auto owners = CaptureActionReclaimableOwners(engine);
    struct FactoryObservation {
        std::array<const harken::Engine::OriginalQueueSourcePreparationHolder*, 4> originals{};
        std::uint32_t count = 0;
        std::uint32_t head = 0;
        std::uint64_t block = 0;
        bool composite = false;
        const harken::EngineOriginalCompositeCompletionPreparation* compositeOriginal = nullptr;
        harken::CompositeCompletionOwnerPool::OriginalLifetimePin compositeLoan;
        harken::OccurrenceStatePool::OriginalCompositeCompletionOwnerPin compositeLeafLoan;
        harken::CompositeCompletionOwnerToken compositeToken{};
        std::uint32_t compositeFactoryCount = 0;
        std::array<harken::VoiceLedger::OriginalCompositeCompletionMutationOwner, 2> ledgerLoans;
        std::array<harken::VoiceLedger::PreparedCommitInput, 2> ledgerInputs{};
        std::array<const harken::EngineOriginalOccurrencePreparation*, 8> occurrenceOriginals{};
        std::array<harken::OccurrenceStatePool::OriginalStoragePin, 8> occurrenceLoans;
        std::array<harken::OccurrenceKey, 8> occurrenceKeys{};
        std::uint32_t occurrenceCount = 0;
        std::uint32_t preparedLeafFactoryCount = 0;
        std::array<harken::OriginalDecisionLifetimePin, 16> decisionLoans;
        std::array<harken::DecisionReserveRequest, 16> decisionRequests{};
        std::array<harken::DecisionToken, 16> decisionTokens{};
        std::uint32_t decisionCount = 0;
        std::array<harken::PlayableInstanceTable::OriginalLifetimePin, 16> playableLoans;
        std::array<harken::PlayableInstanceHandle, 16> playableHandles{};
        std::array<harken::PlayableInstanceHandle, 16> playableParents{};
        std::array<std::uint64_t, 16> playableEpochs{};
        std::uint32_t playableCount = 0, treeFactoryCount = 0;
    } observation;
    observation.head = engine.commands.PublishedHead();
    observation.block = engine.mixer.BlocksRendered();
    observation.composite = composite;
    if (retainTrees) {
        ASSERT_TRUE(retainComposite && retainOccurrences);
        engine.originalPlayableTreePreparationContextForTest = &observation;
        engine.originalPlayableTreePreparationHookForTest = [](
            harken::Engine& actual, harken::PlayableTreeExecutor& tree, void* context) {
            auto& seen = *static_cast<FactoryObservation*>(context);
            ASSERT_EQ(0u, seen.treeFactoryCount++);
            EXPECT_EQ(seen.head, actual.commands.PublishedHead());
            EXPECT_EQ(seen.block, actual.mixer.BlocksRendered());
            EXPECT_FALSE(actual.originalInitialSingleQueueOriginProducerEnabled);
            ASSERT_TRUE(actual.preparedVoiceCommandBatchProof.Valid());
            const auto* proof = tree.OriginalPreparedParentLinks(actual.playableInstances);
            ASSERT_NE(nullptr, proof);
            ASSERT_NE(nullptr, seen.compositeOriginal);
            ASSERT_EQ(2u, seen.count);
            const auto root = seen.originals[0]->OriginalCompositeLedgerInput().parent.internalToken;
            ASSERT_NE(0u, root);
            for (const auto& original : actual.originalPlayableLifetimeHolders) {
                if (!original.Valid() || !actual.playableInstances.MatchesPreparedOriginalAncestry(
                        *proof, original.OriginalHandle(), root)) continue;
                const auto index = seen.playableCount;
                ASSERT_LT(index, seen.playableLoans.size());
                ASSERT_TRUE(actual.playableInstances.IsOriginalLifetimePinFor(original, original.OriginalHandle()));
                ASSERT_TRUE(original.Borrow(&seen.playableLoans[index]));
                seen.playableHandles[index] = original.OriginalHandle();
                seen.playableParents[index] = original.OriginalParent();
                seen.playableEpochs[index] = original.OriginalScheduleEpoch();
                ++seen.playableCount;
            }
            ASSERT_GT(seen.playableCount, 0u);
            harken::CompositeCompletionOwnerInfo aggregate{};
            ASSERT_TRUE(actual.compositeCompletionOwners.CaptureOriginal(
                seen.compositeOriginal->OriginalOwner(), &aggregate));
            for (std::uint32_t index = 0; index < aggregate.leafCount; ++index) {
                harken::KnownScheduleLeafV1 leaf{};
                ASSERT_TRUE(actual.compositeCompletionOwners.CaptureOriginalLeaf(
                    seen.compositeOriginal->OriginalOwner(), index, &leaf));
                const auto found = std::find_if(seen.occurrenceOriginals.begin(),
                    seen.occurrenceOriginals.begin() + seen.occurrenceCount,
                    [&](const auto* original) { return original != nullptr &&
                        original->OriginalToken().slot == leaf.occurrence.slot &&
                        original->OriginalToken().generation == leaf.occurrence.generation; });
                ASSERT_NE(seen.occurrenceOriginals.begin() + seen.occurrenceCount, found);
                harken::OccurrenceKey key{};
                ASSERT_TRUE((*found)->OriginalStorage().CaptureOriginalKey(&key));
                EXPECT_TRUE(actual.playableInstances.MatchesPreparedOriginalAncestry(
                    *proof, key.arrangingInstance, root));
                EXPECT_EQ(root, seen.originals[index]->OriginalCompositeLedgerInput().parent.internalToken);
                EXPECT_EQ(nullptr, actual.OriginalSinglePreparationForArm(seen.originals[index]->OriginalArm()));
            }
        };
    }
    if (retainDecisions) {
        engine.originalQueueDecisionPreparationContextForTest = &observation;
        engine.originalQueueDecisionPreparationHookForTest = [](
            harken::Engine& actual, const harken::PreparedDecisionReservation& prepared,
            const harken::OriginalDecisionLifetimePin& original, void* context) {
            auto& seen = *static_cast<FactoryObservation*>(context);
            const auto index = seen.decisionCount;
            ASSERT_LT(index, seen.decisionLoans.size());
            EXPECT_EQ(seen.head, actual.commands.PublishedHead());
            EXPECT_EQ(seen.block, actual.mixer.BlocksRendered());
            EXPECT_FALSE(actual.originalInitialSingleQueueOriginProducerEnabled);
            ASSERT_TRUE(actual.decisions.MatchesOriginalPreparedDecision(original, prepared));
            ASSERT_TRUE(actual.decisions.MatchesOriginalDecisionFactory(original, prepared.OriginalRequest()));
            EXPECT_EQ(&actual.decisions, original.Owner());
            ASSERT_LT(prepared.Token().slot, actual.originalSingleDecisionBaselines.size());
            EXPECT_EQ(&original, &actual.originalSingleDecisionBaselines[prepared.Token().slot]);
            ASSERT_TRUE(original.Borrow(&seen.decisionLoans[index]));
            EXPECT_FALSE(original.Borrow(&seen.decisionLoans[index]));
            seen.decisionRequests[index] = prepared.OriginalRequest();
            seen.decisionTokens[index] = prepared.Token();
            ++seen.decisionCount;
        };
    }
    engine.originalQueueSourcePreparationContextForTest = &observation;
    engine.originalQueueSourcePreparationHookForTest = [](
        harken::Engine& actual, const harken::Engine::OriginalQueueSourcePreparationHolder& original,
        void* context) {
        auto& seen = *static_cast<FactoryObservation*>(context);
        ASSERT_LT(seen.count, seen.originals.size());
        EXPECT_EQ(seen.head, actual.commands.PublishedHead());
        EXPECT_EQ(seen.block, actual.mixer.BlocksRendered());
        ASSERT_TRUE(original.OriginalSource().Valid());
        ASSERT_TRUE(original.OriginalBody().Valid());
        EXPECT_TRUE(actual.originalSourceSubmissions.IsOriginalSourceLifetimePinFor(
            original.OriginalSource(), original.OriginalArm()));
        EXPECT_TRUE(actual.voices.IsOriginalSourceBodyLifetimePinFor(
            original.OriginalBody(), original.OriginalArm(), original.OriginalSourceIdentity()));
        const auto* single = actual.OriginalSinglePreparationForArm(original.OriginalArm());
        if (seen.composite) EXPECT_EQ(nullptr, single);
        else ASSERT_NE(nullptr, single);
        seen.originals[seen.count++] = &original;
    };
    if (retainOccurrences) {
        ASSERT_TRUE(composite);
        engine.originalOccurrencePreparationContextForTest = &observation;
        engine.originalOccurrencePreparationHookForTest = [](
            harken::Engine& actual, const harken::EngineOriginalOccurrencePreparation& original, void* context) {
            auto& seen = *static_cast<FactoryObservation*>(context);
            const auto index = seen.occurrenceCount;
            ASSERT_LT(index, seen.occurrenceLoans.size());
            EXPECT_EQ(seen.head, actual.commands.PublishedHead());
            EXPECT_EQ(seen.block, actual.mixer.BlocksRendered());
            ASSERT_TRUE(actual.timelineOccurrences.IsOriginalStoragePinFor(original.OriginalStorage(), original.OriginalToken()));
            EXPECT_FALSE(original.OriginalStorage().NativeEnded());
            ASSERT_TRUE(original.OriginalStorage().CaptureOriginalKey(&seen.occurrenceKeys[index]));
            ASSERT_TRUE(original.OriginalStorage().Borrow(&seen.occurrenceLoans[index]));
            seen.occurrenceOriginals[index] = &original;
            ++seen.occurrenceCount;
        };
    }
    if (retainComposite) {
        ASSERT_TRUE(composite);
        engine.originalCompositePreparationContextForTest = &observation;
        engine.originalCompositePreparationHookForTest = [](
            harken::Engine& actual, const harken::EngineOriginalCompositeCompletionPreparation& original,
            void* context) {
            auto& seen = *static_cast<FactoryObservation*>(context);
            ASSERT_EQ(0u, seen.compositeFactoryCount);
            ++seen.compositeFactoryCount;
            EXPECT_EQ(seen.head, actual.commands.PublishedHead());
            EXPECT_EQ(seen.block, actual.mixer.BlocksRendered());
            EXPECT_FALSE(actual.originalInitialSingleQueueOriginProducerEnabled);
            ASSERT_TRUE(actual.compositeCompletionOwners.IsOriginalLifetimePinFor(
                original.OriginalOwner(), original.OriginalToken()));
            EXPECT_FALSE(actual.compositeCompletionOwners.IsOriginalLifetimePinned(original.OriginalOwner()));
            harken::CompositeCompletionOwnerInfo prepared{};
            ASSERT_TRUE(actual.compositeCompletionOwners.CaptureOriginal(original.OriginalOwner(), &prepared));
            ASSERT_EQ(2u, prepared.leafCount);
            EXPECT_EQ(1u, prepared.aggregateRevision);
            ASSERT_TRUE(original.OriginalOwner().Borrow(&seen.compositeLoan));
            seen.compositeOriginal = &original;
            seen.compositeToken = original.OriginalToken();
        };
    }
    if (retainPreparedLeaf) {
        ASSERT_TRUE(retainComposite);
        engine.originalCompositeLeafPreparationContextForTest = &observation;
        engine.originalCompositeLeafPreparationHookForTest = [](
            harken::Engine& actual, const harken::EngineOriginalCompositeCompletionPreparation& original, void* context) {
            auto& seen = *static_cast<FactoryObservation*>(context);
            ASSERT_EQ(0u, seen.preparedLeafFactoryCount++);
            EXPECT_EQ(seen.head, actual.commands.PublishedHead());
            EXPECT_EQ(seen.block, actual.mixer.BlocksRendered());
            EXPECT_EQ(seen.compositeOriginal, &original);
            EXPECT_FALSE(actual.compositeCompletionOwners.IsOriginalLifetimePinned(original.OriginalOwner()));
            harken::CompositeCompletionOwnerInfo row{};
            ASSERT_TRUE(actual.compositeCompletionOwners.CapturePrepared(original.OriginalToken(), &row));
            ASSERT_EQ(2u, row.leafCount);
            for (std::uint32_t i = 0; i < row.leafCount; ++i) {
                harken::KnownScheduleLeafV1 leaf{};
                ASSERT_TRUE(actual.compositeCompletionOwners.CapturePreparedLeaf(original.OriginalToken(), i, &leaf));
                auto* held = actual.compositeCompletionOwners.ResolveOriginalPreparedLeafCommit(actual.timelineOccurrences, leaf.occurrence);
                ASSERT_NE(nullptr, held);
                EXPECT_TRUE(actual.timelineOccurrences.IsPreparedCompositeCompletionCommitFor(*held, leaf.occurrence));
                ASSERT_LT(i, seen.count);
                const auto& ledger = seen.originals[i]->OriginalCompositeLedgerInput();
                EXPECT_TRUE(harken::SameCompletionOwner(leaf.predicate.owner, ledger.completionMutation.owner));
                EXPECT_EQ(leaf.occurrence.slot, ledger.completionMutation.occurrence.slot);
                EXPECT_EQ(leaf.occurrence.generation, ledger.completionMutation.occurrence.generation);
                EXPECT_TRUE(seen.originals[i]->OriginalSource().Valid());
                EXPECT_TRUE(seen.originals[i]->OriginalBody().Valid());
                EXPECT_TRUE(seen.originals[i]->OriginalCompositeLedger().Valid());
            }
            ASSERT_TRUE(actual.compositeCompletionOwners.BorrowOriginalPreparedLeafCompletion(original.OriginalOwner(), 0, &seen.compositeLeafLoan));
        };
    }
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
    engine.originalPlayableTreePreparationHookForTest = nullptr;
    engine.originalPlayableTreePreparationContextForTest = nullptr;
    engine.originalQueueDecisionPreparationHookForTest = nullptr;
    engine.originalQueueDecisionPreparationContextForTest = nullptr;
    engine.originalCompositeLeafPreparationHookForTest = nullptr;
    engine.originalCompositeLeafPreparationContextForTest = nullptr;
    engine.originalOccurrencePreparationHookForTest = nullptr;
    engine.originalOccurrencePreparationContextForTest = nullptr;
    engine.originalCompositePreparationHookForTest = nullptr;
    engine.originalCompositePreparationContextForTest = nullptr;
    engine.originalQueueSourcePreparationHookForTest = nullptr;
    engine.originalQueueSourcePreparationContextForTest = nullptr;
    ASSERT_NE(0u, firing);
    ASSERT_EQ(composite ? 2u : 1u, observation.count);
    if (retainTrees) {
        ASSERT_EQ(1u, observation.treeFactoryCount);
        ASSERT_GT(observation.playableCount, 0u);
    }
    if (retainComposite) {
        ASSERT_EQ(1u, observation.compositeFactoryCount);
        ASSERT_NE(nullptr, observation.compositeOriginal);
        EXPECT_TRUE(engine.compositeCompletionOwners.IsOriginalLifetimePinned(observation.compositeLoan));
        if (retainPreparedLeaf) {
            ASSERT_EQ(1u, observation.preparedLeafFactoryCount);
            ASSERT_TRUE(observation.compositeLeafLoan.Valid());
        } else {
            ASSERT_TRUE(engine.compositeCompletionOwners.BorrowOriginalLeafCompletion(
                observation.compositeLoan, 0, &observation.compositeLeafLoan));
        }
    }
    if (retainOccurrences) {
        harken::CompositeCompletionOwnerInfo actual{};
        ASSERT_TRUE(engine.compositeCompletionOwners.CaptureOriginal(observation.compositeLoan, &actual));
        const auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& value) {
                return value.queueCurrentCompositeOwner.slot == observation.compositeToken.slot &&
                    value.queueCurrentCompositeOwner.generation == observation.compositeToken.generation;
            });
        ASSERT_NE(engine.playableServices.end(), row);
        ASSERT_NE(0u, row->queueSuccessorOccurrence.generation);
        // The real prepare also reserves the next Sound occurrence separately.
        ASSERT_EQ(actual.leafCount + 2u, observation.occurrenceCount);
        std::uint32_t aggregates = 0, leaves = 0, successors = 0;
        for (std::uint32_t index = 0; index < observation.occurrenceCount; ++index) {
            const auto token = observation.occurrenceLoans[index].OriginalToken();
            if (token.slot == actual.composedOccurrence.slot && token.generation == actual.composedOccurrence.generation) ++aggregates;
            if (token.slot == row->queueSuccessorOccurrence.slot && token.generation == row->queueSuccessorOccurrence.generation) {
                ++successors;
                EXPECT_EQ(CanonicalActionWorld::kSecondSound, observation.occurrenceKeys[index].clipId);
                EXPECT_EQ(row->rootInstance, observation.occurrenceKeys[index].arrangingInstance);
            }
            for (std::uint32_t ordinal = 0; ordinal < actual.leafCount; ++ordinal) {
                harken::KnownScheduleLeafV1 leaf{};
                ASSERT_TRUE(engine.compositeCompletionOwners.CaptureLeaf(observation.compositeToken, ordinal, &leaf));
                if (token.slot == leaf.occurrence.slot && token.generation == leaf.occurrence.generation) ++leaves;
            }
        }
        EXPECT_EQ(1u, aggregates);
        EXPECT_EQ(2u, leaves);
        EXPECT_EQ(1u, successors);
    }
    if (retainDecisions) {
        ASSERT_GE(observation.decisionCount, 2u);
        const auto row = std::find_if(engine.playableServices.begin(), engine.playableServices.end(),
            [&](const harken::EnginePlayableServiceRow& value) {
                return value.queueMode && value.pendingImmediateCohortRoot != 0 &&
                    (!composite || (value.queueCurrentCompositeOwner.slot == observation.compositeToken.slot &&
                        value.queueCurrentCompositeOwner.generation == observation.compositeToken.generation));
            });
        ASSERT_NE(engine.playableServices.end(), row);
        std::uint32_t currentMatches = 0, successorMatches = 0;
        for (std::uint32_t index = 0; index < observation.decisionCount; ++index) {
            const auto token = observation.decisionTokens[index];
            EXPECT_TRUE(engine.decisions.MatchesOriginalDecisionFactory(
                observation.decisionLoans[index], observation.decisionRequests[index]));
            if (token.slot == row->queueDecision.slot && token.generation == row->queueDecision.generation) ++currentMatches;
            if (row->queueSuccessorDecision.Valid() && token.slot == row->queueSuccessorDecision.slot &&
                token.generation == row->queueSuccessorDecision.generation) ++successorMatches;
        }
        EXPECT_EQ(1u, currentMatches);
        EXPECT_EQ(row->queueSuccessorDecision.Valid() ? 1u : 0u, successorMatches);
    }
    if (retainCompositeLedger) {
        ASSERT_TRUE(composite);
        ASSERT_EQ(2u, observation.count);
        for (std::uint32_t index = 0; index < observation.count; ++index) {
            const auto* actual = observation.originals[index];
            ASSERT_NE(nullptr, actual);
            ASSERT_TRUE(actual->OriginalCompositeLedger().Valid());
            observation.ledgerInputs[index] = actual->OriginalCompositeLedgerInput();
            const auto& input = observation.ledgerInputs[index];
            ASSERT_TRUE(engine.ledger.IsOriginalCompositeCompletionMutationOwnerFor(
                actual->OriginalCompositeLedger(), input.identity, input.parent,
                input.renderHandle, input.completionMutation));
            ASSERT_TRUE(actual->OriginalCompositeLedger().Borrow(&observation.ledgerLoans[index]));
            EXPECT_TRUE(engine.ledger.IsCurrentOriginalCompositeCompletionMutationOwner(observation.ledgerLoans[index]));
            EXPECT_FALSE(engine.ledger.HasOriginalCompositeCompletionNativeEnd(observation.ledgerLoans[index]));
        }
    }
    ASSERT_EQ(observation.block, engine.mixer.BlocksRendered());
    ASSERT_GT(engine.commands.PublishedHead(), observation.head);
    const auto* original = observation.originals[0];
    ASSERT_NE(nullptr, original);
    const auto arm = original->OriginalArm();
    const auto render = original->OriginalSourceIdentity();
    ASSERT_EQ(original, engine.OriginalQueueSourcePreparationForArm(arm));
    const auto* source = engine.originalSourceSubmissions.Find(arm);
    ASSERT_NE(nullptr, source);
    ASSERT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Published, source->State());
    harken::VoiceReleaseObserver physicalRelease{};
    ASSERT_TRUE(engine.voices.CaptureReleaseObserver(render, &physicalRelease));
    harken::PreparedSingleCurrentOriginBundle::SourcePin sourceLoan;
    harken::PreparedSingleCurrentOriginBundle::BodyPin bodyLoan;
    ASSERT_TRUE(original->OriginalSource().Borrow(&sourceLoan));
    ASSERT_TRUE(original->OriginalBody().Borrow(&bodyLoan));
    EXPECT_FALSE(original->OriginalSource().Borrow(&sourceLoan));
    EXPECT_FALSE(original->OriginalBody().Borrow(&bodyLoan));
    EXPECT_FALSE(engine.ReturnOriginalQueueSourcePreparationAfterPhysicalRelease(arm));
    if (!composite) {
        const auto* single = engine.OriginalSinglePreparationForArm(arm);
        ASSERT_NE(nullptr, single);
        EXPECT_TRUE(single->OriginalSource().Valid());
        EXPECT_TRUE(single->OriginalBody().Valid());
        EXPECT_TRUE(single->OriginalLedger().Valid());
    }
    if (joinedTerm) {
        for (auto& loan : observation.playableLoans) loan.Release();
        for (auto& loan : observation.decisionLoans) EXPECT_TRUE(loan.Release());
        for (auto& loan : observation.occurrenceLoans) loan.Release();
        for (auto& loan : observation.ledgerLoans) loan.Release();
        observation.compositeLeafLoan.Release();
        observation.compositeLoan.Release();
        if (retainComposite) ASSERT_TRUE(observation.compositeOriginal->OriginalOwner().Valid());
        sourceLoan.Release();
        bodyLoan.Release();
        ASSERT_TRUE(original->OriginalSource().Valid());
        ASSERT_TRUE(original->OriginalBody().Valid());
        ASSERT_EQ(observation.block, engine.mixer.BlocksRendered());
        ASSERT_EQ(VN_OK, Vn_Term());
        return;
    }
    bool heard = false, started = false;
    for (std::uint32_t block = 0; block < 128u; ++block) {
        ASSERT_EQ(VN_OK, Vn_Update());
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        const auto published = engine.mixer.BlocksRendered();
        ASSERT_EQ(previous + 1u, published);
        const auto output = engine.nullBackend.LastBlock();
        const bool audible = harkentest::Peak(output,
            engine.nullBackend.BlockFrames() * engine.nullBackend.Channels()) > 0.001f;
        harken::TimelineArmObservation actual{};
        ASSERT_TRUE(engine.timelineArms.Observe(arm, &actual));
        if (!started && actual.startedBlockSequence != 0) {
            EXPECT_EQ(published, actual.startedBlockSequence);
            EXPECT_TRUE(audible);
            started = true;
        }
        heard = heard || audible;

    }
    ASSERT_TRUE(started);
    ASSERT_TRUE(heard);
    ASSERT_TRUE(engine.voices.ReleaseObserved(physicalRelease));
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(harken::OriginalSourceSubmissionRegistry::Phase::Disposed, source->State());
    EXPECT_FALSE(original->OriginalSource().Valid());
    EXPECT_FALSE(original->OriginalBody().Valid());
    EXPECT_EQ(nullptr, engine.OriginalQueueSourcePreparationForArm(arm));
    EXPECT_TRUE(sourceLoan.Valid());
    EXPECT_TRUE(bodyLoan.Valid());
    EXPECT_TRUE(engine.originalSourceSubmissions.IsOriginalSourceLifetimePinFor(sourceLoan, arm));
    EXPECT_TRUE(engine.voices.IsOriginalSourceBodyLifetimePinFor(bodyLoan, arm, render));
    if (retainDecisions) {
        // Native audio retirement proceeds while immutable factory loans keep
        // only their actual Decision rows from reuse.
        for (std::uint32_t index = 0; index < observation.decisionCount; ++index) {
            auto& loan = observation.decisionLoans[index];
            ASSERT_TRUE(engine.decisions.IsOriginalDecisionLifetimePinFor(loan, observation.decisionTokens[index]));
            EXPECT_TRUE(engine.decisions.MatchesOriginalDecisionFactory(loan, observation.decisionRequests[index]));
            EXPECT_TRUE(loan.Release());
        }
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    // ACK/Source disposal never substitutes for the genuine physical release.
    if (retainComposite) {
        EXPECT_FALSE(observation.compositeOriginal->OriginalOwner().Valid());
        EXPECT_TRUE(observation.compositeLoan.Valid());
        EXPECT_FALSE(engine.compositeCompletionOwners.IsOriginalLifetimePinned(observation.compositeLoan));
        harken::CompositeCompletionOwnerInfo retained{};
        ASSERT_TRUE(engine.compositeCompletionOwners.CaptureOriginal(observation.compositeLoan, &retained));
        EXPECT_EQ(2u, retained.leafCount);
        EXPECT_EQ(1u, retained.aggregateRevision);
        EXPECT_FALSE(engine.compositeCompletionOwners.Capture(observation.compositeToken, &retained));
        EXPECT_TRUE(observation.compositeLeafLoan.Valid());
        const auto freeLeafBeforeReturn = engine.timelineOccurrences.FreeCount();
        ASSERT_EQ(retainOccurrences ? observation.occurrenceCount : 1u, engine.timelineOccurrences.RetainedStorageCount());
        observation.compositeLeafLoan.Release();
        EXPECT_EQ(freeLeafBeforeReturn + (retainOccurrences ? 0u : 1u), engine.timelineOccurrences.FreeCount());
        EXPECT_EQ(retainOccurrences ? observation.occurrenceCount : 0u, engine.timelineOccurrences.RetainedStorageCount());
        const auto freeBeforeReturn = engine.compositeCompletionOwners.FreeCount();
        observation.compositeLoan.Release();
        EXPECT_EQ(freeBeforeReturn + 1u, engine.compositeCompletionOwners.FreeCount());
    }
    if (retainCompositeLedger) {
        const auto freeBeforeReturn = engine.ledger.AvailableEntryCount();
        for (std::uint32_t index = 0; index < observation.count; ++index) {
            const auto& input = observation.ledgerInputs[index];
            auto& loan = observation.ledgerLoans[index];
            ASSERT_TRUE(engine.ledger.HasOriginalCompositeCompletionNativeEnd(loan));
            ASSERT_TRUE(engine.ledger.IsOriginalCompositeCompletionMutationOwnerFor(
                loan, input.identity, input.parent, input.renderHandle, input.completionMutation));
            EXPECT_FALSE(engine.ledger.IsCurrentOriginalCompositeCompletionMutationOwner(loan));
            EXPECT_FALSE(observation.originals[index]->OriginalCompositeLedger().Valid());
            loan.Release();
            EXPECT_EQ(freeBeforeReturn + index + 1u, engine.ledger.AvailableEntryCount());
        }
    }
    if (retainOccurrences) {
        const auto freeBeforeReturn = engine.timelineOccurrences.FreeCount();
        for (std::uint32_t index = 0; index < observation.occurrenceCount; ++index) {
            auto& loan = observation.occurrenceLoans[index];
            ASSERT_TRUE(loan.NativeEnded());
            EXPECT_FALSE(observation.occurrenceOriginals[index]->OriginalStorage().Valid());
            EXPECT_EQ(nullptr, engine.timelineOccurrences.KeyOf(loan.OriginalToken()));
            harken::OccurrenceKey retained{};
            ASSERT_TRUE(loan.CaptureOriginalKey(&retained));
            EXPECT_EQ(observation.occurrenceKeys[index].arrangingInstance, retained.arrangingInstance);
            EXPECT_EQ(observation.occurrenceKeys[index].clipId, retained.clipId);
            loan.Release();
            EXPECT_EQ(freeBeforeReturn + index + 1u, engine.timelineOccurrences.FreeCount());
        }
        EXPECT_EQ(0u, engine.timelineOccurrences.RetainedStorageCount());
    }
    if (retainTrees) {
        bool nativeDispositionRequestedWhileHeld = false;
        for (std::uint32_t index = 0; index < observation.playableCount; ++index) {
            auto& loan = observation.playableLoans[index];
            ASSERT_TRUE(engine.playableInstances.IsOriginalLifetimePinFor(loan, observation.playableHandles[index]));
            EXPECT_EQ(observation.playableParents[index], loan.OriginalParent());
            EXPECT_EQ(observation.playableEpochs[index], loan.OriginalScheduleEpoch());
            nativeDispositionRequestedWhileHeld = nativeDispositionRequestedWhileHeld ||
                engine.playableInstances.HasRequestedOriginalLifetimeDisposition(loan);
            loan.Release();
            EXPECT_FALSE(loan.Valid());
        }
        EXPECT_TRUE(nativeDispositionRequestedWhileHeld);
    }
    sourceLoan.Release();
    bodyLoan.Release();
    if (retainTrees) {
        // Returning a storage loan does not execute the native retirement path.
        // Normal updates must finish the same original tree before API release.
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        for (std::uint32_t block = 0; block < 192u; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
            const auto previous = engine.mixer.BlocksRendered();
            engine.nullBackend.Pump(1);
            ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
            EXPECT_FALSE(engine.runtimeRecreateRequired);
        }
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state)
            << NativeQueueOriginalLoanCleanupDiagnostic(engine, firing);
        EXPECT_EQ(0u, info.livePlayableCount);
        for (std::uint32_t index = 0; index < observation.playableCount; ++index) {
            const auto handle = observation.playableHandles[index];
            EXPECT_FALSE(engine.playableInstances.IsOriginalLifetimePinFor(
                engine.originalPlayableLifetimeHolders[static_cast<std::uint32_t>(handle)], handle));
        }
    }
    ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    for (std::uint32_t block = 0; block < 192u && CaptureActionReclaimableOwners(engine) != owners; ++block) {
        const auto previous = engine.mixer.BlocksRendered();
        engine.nullBackend.Pump(1);
        ASSERT_EQ(previous + 1u, engine.mixer.BlocksRendered());
        ASSERT_EQ(VN_OK, Vn_Update());
    }
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(engine));
    EXPECT_FALSE(engine.runtimeRecreateRequired);
}

TEST(ActionFiringApi, QueueSourceSameCapturePreservesGenuineSingleAndReturnsOnPhysicalEnd) {
    CheckQueueSourceFactoryStaging(false, false);
}
TEST(ActionFiringApi, QueueSourceCompositeCaptureDoesNotIssueSingleAndKeepsForeignStorageUntilReturn) {
    CheckQueueSourceFactoryStaging(true, false);
}
TEST(ActionFiringApi, QueueSourceCompositeJoinedTermReturnsOwnBeforeSourceBodyReceivers) {
    CheckQueueSourceFactoryStaging(true, true);
}

TEST(ActionFiringApi, QueueCompositeSameFactoryOutputPreservesRealPcmEndAndForeignStorage) {
    CheckQueueSourceFactoryStaging(true, false, true);
}
TEST(ActionFiringApi, QueueCompositeSameFactoryOutputReturnsOwnAfterActualJoinedTerm) {
    CheckQueueSourceFactoryStaging(true, true, true);
}

TEST(ActionFiringApi, QueueCompositeLedgerSameSourceFactoryKeepsRealPcmAndNativeEndBeforeLastForeignReturn) {
    CheckQueueSourceFactoryStaging(true, false, true, true);
}
TEST(ActionFiringApi, QueueCompositeLedgerSameSourceFactoryReturnsOwnAfterActualJoinedTermBeforeAck) {
    CheckQueueSourceFactoryStaging(true, true, true, true);
}

static void CheckQueueSourceRetainedPreparationRefusal(bool composite) {
    (void)Vn_Term();
    std::vector<float> samples(512, 0.25f);
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto& engine = *session.Engine();
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kSecondSound, &pcm));
    CanonicalActionWorld image(
        engine.registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision,
        engine.registry.Lookup(CanonicalActionWorld::kSecondSound).contentRevision);
    image.MakeImmediateSequenceQueuePlayAction();
    if (composite) image.MakeFirstQueueChildCompositeTrack();
    ASSERT_EQ(harken::WorldInstallStatus::Ok,
        harken::InstallContainerWorldV1(engine, image.world).status);
    const auto owners = CaptureActionReclaimableOwners(engine);
    const auto head = engine.commands.PublishedHead();
    const auto audio = engine.mixer.BlocksRendered();
    struct FactoryLoan {
        harken::PreparedSingleCurrentOriginBundle::SourcePin source;
        harken::PreparedSingleCurrentOriginBundle::BodyPin body;
        harken::TimelineArmToken arm{};
        harken::VoiceReleaseObserver physical{};
        std::uint32_t calls = 0;
    } loan;
    engine.originalQueueSourcePreparationContextForTest = &loan;
    engine.originalQueueSourcePreparationHookForTest = [](
        harken::Engine& actual, const harken::Engine::OriginalQueueSourcePreparationHolder& original,
        void* context) {
        auto& output = *static_cast<FactoryLoan*>(context);
        ASSERT_EQ(0u, output.calls++);
        ASSERT_TRUE(original.OriginalSource().Borrow(&output.source));
        ASSERT_TRUE(original.OriginalBody().Borrow(&output.body));
        output.arm = original.OriginalArm();
        ASSERT_TRUE(actual.voices.CaptureReleaseObserver(original.OriginalSourceIdentity(), &output.physical));
        // Refuse only the actual post-Capture preparation stage. All native
        // cancellation, physical disposal and foreign loans remain genuine.
        actual.forceTimelineInheritedStopPreparationRefusalForTest = true;
    };
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    ASSERT_EQ(VN_OK, Vn_CreateEmitter(&desc.emitter));
    VnActionFiringHandle firing = 0;
    EXPECT_EQ(VN_BACKPRESSURE, Vn_PostAction(&desc, &firing));
    engine.originalQueueSourcePreparationHookForTest = nullptr;
    engine.originalQueueSourcePreparationContextForTest = nullptr;
    ASSERT_EQ(1u, loan.calls);
    EXPECT_EQ(0u, firing);
    EXPECT_EQ(head, engine.commands.PublishedHead());
    EXPECT_EQ(audio, engine.mixer.BlocksRendered());
    EXPECT_FALSE(engine.forceTimelineInheritedStopPreparationRefusalForTest);
    // Preserve the existing generic fault classification; this test proves
    // retained native cleanup and does not reclassify failure as acceptance.
    EXPECT_TRUE(engine.runtimeRecreateRequired);
    ASSERT_TRUE(loan.source.Valid());
    ASSERT_TRUE(loan.body.Valid());
    ASSERT_TRUE(engine.voices.ReleaseObserved(loan.physical));
    harken::TimelineArmObservation native{};
    ASSERT_TRUE(engine.timelineArms.Observe(loan.arm, &native));
    EXPECT_EQ(harken::ArmState::Prepared, native.state);
    auto retained = std::find_if(engine.actionPlayScratch.begin(), engine.actionPlayScratch.end(),
        [&](const auto& candidate) {
            return candidate.voiceStartCount != 0 &&
                harken::Engine::SameOriginalSingleArm(candidate.voiceStarts[0].arm, loan.arm);
        });
    ASSERT_NE(engine.actionPlayScratch.end(), retained);
    ASSERT_EQ(1u, retained->voiceStartCount);
    EXPECT_EQ(harken::EngineFrontierAttemptPhase::CancelPending, retained->storage.phase);
    EXPECT_TRUE(retained->voiceStarts[0].prepared);
    EXPECT_TRUE(retained->voiceStarts[0].armOwnershipHeld);
    EXPECT_FALSE(retained->voiceStarts[0].voiceOwnershipHeld);
    const auto generation = retained->storage.generation;
    ASSERT_EQ(VN_OK, Vn_Update());
    EXPECT_EQ(1u, retained->voiceStartCount);
    EXPECT_EQ(generation, retained->storage.generation);
    EXPECT_EQ(harken::EngineFrontierAttemptPhase::CancelPending, retained->storage.phase);
    EXPECT_EQ(head, engine.commands.PublishedHead());
    EXPECT_EQ(audio, engine.mixer.BlocksRendered());
    loan.source.Release();
    loan.body.Release();
    for (std::uint32_t update = 0; update < 8u &&
         retained->storage.phase != harken::EngineFrontierAttemptPhase::Free; ++update)
        ASSERT_EQ(VN_OK, Vn_Update());
    ASSERT_EQ(harken::EngineFrontierAttemptPhase::Free, retained->storage.phase);
    EXPECT_EQ(generation, retained->storage.generation);
    EXPECT_EQ(0u, retained->voiceStartCount);
    EXPECT_FALSE(engine.timelineArms.Observe(loan.arm, &native));
    EXPECT_EQ(head, engine.commands.PublishedHead());
    EXPECT_EQ(audio, engine.mixer.BlocksRendered());
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(desc.emitter));
    EXPECT_EQ(owners, CaptureActionReclaimableOwners(engine));
}
