namespace {
void CheckDefaultSelectionHistory(bool global) {
    (void)Vn_Term();
    harkentest::EngineSession session(harkentest::MakeNullConfig(8, 64, 48000));
    ASSERT_EQ(VN_OK, session.InitResult());
    auto* engine = session.Engine();
    const std::vector<float> samples(64, 0.25f);
    const auto pcm = harkentest::MonoDesc(samples, 48000);
    ASSERT_EQ(VN_OK, Vn_RegisterPCM(CanonicalActionWorld::kFirstSound, &pcm));
    CanonicalActionWorld image(engine->registry.Lookup(CanonicalActionWorld::kFirstSound).contentRevision);
    image.MakeImmediateRandomContainerPlayAction();
    image.containers[0].memoryScope = global ? harken::MemoryScopeV1::Global : harken::MemoryScopeV1::Emitter;
    image.world.identity.runtimeSemanticFingerprint = harken::ComputeCurrentWorldFingerprintV4(image.world);
    ASSERT_EQ(harken::WorldInstallStatus::Ok, harken::InstallContainerWorldV1(*engine, image.world).status);
    VnEmitterCreateDescV1 create{};
    create.structSize = sizeof(create);
    create.flags = VN_EMITTER_CREATE_STATE_ONLY;
    VnEmitterHandle independent = 0;
    ASSERT_EQ(VN_OK, Vn_CreateEmitterEx(&create, &independent));
    const auto keyFor = [&](VnEmitterHandle state) {
        harken::SelectionMemoryKeyV1 key{};
        key.world = engine->variables.CurrentWorldGeneration();
        key.containerStableId = image.containers[0].containerStableId;
        key.programSemanticFingerprint = image.containers[0].programSemanticFingerprint;
        key.memoryScope = image.containers[0].memoryScope;
        key.emitterSlot = global ? UINT32_MAX : static_cast<std::uint32_t>(state);
        key.emitterGeneration = global ? 0u : static_cast<std::uint32_t>(state >> 32);
        return key;
    };
    const auto defaultKey = keyFor(engine->emitters.DefaultState());
    EXPECT_FALSE(engine->selectionMemory.Snapshot(defaultKey).found);
    auto desc = ValidPostDesc();
    desc.actionId = image.actions[9].actionStableId;
    desc.emitter = engine->emitters.DefaultState();
    VnActionFiringHandle firing = 99;
    EXPECT_EQ(VN_STALE_HANDLE, Vn_PostAction(&desc, &firing));
    EXPECT_EQ(0u, firing);
    EXPECT_FALSE(engine->selectionMemory.Snapshot(defaultKey).found);
    for (unsigned play = 0; play < 3; ++play) {
        desc.emitter = play == 1 ? independent : 0;
        ASSERT_EQ(VN_OK, Vn_PostAction(&desc, &firing));
        VnActionFiringInfo info{};
        info.structSize = sizeof(info);
        for (unsigned block = 0; block < 32; ++block) {
            ASSERT_EQ(VN_OK, Vn_Update());
            engine->nullBackend.Pump(1);
            ASSERT_EQ(VN_OK, Vn_Update());
            ASSERT_EQ(VN_OK, Vn_QueryActionFiring(firing, &info));
            if (info.state == VN_ACTION_FIRING_TERMINAL_RETAINED) break;
        }
        ASSERT_EQ(VN_ACTION_FIRING_TERMINAL_RETAINED, info.state);
        ASSERT_EQ(VN_OK, Vn_ReleaseActionFiring(firing));
        const auto history = engine->selectionMemory.Snapshot(defaultKey);
        ASSERT_TRUE(history.found);
        EXPECT_EQ(global ? play + 1u : (play == 2 ? 2u : 1u), history.selectionOrdinal);
    }
    EXPECT_EQ(global ? 3u : 1u, engine->selectionMemory.Snapshot(keyFor(independent)).selectionOrdinal);
    ASSERT_EQ(VN_OK, Vn_DestroyEmitter(independent));
    EXPECT_TRUE(engine->selectionMemory.Snapshot(defaultKey).found);
    ASSERT_EQ(harken::PlayableResetStatus::Ok,
              harken::ResetCurrentPlayableByIdentity(harken::PlayableKindV1::Container,
                  image.containers[0].containerStableId, 0));
    const auto reset = engine->selectionMemory.Snapshot(defaultKey);
    EXPECT_EQ(0u, reset.selectionOrdinal);
    EXPECT_EQ(1u, reset.resetEpoch);
}
}
TEST(ActionDefaultContext, DefaultHistoryPersistsAndStateOnlyHistoryIsIndependent) { CheckDefaultSelectionHistory(false); }
TEST(ActionDefaultContext, AuthoredGlobalHistoryRemainsShared) { CheckDefaultSelectionHistory(true); }
